/**
 * @cipherbox/core - Folder Metadata Encryption
 *
 * Encrypts and decrypts folder metadata using AES-256-GCM.
 * Folder metadata is JSON serialized before encryption.
 */

import {
  encryptAesGcm,
  decryptAesGcm,
  generateIv,
  bytesToHex,
  hexToBytes,
  CryptoError,
  ECIES_MIN_CIPHERTEXT_SIZE,
} from '@cipherbox/crypto';
import type { FolderMetadata, EncryptedFolderMetadata } from './types';

/**
 * [SECURITY: MEDIUM-08] Chunk-based base64 encoding to avoid call stack issues
 * with large Uint8Arrays (spread operator has argument limits ~65536)
 */
function uint8ArrayToBase64(bytes: Uint8Array): string {
  const CHUNK_SIZE = 32768;
  let result = '';
  for (let i = 0; i < bytes.length; i += CHUNK_SIZE) {
    const chunk = bytes.subarray(i, Math.min(i + CHUNK_SIZE, bytes.length));
    result += String.fromCharCode(...chunk);
  }
  return btoa(result);
}

/**
 * [SECURITY: MEDIUM-07] Runtime validation for decrypted folder metadata.
 * Accepts only v2 schema. Rejects v1 data.
 * - v2 children: FolderEntry | FilePointer (with fileMetaIpnsName field)
 */
export function validateFolderMetadata(data: unknown): FolderMetadata {
  if (typeof data !== 'object' || data === null) {
    throw new CryptoError('Invalid metadata format: not an object', 'DECRYPTION_FAILED');
  }

  const obj = data as Record<string, unknown>;

  // Only v2 is accepted
  if (obj.version !== 'v2') {
    throw new CryptoError(
      'Invalid metadata format: unsupported version (only v2 accepted)',
      'DECRYPTION_FAILED'
    );
  }

  // Validate children array
  if (!Array.isArray(obj.children)) {
    throw new CryptoError('Invalid metadata format: children must be array', 'DECRYPTION_FAILED');
  }

  // Basic validation of each child entry
  for (const child of obj.children) {
    if (typeof child !== 'object' || child === null) {
      throw new CryptoError('Invalid metadata format: invalid child entry', 'DECRYPTION_FAILED');
    }
    const entry = child as Record<string, unknown>;
    if (entry.type !== 'file' && entry.type !== 'folder') {
      throw new CryptoError('Invalid metadata format: unknown child type', 'DECRYPTION_FAILED');
    }
    if (typeof entry.id !== 'string' || typeof entry.name !== 'string') {
      throw new CryptoError('Invalid metadata format: missing id or name', 'DECRYPTION_FAILED');
    }

    // v2 file children must have fileMetaIpnsName (FilePointer)
    if (entry.type === 'file') {
      const hasIpnsName = typeof entry.fileMetaIpnsName === 'string';
      if (!hasIpnsName) {
        throw new CryptoError(
          'Invalid metadata format: file entry must have fileMetaIpnsName',
          'DECRYPTION_FAILED'
        );
      }
      // Optional: ipnsPrivateKeyEncrypted must be a hex string long enough to hold ECIES output
      if (entry.ipnsPrivateKeyEncrypted !== undefined) {
        if (
          typeof entry.ipnsPrivateKeyEncrypted !== 'string' ||
          entry.ipnsPrivateKeyEncrypted.length < ECIES_MIN_CIPHERTEXT_SIZE * 2
        ) {
          throw new CryptoError(
            `Invalid metadata format: ipnsPrivateKeyEncrypted must be a hex string (min ${ECIES_MIN_CIPHERTEXT_SIZE * 2} chars)`,
            'DECRYPTION_FAILED'
          );
        }
      }
    }
  }

  return data as FolderMetadata;
}

/**
 * Encrypts folder metadata with AES-256-GCM.
 *
 * @param metadata - Plaintext folder metadata object (v2)
 * @param folderKey - 32-byte AES key for this folder
 * @returns Encrypted metadata with IV (hex) and ciphertext (base64)
 */
export async function encryptFolderMetadata(
  metadata: FolderMetadata,
  folderKey: Uint8Array
): Promise<EncryptedFolderMetadata> {
  const iv = generateIv();
  const plaintext = new TextEncoder().encode(JSON.stringify(metadata));
  const ciphertext = await encryptAesGcm(plaintext, folderKey, iv);

  return {
    iv: bytesToHex(iv),
    data: uint8ArrayToBase64(ciphertext),
  };
}

/**
 * Decrypts folder metadata encrypted with AES-256-GCM.
 * Returns v2 metadata only. Rejects v1 data.
 *
 * @param encrypted - Encrypted metadata with IV (hex) and ciphertext (base64)
 * @param folderKey - 32-byte AES key for this folder
 * @returns Decrypted folder metadata object (v2)
 * @throws CryptoError if decryption fails (wrong key, corrupted data, etc.)
 */
export async function decryptFolderMetadata(
  encrypted: EncryptedFolderMetadata,
  folderKey: Uint8Array
): Promise<FolderMetadata> {
  const iv = hexToBytes(encrypted.iv);
  const ciphertext = Uint8Array.from(atob(encrypted.data), (c) => c.charCodeAt(0));
  const plaintext = await decryptAesGcm(ciphertext, folderKey, iv);
  const parsed = JSON.parse(new TextDecoder().decode(plaintext));
  return validateFolderMetadata(parsed);
}

/**
 * @cipherbox/core - Folder Module
 *
 * Folder metadata types and encryption utilities.
 * v2 schema with per-file IPNS pointers (FilePointer children).
 */

// Types
export type { FolderMetadata, FolderChild, FolderEntry, EncryptedFolderMetadata } from './types';

// Encryption functions and validators
export { encryptFolderMetadata, decryptFolderMetadata, validateFolderMetadata } from './metadata';

/**
 * @cipherbox/core - Per-File Metadata Types
 *
 * Type definitions for per-file IPNS metadata records.
 * Each file gets its own IPNS record containing encrypted metadata,
 * while the parent folder only stores a slim FilePointer reference.
 */

/** A single past version of a file. Stores full crypto context for independent decryption. */
export type VersionEntry = {
  /** IPFS CID of the encrypted file content for this version */
  cid: string;
  /** Hex-encoded ECIES-wrapped AES-256 key for decrypting this version */
  fileKeyEncrypted: string;
  /** Hex-encoded IV used for this version's encryption */
  fileIv: string;
  /** Original file size in bytes (before encryption) */
  size: number;
  /** When this version was created (Unix ms) -- i.e., when it became a "past" version */
  timestamp: number;
  /** Encryption mode used for this version */
  encryptionMode: 'GCM' | 'CTR';
};

/**
 * Decrypted per-file metadata structure.
 * Stored as an encrypted blob in the file's own IPNS record.
 * Encrypted with the parent folder's folderKey (NOT the file's own key).
 */
export type FileMetadata = {
  /** Schema version */
  version: 'v1';
  /** IPFS CID of the encrypted file content */
  cid: string;
  /** Hex-encoded ECIES-wrapped AES-256 key for decrypting file */
  fileKeyEncrypted: string;
  /** Hex-encoded IV used for file encryption */
  fileIv: string;
  /** Original file size in bytes (before encryption) */
  size: number;
  /** MIME type of the original file */
  mimeType: string;
  /** Encryption mode (optional for backward compat; defaults to 'GCM') */
  encryptionMode?: 'GCM' | 'CTR';
  /** Creation timestamp (Unix ms) */
  createdAt: number;
  /** Last modification timestamp (Unix ms) */
  modifiedAt: number;
  /** Past versions of this file (newest first). Omitted if no versions exist. */
  versions?: VersionEntry[];
};

/**
 * Slim file reference stored in v2 folder metadata.
 * Points to a file's own IPNS record instead of embedding all file data inline.
 */
export type FilePointer = {
  type: 'file';
  /** UUID for internal reference */
  id: string;
  /** File name (plaintext, since folder metadata is encrypted) */
  name: string;
  /** IPNS name of the file's own metadata record */
  fileMetaIpnsName: string;
  /** Hex-encoded ECIES-wrapped Ed25519 private key for signing this file's IPNS record.
   *  Present for files created after the random-key migration. Absent for legacy files
   *  whose IPNS key is derived deterministically via HKDF. */
  ipnsPrivateKeyEncrypted?: string;
  /** Creation timestamp (Unix ms) */
  createdAt: number;
  /** Last modification timestamp (Unix ms) */
  modifiedAt: number;
};

/**
 * Encrypted file metadata for storage/transmission.
 * Same format as EncryptedFolderMetadata (hex IV + base64 ciphertext).
 */
export type EncryptedFileMetadata = {
  /** Hex-encoded 12-byte IV for AES-GCM */
  iv: string;
  /** Base64-encoded AES-GCM ciphertext (includes 16-byte auth tag) */
  data: string;
};

/**
 * @cipherbox/core - File IPNS Key Management
 *
 * Two strategies for per-file IPNS keypairs:
 *
 * 1. Deterministic (legacy): `deriveFileIpnsKeypair` derives an Ed25519 keypair
 *    from the user's secp256k1 privateKey + fileId via HKDF-SHA256.
 *
 * 2. Random (new files): `generateFileIpnsKeypair` generates a fresh Ed25519
 *    keypair via CSPRNG. The private key is ECIES-wrapped and stored in the
 *    parent folder's FilePointer so it can be recovered from any device.
 */

import {
  deriveKey,
  generateEd25519Keypair,
  CryptoError,
  SECP256K1_PRIVATE_KEY_SIZE,
} from '@cipherbox/crypto';
import * as ed from '@noble/ed25519';
import { deriveIpnsName } from '../ipns/derive-name';

const FILE_HKDF_SALT = new TextEncoder().encode('CipherBox-v1');

/**
 * Derive a deterministic Ed25519 IPNS keypair for a specific file.
 */
export async function deriveFileIpnsKeypair(
  userPrivateKey: Uint8Array,
  fileId: string
): Promise<{
  privateKey: Uint8Array;
  publicKey: Uint8Array;
  ipnsName: string;
}> {
  if (userPrivateKey.length !== SECP256K1_PRIVATE_KEY_SIZE) {
    throw new CryptoError('Invalid private key size for file IPNS derivation', 'INVALID_KEY_SIZE');
  }

  if (!fileId || fileId.length < 10) {
    throw new CryptoError(
      'Invalid fileId: must be a non-empty string of at least 10 characters',
      'INVALID_INPUT'
    );
  }

  const fileHkdfInfo = new TextEncoder().encode(`cipherbox-file-ipns-v1:${fileId}`);

  const ed25519Seed = await deriveKey({
    inputKey: userPrivateKey,
    salt: FILE_HKDF_SALT,
    info: fileHkdfInfo,
    outputLength: 32,
  });

  const ed25519PublicKey = await ed.getPublicKeyAsync(ed25519Seed);
  const ipnsName = await deriveIpnsName(ed25519PublicKey);

  return {
    privateKey: ed25519Seed,
    publicKey: ed25519PublicKey,
    ipnsName,
  };
}

/**
 * Generate a random Ed25519 IPNS keypair for a new file.
 */
export async function generateFileIpnsKeypair(): Promise<{
  privateKey: Uint8Array;
  publicKey: Uint8Array;
  ipnsName: string;
}> {
  const keypair = generateEd25519Keypair();
  const ipnsName = await deriveIpnsName(keypair.publicKey);

  return {
    privateKey: keypair.privateKey,
    publicKey: keypair.publicKey,
    ipnsName,
  };
}

