113→// ─── Encrypt / Decrypt Round-Trip ────────────────────────────────────────
114→
115→describe('encryptBinMetadata / decryptBinMetadata', () => {
116→  it('rejects Ed25519 IPNS public keys for ECIES encryption', async () => {
117→    const rootKeypair = generateTestKeypair();
118→    const ipnsKeypair = await deriveBinIpnsKeypair(rootKeypair.privateKey);
119→    const metadata = createTestBinMetadata(1);
120→
121→    await expect(encryptBinMetadata(metadata, ipnsKeypair.publicKey)).rejects.toThrow();
122→  });
123→
124→  it('round-trips empty bin metadata', async () => {
125→    const keypair = generateTestKeypair();
126→    const metadata: RecycleBinMetadata = {
127→      version: 'v1',
128→      sequenceNumber: 0,
129→      entries: [],
130→    };
131→
132→    const encrypted = await encryptBinMetadata(metadata, keypair.publicKey);
133→    expect(encrypted).toBeInstanceOf(Uint8Array);
134→    expect(encrypted.length).toBeGreaterThan(0);
135→
136→    const decrypted = await decryptBinMetadata(encrypted, keypair.privateKey);
137→    expect(decrypted).toEqual(metadata);
138→  });
139→
140→  it('round-trips bin metadata with file entries', async () => {
141→    const keypair = generateTestKeypair();
142→    const metadata = createTestBinMetadata(3);
143→
144→    const encrypted = await encryptBinMetadata(metadata, keypair.publicKey);
145→    const decrypted = await decryptBinMetadata(encrypted, keypair.privateKey);
146→
147→    expect(decrypted.version).toBe('v1');
148→    expect(decrypted.sequenceNumber).toBe(3);
149→    expect(decrypted.entries).toHaveLength(3);
150→    expect(decrypted.entries[0].itemType).toBe('file');
151→    expect(decrypted.entries[1].itemType).toBe('folder');
152→  });
153→
154→  it('preserves all entry fields through round-trip', async () => {
155→    const keypair = generateTestKeypair();
156→    const metadata = createTestBinMetadata(1);
157→
158→    const encrypted = await encryptBinMetadata(metadata, keypair.publicKey);
159→    const decrypted = await decryptBinMetadata(encrypted, keypair.privateKey);
160→
161→    const original = metadata.entries[0];
162→    const restored = decrypted.entries[0];
163→    expect(restored.id).toBe(original.id);
164→    expect(restored.name).toBe(original.name);
165→    expect(restored.originalParentIpnsName).toBe(original.originalParentIpnsName);
166→    expect(restored.originalPath).toBe(original.originalPath);
167→    expect(restored.deletedAt).toBe(original.deletedAt);
168→    expect(restored.size).toBe(original.size);
169→    expect(restored.mimeType).toBe(original.mimeType);
170→    expect(restored.filePointer).toEqual(original.filePointer);
171→    expect(restored.contentCid).toBe(original.contentCid);
172→    expect(restored.contentSize).toBe(original.contentSize);
173→  });
174→
175→  it('fails to decrypt with wrong key', async () => {
176→    const keypair1 = generateTestKeypair();
177→    const keypair2 = generateTestKeypair();
178→    const metadata = createTestBinMetadata(1);
179→
180→    const encrypted = await encryptBinMetadata(metadata, keypair1.publicKey);
181→    await expect(decryptBinMetadata(encrypted, keypair2.privateKey)).rejects.toThrow();
182→  });
183→
184→  it('fails to decrypt corrupted data', async () => {
185→    const keypair = generateTestKeypair();
186→    const metadata = createTestBinMetadata(1);
187→
188→    const encrypted = await encryptBinMetadata(metadata, keypair.publicKey);
189→    // Flip a byte in the middle of the ciphertext
190→    encrypted[Math.floor(encrypted.length / 2)] ^= 0xff;
191→
192→    await expect(decryptBinMetadata(encrypted, keypair.privateKey)).rejects.toThrow();
193→  });
194→});
