 16→/**
 17→ * Generate a secp256k1 keypair for testing (matches pattern from ecies.test.ts).
 18→ */
 19→function generateTestKeypair(): { publicKey: Uint8Array; privateKey: Uint8Array } {
 20→  const privateKey = secp256k1.utils.randomPrivateKey();
 21→  const publicKey = secp256k1.getPublicKey(privateKey, false); // uncompressed, 65 bytes
 22→  return { publicKey, privateKey };
 23→}
 24→
 25→/**
 26→ * Create a minimal valid DeviceRegistry for testing.
 27→ */
 28→function createTestRegistry(deviceCount = 1): DeviceRegistry {
 29→  const now = Date.now();
 30→  const devices = Array.from({ length: deviceCount }, (_, i) => ({
 31→    deviceId: `${i.toString(16).padStart(2, '0')}${'a'.repeat(62)}`,
 32→    publicKey: `${'b'.repeat(64)}`,
 33→    name: `Test Device ${i}`,
 34→    platform: 'web' as const,
 35→    appVersion: '0.2.0',
 36→    deviceModel: 'Chrome 123',
 37→    ipHash: `${i.toString(16).padStart(2, '0')}${'c'.repeat(62)}`,
 38→    status: i === 0 ? ('authorized' as const) : ('pending' as const),
 39→    createdAt: now - i * 1000,
 40→    lastSeenAt: now,
 41→    revokedAt: null,
 42→    revokedBy: null,
 43→  }));
 44→
 45→  return {
 46→    version: 'v1',
 47→    sequenceNumber: deviceCount,
 48→    devices,
 49→  };
 50→}
