 98→describe('encryptRegistry / decryptRegistry', () => {
 99→  it('round-trips a DeviceRegistry with 1 device entry', async () => {
100→    const keypair = generateTestKeypair();
101→    const registry = createTestRegistry(1);
102→
103→    const encrypted = await encryptRegistry(registry, keypair.publicKey);
104→    const decrypted = await decryptRegistry(encrypted, keypair.privateKey);
105→
106→    expect(decrypted).toEqual(registry);
107→  });
108→
109→  it('round-trips a DeviceRegistry with multiple devices', async () => {
110→    const keypair = generateTestKeypair();
111→    const registry = createTestRegistry(5);
112→
113→    const encrypted = await encryptRegistry(registry, keypair.publicKey);
114→    const decrypted = await decryptRegistry(encrypted, keypair.privateKey);
115→
116→    expect(decrypted).toEqual(registry);
117→    expect(decrypted.devices).toHaveLength(5);
118→  });
119→
120→  it('throws CryptoError when decrypting with wrong privateKey', async () => {
121→    const keypair1 = generateTestKeypair();
122→    const keypair2 = generateTestKeypair();
123→    const registry = createTestRegistry(1);
124→
125→    const encrypted = await encryptRegistry(registry, keypair1.publicKey);
126→
127→    await expect(decryptRegistry(encrypted, keypair2.privateKey)).rejects.toThrow(
128→      'Key unwrapping failed'
129→    );
130→  });
131→
132→  it('produces encrypted output different from plaintext', async () => {
133→    const keypair = generateTestKeypair();
134→    const registry = createTestRegistry(1);
135→
136→    const plaintext = new TextEncoder().encode(JSON.stringify(registry));
137→    const encrypted = await encryptRegistry(registry, keypair.publicKey);
138→
139→    // Encrypted output should not equal plaintext
140→    expect(encrypted).not.toEqual(plaintext);
141→  });
142→
143→  it('produces encrypted output larger than plaintext by ECIES overhead', async () => {
144→    const keypair = generateTestKeypair();
145→    const registry = createTestRegistry(1);
146→
147→    const plaintext = new TextEncoder().encode(JSON.stringify(registry));
148→    const encrypted = await encryptRegistry(registry, keypair.publicKey);
149→
150→    // ECIES overhead: ~97 bytes (65 ephemeral pubkey + 16 nonce + 16 tag)
151→    const overhead = encrypted.length - plaintext.length;
152→    expect(overhead).toBeGreaterThanOrEqual(80);
153→    expect(overhead).toBeLessThanOrEqual(120);
154→  });
155→
156→  it('produces different ciphertext on each encryption (ECIES nondeterminism)', async () => {
157→    const keypair = generateTestKeypair();
158→    const registry = createTestRegistry(1);
159→
160→    const encrypted1 = await encryptRegistry(registry, keypair.publicKey);
161→    const encrypted2 = await encryptRegistry(registry, keypair.publicKey);
162→
163→    // Different due to ephemeral key
164→    expect(encrypted1).not.toEqual(encrypted2);
165→
166→    // Both decrypt to same registry
167→    const decrypted1 = await decryptRegistry(encrypted1, keypair.privateKey);
168→    const decrypted2 = await decryptRegistry(encrypted2, keypair.privateKey);
169→    expect(decrypted1).toEqual(decrypted2);
170→  });
171→});
