 61→  it('uses default 24h lifetime', async () => {
 62→    const keypair = generateEd25519Keypair();
 63→    const value = '/ipfs/REDACTED';
 64→    const beforeCreate = Date.now();
 65→
 66→    const record = await createIpnsRecord(keypair.privateKey, value, 0n);
 67→    const afterCreate = Date.now();
 68→
 69→    // Parse validity timestamp (RFC3339)
 70→    const validityDate = new Date(record.validity);
