  1→/**
  2→ * @cipherbox/crypto - IPNS Tests
  3→ *
  4→ * Tests for IPNS record signing utilities.
  5→ */
  6→
  7→import { describe, it, expect } from 'vitest';
  8→import { signIpnsData, IPNS_SIGNATURE_PREFIX } from '../ipns';
  9→import { generateEd25519Keypair, verifyEd25519 } from '../ed25519';
 10→import { ED25519_SIGNATURE_SIZE } from '../constants';
 11→
 12→describe('IPNS Signature Prefix', () => {
 13→  it('has correct bytes for "ipns-signature:"', () => {
 14→    // Verify prefix is correct UTF-8 encoding of "ipns-signature:"
 15→    const expectedString = 'ipns-signature:';
 16→    const decoded = new TextDecoder().decode(IPNS_SIGNATURE_PREFIX);
 17→
 18→    expect(decoded).toBe(expectedString);
 19→    expect(IPNS_SIGNATURE_PREFIX.length).toBe(15);
 20→  });
 21→
 22→  it('matches IPFS spec byte values', () => {
 23→    // Verify individual byte values per IPFS spec
 24→    const expected = [
 25→      0x69,
 26→      0x70,
 27→      0x6e,
 28→      0x73,
 29→      0x2d, // "ipns-"
 30→      0x73,
 31→      0x69,
 32→      0x67,
 33→      0x6e,
 34→      0x61, // "signa"
 35→      0x74,
 36→      0x75,
 37→      0x72,
 38→      0x65,
 39→      0x3a, // "ture:"
 40→    ];
 41→
 42→    expect(Array.from(IPNS_SIGNATURE_PREFIX)).toEqual(expected);
 43→  });
 44→});
 45→
 46→describe('IPNS Data Signing', () => {
 47→  it('returns 64-byte signature', async () => {
 48→    const keypair = generateEd25519Keypair();
 49→    const cborData = new Uint8Array([0x01, 0x02, 0x03, 0x04]);
 50→
 51→    const signature = await signIpnsData(cborData, keypair.privateKey);
 52→
 53→    expect(signature).toBeInstanceOf(Uint8Array);
 54→    expect(signature.length).toBe(ED25519_SIGNATURE_SIZE);
 55→  });
 56→
 57→  it('signature is verifiable with Ed25519 using prefixed data', async () => {
 58→    const keypair = generateEd25519Keypair();
 59→    const cborData = new Uint8Array([0xa1, 0x63, 0x66, 0x6f, 0x6f, 0x63, 0x62, 0x61, 0x72]); // CBOR example
 60→
 61→    const signature = await signIpnsData(cborData, keypair.privateKey);
 62→
 63→    // Reconstruct the signed data (prefix + cbor)
 64→    const dataToVerify = new Uint8Array(IPNS_SIGNATURE_PREFIX.length + cborData.length);
 65→    dataToVerify.set(IPNS_SIGNATURE_PREFIX, 0);
 66→    dataToVerify.set(cborData, IPNS_SIGNATURE_PREFIX.length);
 67→
 68→    // Verify with standard Ed25519 verification
 69→    const isValid = await verifyEd25519(signature, dataToVerify, keypair.publicKey);
 70→
 71→    expect(isValid).toBe(true);
 72→  });
 73→
 74→  it('same data signed with same key produces same signature (deterministic)', async () => {
 75→    const keypair = generateEd25519Keypair();
 76→    const cborData = new TextEncoder().encode('deterministic cbor data');
 77→
 78→    const signature1 = await signIpnsData(cborData, keypair.privateKey);
 79→    const signature2 = await signIpnsData(cborData, keypair.privateKey);
 80→
 81→    // Ed25519 signatures are deterministic
 82→    expect(signature1).toEqual(signature2);
 83→  });
 84→
 85→  it('different data produces different signature', async () => {
 86→    const keypair = generateEd25519Keypair();
 87→    const cborData1 = new TextEncoder().encode('data version 1');
 88→    const cborData2 = new TextEncoder().encode('data version 2');
 89→
 90→    const signature1 = await signIpnsData(cborData1, keypair.privateKey);
 91→    const signature2 = await signIpnsData(cborData2, keypair.privateKey);
 92→
 93→    expect(signature1).not.toEqual(signature2);
 94→  });
 95→
 96→  it('works with empty CBOR data', async () => {
 97→    const keypair = generateEd25519Keypair();
 98→    const emptyCbor = new Uint8Array(0);
 99→
100→    const signature = await signIpnsData(emptyCbor, keypair.privateKey);
101→
102→    expect(signature.length).toBe(ED25519_SIGNATURE_SIZE);
103→
104→    // Verify signature is valid for just the prefix
105→    const isValid = await verifyEd25519(signature, IPNS_SIGNATURE_PREFIX, keypair.publicKey);
106→    expect(isValid).toBe(true);
107→  });
108→
109→  it('different keys produce different signatures', async () => {
110→    const keypair1 = generateEd25519Keypair();
111→    const keypair2 = generateEd25519Keypair();
112→    const cborData = new TextEncoder().encode('test data');
113→
114→    const signature1 = await signIpnsData(cborData, keypair1.privateKey);
115→    const signature2 = await signIpnsData(cborData, keypair2.privateKey);
116→
117→    expect(signature1).not.toEqual(signature2);
118→  });
119→
120→  it('validates private key length (via Ed25519)', async () => {
121→    const invalidPrivateKey = new Uint8Array(16); // Wrong size
122→    const cborData = new TextEncoder().encode('test');
123→
124→    await expect(signIpnsData(cborData, invalidPrivateKey)).rejects.toThrow('Signing failed');
125→  });
126→});
