  7→import { describe, it, expect } from 'vitest';
  8→import * as secp256k1 from '@noble/secp256k1';
  9→import { initializeVault, encryptVaultKeys, decryptVaultKeys } from '../vault';
 10→import { ED25519_PUBLIC_KEY_SIZE, ED25519_PRIVATE_KEY_SIZE, AES_KEY_SIZE } from '../constants';
 11→
 12→/**
 13→ * Generate a secp256k1 keypair for testing.
 14→ */
 15→function generateTestKeypair(): { publicKey: Uint8Array; privateKey: Uint8Array } {
 16→  const privateKey = secp256k1.utils.randomPrivateKey();
 17→  const publicKey = secp256k1.getPublicKey(privateKey, false); // uncompressed
 18→  return { publicKey, privateKey };
 19→}
 20→
 21→describe('Vault Initialization', () => {
 22→  describe('initializeVault', () => {
 23→    it('should return valid VaultInit structure', async () => {
 24→      const userKeypair = generateTestKeypair();
 25→      const vault = await initializeVault(userKeypair.privateKey);
 26→
 27→      expect(vault).toHaveProperty('rootFolderKey');
 28→      expect(vault).toHaveProperty('rootIpnsKeypair');
 29→      expect(vault.rootIpnsKeypair).toHaveProperty('publicKey');
 30→      expect(vault.rootIpnsKeypair).toHaveProperty('privateKey');
 31→    });
 32→
 33→    it('should generate 32-byte root folder key', async () => {
 34→      const userKeypair = generateTestKeypair();
 35→      const vault = await initializeVault(userKeypair.privateKey);
 36→
 37→      expect(vault.rootFolderKey.length).toBe(AES_KEY_SIZE);
 38→    });
 39→
 40→    it('should generate Ed25519 keypair with correct sizes', async () => {
 41→      const userKeypair = generateTestKeypair();
 42→      const vault = await initializeVault(userKeypair.privateKey);
 43→
 44→      expect(vault.rootIpnsKeypair.publicKey.length).toBe(ED25519_PUBLIC_KEY_SIZE);
 45→      expect(vault.rootIpnsKeypair.privateKey.length).toBe(ED25519_PRIVATE_KEY_SIZE);
 46→    });
 47→
 48→    it('should produce unique folder keys but deterministic IPNS keys for different private keys', async () => {
 49→      const userKeypair1 = generateTestKeypair();
 50→      const userKeypair2 = generateTestKeypair();
 51→      const userKeypair3 = generateTestKeypair();
 52→
 53→      const vault1 = await initializeVault(userKeypair1.privateKey);
 54→      const vault2 = await initializeVault(userKeypair2.privateKey);
 55→      const vault3 = await initializeVault(userKeypair3.privateKey);
 56→
 57→      // Root folder keys should be unique (random)
 58→      expect(vault1.rootFolderKey).not.toEqual(vault2.rootFolderKey);
 59→      expect(vault2.rootFolderKey).not.toEqual(vault3.rootFolderKey);
 60→
 61→      // IPNS keypairs should be unique for different private keys
 62→      expect(vault1.rootIpnsKeypair.publicKey).not.toEqual(vault2.rootIpnsKeypair.publicKey);
 63→      expect(vault1.rootIpnsKeypair.privateKey).not.toEqual(vault2.rootIpnsKeypair.privateKey);
 64→    });
 65→
 66→    it('should generate keys with high entropy', async () => {
 67→      const userKeypair = generateTestKeypair();
 68→      const vault = await initializeVault(userKeypair.privateKey);
 69→
 70→      // Check root folder key has non-trivial entropy
 71→      const folderKeyUnique = new Set(vault.rootFolderKey);
 72→      expect(folderKeyUnique.size).toBeGreaterThan(1);
 73→
 74→      // Check IPNS private key has non-trivial entropy
 75→      const ipnsKeyUnique = new Set(vault.rootIpnsKeypair.privateKey);
 76→      expect(ipnsKeyUnique.size).toBeGreaterThan(1);
 77→    });
 78→  });
 79→});
