 81→describe('Vault Key Encryption/Decryption', () => {
 82→  describe('encryptVaultKeys', () => {
 83→    it('should return EncryptedVaultKeys structure', async () => {
 84→      const userKeypair = generateTestKeypair();
 85→      const vault = await initializeVault(userKeypair.privateKey);
 86→
 87→      const encrypted = await encryptVaultKeys(vault, userKeypair.publicKey);
