 72→// ─── IPNS Derivation ─────────────────────────────────────────────────────
 73→
 74→describe('deriveBinIpnsKeypair', () => {
 75→  it('derives an IPNS name starting with k51 from a 32-byte key', async () => {
 76→    const keypair = generateTestKeypair();
 77→    const result = await deriveBinIpnsKeypair(keypair.privateKey);
 78→
 79→    expect(result.ipnsName).toMatch(/^k51/);
 80→    expect(result.privateKey).toBeInstanceOf(Uint8Array);
 81→    expect(result.privateKey.length).toBe(32);
 82→    expect(result.publicKey).toBeInstanceOf(Uint8Array);
 83→    expect(result.publicKey.length).toBe(32);
 84→  });
 85→
 86→  it('produces the same IPNS name for the same privateKey (determinism)', async () => {
 87→    const keypair = generateTestKeypair();
 88→
 89→    const result1 = await deriveBinIpnsKeypair(keypair.privateKey);
 90→    const result2 = await deriveBinIpnsKeypair(keypair.privateKey);
 91→
 92→    expect(result1.ipnsName).toBe(result2.ipnsName);
 93→    expect(result1.privateKey).toEqual(result2.privateKey);
 94→    expect(result1.publicKey).toEqual(result2.publicKey);
 95→  });
 96→
 97→  it('produces different IPNS names for different privateKeys', async () => {
