  1→/**
  2→ * @cipherbox/crypto - Device Registry Tests
  3→ *
  4→ * Tests for registry crypto operations: IPNS derivation, ECIES encryption/decryption,
  5→ * schema validation, and device keypair generation.
  6→ */
  7→
  8→import { describe, it, expect } from 'vitest';
  9→import * as secp256k1 from '@noble/secp256k1';
 10→import { deriveRegistryIpnsKeypair } from '../registry/derive-ipns';
 11→import { encryptRegistry, decryptRegistry } from '../registry/encrypt';
 12→import { validateDeviceRegistry } from '../registry/schema';
