 52→describe('deriveRegistryIpnsKeypair', () => {
 53→  it('derives an IPNS name starting with k51 from a 32-byte key', async () => {
 54→    const keypair = generateTestKeypair();
 55→    const result = await deriveRegistryIpnsKeypair(keypair.privateKey);
 56→
