 65→
 66→    it('should generate keys with high entropy', async () => {
 67→      const userKeypair = generateTestKeypair();
 68→      const vault = await initializeVault(userKeypair.privateKey);
 69→
 70→      // Check root folder key has non-trivial entropy
 71→      const folderKeyUnique = new Set(vault.rootFolderKey);
 72→      expect(folderKeyUnique.size).toBeGreaterThan(1);
 73→
 74→      // Check IPNS private key has non-trivial entropy
 75→      const ipnsKeyUnique = new Set(vault.rootIpnsKeypair.privateKey);
 76→      expect(ipnsKeyUnique.size).toBeGreaterThan(1);
 77→    });
 78→  });
 79→});
 80→
 81→describe('Vault Key Encryption/Decryption', () => {
 82→  describe('encryptVaultKeys', () => {
 83→    it('should return EncryptedVaultKeys structure', async () => {
 84→      const userKeypair = generateTestKeypair();
 85→      const vault = await initializeVault(userKeypair.privateKey);
 86→
 87→      const encrypted = await encryptVaultKeys(vault, userKeypair.publicKey);
 88→
 89→      expect(encrypted).toHaveProperty('encryptedRootFolderKey');
 90→      expect(encrypted).toHaveProperty('encryptedIpnsPrivateKey');
 91→    });
 92→
 93→    it('should produce encrypted data larger than plaintext', async () => {
 94→      const userKeypair = generateTestKeypair();
 95→      const vault = await initializeVault(userKeypair.privateKey);
 96→
 97→      const encrypted = await encryptVaultKeys(vault, userKeypair.publicKey);
 98→
 99→      // ECIES adds ephemeral key (65 bytes) + tag (16 bytes)
100→      expect(encrypted.encryptedRootFolderKey.length).toBeGreaterThan(vault.rootFolderKey.length);
101→      expect(encrypted.encryptedIpnsPrivateKey.length).toBeGreaterThan(
102→        vault.rootIpnsKeypair.privateKey.length
103→      );
104→    });
105→
106→    it('should produce different encrypted data each time due to ECIES ephemeral keys', async () => {
107→      const userKeypair = generateTestKeypair();
108→      const vault = await initializeVault(userKeypair.privateKey);
109→
110→      const encrypted1 = await encryptVaultKeys(vault, userKeypair.publicKey);
111→      const encrypted2 = await encryptVaultKeys(vault, userKeypair.publicKey);
112→
113→      // Same plaintext should produce different ciphertext
114→      expect(encrypted1.encryptedRootFolderKey).not.toEqual(encrypted2.encryptedRootFolderKey);
115→      expect(encrypted1.encryptedIpnsPrivateKey).not.toEqual(encrypted2.encryptedIpnsPrivateKey);
116→    });
117→  });
118→
119→  describe('decryptVaultKeys', () => {
120→    it('should recover original keys after encrypt/decrypt round-trip', async () => {
121→      const userKeypair = generateTestKeypair();
122→      const vault = await initializeVault(userKeypair.privateKey);
123→
124→      const encrypted = await encryptVaultKeys(vault, userKeypair.publicKey);
125→      const decrypted = await decryptVaultKeys(encrypted, userKeypair.privateKey);
126→
127→      expect(decrypted.rootFolderKey).toEqual(vault.rootFolderKey);
128→      expect(decrypted.rootIpnsKeypair.publicKey).toEqual(vault.rootIpnsKeypair.publicKey);
129→      expect(decrypted.rootIpnsKeypair.privateKey).toEqual(vault.rootIpnsKeypair.privateKey);
130→    });
131→
132→    it('should throw with wrong private key', async () => {
133→      const userKeypair1 = generateTestKeypair();
134→      const userKeypair2 = generateTestKeypair();
135→      const vault = await initializeVault(userKeypair1.privateKey);
136→
137→      const encrypted = await encryptVaultKeys(vault, userKeypair1.publicKey);
138→
139→      await expect(decryptVaultKeys(encrypted, userKeypair2.privateKey)).rejects.toThrow(
140→        'Key unwrapping failed'
141→      );
142→    });
143→
144→    it('should throw on tampered encrypted root folder key', async () => {
145→      const userKeypair = generateTestKeypair();
146→      const vault = await initializeVault(userKeypair.privateKey);
147→
148→      const encrypted = await encryptVaultKeys(vault, userKeypair.publicKey);
149→
150→      // Tamper with encrypted data
151→      const tampered = { ...encrypted };
152→      tampered.encryptedRootFolderKey = new Uint8Array(encrypted.encryptedRootFolderKey);
153→      tampered.encryptedRootFolderKey[10] ^= 0xff;
154→
155→      await expect(decryptVaultKeys(tampered, userKeypair.privateKey)).rejects.toThrow(
156→        'Key unwrapping failed'
157→      );
158→    });
159→
160→    it('should throw on tampered encrypted IPNS private key', async () => {
161→      const userKeypair = generateTestKeypair();
162→      const vault = await initializeVault(userKeypair.privateKey);
163→
164→      const encrypted = await encryptVaultKeys(vault, userKeypair.publicKey);
165→
166→      // Tamper with encrypted data
167→      const tampered = { ...encrypted };
168→      tampered.encryptedIpnsPrivateKey = new Uint8Array(encrypted.encryptedIpnsPrivateKey);
169→      tampered.encryptedIpnsPrivateKey[10] ^= 0xff;
170→
171→      await expect(decryptVaultKeys(tampered, userKeypair.privateKey)).rejects.toThrow(
172→        'Key unwrapping failed'
173→      );
174→    });
175→  });
176→
177→  describe('full lifecycle', () => {
178→    it('should work for multiple encrypt/decrypt cycles', async () => {
179→      const userKeypair = generateTestKeypair();
180→      const vault = await initializeVault(userKeypair.privateKey);
181→
182→      // Simulate multiple login sessions
183→      for (let i = 0; i < 3; i++) {
184→        const encrypted = await encryptVaultKeys(vault, userKeypair.publicKey);
185→        const decrypted = await decryptVaultKeys(encrypted, userKeypair.privateKey);
186→
187→        expect(decrypted.rootFolderKey).toEqual(vault.rootFolderKey);
188→        expect(decrypted.rootIpnsKeypair.publicKey).toEqual(vault.rootIpnsKeypair.publicKey);
189→        expect(decrypted.rootIpnsKeypair.privateKey).toEqual(vault.rootIpnsKeypair.privateKey);
190→      }
191→    });
192→
193→    it('should work with different user keypairs for different users', async () => {
194→      // Simulate two different users
195→      const user1Keypair = generateTestKeypair();
196→      const user2Keypair = generateTestKeypair();
197→
198→      const vault1 = await initializeVault(user1Keypair.privateKey);
199→      const vault2 = await initializeVault(user2Keypair.privateKey);
200→
201→      // User 1 encrypts and can decrypt
202→      const encrypted1 = await encryptVaultKeys(vault1, user1Keypair.publicKey);
203→      const decrypted1 = await decryptVaultKeys(encrypted1, user1Keypair.privateKey);
204→      expect(decrypted1.rootFolderKey).toEqual(vault1.rootFolderKey);
205→
206→      // User 2 encrypts and can decrypt
207→      const encrypted2 = await encryptVaultKeys(vault2, user2Keypair.publicKey);
208→      const decrypted2 = await decryptVaultKeys(encrypted2, user2Keypair.privateKey);
209→      expect(decrypted2.rootFolderKey).toEqual(vault2.rootFolderKey);
210→
211→      // User 1 cannot decrypt User 2's encrypted keys
212→      await expect(decryptVaultKeys(encrypted2, user1Keypair.privateKey)).rejects.toThrow();
213→    });
214→  });
215→});
