 29→    expect(result1.privateKey).toEqual(result2.privateKey);
 30→    expect(result1.publicKey).toEqual(result2.publicKey);
 31→    expect(result1.ipnsName).toBe(result2.ipnsName);
 32→  });
 33→
 34→  it('produces different results for different private keys', async () => {
 35→    const privateKey1 = randomPrivateKey();
 36→    const privateKey2 = randomPrivateKey();
 37→
 38→    const result1 = await deriveVaultIpnsKeypair(privateKey1);
 39→    const result2 = await deriveVaultIpnsKeypair(privateKey2);
 40→
 41→    expect(result1.ipnsName).not.toBe(result2.ipnsName);
 42→    expect(result1.privateKey).not.toEqual(result2.privateKey);
 43→    expect(result1.publicKey).not.toEqual(result2.publicKey);
 44→  });
