/**
 * Folder operations - Stateless folder CRUD with encryption
 *
 * Extracted from: apps/web/src/services/folder.service.ts
 * All store access replaced with explicit parameters.
 * Functions take metadata in, return updated metadata out.
 */

import {
  generateEd25519Keypair,
  deriveIpnsName,
  generateRandomBytes,
  wrapKey,
  bytesToHex,
  hexToBytes,
} from '@cipherbox/crypto';
import {
  encryptFolderMetadata,
  decryptFolderMetadata,
  type FolderMetadata,
  type EncryptedFolderMetadata,
  type FolderEntry,
  type FolderChild,
  type FilePointer,
} from '@cipherbox/core';
import type { SdkContext, TeeKeys } from '../types';
import { addToIpfs, fetchFromIpfs } from '../ipfs';
import { createAndPublishIpnsRecord, resolveIpnsRecord } from '../ipns';

/**
 * Fetch and decrypt folder metadata from IPFS.
 *
 * @param cid - IPFS CID of the encrypted metadata blob
 * @param folderKey - Decrypted AES-256 folder key
 * @param ctx - SDK context for IPFS access
 * @returns Decrypted folder metadata (v2)
 */
export async function fetchAndDecryptMetadata(
  cid: string,
  folderKey: Uint8Array,
  ctx: SdkContext,
): Promise<FolderMetadata> {
  const encryptedBytes = await fetchFromIpfs(ctx, cid);
  const encryptedJson = new TextDecoder().decode(encryptedBytes);
  const encrypted: EncryptedFolderMetadata = JSON.parse(encryptedJson);
  return decryptFolderMetadata(encrypted, folderKey);
}

/**
 * Load a folder's metadata from IPNS.
 *
 * Resolves the folder's IPNS name to get the current metadata CID,
 * fetches and decrypts the metadata.
 *
 * @returns Decrypted folder metadata, sequence number, and CID, or null if IPNS not found
 */
export async function loadFolderMetadata(params: {
  ipnsName: string;
  folderKey: Uint8Array;
  ctx: SdkContext;
}): Promise<{
  metadata: FolderMetadata;
  sequenceNumber: bigint;
  cid: string;
} | null> {
  const resolved = await resolveIpnsRecord(params.ipnsName);
  if (!resolved) return null;

  const metadata = await fetchAndDecryptMetadata(
    resolved.cid,
    params.folderKey,
    params.ctx,
  );

  return {
    metadata,
    sequenceNumber: resolved.sequenceNumber,
    cid: resolved.cid,
  };
}

/**
 * Create a new subfolder with generated keys.
 *
 * Generates new Ed25519 IPNS keypair and AES-256 folder key,
 * wraps them with the user's public key for storage.
 *
 * @returns Created folder entry and decrypted keys
 */
export async function createSubfolder(params: {
  name: string;
  userPublicKey: Uint8Array;
  teeKeys?: TeeKeys;
}): Promise<{
  folder: FolderEntry;
  ipnsPrivateKey: Uint8Array;
  folderKey: Uint8Array;
  encryptedIpnsPrivateKey?: string;
  keyEpoch?: number;
}> {
  // 1. Generate Ed25519 keypair for folder IPNS
  const ipnsKeypair = await generateEd25519Keypair();
  const ipnsName = await deriveIpnsName(ipnsKeypair.publicKey);

  // 2. Generate random AES-256 folder key
  const folderKey = generateRandomBytes(32);

  // 3. Wrap keys with user's public key (ECIES encryption)
  const ipnsPrivateKeyEncrypted = bytesToHex(
    await wrapKey(ipnsKeypair.privateKey, params.userPublicKey),
  );
  const folderKeyEncrypted = bytesToHex(
    await wrapKey(folderKey, params.userPublicKey),
  );

  // 4. TEE-02: Encrypt IPNS private key with TEE public key for republishing
  let encryptedIpnsPrivateKey: string | undefined;
  let keyEpoch: number | undefined;

  if (params.teeKeys?.currentPublicKey) {
    const teePublicKey = hexToBytes(params.teeKeys.currentPublicKey);
    const encryptedKey = await wrapKey(ipnsKeypair.privateKey, teePublicKey);
    encryptedIpnsPrivateKey = bytesToHex(encryptedKey);
    keyEpoch = params.teeKeys.currentEpoch;
  }

  // 5. Create folder entry for parent's metadata
  const now = Date.now();
  const folder: FolderEntry = {
    type: 'folder',
    id: crypto.randomUUID(),
    name: params.name,
    ipnsName,
    ipnsPrivateKeyEncrypted,
    folderKeyEncrypted,
    createdAt: now,
    modifiedAt: now,
  };

  return {
    folder,
    ipnsPrivateKey: ipnsKeypair.privateKey,
    folderKey,
    encryptedIpnsPrivateKey,
    keyEpoch,
  };
}

/**
 * Update folder metadata and publish to IPNS.
 *
 * Encrypts the metadata with the folder key, uploads to IPFS,
 * and publishes an updated IPNS record pointing to the new CID.
 *
 * @returns New CID and sequence number
 */
export async function updateFolderMetadataAndPublish(params: {
  children: FolderChild[];
  folderKey: Uint8Array;
  ipnsPrivateKey: Uint8Array;
  ipnsName: string;
  sequenceNumber: bigint;
  ctx: SdkContext;
  encryptedIpnsPrivateKey?: string;
  keyEpoch?: number;
}): Promise<{ cid: string; newSequenceNumber: bigint }> {
  // 1. Create v2 folder metadata
  const metadata: FolderMetadata = {
    version: 'v2',
    children: params.children,
  };

  // 2. Encrypt metadata with folder key
  const encrypted = await encryptFolderMetadata(metadata, params.folderKey);

  // 3. Upload to IPFS via backend relay
  const jsonStr = JSON.stringify(encrypted);
  const encryptedBytes = new TextEncoder().encode(jsonStr);
  const { cid } = await addToIpfs(params.ctx, encryptedBytes);

  // 4. Publish IPNS record pointing to new CID
  const newSeq = params.sequenceNumber + 1n;
  await createAndPublishIpnsRecord({
    ipnsPrivateKey: params.ipnsPrivateKey,
    ipnsName: params.ipnsName,
    metadataCid: cid,
    sequenceNumber: newSeq,
    encryptedIpnsPrivateKey: params.encryptedIpnsPrivateKey,
    keyEpoch: params.keyEpoch,
    expectedSequenceNumber: params.sequenceNumber.toString(),
  });

  return { cid, newSequenceNumber: newSeq };
}

/**
 * Rename a child entry (folder or file) in folder metadata.
 *
 * Pure metadata operation: returns updated children array without publishing.
 */
export function renameInFolder(params: {
  children: FolderChild[];
  childId: string;
  newName: string;
}): { updatedChildren: FolderChild[]; renamedChild: FolderChild } {
  const children = [...params.children];
  const index = children.findIndex((c) => c.id === params.childId);

  if (index === -1) throw new Error('Item not found');

  const nameExists = children.some(
    (c) => c.name === params.newName && c.id !== params.childId,
  );
  if (nameExists) throw new Error('An item with this name already exists');

  const renamedChild = {
    ...children[index],
    name: params.newName,
    modifiedAt: Date.now(),
  };
  children[index] = renamedChild;

  return { updatedChildren: children, renamedChild };
}

/**
 * Remove a child entry (folder or file) from folder metadata.
 *
 * Pure metadata operation: returns updated children array and the removed item.
 */
export function deleteFromFolder(params: {
  children: FolderChild[];
  childId: string;
}): { updatedChildren: FolderChild[]; removedItem: FolderChild } {
  const index = params.children.findIndex((c) => c.id === params.childId);
  if (index === -1) throw new Error('Item not found');

  const removedItem = params.children[index];
  const updatedChildren = params.children.filter((c) => c.id !== params.childId);

  return { updatedChildren, removedItem };
}

/**
 * Add a file pointer to folder children.
 *
 * Pure metadata operation: returns updated children array with the new file pointer.
 */
export function addFilePointerToFolder(params: {
  children: FolderChild[];
  fileId: string;
  fileName: string;
  fileMetaIpnsName: string;
  ipnsPrivateKeyEncrypted: string;
}): { updatedChildren: FolderChild[]; filePointer: FilePointer } {
  const nameExists = params.children.some((c) => c.name === params.fileName);
  if (nameExists) throw new Error('A file with this name already exists');

  const now = Date.now();
  const filePointer: FilePointer = {
    type: 'file',
    id: params.fileId,
    name: params.fileName,
    fileMetaIpnsName: params.fileMetaIpnsName,
    ipnsPrivateKeyEncrypted: params.ipnsPrivateKeyEncrypted,
    createdAt: now,
    modifiedAt: now,
  };

  return {
    updatedChildren: [...params.children, filePointer],
    filePointer,
  };
}

/**
 * Move a child entry between folders.
 *
 * Pure metadata operation: returns updated source and dest children arrays.
 * Uses add-before-remove pattern conceptually (caller publishes dest first, then source).
 */
export function moveItem(params: {
  sourceChildren: FolderChild[];
  destChildren: FolderChild[];
  childId: string;
}): {
  updatedSourceChildren: FolderChild[];
  updatedDestChildren: FolderChild[];
  movedItem: FolderChild;
} {
  const index = params.sourceChildren.findIndex((c) => c.id === params.childId);
  if (index === -1) throw new Error('Item not found');

  const movedItem = {
    ...params.sourceChildren[index],
    modifiedAt: Date.now(),
  };

  // Check name collision in destination
  const nameExists = params.destChildren.some(
    (c) => c.name === movedItem.name,
  );
  if (nameExists) {
    throw new Error('An item with this name already exists in destination');
  }

  const updatedSourceChildren = params.sourceChildren.filter(
    (c) => c.id !== params.childId,
  );
  const updatedDestChildren = [...params.destChildren, movedItem];

  return { updatedSourceChildren, updatedDestChildren, movedItem };
}

/**
 * File Metadata Service - Per-file IPNS operations
 *
 * Extracted from: apps/web/src/services/file-metadata.service.ts
 * Change: teeKeys passed explicitly instead of read from useAuthStore.
 * Change: IPFS/IPNS operations use sdk-core internal modules instead of web app imports.
 */

import {
  generateFileIpnsKeypair,
  encryptFileMetadata,
  decryptFileMetadata,
  createIpnsRecord,
  marshalIpnsRecord,
  type FileMetadata,
  type EncryptedFileMetadata,
  type VersionEntry,
} from '@cipherbox/core';
import { wrapKey, bytesToHex, hexToBytes } from '@cipherbox/crypto';
import type { SdkContext, TeeKeys } from '../types';
import { addToIpfs, fetchFromIpfs } from '../ipfs';
import { resolveIpnsRecord } from '../ipns';

/** IPNS record lifetime: 24 hours in milliseconds */
const IPNS_LIFETIME_MS = 24 * 60 * 60 * 1000;

/** Maximum number of past versions retained per file (VER-04) */
const MAX_VERSIONS_PER_FILE = 10;

/** Safe base64 encoding that avoids call stack overflow from spread operator */
function uint8ToBase64(bytes: Uint8Array): string {
  let binary = '';
  for (let i = 0; i < bytes.length; i++) {
    binary += String.fromCharCode(bytes[i]);
  }
  return btoa(binary);
}

/** Record payload ready for batch publish */
export type FileIpnsRecordPayload = {
  ipnsName: string;
  recordBase64: string;
  metadataCid: string;
  encryptedIpnsPrivateKey?: string;
  keyEpoch?: number;
};

/**
 * Create a per-file IPNS metadata record.
 *
 * Generates a random Ed25519 IPNS keypair for the file, encrypts file metadata
 * with the parent folder's key, uploads to IPFS, and creates a signed IPNS record.
 *
 * @returns File IPNS name, record payload for batch publish, and ECIES-wrapped IPNS private key
 */
export async function createFileMetadata(params: {
  fileId: string;
  cid: string;
  fileKeyEncrypted: string;
  fileIv: string;
  size: number;
  mimeType: string;
  folderKey: Uint8Array;
  userPublicKey: Uint8Array;
  ctx: SdkContext;
  teeKeys?: TeeKeys;
  encryptionMode?: 'GCM' | 'CTR';
}): Promise<{
  fileMetaIpnsName: string;
  ipnsRecord: FileIpnsRecordPayload;
  ipnsPrivateKeyEncrypted: string;
}> {
  // 1. Generate random Ed25519 IPNS keypair for this file
  const ipnsKeypair = await generateFileIpnsKeypair();

  // 2. ECIES-wrap the IPNS private key with user's public key for storage in FilePointer
  const wrappedIpnsKey = await wrapKey(ipnsKeypair.privateKey, params.userPublicKey);
  const ipnsPrivateKeyEncrypted = bytesToHex(wrappedIpnsKey);

  // 3. Create FileMetadata object
  const now = Date.now();
  const metadata: FileMetadata = {
    version: 'v1',
    cid: params.cid,
    fileKeyEncrypted: params.fileKeyEncrypted,
    fileIv: params.fileIv,
    size: params.size,
    mimeType: params.mimeType,
    encryptionMode: params.encryptionMode ?? 'GCM',
    createdAt: now,
    modifiedAt: now,
  };

  // 4. Encrypt with parent folderKey
  const encrypted: EncryptedFileMetadata = await encryptFileMetadata(
    metadata,
    params.folderKey,
  );

  // 5. Upload encrypted metadata to IPFS
  const jsonStr = JSON.stringify(encrypted);
  const encryptedBytes = new TextEncoder().encode(jsonStr);
  const { cid: metadataCid } = await addToIpfs(params.ctx, encryptedBytes);

  // 6. Create IPNS record (sequence number 1 for new records)
  const record = await createIpnsRecord(
    ipnsKeypair.privateKey,
    `/ipfs/${metadataCid}`,
    1n,
    IPNS_LIFETIME_MS,
  );

  // 7. Marshal and base64 encode the record
  const recordBytes = marshalIpnsRecord(record);
  const recordBase64 = uint8ToBase64(recordBytes);

  // 8. TEE enrollment: encrypt IPNS private key with TEE public key
  let teeEncryptedIpnsPrivateKey: string | undefined;
  let keyEpoch: number | undefined;

  if (params.teeKeys?.currentPublicKey) {
    const teePublicKey = hexToBytes(params.teeKeys.currentPublicKey);
    const encryptedKey = await wrapKey(ipnsKeypair.privateKey, teePublicKey);
    teeEncryptedIpnsPrivateKey = bytesToHex(encryptedKey);
    keyEpoch = params.teeKeys.currentEpoch;
  }

  // Zero the private key now that wrapping, signing, and TEE enrollment are done
  ipnsKeypair.privateKey.fill(0);

  return {
    fileMetaIpnsName: ipnsKeypair.ipnsName,
    ipnsRecord: {
      ipnsName: ipnsKeypair.ipnsName,
      recordBase64,
      metadataCid,
      encryptedIpnsPrivateKey: teeEncryptedIpnsPrivateKey,
      keyEpoch,
    },
    ipnsPrivateKeyEncrypted,
  };
}

/**
 * Resolve a file's per-IPNS metadata record.
 *
 * Resolves the file's IPNS name to get the current metadata CID,
 * fetches the encrypted metadata from IPFS, and decrypts with the
 * parent folder's key.
 *
 * @returns Decrypted file metadata and the resolved metadata CID
 */
export async function resolveFileMetadata(
  fileMetaIpnsName: string,
  folderKey: Uint8Array,
  ctx: SdkContext,
): Promise<{ metadata: FileMetadata; metadataCid: string }> {
  const resolved = await resolveIpnsRecord(fileMetaIpnsName);

  if (!resolved) {
    throw new Error('File metadata IPNS not found');
  }

  const encryptedBytes = await fetchFromIpfs(ctx, resolved.cid);
  const encryptedJson = new TextDecoder().decode(encryptedBytes);
  const encrypted: EncryptedFileMetadata = JSON.parse(encryptedJson);
  const metadata = await decryptFileMetadata(encrypted, folderKey);

  return { metadata, metadataCid: resolved.cid };
}

/**
 * Update an existing file's per-IPNS metadata record.
 *
 * Merges updates into the current metadata, re-encrypts, uploads to IPFS,
 * and creates a new IPNS record with an incremented sequence number.
 *
 * @returns Updated IPNS record payload for publish, plus CIDs of pruned versions to unpin
 */
export async function updateFileMetadata(params: {
  fileIpnsPrivateKey: Uint8Array;
  fileMetaIpnsName: string;
  folderKey: Uint8Array;
  currentMetadata: FileMetadata;
  updates: Partial<
    Pick<FileMetadata, 'cid' | 'fileKeyEncrypted' | 'fileIv' | 'size' | 'encryptionMode'>
  >;
  createVersion: boolean;
  ctx: SdkContext;
}): Promise<{
  ipnsRecord: FileIpnsRecordPayload;
  prunedCids: string[];
}> {
  // 1. Build version history
  let versions: VersionEntry[] | undefined;
  let prunedCids: string[] = [];

  if (params.createVersion) {
    const versionEntry: VersionEntry = {
      cid: params.currentMetadata.cid,
      fileKeyEncrypted: params.currentMetadata.fileKeyEncrypted,
      fileIv: params.currentMetadata.fileIv,
      size: params.currentMetadata.size,
      timestamp: Date.now(),
      encryptionMode: params.currentMetadata.encryptionMode ?? 'GCM',
    };
    const allVersions = [versionEntry, ...(params.currentMetadata.versions ?? [])];

    versions = allVersions.slice(0, MAX_VERSIONS_PER_FILE);
    prunedCids = allVersions.slice(MAX_VERSIONS_PER_FILE).map((v) => v.cid);
  } else {
    versions = params.currentMetadata.versions;
  }

  // 2. Merge updates into current metadata
  const updatedMetadata: FileMetadata = {
    ...params.currentMetadata,
    ...params.updates,
    ...(versions && versions.length > 0
      ? { versions }
      : { versions: undefined }),
    modifiedAt: Date.now(),
  };

  // 3. Resolve current IPNS to get sequence number
  const resolved = await resolveIpnsRecord(params.fileMetaIpnsName);
  if (!resolved) {
    throw new Error(
      `Cannot update file metadata: existing IPNS record not found for ${params.fileMetaIpnsName}`,
    );
  }
  const newSeq = resolved.sequenceNumber + 1n;

  // 4. Encrypt updated metadata with folderKey
  const encrypted = await encryptFileMetadata(updatedMetadata, params.folderKey);

  // 5. Upload to IPFS
  const jsonStr = JSON.stringify(encrypted);
  const encryptedBytes = new TextEncoder().encode(jsonStr);
  const { cid: metadataCid } = await addToIpfs(params.ctx, encryptedBytes);

  // 6. Create new IPNS record with incremented sequence number
  const record = await createIpnsRecord(
    params.fileIpnsPrivateKey,
    `/ipfs/${metadataCid}`,
    newSeq,
    IPNS_LIFETIME_MS,
  );

  const recordBytes = marshalIpnsRecord(record);
  const recordBase64 = uint8ToBase64(recordBytes);

  return {
    ipnsRecord: {
      ipnsName: params.fileMetaIpnsName,
      recordBase64,
      metadataCid,
    },
    prunedCids,
  };
}

/**
 * Upload operations - Encrypt and upload files to IPFS
 *
 * Extracted from: apps/web/src/services/upload.service.ts + file-crypto.service.ts
 * Change: Takes raw Uint8Array data instead of File objects (no browser DOM deps).
 * Change: Takes explicit SdkContext instead of reading stores.
 * Does NOT handle: multi-file orchestration, upload queue, progress UI, quota checking.
 */

import {
  generateFileKey,
  generateIv,
  encryptAesGcm,
  wrapKey,
  clearBytes,
  bytesToHex,
} from '@cipherbox/crypto';
import type { SdkContext, TeeKeys, ProgressCallback } from '../types';
import { addToIpfs } from '../ipfs';
import { createFileMetadata, type FileIpnsRecordPayload } from '../file';

/**
 * Result of a single file upload operation.
 */
export type UploadResult = {
  /** IPFS CID of the encrypted file content */
  cid: string;
  /** Encrypted file size in bytes */
  encryptedSize: number;
  /** File metadata IPNS name (for FilePointer) */
  fileMetaIpnsName: string;
  /** File IPNS record payload for batch publish */
  ipnsRecord: FileIpnsRecordPayload;
  /** ECIES-wrapped IPNS private key (hex) for storage in FilePointer */
  ipnsPrivateKeyEncrypted: string;
};

/**
 * Encrypt and upload a file to IPFS, creating file metadata.
 *
 * This is the core single-file upload pipeline:
 * 1. Generate file key + IV
 * 2. Encrypt the file content with AES-256-GCM
 * 3. Upload encrypted blob to IPFS
 * 4. Create per-file IPNS metadata record
 *
 * Returns everything needed to add a FilePointer to the parent folder.
 *
 * @param params.data - Raw file content as Uint8Array
 * @param params.fileId - Pre-generated UUID for this file
 * @param params.mimeType - MIME type of the original file
 * @param params.folderKey - Parent folder's decrypted AES-256 key
 * @param params.userPublicKey - User's secp256k1 public key for ECIES wrapping
 * @param params.ctx - SDK context for API access
 * @param params.onProgress - Optional upload progress callback
 * @param params.teeKeys - Optional TEE keys for IPNS private key enrollment
 */
export async function uploadFile(params: {
  data: Uint8Array;
  fileId: string;
  mimeType: string;
  folderKey: Uint8Array;
  userPublicKey: Uint8Array;
  ctx: SdkContext;
  onProgress?: ProgressCallback;
  teeKeys?: TeeKeys;
}): Promise<UploadResult> {
  // 1. Generate unique file key and IV
  const fileKey = generateFileKey();
  const iv = generateIv();

  try {
    // 2. Encrypt with AES-256-GCM
    const ciphertext = await encryptAesGcm(params.data, fileKey, iv);

    // 3. Wrap file key with user's public key (ECIES)
    const wrappedKey = await wrapKey(fileKey, params.userPublicKey);

    // 4. Upload encrypted content to IPFS
    const { cid, size: encryptedSize } = await addToIpfs(
      params.ctx,
      ciphertext,
      params.onProgress,
    );

    // 5. Create per-file IPNS metadata record
    const fileMetaResult = await createFileMetadata({
      fileId: params.fileId,
      cid,
      fileKeyEncrypted: bytesToHex(wrappedKey),
      fileIv: bytesToHex(iv),
      size: params.data.length,
      mimeType: params.mimeType,
      folderKey: params.folderKey,
      userPublicKey: params.userPublicKey,
      ctx: params.ctx,
      teeKeys: params.teeKeys,
      encryptionMode: 'GCM',
    });

    return {
      cid,
      encryptedSize,
      fileMetaIpnsName: fileMetaResult.fileMetaIpnsName,
      ipnsRecord: fileMetaResult.ipnsRecord,
      ipnsPrivateKeyEncrypted: fileMetaResult.ipnsPrivateKeyEncrypted,
    };
  } finally {
    // 6. Clear sensitive key from memory
    clearBytes(fileKey);
  }
}

/**
 * Download operations - Fetch and decrypt files from IPFS
 *
 * Extracted from: apps/web/src/services/download.service.ts
 * Change: Takes SdkContext for IPFS access.
 * Does NOT handle: browser download trigger (document.createElement, URL.createObjectURL).
 */

import {
  decryptAesGcm,
  decryptAesCtr,
  unwrapKey,
  hexToBytes,
  clearBytes,
} from '@cipherbox/crypto';
import type { SdkContext, DownloadProgressCallback } from '../types';
import { fetchFromIpfs } from '../ipfs';

/**
 * Download and decrypt a file from IPFS.
 *
 * Fetches the encrypted file content from IPFS via the backend relay,
 * unwraps the file key, and decrypts the content.
 *
 * @param params.cid - IPFS CID of the encrypted file content
 * @param params.fileKeyEncrypted - Hex-encoded ECIES-wrapped file key
 * @param params.fileIv - Hex-encoded IV used for encryption
 * @param params.userPrivateKey - User's secp256k1 private key for key unwrapping
 * @param params.encryptionMode - Encryption mode: 'GCM' (default) or 'CTR'
 * @param params.ctx - SDK context for IPFS access
 * @param params.onProgress - Optional download progress callback
 * @returns Decrypted file content as Uint8Array
 */
export async function downloadAndDecrypt(params: {
  cid: string;
  fileKeyEncrypted: string;
  fileIv: string;
  userPrivateKey: Uint8Array;
  encryptionMode?: 'GCM' | 'CTR';
  ctx: SdkContext;
  onProgress?: DownloadProgressCallback;
}): Promise<Uint8Array> {
  // 1. Fetch encrypted file from IPFS
  const ciphertext = await fetchFromIpfs(params.ctx, params.cid, params.onProgress);

  // 2. Convert hex strings to bytes
  const iv = hexToBytes(params.fileIv);
  const wrappedKey = hexToBytes(params.fileKeyEncrypted);

  // 3. Unwrap file key using user's private key
  const fileKey = await unwrapKey(wrappedKey, params.userPrivateKey);

  try {
    // 4. Decrypt file content (CTR for streaming media, GCM for everything else)
    const plaintext =
      params.encryptionMode === 'CTR'
        ? await decryptAesCtr(ciphertext, fileKey, iv)
        : await decryptAesGcm(ciphertext, fileKey, iv);
    return plaintext;
  } finally {
    // 5. Clear file key from memory
    clearBytes(fileKey);
  }
}

// Types
export type {
  SdkContext,
  TeeKeys,
  IpfsAddResult,
  ProgressCallback,
  DownloadProgressCallback,
} from './types';

// IPFS operations
export { addToIpfs, fetchFromIpfs, unpinFromIpfs } from './ipfs';

// IPNS operations
export {
  createAndPublishIpnsRecord,
  batchPublishIpnsRecords,
  resolveIpnsRecord,
  verifyIpnsSignature,
} from './ipns';

// Folder operations
export {
  fetchAndDecryptMetadata,
  loadFolderMetadata,
  createSubfolder,
  updateFolderMetadataAndPublish,
  renameInFolder,
  deleteFromFolder,
  addFilePointerToFolder,
  moveItem,
} from './folder';

// File metadata operations
export {
  createFileMetadata,
  resolveFileMetadata,
  updateFileMetadata,
  type FileIpnsRecordPayload,
} from './file';

// Upload operations
export { uploadFile, type UploadResult } from './upload';

// Download operations
export { downloadAndDecrypt } from './download';

