260→       export type SdkEvent =
261→         | { type: 'folder:loaded'; folderId: string; ipnsName: string; children: FolderChild[] }
262→         | { type: 'folder:updated'; folderId: string; ipnsName: string; children: FolderChild[] }
263→         | { type: 'folder:deleted'; folderId: string }
