190→/**
191→ * Rename a child entry (folder or file) in folder metadata.
192→ *
193→ * Pure metadata operation: returns updated children array without publishing.
194→ */
195→export function renameInFolder(params: {
196→  children: FolderChild[];
197→  childId: string;
198→  newName: string;
199→}): { updatedChildren: FolderChild[]; renamedChild: FolderChild } {
200→  const children = [...params.children];
201→  const index = children.findIndex((c) => c.id === params.childId);
202→
203→  if (index === -1) throw new Error('Item not found');
204→
205→  const nameExists = children.some((c) => c.name === params.newName && c.id !== params.childId);
206→  if (nameExists) throw new Error('An item with this name already exists');
207→
208→  const renamedChild = {
209→    ...children[index],
210→    name: params.newName,
211→    modifiedAt: Date.now(),
212→  };
213→  children[index] = renamedChild;
214→
215→  return { updatedChildren: children, renamedChild };
216→}
