236→/**
237→ * Add a file pointer to folder children.
238→ *
239→ * Pure metadata operation: returns updated children array with the new file pointer.
240→ */
241→export function addFilePointerToFolder(params: {
242→  children: FolderChild[];
243→  fileId: string;
244→  fileName: string;
245→  fileMetaIpnsName: string;
246→  ipnsPrivateKeyEncrypted: string;
247→}): { updatedChildren: FolderChild[]; filePointer: FilePointer } {
248→  const nameExists = params.children.some((c) => c.name === params.fileName);
249→  if (nameExists) throw new Error('A file with this name already exists');
250→
251→  const now = Date.now();
252→  const filePointer: FilePointer = {
253→    type: 'file',
254→    id: params.fileId,
255→    name: params.fileName,
256→    fileMetaIpnsName: params.fileMetaIpnsName,
257→    ipnsPrivateKeyEncrypted: params.ipnsPrivateKeyEncrypted,
258→    createdAt: now,
259→    modifiedAt: now,
260→  };
261→
262→  return {
263→    updatedChildren: [...params.children, filePointer],
264→    filePointer,
265→  };
