268→/**
269→ * Move a child entry between folders.
270→ *
271→ * Pure metadata operation: returns updated source and dest children arrays.
272→ * Uses add-before-remove pattern conceptually (caller publishes dest first, then source).
273→ */
274→export function moveItem(params: {
275→  sourceChildren: FolderChild[];
276→  destChildren: FolderChild[];
277→  childId: string;
278→}): {
279→  updatedSourceChildren: FolderChild[];
280→  updatedDestChildren: FolderChild[];
281→  movedItem: FolderChild;
282→} {
283→  const index = params.sourceChildren.findIndex((c) => c.id === params.childId);
284→  if (index === -1) throw new Error('Item not found');
285→
286→  const movedItem = {
287→    ...params.sourceChildren[index],
288→    modifiedAt: Date.now(),
289→  };
290→
291→  // Check name collision in destination
292→  const nameExists = params.destChildren.some((c) => c.name === movedItem.name);
293→  if (nameExists) {
294→    throw new Error('An item with this name already exists in destination');
295→  }
296→
297→  const updatedSourceChildren = params.sourceChildren.filter((c) => c.id !== params.childId);
298→  const updatedDestChildren = [...params.destChildren, movedItem];
299→
300→  return { updatedSourceChildren, updatedDestChildren, movedItem };
301→}
