 53→/**
 54→ * Load and decrypt bin metadata from IPNS.
 55→ *
 56→ * @returns Decrypted metadata and IPNS resolution data, or null if no bin exists yet
 57→ */
 58→async function loadBinMetadata(params: { userPrivateKey: Uint8Array }): Promise<{
 59→  metadata: RecycleBinMetadata;
 60→  ipnsName: string;
 61→  sequenceNumber: bigint;
 62→} | null> {
 63→  const binIpns = await deriveBinIpnsKeypair(params.userPrivateKey);
 64→  const resolved = await resolveIpnsRecord(binIpns.ipnsName);
 65→
 66→  if (!resolved) {
 67→    return null;
 68→  }
 69→
 70→  const encryptedBytes = await fetchFromIpfs(resolved.cid);
 71→  const metadata = await decryptBinMetadata(encryptedBytes, params.userPrivateKey);
 72→
 73→  return {
 74→    metadata,
 75→    ipnsName: binIpns.ipnsName,
 76→    sequenceNumber: resolved.sequenceNumber,
 77→  };
 78→}
