 80→/**
 81→ * Encrypt and publish bin metadata to IPNS.
 82→ *
 83→ * Handles TEE enrollment on first write.
 84→ */
 85→async function saveBinMetadata(params: {
 86→  metadata: RecycleBinMetadata;
 87→  userPublicKey: Uint8Array;
 88→  userPrivateKey: Uint8Array;
 89→}): Promise<void> {
 90→  const binIpns = await deriveBinIpnsKeypair(params.userPrivateKey);
 91→
 92→  // Encrypt metadata with user's public key (ECIES)
 93→  const encryptedBytes = await encryptBinMetadata(params.metadata, params.userPublicKey);
 94→
 95→  // Pin to IPFS
 96→  const { cid } = await addToIpfs(new Blob([encryptedBytes as BlobPart]));
 97→
 98→  // TEE enrollment on first write (fire-and-forget)
 99→  let encryptedIpnsKey: string | undefined;
100→  let keyEpoch: number | undefined;
101→
102→  const enrollingTee = !binTeeEnrolled;
103→  if (enrollingTee) {
104→    const teeKeys = useAuthStore.getState().teeKeys;
105→    if (teeKeys?.currentPublicKey) {
106→      try {
107→        const wrappedKey = await wrapKey(binIpns.privateKey, hexToBytes(teeKeys.currentPublicKey));
108→        encryptedIpnsKey = bytesToHex(wrappedKey);
109→        keyEpoch = teeKeys.currentEpoch;
110→      } catch (err) {
111→        console.error('[Bin] TEE enrollment failed (non-blocking):', err);
112→      }
113→    }
114→  }
115→
116→  // Publish IPNS record
117→  await createAndPublishIpnsRecord({
118→    ipnsPrivateKey: binIpns.privateKey,
119→    ipnsName: binIpns.ipnsName,
120→    metadataCid: cid,
121→    sequenceNumber: BigInt(params.metadata.sequenceNumber),
122→    encryptedIpnsPrivateKey: encryptedIpnsKey,
123→    keyEpoch,
124→  });
125→
126→  // Mark TEE enrolled only after successful publish
127→  if (enrollingTee && encryptedIpnsKey) {
128→    binTeeEnrolled = true;
129→  }
130→}
