180→/**
181→ * Ensure sent shares cache is fresh (fetched within last 30s).
182→ * Returns the current sent shares array.
183→ */
184→async function ensureFreshSentShares(): Promise<SentShare[]> {
185→  const store = useShareStore.getState();
186→  if (store.lastSentFetchedAt && Date.now() - store.lastSentFetchedAt < 30_000) {
187→    return store.sentShares;
188→  }
189→  // Re-wrapping needs the full set — paginate through all pages
190→  const allShares = await fetchAllSentShares();
191→  useShareStore.getState().setSentShares(allShares);
192→  return allShares;
193→}
