195→/**
196→ * Fetch ALL sent shares by paginating through the API.
197→ * The API enforces a max limit of 100 per page.
198→ */
199→async function fetchAllSentShares(): Promise<SentShare[]> {
200→  const pageSize = 100;
201→  let offset = 0;
202→  const allShares: SentShare[] = [];
203→
204→  while (true) {
205→    const { shares, total } = await fetchSentShares(pageSize, offset);
206→    allShares.push(...shares);
207→    offset += shares.length;
208→    if (offset >= total || shares.length === 0) break;
209→  }
210→
211→  return allShares;
212→}
