223→/**
224→ * Find active shares that cover a given folder, including ancestor shares.
225→ * A folder is "covered" if it or any of its ancestor folders is shared.
226→ *
227→ * Walks the ancestor chain and checks each folder's IPNS name against sent shares.
228→ *
229→ * @param folderIpnsName - IPNS name of the current folder
230→ * @param folders - Current folder tree from the folder store
231→ * @param currentFolderId - ID of the current folder in the tree
232→ * @returns Array of sent shares covering this folder (may be from ancestor)
233→ */
234→export async function findCoveringShares(
235→  folderIpnsName: string,
236→  folders: Record<string, FolderNode>,
237→  currentFolderId: string | null
238→): Promise<SentShare[]> {
239→  const shares = await ensureFreshSentShares();
240→  if (shares.length === 0) return [];
241→
242→  // Collect all IPNS names from this folder up to root
243→  const ipnsNames = new Set<string>();
244→  ipnsNames.add(folderIpnsName);
245→
246→  let walkId = currentFolderId;
247→  while (walkId) {
248→    const node = folders[walkId];
249→    if (!node) break;
250→    ipnsNames.add(node.ipnsName);
251→    walkId = node.parentId;
252→  }
253→
254→  return shares.filter((s) => ipnsNames.has(s.ipnsName));
255→}
