257→/**
258→ * After adding a file or subfolder to a shared folder, re-wrap the new key
259→ * for all existing share recipients.
260→ *
261→ * This is a fire-and-forget operation -- failures are logged but don't block
262→ * the primary upload/create flow.
263→ *
264→ * IMPORTANT: Callers are responsible for zeroing `newItems[*].plaintextKey`
265→ * after this function completes. This function does NOT zero the keys because
266→ * some callers (e.g., subfolder creation) keep the key alive in the store.
267→ * Use a `finally` block to ensure zeroing even on errors.
268→ *
269→ * @param params.folderIpnsName - IPNS name of the folder being modified
270→ * @param params.folders - Current folder tree from the store
271→ * @param params.currentFolderId - ID of the current folder in the tree
272→ * @param params.newItems - New items whose keys need re-wrapping
273→ */
274→export async function reWrapForRecipients(params: {
275→  folderIpnsName: string;
276→  folders: Record<string, FolderNode>;
277→  currentFolderId: string | null;
278→  newItems: Array<{
279→    keyType: 'file' | 'folder';
280→    itemId: string;
281→    plaintextKey: Uint8Array;
282→  }>;
283→}): Promise<{ failedRecipients: string[] }> {
284→  const coveringShares = await findCoveringShares(
285→    params.folderIpnsName,
286→    params.folders,
287→    params.currentFolderId
288→  );
289→
290→  if (coveringShares.length === 0) return { failedRecipients: [] };
291→
292→  const failedRecipients: string[] = [];
293→
294→  // For each share recipient, re-wrap all new item keys
295→  for (const share of coveringShares) {
296→    try {
297→      const recipientPubKey = hexToBytes(
298→        share.recipientPublicKey.startsWith('0x')
299→          ? share.recipientPublicKey.slice(2)
300→          : share.recipientPublicKey
301→      );
302→
303→      const wrappedKeys: Array<{
304→        keyType: 'file' | 'folder';
305→        itemId: string;
306→        encryptedKey: string;
307→      }> = [];
308→
309→      for (const item of params.newItems) {
310→        const wrapped = await wrapKey(item.plaintextKey, recipientPubKey);
311→        wrappedKeys.push({
312→          keyType: item.keyType,
313→          itemId: item.itemId,
314→          encryptedKey: bytesToHex(wrapped),
315→        });
316→      }
317→
318→      // Add the wrapped keys to this share via API
319→      await addShareKeys(share.shareId, wrappedKeys);
320→    } catch (err) {
321→      console.warn(
322→        `[share] Failed to re-wrap keys for recipient ${share.recipientPublicKey.slice(0, 10)}...:`,
323→        err
324→      );
325→      failedRecipients.push(share.recipientPublicKey);
326→    }
327→  }
328→
329→  return { failedRecipients };
330→}
