390→/**
391→ * Execute lazy key rotation for a folder.
392→ * Called when a folder modification is about to happen and pending rotations exist.
393→ *
394→ * Protocol:
395→ * 1. Generate new random folderKey
396→ * 2. Re-wrap new folderKey for each REMAINING (non-revoked) active recipient
397→ * 3. Update remaining shares with the new encrypted key
398→ * 4. Hard-delete revoked share records (rotation complete)
399→ * 5. Invalidate share cache
400→ *
401→ * NOTE: The actual folder metadata re-encryption (decrypt with old key, re-encrypt
402→ * with new key, re-publish IPNS) is handled by the caller (folder.service.ts)
403→ * since it has access to the folder's IPNS private key and publishing infrastructure.
404→ *
405→ * @returns The new folderKey for the caller to use
406→ */
407→export async function executeLazyRotation(params: {
408→  folderIpnsName: string;
409→  oldFolderKey: Uint8Array;
410→  ownerPublicKey: Uint8Array;
411→}): Promise<{ newFolderKey: Uint8Array }> {
412→  // 1. Generate new random 32-byte folderKey
413→  const newFolderKey = generateRandomBytes(32);
414→
415→  // 2. Fetch pending rotations and active shares for this folder
416→  const [pendingRotations, activeSentShares] = await Promise.all([
417→    fetchPendingRotations(),
418→    getSentSharesForItem(params.folderIpnsName),
419→  ]);
420→
421→  const revokedForFolder = pendingRotations.filter((r) => r.ipnsName === params.folderIpnsName);
422→  const revokedShareIds = new Set(revokedForFolder.map((r) => r.shareId));
423→
424→  // Active shares that are NOT revoked -- these recipients keep access
425→  const remainingShares = activeSentShares.filter((s) => !revokedShareIds.has(s.shareId));
426→
427→  // 3. Re-wrap new folderKey for each remaining recipient
428→  const reWrapFailures: string[] = [];
429→  for (const share of remainingShares) {
430→    try {
431→      const recipientPubKey = hexToBytes(
432→        share.recipientPublicKey.startsWith('0x')
433→          ? share.recipientPublicKey.slice(2)
434→          : share.recipientPublicKey
435→      );
436→      const wrapped = await wrapKey(newFolderKey, recipientPubKey);
437→      await updateShareKey(share.shareId, bytesToHex(wrapped));
438→    } catch (err) {
439→      console.warn(
440→        `[share] Failed to update share key for remaining recipient ${share.recipientPublicKey.slice(0, 10)}...:`,
441→        err
442→      );
443→      reWrapFailures.push(share.shareId);
444→    }
445→  }
446→
447→  if (reWrapFailures.length > 0) {
448→    newFolderKey.fill(0);
449→    throw new Error(
450→      `Key rotation failed: could not re-wrap key for ${reWrapFailures.length} recipient(s). ` +
451→        'Aborting to prevent inconsistent state.'
452→    );
453→  }
454→
455→  // 4. Hard-delete all revoked shares for this folder
456→  for (const revoked of revokedForFolder) {
457→    try {
458→      await completeShareRotation(revoked.shareId);
459→    } catch (err) {
460→      console.warn(`[share] Failed to complete rotation for share ${revoked.shareId}:`, err);
461→    }
462→  }
463→
464→  // 5. Invalidate the sent shares cache so next check fetches fresh state
465→  useShareStore.getState().setSentShares([]);
466→
467→  return { newFolderKey };
468→}
469→

150→
151→  try {
152→    // Reset TEE enrollment tracking for new session
153→    binTeeEnrolled = false;
154→
155→    // Try to load existing bin metadata (derives IPNS keypair internally)
156→    const loaded = await loadBinMetadata({ userPrivateKey: params.userPrivateKey });
157→
158→    // Set IPNS name from loaded result, or derive if no bin exists yet
159→    if (loaded) {
160→      store.setBinIpnsName(loaded.ipnsName);
161→    } else {
162→      const binIpns = await deriveBinIpnsKeypair(params.userPrivateKey);
163→      store.setBinIpnsName(binIpns.ipnsName);
164→    }
165→
166→    if (loaded) {
167→      store.setEntries(loaded.metadata.entries, loaded.metadata.sequenceNumber);
168→    } else {
169→      // No bin exists yet -- initialize with empty state
170→      store.setEntries([], 0);
171→    }
172→  } catch (error) {
173→    console.error('[Bin] Failed to initialize bin:', error);
174→    store.setError(error instanceof Error ? error.message : 'Failed to initialize bin');
175→    store.setLoading(false);
176→  }
177→}
