179→/**
180→ * Resolve file metadata and enrich a bin entry with content CID, size, and version CIDs.
181→ * Best-effort: errors are caught and logged, the entry is left un-enriched.
182→ */
183→async function enrichBinEntryWithFileMetadata(
184→  entry: BinEntry,
185→  item: FolderChild,
186→  folderKey: Uint8Array
187→): Promise<void> {
188→  try {
189→    const fp = item as FilePointer;
190→    const { metadata: fileMeta } = await resolveFileMetadata(fp.fileMetaIpnsName, folderKey);
191→    entry.contentCid = fileMeta.cid;
192→    entry.contentSize = fileMeta.size;
193→    if (Number.isFinite(fileMeta.size)) {
194→      entry.size = fileMeta.size;
195→    }
196→    if (fileMeta.mimeType) {
197→      entry.mimeType = fileMeta.mimeType;
198→    }
199→    if (Array.isArray(fileMeta.versions) && fileMeta.versions.length > 0) {
200→      entry.versionCids = fileMeta.versions
201→        .filter((v) => v.cid)
202→        .map((v) => ({ cid: v.cid, size: v.size ?? 0 }));
203→    }
204→  } catch (err) {
205→    console.warn('[Bin] Failed to resolve file CID for bin entry (non-blocking):', err);
206→  }
207→}
