211→// ---------------------------------------------------------------------------
212→
213→/**
214→ * Add a deleted item to the recycle bin.
215→ *
216→ * Creates a BinEntry from the FolderChild that was removed from its parent,
217→ * appends it to the bin metadata, encrypts, and publishes.
218→ *
219→ * @param params.item - The FolderChild (FilePointer or FolderEntry) that was removed
220→ * @param params.parentIpnsName - IPNS name of the original parent folder
221→ * @param params.parentPath - Breadcrumb path at deletion time (e.g., "My Vault / Documents")
222→ * @param params.userPublicKey - User's secp256k1 public key for ECIES encryption
223→ * @param params.userPrivateKey - User's secp256k1 private key for IPNS derivation
224→ */
225→export async function addToBin(params: {
226→  item: FolderChild;
227→  parentIpnsName: string;
228→  parentPath: string;
229→  userPublicKey: Uint8Array;
230→  userPrivateKey: Uint8Array;
231→  folderKey?: Uint8Array;
232→}): Promise<void> {
233→  const { item, parentIpnsName, parentPath, userPublicKey, userPrivateKey, folderKey } = params;
234→
235→  // Build bin entry
236→  const isFile = item.type === 'file';
237→  const entry: BinEntry = {
238→    id: crypto.randomUUID(),
239→    itemType: isFile ? 'file' : 'folder',
240→    name: item.name,
241→    originalParentIpnsName: parentIpnsName,
242→    originalPath: parentPath,
243→    deletedAt: Date.now(),
244→    size: 0,
245→    mimeType: '',
246→    filePointer: isFile ? (item as FilePointer) : undefined,
247→    folderEntry: !isFile ? (item as FolderEntry) : undefined,
248→  };
249→
250→  // Resolve file CID+size at soft-delete time (when folderKey is available)
251→  if (isFile && folderKey) {
252→    await enrichBinEntryWithFileMetadata(entry, item, folderKey);
253→  }
254→
255→  // Read current bin state and build updated metadata
256→  const store = useBinStore.getState();
257→  const currentEntries = [...store.entries, entry];
258→  const newSeq = store.sequenceNumber + 1;
259→
260→  const metadata: RecycleBinMetadata = {
261→    version: BIN_METADATA_VERSION,
262→    sequenceNumber: newSeq,
263→    entries: currentEntries,
264→  };
265→
266→  // Encrypt and publish (non-blocking: folder delete already committed, bin is best-effort)
267→  try {
268→    await saveBinMetadata({ metadata, userPublicKey, userPrivateKey });
269→    store.setEntries(currentEntries, newSeq);
270→  } catch {
271→    console.error('[Bin] addToBin publish failed (non-blocking)');
272→  }
273→}
