279→/**
280→ * Add multiple deleted items to the recycle bin in a single IPNS publish.
281→ *
282→ * Unlike calling addToBin in a loop (which publishes per-item), this batches
283→ * all entries into one metadata update.
284→ */
285→export async function addManyToBin(params: {
286→  items: FolderChild[];
287→  parentIpnsName: string;
288→  parentPath: string;
289→  userPublicKey: Uint8Array;
290→  userPrivateKey: Uint8Array;
291→  folderKey?: Uint8Array;
292→}): Promise<void> {
293→  const { items, parentIpnsName, parentPath, userPublicKey, userPrivateKey, folderKey } = params;
294→  if (items.length === 0) return;
295→
296→  const now = Date.now();
297→  const newEntries: BinEntry[] = [];
298→  for (const item of items) {
299→    const isFile = item.type === 'file';
300→    const entry: BinEntry = {
301→      id: crypto.randomUUID(),
302→      itemType: isFile ? 'file' : 'folder',
303→      name: item.name,
304→      originalParentIpnsName: parentIpnsName,
305→      originalPath: parentPath,
306→      deletedAt: now,
307→      size: 0,
308→      mimeType: '',
309→      filePointer: isFile ? (item as FilePointer) : undefined,
310→      folderEntry: !isFile ? (item as FolderEntry) : undefined,
311→    };
312→
313→    // Resolve file CID+size at soft-delete time (when folderKey is available)
314→    if (isFile && folderKey) {
315→      await enrichBinEntryWithFileMetadata(entry, item, folderKey);
316→    }
317→
318→    newEntries.push(entry);
319→  }
320→
321→  const store = useBinStore.getState();
322→  const currentEntries = [...store.entries, ...newEntries];
323→  const newSeq = store.sequenceNumber + 1;
324→
325→  const metadata: RecycleBinMetadata = {
326→    version: BIN_METADATA_VERSION,
327→    sequenceNumber: newSeq,
328→    entries: currentEntries,
329→  };
330→
331→  // Non-blocking: folder delete already committed, bin is best-effort
332→  try {
333→    await saveBinMetadata({ metadata, userPublicKey, userPrivateKey });
334→    store.setEntries(currentEntries, newSeq);
335→  } catch {
336→    console.error('[Bin] addManyToBin publish failed (non-blocking)');
337→  }
338→}
