  1→/**
  2→ * IPNS Service - Record creation, publishing, and resolution
  3→ *
  4→ * Extracted from: apps/web/src/services/ipns.service.ts
  5→ * Change: Uses @cipherbox/api-client generated functions instead of web app local imports.
  6→ * The ipns.service.ts was already clean (no store deps), so the extraction is straightforward.
  7→ */
  8→
  9→import { createIpnsRecord, marshalIpnsRecord, IPNS_SIGNATURE_PREFIX } from '@cipherbox/core';
 10→import { verifyEd25519, concatBytes } from '@cipherbox/crypto';
 11→import {
 12→  ipnsControllerPublishRecord,
 13→  ipnsControllerPublishBatch,
 14→  ipnsControllerResolveRecord,
 15→} from '@cipherbox/api-client';
 16→import type { PublishIpnsEntryDtoRecordType } from '@cipherbox/api-client';
 17→
 18→/**
 19→ * Create an IPNS record locally and publish via backend.
 20→ *
 21→ * The record is signed locally using the Ed25519 private key, then
 22→ * the backend relays it to the IPFS network via delegated routing.
 23→ *
 24→ * @param params.ipnsPrivateKey - Ed25519 private key (64 bytes in libp2p format)
 25→ * @param params.ipnsName - IPNS name (k51.../bafzaa... format)
 26→ * @param params.metadataCid - CID of the encrypted metadata blob
 27→ * @param params.sequenceNumber - Current sequence number (will be incremented before publish)
 28→ * @param params.encryptedIpnsPrivateKey - Hex ECIES-wrapped key for TEE (first publish only)
 29→ * @param params.keyEpoch - TEE key epoch (required with encryptedIpnsPrivateKey)
 30→ * @param params.expectedSequenceNumber - Pre-increment sequence number for conflict detection (folder records only)
 31→ */
 32→export async function createAndPublishIpnsRecord(params: {
 33→  ipnsPrivateKey: Uint8Array;
 34→  ipnsName: string;
 35→  metadataCid: string;
 36→  sequenceNumber: bigint;
 37→  encryptedIpnsPrivateKey?: string;
 38→  keyEpoch?: number;
 39→  expectedSequenceNumber?: string;
 40→}): Promise<{ success: boolean; sequenceNumber: bigint }> {
 41→  // 1. Create IPNS record pointing to /ipfs/{metadataCid}
 42→  // 24 hour lifetime (will be republished by TEE every 3 hours)
 43→  const record = await createIpnsRecord(
 44→    params.ipnsPrivateKey,
 45→    `/ipfs/${params.metadataCid}`,
 46→    params.sequenceNumber,
 47→    24 * 60 * 60 * 1000 // 24 hours in ms
 48→  );
 49→
 50→  // 2. Marshal to bytes for transport
 51→  const recordBytes = marshalIpnsRecord(record);
 52→
 53→  // 3. Base64 encode for API transmission
 54→  const recordBase64 = btoa(String.fromCharCode(...recordBytes));
 55→
 56→  // 4. Call backend API to relay to IPFS network
 57→  const response = await ipnsControllerPublishRecord({
 58→    ipnsName: params.ipnsName,
 59→    record: recordBase64,
 60→    metadataCid: params.metadataCid,
 61→    encryptedIpnsPrivateKey: params.encryptedIpnsPrivateKey,
 62→    keyEpoch: params.keyEpoch,
 63→    expectedSequenceNumber: params.expectedSequenceNumber,
 64→  });
 65→
 66→  return {
 67→    success: response.success,
 68→    sequenceNumber: BigInt(response.sequenceNumber),
 69→  };
 70→}
 71→
 72→/**
 73→ * Batch publish multiple IPNS records in a single API call.
 74→ *
 75→ * Sends all records (folder and/or file) to the batch endpoint,
 76→ * which processes them with concurrency-limited parallelism.
 77→ * Partial success is allowed: individual failures do not fail the batch.
 78→ *
 79→ * @param records - Array of IPNS record payloads to publish
 80→ * @returns Success and failure counts
 81→ */
 82→export async function batchPublishIpnsRecords(
 83→  records: Array<{
 84→    ipnsName: string;
 85→    recordBase64: string;
 86→    metadataCid: string;
 87→    encryptedIpnsPrivateKey?: string;
 88→    keyEpoch?: number;
 89→    recordType?: 'folder' | 'file';
 90→    /** Pre-increment sequence number for conflict detection (folder records only) */
 91→    expectedSequenceNumber?: string;
 92→  }>
 93→): Promise<{ totalSucceeded: number; totalFailed: number }> {
 94→  const response = await ipnsControllerPublishBatch({
 95→    records: records.map((r) => ({
 96→      ipnsName: r.ipnsName,
 97→      record: r.recordBase64,
 98→      metadataCid: r.metadataCid,
 99→      encryptedIpnsPrivateKey: r.encryptedIpnsPrivateKey,
100→      keyEpoch: r.keyEpoch,
101→      recordType: r.recordType as PublishIpnsEntryDtoRecordType | undefined,
102→      expectedSequenceNumber: r.expectedSequenceNumber,
103→    })),
104→  });
105→
106→  return {
107→    totalSucceeded: response.totalSucceeded,
108→    totalFailed: response.totalFailed,
109→  };
110→}
111→
112→/**
113→ * Verify the Ed25519 signature on an IPNS record.
114→ * Per IPFS spec, the signature is over "ipns-signature:" + cborData.
115→ *
116→ * @param signatureV2 - base64 Ed25519 signature (64 bytes)
117→ * @param data - base64 CBOR data that was signed
118→ * @param pubKey - base64 raw Ed25519 public key (32 bytes)
119→ * @returns true if valid
120→ */
121→export async function verifyIpnsSignature(
122→  signatureV2: string,
123→  data: string,
124→  pubKey: string
125→): Promise<boolean> {
126→  const sigBytes = Uint8Array.from(atob(signatureV2), (c) => c.charCodeAt(0));
127→  const dataBytes = Uint8Array.from(atob(data), (c) => c.charCodeAt(0));
128→  const pubKeyBytes = Uint8Array.from(atob(pubKey), (c) => c.charCodeAt(0));
129→
130→  // Per IPFS IPNS spec, signature is over "ipns-signature:" + cborData
131→  const signedData = concatBytes(IPNS_SIGNATURE_PREFIX, dataBytes);
132→  return verifyEd25519(sigBytes, signedData, pubKeyBytes);
133→}
134→
135→/**
136→ * Resolve an IPNS name to its current CID and sequence number.
137→ *
138→ * Calls backend API which relays to the delegated routing service for resolution.
139→ * When the response includes IPNS signature data (from delegated routing),
140→ * verifies the Ed25519 signature before trusting the CID.
141→ *
142→ * @param ipnsName - IPNS name to resolve (k51.../bafzaa... format)
143→ * @returns Current CID, sequence number, and signature verification status, or null if not found
144→ */
145→export async function resolveIpnsRecord(
146→  ipnsName: string
147→): Promise<{ cid: string; sequenceNumber: bigint; signatureVerified: boolean } | null> {
148→  try {
149→    const response = await ipnsControllerResolveRecord({ ipnsName });
150→
151→    if (!response.success) {
152→      return null;
153→    }
154→
155→    // Verify IPNS signature if all signature fields are present
156→    let signatureVerified = false;
157→    if (response.signatureV2 && response.data && response.pubKey) {
158→      const valid = await verifyIpnsSignature(response.signatureV2, response.data, response.pubKey);
159→      if (!valid) {
160→        throw new Error('IPNS signature verification failed - record may be tampered');
161→      }
162→      signatureVerified = true;
163→    } else {
164→      console.warn('IPNS resolve returned without signature data, skipping verification');
165→    }
166→
167→    return {
168→      cid: response.cid,
169→      sequenceNumber: BigInt(response.sequenceNumber),
170→      signatureVerified,
171→    };
172→  } catch (error) {
173→    // 404 means IPNS name not found - return null
174→    // Other errors should propagate (including signature verification failures)
175→    if (error instanceof Error && (error as Error & { status?: number }).status === 404) {
176→      return null;
177→    }
178→    throw error;
179→  }
180→}
