content.content:
  1→/**
  2→ * @cipherbox/sdk - CipherBoxClient
  3→ *
  4→ * Stateful client orchestrating folder CRUD, file upload/download,
  5→ * and event-driven change notification. Wraps @cipherbox/sdk-core
  6→ * stateless functions with internal state management (FolderTree, KeyCache).
  7→ *
  8→ * Design principles:
  9→ * - Zero React/Zustand/browser dependencies
 10→ * - All state flows through typed events (SdkEvent)
 11→ * - Operations are wrapped with withOperation() for consistent
 12→ *   start/end/error event emission
 13→ * - Key material is cleared on destroy()
 14→ */
 15→
 16→import type { SdkContext, ProgressCallback, DownloadProgressCallback } from '@cipherbox/sdk-core';
 17→import * as sdkCore from '@cipherbox/sdk-core';
 18→import type { FolderChild } from '@cipherbox/core';
 19→import type { CipherBoxClientConfig, FolderState } from './types';
 20→import { SdkEventEmitter, type SdkEvent, type SdkEventHandler } from './events';
 21→import { FolderTree } from './state/folder-tree';
 22→import { KeyCache } from './state/key-cache';
 23→
 24→export class CipherBoxClient {
 25→  private config: CipherBoxClientConfig;
 26→  private ctx: SdkContext;
 27→  private emitter: SdkEventEmitter;
 28→  private folderTree: FolderTree;
 29→  private keyCache: KeyCache;
 30→
 31→  constructor(config: CipherBoxClientConfig) {
 32→    this.config = config;
 33→    this.ctx = {
 34→      apiUrl: config.apiUrl,
 35→      getAccessToken: config.getAccessToken,
 36→    };
 37→    this.emitter = new SdkEventEmitter();
 38→    this.folderTree = new FolderTree();
 39→    this.keyCache = new KeyCache();
 40→  }
 41→
 42→  // ---- Event subscription ----
 43→
 44→  /** Subscribe to SDK events. Returns an unsubscribe function. */
 45→  on(handler: SdkEventHandler): () => void {
 46→    return this.emitter.on(handler);
 47→  }
 48→
 49→  /** Unsubscribe a previously registered handler. */
 50→  off(handler: SdkEventHandler): void {
 51→    this.emitter.off(handler);
 52→  }
 53→
 54→  // ---- Lifecycle ----
 55→
 56→  /**
 57→   * Destroy the client, clearing all sensitive state.
 58→   * After calling destroy(), the client instance should not be reused.
 59→   */
 60→  destroy(): void {
 61→    this.folderTree.clear();
 62→    this.keyCache.clear();
 63→    this.emitter.removeAll();
 64→  }
 65→
 66→  // ---- Internal state access (for bin/share modules) ----
 67→
 68→  /** @internal Get the folder tree for bin/share operations */
 69→  getFolderTree(): FolderTree {
 70→    return this.folderTree;
 71→  }
 72→
 73→  /** @internal Get the SDK context */
 74→  getContext(): SdkContext {
 75→    return this.ctx;
 76→  }
 77→
 78→  /** @internal Get the client config */
 79→  getConfig(): CipherBoxClientConfig {
 80→    return this.config;
 81→  }
 82→
 83→  /** @internal Emit an event (used by bin/share modules) */
 84→  emitEvent(event: SdkEvent): void {
 85→    this.emitter.emit(event);
 86→  }
