 88→  // ---- Folder operations ----
 89→
 90→  /**
 91→   * Load a folder's metadata from IPNS.
 92→   *
 93→   * Resolves the folder's IPNS record, decrypts metadata, stores state
 94→   * internally, and emits a 'folder:loaded' event.
 95→   *
 96→   * @param ipnsName - Folder's IPNS name
 97→   * @param folderKey - Decrypted AES-256 folder key
 98→   * @param ipnsKeypair - Ed25519 keypair for IPNS signing
 99→   * @returns The loaded folder state, or null if IPNS record not found
100→   */
101→  async loadFolder(
102→    ipnsName: string,
103→    folderKey: Uint8Array,
104→    ipnsKeypair: { publicKey: Uint8Array; privateKey: Uint8Array }
105→  ): Promise<FolderState | null> {
106→    return this.withOperation('loadFolder', async () => {
107→      const result = await sdkCore.loadFolderMetadata({
108→        ipnsName,
109→        folderKey,
110→        ctx: this.ctx,
111→      });
112→
113→      if (!result) return null;
114→
115→      const state: FolderState = {
116→        ipnsName,
117→        folderKey,
118→        ipnsKeypair,
119→        sequenceNumber: result.sequenceNumber,
120→        children: result.metadata.children,
121→        metadata: result.metadata,
122→        lastLoadedAt: Date.now(),
123→      };
124→
125→      this.folderTree.set(ipnsName, state);
126→
127→      this.emitter.emit({
128→        type: 'folder:loaded',
129→        folderId: ipnsName,
130→        ipnsName,
131→        children: result.metadata.children,
132→      });
133→
134→      return state;
135→    });
136→  }
137→
138→  /**
139→   * Create a new subfolder inside an existing folder.
140→   *
141→   * Generates IPNS keypair and folder key, wraps with user's public key,
142→   * adds folder entry to parent metadata, publishes parent IPNS record,
143→   * and publishes empty folder metadata for the new subfolder.
144→   *
145→   * @param parentIpnsName - IPNS name of the parent folder
146→   * @param name - Name for the new subfolder
147→   * @returns Created folder's IPNS name and folder key
148→   */
149→  async createFolder(
150→    parentIpnsName: string,
151→    name: string
152→  ): Promise<{ ipnsName: string; folderKey: Uint8Array }> {
153→    return this.withOperation('createFolder', async () => {
154→      const parent = this.folderTree.get(parentIpnsName);
155→      if (!parent) throw new Error('Parent folder not loaded');
156→
157→      // 1. Create subfolder (generates keys, wraps with user public key)
158→      const { folder, ipnsPrivateKey, folderKey, encryptedIpnsPrivateKey, keyEpoch } =
159→        await sdkCore.createSubfolder({
160→          name,
161→          userPublicKey: this.config.vaultKeypair.publicKey,
162→          teeKeys: this.config.teeKeys,
163→        });
164→
165→      // 2. Add folder entry to parent's children
166→      const updatedChildren: FolderChild[] = [...parent.children, folder];
167→
168→      // 3. Update parent metadata and publish
169→      const { newSequenceNumber } = await sdkCore.updateFolderMetadataAndPublish({
170→        children: updatedChildren,
171→        folderKey: parent.folderKey,
172→        ipnsPrivateKey: parent.ipnsKeypair.privateKey,
173→        ipnsName: parentIpnsName,
174→        sequenceNumber: parent.sequenceNumber,
175→        ctx: this.ctx,
176→        encryptedIpnsPrivateKey: encryptedIpnsPrivateKey,
177→        keyEpoch,
178→      });
179→
180→      // 4. Update parent state
181→      parent.children = updatedChildren;
182→      parent.sequenceNumber = newSequenceNumber;
183→      parent.lastLoadedAt = Date.now();
184→      this.folderTree.set(parentIpnsName, parent);
185→
186→      // 5. Publish empty metadata for the new subfolder
187→      await sdkCore.updateFolderMetadataAndPublish({
188→        children: [],
189→        folderKey,
190→        ipnsPrivateKey,
191→        ipnsName: folder.ipnsName,
192→        sequenceNumber: 0n,
193→        ctx: this.ctx,
194→        encryptedIpnsPrivateKey,
195→        keyEpoch,
196→      });
197→
198→      // 7. Emit parent folder updated event
199→      this.emitter.emit({
200→        type: 'folder:updated',
201→        folderId: parentIpnsName,
202→        ipnsName: parentIpnsName,
203→        children: updatedChildren,
204→      });
205→
206→      return { ipnsName: folder.ipnsName, folderKey };
207→    });
208→  }
