210→  /**
211→   * Rename a child entry (folder or file) in a folder.
212→   *
213→   * Updates the name in the folder's metadata and publishes the change.
214→   *
215→   * @param folderIpnsName - IPNS name of the folder containing the item
216→   * @param childId - ID of the child to rename
217→   * @param newName - New name for the child
218→   */
219→  async renameItem(folderIpnsName: string, childId: string, newName: string): Promise<void> {
220→    return this.withOperation('renameItem', async () => {
221→      const folder = this.folderTree.get(folderIpnsName);
222→      if (!folder) throw new Error('Folder not loaded');
223→
224→      // 1. Rename in metadata (pure operation)
225→      const { updatedChildren } = sdkCore.renameInFolder({
226→        children: folder.children,
227→        childId,
228→        newName,
229→      });
230→
231→      // 2. Publish updated metadata
232→      const { newSequenceNumber } = await sdkCore.updateFolderMetadataAndPublish({
233→        children: updatedChildren,
234→        folderKey: folder.folderKey,
235→        ipnsPrivateKey: folder.ipnsKeypair.privateKey,
236→        ipnsName: folderIpnsName,
237→        sequenceNumber: folder.sequenceNumber,
238→        ctx: this.ctx,
239→      });
240→
241→      // 3. Update internal state
242→      folder.children = updatedChildren;
243→      folder.sequenceNumber = newSequenceNumber;
244→      folder.lastLoadedAt = Date.now();
245→      this.folderTree.set(folderIpnsName, folder);
246→
247→      // 4. Emit update event
248→      this.emitter.emit({
249→        type: 'folder:updated',
250→        folderId: folderIpnsName,
251→        ipnsName: folderIpnsName,
252→        children: updatedChildren,
253→      });
254→    });
255→  }
256→
257→  /**
258→   * Move a child entry between two folders.
259→   *
260→   * Removes from source, adds to destination, publishes both IPNS records
261→   * (destination first for crash safety -- add-before-remove pattern).
262→   *
263→   * @param sourceIpnsName - IPNS name of the source folder
264→   * @param destIpnsName - IPNS name of the destination folder
265→   * @param childId - ID of the child to move
266→   */
267→  async moveItem(sourceIpnsName: string, destIpnsName: string, childId: string): Promise<void> {
268→    return this.withOperation('moveItem', async () => {
269→      const source = this.folderTree.get(sourceIpnsName);
270→      const dest = this.folderTree.get(destIpnsName);
271→      if (!source) throw new Error('Source folder not loaded');
272→      if (!dest) throw new Error('Destination folder not loaded');
273→
274→      // 1. Compute updated children for both folders (pure operation)
275→      const { updatedSourceChildren, updatedDestChildren } = sdkCore.moveItem({
276→        sourceChildren: source.children,
277→        destChildren: dest.children,
278→        childId,
279→      });
280→
281→      // 2. Publish destination first (add-before-remove for crash safety)
282→      const destResult = await sdkCore.updateFolderMetadataAndPublish({
283→        children: updatedDestChildren,
284→        folderKey: dest.folderKey,
285→        ipnsPrivateKey: dest.ipnsKeypair.privateKey,
286→        ipnsName: destIpnsName,
287→        sequenceNumber: dest.sequenceNumber,
288→        ctx: this.ctx,
289→      });
290→
291→      // 3. Publish source (remove)
292→      const sourceResult = await sdkCore.updateFolderMetadataAndPublish({
293→        children: updatedSourceChildren,
294→        folderKey: source.folderKey,
295→        ipnsPrivateKey: source.ipnsKeypair.privateKey,
296→        ipnsName: sourceIpnsName,
297→        sequenceNumber: source.sequenceNumber,
298→        ctx: this.ctx,
299→      });
300→
301→      // 4. Update internal state
302→      source.children = updatedSourceChildren;
303→      source.sequenceNumber = sourceResult.newSequenceNumber;
304→      dest.children = updatedDestChildren;
305→      dest.sequenceNumber = destResult.newSequenceNumber;
306→      this.folderTree.set(sourceIpnsName, source);
307→      this.folderTree.set(destIpnsName, dest);
308→
309→      // 5. Emit events for both folders
310→      this.emitter.emit({
311→        type: 'folder:updated',
312→        folderId: sourceIpnsName,
313→        ipnsName: sourceIpnsName,
314→        children: updatedSourceChildren,
315→      });
316→      this.emitter.emit({
317→        type: 'folder:updated',
318→        folderId: destIpnsName,
319→        ipnsName: destIpnsName,
320→        children: updatedDestChildren,
321→      });
322→    });
323→  }
324→
325→  /**
326→   * Delete a child entry from a folder's metadata.
327→   *
328→   * This is a simple metadata delete -- it does NOT move to bin.
329→   * Use deleteToBin() for soft-delete with bin support.
330→   *
331→   * @param folderIpnsName - IPNS name of the folder containing the item
332→   * @param childId - ID of the child to delete
333→   * @returns The removed child entry
334→   */
335→  async deleteItem(folderIpnsName: string, childId: string): Promise<{ removedItem: FolderChild }> {
336→    return this.withOperation('deleteItem', async () => {
337→      const folder = this.folderTree.get(folderIpnsName);
338→      if (!folder) throw new Error('Folder not loaded');
339→
340→      // 1. Remove from metadata (pure operation)
341→      const { updatedChildren, removedItem } = sdkCore.deleteFromFolder({
342→        children: folder.children,
343→        childId,
344→      });
345→
346→      // 2. Publish updated metadata
347→      const { newSequenceNumber } = await sdkCore.updateFolderMetadataAndPublish({
348→        children: updatedChildren,
349→        folderKey: folder.folderKey,
350→        ipnsPrivateKey: folder.ipnsKeypair.privateKey,
351→        ipnsName: folderIpnsName,
352→        sequenceNumber: folder.sequenceNumber,
353→        ctx: this.ctx,
354→      });
355→
356→      // 3. Update internal state
357→      folder.children = updatedChildren;
358→      folder.sequenceNumber = newSequenceNumber;
359→      folder.lastLoadedAt = Date.now();
360→      this.folderTree.set(folderIpnsName, folder);
361→
362→      // 4. Emit update event
363→      this.emitter.emit({
364→        type: 'folder:updated',
365→        folderId: folderIpnsName,
366→        ipnsName: folderIpnsName,
367→        children: updatedChildren,
368→      });
369→
370→      return { removedItem };
371→    });
372→  }
373→
374→  // ---- File operations ----
375→
376→  /**
377→   * Upload a file to a folder.
378→   *
379→   * Encrypts the file, uploads to IPFS, creates per-file IPNS metadata,
380→   * adds a FilePointer to the parent folder's metadata, and publishes.
381→   *
382→   * @param folderIpnsName - IPNS name of the target folder
383→   * @param data - Raw file content as Uint8Array
384→   * @param fileName - Display name for the file
385→   * @param mimeType - MIME type of the file
386→   * @param onProgress - Optional upload progress callback
387→   * @returns CID of the uploaded encrypted file
388→   */
389→  async uploadFile(
390→    folderIpnsName: string,
391→    data: Uint8Array,
392→    fileName: string,
393→    mimeType: string,
394→    onProgress?: ProgressCallback
395→  ): Promise<{ cid: string }> {
396→    return this.withOperation('uploadFile', async () => {
397→      const folder = this.folderTree.get(folderIpnsName);
398→      if (!folder) throw new Error('Folder not loaded');
399→
400→      const fileId = crypto.randomUUID();
401→
402→      // 1. Encrypt and upload file, create file metadata
403→      const uploadResult = await sdkCore.uploadFile({
404→        data,
405→        fileId,
406→        mimeType,
407→        folderKey: folder.folderKey,
408→        userPublicKey: this.config.vaultKeypair.publicKey,
409→        ctx: this.ctx,
410→        onProgress,
411→        teeKeys: this.config.teeKeys,
412→      });
413→
414→      // 2. Add FilePointer to folder's children
415→      const { updatedChildren } = sdkCore.addFilePointerToFolder({
416→        children: folder.children,
417→        fileId,
418→        fileName,
419→        fileMetaIpnsName: uploadResult.fileMetaIpnsName,
420→        ipnsPrivateKeyEncrypted: uploadResult.ipnsPrivateKeyEncrypted,
421→      });
422→
423→      // 3. Batch publish: file metadata IPNS + folder metadata IPNS
424→      await sdkCore.batchPublishIpnsRecords([uploadResult.ipnsRecord]);
425→
426→      const { newSequenceNumber } = await sdkCore.updateFolderMetadataAndPublish({
427→        children: updatedChildren,
428→        folderKey: folder.folderKey,
429→        ipnsPrivateKey: folder.ipnsKeypair.privateKey,
430→        ipnsName: folderIpnsName,
431→        sequenceNumber: folder.sequenceNumber,
432→        ctx: this.ctx,
433→      });
434→
435→      // 4. Update internal state
436→      folder.children = updatedChildren;
437→      folder.sequenceNumber = newSequenceNumber;
438→      folder.lastLoadedAt = Date.now();
439→      this.folderTree.set(folderIpnsName, folder);
440→
441→      // 5. Emit events
442→      this.emitter.emit({
443→        type: 'file:uploaded',
444→        folderId: folderIpnsName,
445→        fileName,
446→        cid: uploadResult.cid,
447→      });
448→      this.emitter.emit({
449→        type: 'folder:updated',
450→        folderId: folderIpnsName,
451→        ipnsName: folderIpnsName,
452→        children: updatedChildren,
453→      });
454→
455→      return { cid: uploadResult.cid };
456→    });
457→  }
458→
459→  /**
460→   * Download and decrypt a file from IPFS.
461→   *
462→   * Fetches the encrypted file content, unwraps the file key using the
463→   * user's private key, and decrypts the content.
464→   *
465→   * @param cid - IPFS CID of the encrypted file content
466→   * @param fileKeyEncrypted - Hex-encoded ECIES-wrapped file key
467→   * @param fileIv - Hex-encoded IV used for encryption
468→   * @param encryptionMode - 'GCM' (default) or 'CTR'
469→   * @param onProgress - Optional download progress callback
470→   * @returns Decrypted file content
471→   */
472→  async downloadFile(
473→    cid: string,
474→    fileKeyEncrypted: string,
475→    fileIv: string,
476→    encryptionMode?: 'GCM' | 'CTR',
477→    onProgress?: DownloadProgressCallback
478→  ): Promise<Uint8Array> {
479→    return this.withOperation('downloadFile', async () => {
480→      const plaintext = await sdkCore.downloadAndDecrypt({
481→        cid,
482→        fileKeyEncrypted,
483→        fileIv,
484→        userPrivateKey: this.config.vaultKeypair.privateKey,
485→        encryptionMode,
486→        ctx: this.ctx,
487→        onProgress,
488→      });
489→
490→      this.emitter.emit({ type: 'file:downloaded', cid });
491→
492→      return plaintext;
493→    });
494→  }
495→
496→  // ---- Operation wrapper ----
497→
498→  /**
499→   * Wrap an async operation with event emission and error handling.
500→   *
501→   * Emits 'operation:start' before, 'operation:end' on success (with duration),
502→   * and 'error' on failure. Also calls the config callbacks if provided.
503→   */
504→  private async withOperation<T>(name: string, fn: () => Promise<T>): Promise<T> {
505→    const start = Date.now();
506→    this.config.onOperationStart?.(name);
507→    this.emitter.emit({ type: 'operation:start', operation: name });
508→
509→    try {
510→      const result = await fn();
511→      const durationMs = Date.now() - start;
512→      this.config.onOperationEnd?.(name);
513→      this.emitter.emit({ type: 'operation:end', operation: name, durationMs });
514→      return result;
515→    } catch (error) {
516→      this.config.onError?.(error as Error);
517→      this.emitter.emit({ type: 'error', operation: name, error: error as Error });
518→      throw error;
519→    }
520→  }
521→}
