59→  setLastAuthMethod: (method) => set({ lastAuthMethod: method }),
60→  setUserEmail: (email) => set({ userEmail: email }),
61→  setTeeKeys: (keys) => set({ teeKeys: keys }),
62→
63→  /** Store vault keypair from Core Kit TSS export */
64→  setVaultKeypair: (keypair) => set({ vaultKeypair: keypair }),
65→
66→  /** Store pending auth info for REQUIRED_SHARE completion */
67→  setPendingAuth: (jwt, method) => set({ pendingCipherboxJwt: jwt, pendingAuthMethod: method }),
68→
69→  logout: () => {
70→    // [SECURITY: MEDIUM-02] Zero-fill sensitive key material before clearing
71→    const state = get();
72→    if (state.vaultKeypair) {
73→      if (state.vaultKeypair.privateKey) {
74→        state.vaultKeypair.privateKey.fill(0);
75→      }
76→      if (state.vaultKeypair.publicKey) {
77→        state.vaultKeypair.publicKey.fill(0);
78→      }
79→    }
80→
81→    set({
82→      accessToken: null,
83→      isAuthenticated: false,
84→      userEmail: null,
85→      teeKeys: null,
86→      vaultKeypair: null,
87→      pendingCipherboxJwt: null,
88→      pendingAuthMethod: null,
89→    });
90→  },
91→}));
