  1→import { useCallback, useEffect, useRef, useState } from 'react';
  2→import { useNavigate } from 'react-router-dom';
  3→import { useCoreKitAuth } from '../lib/web3auth/hooks';
  4→import { useCoreKit } from '../lib/web3auth/core-kit-provider';
  5→import { authApi } from '../lib/api/auth';
  6→import { vaultApi } from '../lib/api/vault';
  7→import { useAuthStore } from '../stores/auth.store';
  8→import { useVaultStore } from '../stores/vault.store';
  9→import { useDeviceRegistryStore } from '../stores/device-registry.store';
 10→import { clearAllUserStores } from '../lib/clear-user-stores';
 11→import {
 12→  initializeVault,
 13→  encryptVaultKeys,
 14→  decryptVaultKeys,
 15→  deriveIpnsName,
 16→  hexToBytes,
 17→  bytesToHex,
 18→} from '@cipherbox/crypto';
 19→import { getOrCreateDeviceIdentity } from '../lib/device/identity';
 20→import { detectDeviceInfo } from '../lib/device/info';
 21→import { initializeOrSyncRegistry } from '../services/device-registry.service';
 22→import { initializeBin } from '../services/bin.service';
 23→import { useBinStore } from '../stores/bin.store';
 24→import { vaultControllerGetConfig } from '../api/vault/vault';
 25→
 26→export function useAuth() {
 27→  const navigate = useNavigate();
 28→  const {
 29→    isLoggedIn: coreKitLoggedIn,
 30→    isInitialized: coreKitInitialized,
 31→    isRequiredShare,
 32→    loginWithGoogle: coreKitLoginGoogle,
 33→    loginWithEmailOtp: coreKitLoginEmail,
 34→    loginWithWallet: coreKitLoginWallet,
 35→    getVaultKeypair,
 36→    getPublicKeyHex,
 37→    logout: coreKitLogout,
 38→  } = useCoreKitAuth();
 39→  const { syncStatus } = useCoreKit();
 40→  const {
 41→    accessToken,
 42→    isAuthenticated,
 43→    lastAuthMethod,
 44→    userEmail,
 45→    setAccessToken,
 46→    setLastAuthMethod,
 47→    setUserEmail,
 48→    setVaultKeypair,
 49→  } = useAuthStore();
 50→
 51→  const [isLoggingIn, setIsLoggingIn] = useState(false);
 52→  const [isLoggingOut, setIsLoggingOut] = useState(false);
 53→  const restoringRef = useRef(false);
 54→
 55→  // Stable refs for functions used in the session restoration effect.
 56→  // This prevents the effect from re-firing when function references change.
 57→  const initializeOrLoadVaultRef = useRef<(() => Promise<void>) | null>(null);
 58→  const coreKitLogoutRef = useRef<(() => Promise<void>) | null>(null);
 59→
 60→  // Pending auth state for REQUIRED_SHARE flow.
 61→  // Stored in Zustand (not useState) so the state is shared across all
 62→  // useAuth() hook instances — Login.tsx sets it, useDeviceApproval reads it
 63→  // via its own useAuth() call.
 64→  const pendingAuthMethod = useAuthStore((s) => s.pendingAuthMethod);
 65→  const setPendingAuth = useAuthStore((s) => s.setPendingAuth);
 66→
 67→  const isLoading = !coreKitInitialized || isLoggingIn || isLoggingOut;
 68→
 69→  // Get vault store actions
 70→  const setVaultKeys = useVaultStore((state) => state.setVaultKeys);
 71→
 72→  /**
 73→   * Initialize vault for new users or load existing vault keys.
 74→   * Called after successful backend authentication.
 75→   * Uses Core Kit's getVaultKeypair() instead of PnP provider.
 76→   */
 77→  const initializeOrLoadVault = useCallback(async (): Promise<void> => {
 78→    // Get user's secp256k1 keypair from Core Kit TSS export
 79→    const userKeypair = await getVaultKeypair();
 80→
 81→    if (!userKeypair) {
 82→      throw new Error('Failed to get vault keypair from Core Kit');
 83→    }
 84→
 85→    // Store keypair in auth store for crypto operations
 86→    setVaultKeypair(userKeypair);
 87→
 88→    try {
 89→      // Try to fetch existing vault
 90→      const existingVault = await vaultApi.getVault();
 91→
 92→      // Store TEE keys if available
 93→      if (existingVault.teeKeys) {
 94→        useAuthStore.getState().setTeeKeys(existingVault.teeKeys);
 95→      }
 96→
 97→      // Vault exists - decrypt keys and load into store
 98→      // decryptVaultKeys derives the IPNS public key internally from the decrypted private key
 99→      const decryptedVault = await decryptVaultKeys(
100→        {
101→          encryptedRootFolderKey: hexToBytes(existingVault.encryptedRootFolderKey),
102→          encryptedIpnsPrivateKey: hexToBytes(existingVault.encryptedRootIpnsPrivateKey),
103→        },
104→        userKeypair.privateKey
105→      );
106→
107→      setVaultKeys({
108→        rootFolderKey: decryptedVault.rootFolderKey,
109→        rootIpnsKeypair: decryptedVault.rootIpnsKeypair,
110→        rootIpnsName: existingVault.rootIpnsName,
111→        vaultId: existingVault.id,
112→      });
113→    } catch (error) {
114→      const is404 = (error as { response?: { status?: number } })?.response?.status === 404;
115→
116→      if (is404) {
117→        // New user - initialize vault
118→        console.log(
119→          '[Auth] New user on Core Kit. If migrating from PnP, vault re-initialization may be needed.'
120→        );
121→        const newVault = await initializeVault(userKeypair.privateKey);
122→        const encryptedVault = await encryptVaultKeys(newVault, userKeypair.publicKey);
123→        const rootIpnsName = await deriveIpnsName(newVault.rootIpnsKeypair.publicKey);
124→
125→        const storedVault = await vaultApi.initVault({
126→          ownerPublicKey: bytesToHex(userKeypair.publicKey),
127→          encryptedRootFolderKey: bytesToHex(encryptedVault.encryptedRootFolderKey),
128→          encryptedRootIpnsPrivateKey: bytesToHex(encryptedVault.encryptedIpnsPrivateKey),
129→          rootIpnsName,
130→        });
131→
132→        if (storedVault.teeKeys) {
133→          useAuthStore.getState().setTeeKeys(storedVault.teeKeys);
134→        }
135→
136→        setVaultKeys({
137→          rootFolderKey: newVault.rootFolderKey,
138→          rootIpnsKeypair: newVault.rootIpnsKeypair,
139→          rootIpnsName,
140→          vaultId: storedVault.id,
141→          isNewVault: true,
142→        });
143→      } else {
144→        console.error('[useAuth] Failed to load vault:', error);
145→        throw error;
146→      }
147→    }
148→
149→    // Non-blocking device registry initialization (fire-and-forget)
150→    // Placed after vault load so registry failures never block login
151→    void (async () => {
152→      try {
153→        const deviceKeypair = await getOrCreateDeviceIdentity({
154→          mode: 'persisted',
155→          vaultPrivateKey: userKeypair.privateKey,
156→        });
157→        const deviceInfo = detectDeviceInfo();
158→        const result = await initializeOrSyncRegistry({
159→          userPrivateKey: userKeypair.privateKey,
160→          userPublicKey: userKeypair.publicKey,
161→          deviceKeypair,
162→          deviceInfo: { ...deviceInfo, ipHash: '' },
163→        });
164→        if (result) {
165→          useDeviceRegistryStore
166→            .getState()
167→            .setRegistry(result.registry, result.ipnsName, deviceKeypair.deviceId);
168→        }
169→      } catch (error) {
170→        console.error('[Auth] Device registry init failed (non-blocking):', error);
171→      }
172→    })();
173→
174→    // Non-blocking bin initialization (fire-and-forget)
175→    void (async () => {
176→      try {
177→        await initializeBin({
178→          userPrivateKey: userKeypair.privateKey,
179→          userPublicKey: userKeypair.publicKey,
180→        });
181→      } catch (error) {
182→        console.error('[Auth] Bin initialization failed (non-blocking):', error);
183→      }
184→    })();
185→
186→    // Non-blocking: fetch retention config from API
187→    void (async () => {
188→      try {
189→        const config = await vaultControllerGetConfig();
190→        if (config.recycleBinRetentionDays != null) {
191→          useBinStore.getState().setRetentionDays(config.recycleBinRetentionDays);
192→        }
193→      } catch (error) {
194→        console.error('[Auth] Failed to fetch vault config (non-blocking):', error);
195→      }
196→    })();
197→  }, [getVaultKeypair, setVaultKeypair, setVaultKeys]);
198→
199→  /**
200→   * Complete backend authentication after Core Kit login.
201→   * Sends the CipherBox-issued JWT (which we used for Core Kit loginWithJWT)
202→   * to the backend with loginType 'corekit'. The backend verifies it against
203→   * its own JWKS since CipherBox is the identity provider.
204→   */
205→  const completeBackendAuth = useCallback(
206→    async (authMethod: string, cipherboxJwt: string): Promise<void> => {
207→      // 1. Get real publicKey from Core Kit TSS export
208→      const publicKey = await getPublicKeyHex();
209→      if (!publicKey) {
210→        throw new Error('Failed to get publicKey from Core Kit');
211→      }
212→
213→      // publicKey available for debugging via DevTools if needed
214→
215→      // 2. Authenticate with CipherBox backend
216→      // Backend verifies our CipherBox JWT and resolves placeholder publicKey
217→      const response = await authApi.login({
218→        idToken: cipherboxJwt,
219→        publicKey,
220→        loginType: 'corekit',
221→      });
222→
223→      // 3. Store access token (refresh token in HTTP-only cookie)
224→      setAccessToken(response.accessToken);
225→
226→      // 4. Remember auth method for UX
227→      setLastAuthMethod(authMethod);
228→
229→      // 5. Initialize or load vault
230→      await initializeOrLoadVault();
231→    },
232→    [getPublicKeyHex, setAccessToken, setLastAuthMethod, initializeOrLoadVault]
233→  );
234→
235→  /**
236→   * Complete the login flow after REQUIRED_SHARE is resolved.
237→   * Called after inputFactorKey() succeeds (from recovery phrase or cross-device approval).
238→   * Uses the stored pendingCipherboxJwt to call completeBackendAuth with the REAL publicKey
239→   * (since Core Kit is now LOGGED_IN), then navigates to /files.
240→   */
241→  const completeRequiredShare = useCallback(async (): Promise<void> => {
242→    // Read directly from Zustand store to get fresh values — this callback
243→    // may be called from useDeviceApproval's useAuth() instance, so we
244→    // can't rely on closure-captured selector values.
245→    const { pendingCipherboxJwt: jwt, pendingAuthMethod: method } = useAuthStore.getState();
246→
247→    if (!jwt || !method) {
248→      throw new Error('No pending auth info for REQUIRED_SHARE completion');
249→    }
250→
251→    // Core Kit should now be LOGGED_IN after inputFactorKey()
252→    // Complete backend auth with the REAL publicKey (replaces the placeholder session)
253→    await completeBackendAuth(method, jwt);
254→
255→    // NOW sync Core Kit React state to LOGGED_IN.
256→    // We deliberately delayed this from inputFactorKey() to prevent the session
257→    // restoration effect from firing before backend auth completed.
258→    // At this point isAuthenticated is true (from completeBackendAuth -> setAccessToken),
259→    // so the session restore guard (coreKitLoggedIn && !isAuthenticated) won't trigger.
260→    syncStatus();
261→
262→    // Clear pending state
263→    setPendingAuth(null, null);
264→
265→    // Navigate to files
266→    navigate('/files');
267→  }, [completeBackendAuth, syncStatus, setPendingAuth, navigate]);
268→
269→  /**
270→   * Login with Google OAuth token.
271→   * Flow: Google idToken -> CipherBox backend -> CipherBox JWT ->
272→   * Core Kit loginWithJWT -> backend /auth/login (corekit type)
273→   */
274→  const loginWithGoogle = useCallback(
275→    async (googleIdToken: string): Promise<void> => {
276→      if (isLoggingIn) return;
277→      setIsLoggingIn(true);
278→      try {
279→        // 1. Core Kit login via CipherBox identity provider
280→        const {
281→          cipherboxJwt,
282→          email,
283→          userId,
284→          status: coreKitStatus,
285→        } = await coreKitLoginGoogle(googleIdToken);
286→
287→        if (coreKitStatus === 'required_share') {
288→          // MFA enabled but device factor missing.
289→          // Store pending auth info for later completion after factor input.
290→          setPendingAuth(cipherboxJwt, 'google');
291→
292→          // Obtain temporary backend access token so the new device can
293→          // call bulletin board API endpoints (device-approval/*).
294→          // Uses placeholder publicKey since Core Kit is in REQUIRED_SHARE
295→          // state and we can't export the TSS key yet.
296→          const tempLoginResponse = await authApi.login({
297→            idToken: cipherboxJwt,
298→            publicKey: `pending-core-kit-${userId}`,
299→            loginType: 'corekit',
300→          });
301→          setAccessToken(tempLoginResponse.accessToken);
302→
303→          if (email) {
304→            setUserEmail(email);
305→          }
306→
307→          // Do NOT call completeBackendAuth() or navigate('/files')
308→          // The component tree will see isRequiredShare === true and
309→          // render recovery/approval UI.
310→          return;
311→        }
312→
313→        // Normal path: Core Kit logged in, proceed as before
314→        // 2. Complete backend auth + vault init
315→        await completeBackendAuth('google', cipherboxJwt);
316→
317→        // 3. Store email for UI display (returned from identity endpoint)
318→        if (email) {
319→          setUserEmail(email);
320→        }
321→
322→        // Navigation handled by Login.tsx redirect effect (isAuthenticated → /files)
323→      } catch (error) {
324→        console.error('[useAuth] Google login failed:', error);
325→        throw error;
326→      } finally {
327→        setIsLoggingIn(false);
328→      }
329→    },
330→    [isLoggingIn, coreKitLoginGoogle, completeBackendAuth, setAccessToken, setUserEmail]
331→  );
332→
333→  /**
334→   * Login with Email OTP.
335→   * Flow: email+otp -> CipherBox backend -> CipherBox JWT ->
336→   * Core Kit loginWithJWT -> backend /auth/login (corekit type)
337→   */
338→  const loginWithEmail = useCallback(
339→    async (email: string, otp: string): Promise<void> => {
340→      if (isLoggingIn) return;
341→      setIsLoggingIn(true);
342→      try {
343→        // 1. Core Kit login via CipherBox identity provider
344→        const { cipherboxJwt, userId, status: coreKitStatus } = await coreKitLoginEmail(email, otp);
345→
346→        if (coreKitStatus === 'required_share') {
347→          setPendingAuth(cipherboxJwt, 'email');
348→
349→          const tempLoginResponse = await authApi.login({
350→            idToken: cipherboxJwt,
351→            publicKey: `pending-core-kit-${userId}`,
352→            loginType: 'corekit',
353→          });
354→          setAccessToken(tempLoginResponse.accessToken);
355→          setUserEmail(email);
356→          return;
357→        }
358→
359→        // Normal path
360→        await completeBackendAuth('email', cipherboxJwt);
361→        setUserEmail(email);
362→        // Navigation handled by Login.tsx redirect effect (isAuthenticated → /files)
363→      } catch (error) {
364→        console.error('[useAuth] Email login failed:', error);
365→        throw error;
366→      } finally {
367→        setIsLoggingIn(false);
368→      }
369→    },
370→    [isLoggingIn, coreKitLoginEmail, completeBackendAuth, setAccessToken, setUserEmail]
371→  );
372→
373→  /**
374→   * Login with Wallet (SIWE).
375→   * Flow: Wallet connects + signs SIWE message -> backend verifies ->
376→   * CipherBox JWT -> Core Kit loginWithJWT -> backend /auth/login (corekit type)
377→   */
378→  const loginWithWallet = useCallback(
379→    async (cipherboxJwt: string, userId: string): Promise<void> => {
380→      if (isLoggingIn) return;
381→      setIsLoggingIn(true);
382→      try {
383→        // 1. Core Kit login via CipherBox identity provider
384→        const { status: coreKitStatus } = await coreKitLoginWallet(cipherboxJwt, userId);
385→
386→        if (coreKitStatus === 'required_share') {
387→          setPendingAuth(cipherboxJwt, 'wallet');
388→
389→          const tempLoginResponse = await authApi.login({
390→            idToken: cipherboxJwt,
391→            publicKey: `pending-core-kit-${userId}`,
392→            loginType: 'corekit',
393→          });
394→          setAccessToken(tempLoginResponse.accessToken);
395→          return;
396→        }
397→
398→        // Normal path
399→        await completeBackendAuth('wallet', cipherboxJwt);
400→        // Navigation is handled by Login.tsx's redirect effect (isAuthenticated → /files).
401→        // completeBackendAuth sets the access token early, but initializeOrLoadVault()
402→        // inside it may still be pending. An explicit navigate here would fire AFTER
403→        // vault init completes — by which point the user may have navigated away from
404→        // the login page, causing a disruptive late redirect.
405→      } catch (error) {
406→        console.error('[useAuth] Wallet login failed:', error);
407→        throw error;
408→      } finally {
409→        setIsLoggingIn(false);
410→      }
411→    },
412→    [isLoggingIn, coreKitLoginWallet, completeBackendAuth, setAccessToken]
413→  );
414→
415→  /**
416→   * Legacy login() for backward compatibility with AuthButton.
417→   * With Core Kit, login requires specifying the auth method.
418→   * This will be replaced by the new Login UI in Plan 04.
419→   */
420→  const login = useCallback(async () => {
421→    // Plan 04 will build the new login UI with method selection.
422→    // For now, this is a no-op placeholder that AuthButton calls.
423→    console.warn(
424→      '[useAuth] login() called without method -- ' +
425→        'use loginWithGoogle() or loginWithEmail() instead. ' +
426→        'Plan 04 will provide the new Login UI.'
427→    );
428→  }, []);
429→
430→  // Complete logout: Backend -> Core Kit -> Clear state
431→  const logout = useCallback(async () => {
432→    if (isLoggingOut) return;
433→
434→    setIsLoggingOut(true);
435→    try {
436→      // 1. Call backend logout (clears cookie)
437→      if (accessToken) {
438→        try {
439→          await authApi.logout();
440→        } catch {
441→          // Ignore errors -- we'll clear state anyway
442→        }
443→      }
444→
445→      // 2. Logout Core Kit (clears session from localStorage)
446→      await coreKitLogout();
447→
448→      // 3. Clear all user-scoped stores (centralized helper)
449→      clearAllUserStores();
450→
451→      // 4. Navigate to login
452→      navigate('/');
453→    } catch (error) {
454→      console.error('[useAuth] Logout failed:', error);
455→      // Still clear state even if backend fails
456→      clearAllUserStores();
457→      navigate('/');
458→    } finally {
459→      setIsLoggingOut(false);
460→    }
461→  }, [accessToken, coreKitLogout, navigate, isLoggingOut]);
462→
463→  // Keep function refs up-to-date for use in session restoration effect.
464→  // Using refs prevents the effect from re-firing when function identities change.
465→  initializeOrLoadVaultRef.current = initializeOrLoadVault;
466→  coreKitLogoutRef.current = coreKitLogout;
467→
468→  // Session restoration: if Core Kit restores a session from localStorage
469→  // on init, we have LOGGED_IN status without going through login flow.
470→  // Complete backend auth + vault loading.
471→  useEffect(() => {
472→    const restoreSession = async () => {
473→      // Only restore if Core Kit has a session but we don't have
474→      // a backend access token yet
475→      if (coreKitLoggedIn && !isAuthenticated && !isLoggingIn && !restoringRef.current) {
476→        restoringRef.current = true;
477→        setIsLoggingIn(true);
478→        try {
479→          // Try to refresh using the HTTP-only cookie first
480→          const response = await authApi.refresh();
481→          setAccessToken(response.accessToken);
482→
483→          // Restore email from backend if available
484→          if (response.email) {
485→            setUserEmail(response.email);
486→          }
487→
488→          // Load vault keys from Core Kit keypair
489→          await initializeOrLoadVaultRef.current?.();
490→        } catch {
491→          // No valid backend session -- user needs to re-login
492→          // Core Kit session exists but backend cookie expired
493→          // Clear Core Kit session to avoid inconsistent state
494→          try {
495→            await coreKitLogoutRef.current?.();
496→          } catch {
497→            // Ignore logout errors during cleanup
498→          }
499→        } finally {
500→          restoringRef.current = false;
501→          setIsLoggingIn(false);
502→        }
503→      }
504→    };
505→    restoreSession();
506→  }, [coreKitLoggedIn, isAuthenticated, isLoggingIn, setAccessToken, setUserEmail]);
507→
508→  return {
509→    isLoading,
510→    isAuthenticated,
511→    isRequiredShare,
512→    lastAuthMethod,
513→    userEmail,
514→    pendingAuthMethod,
515→    login,
516→    loginWithGoogle,
517→    loginWithEmail,
518→    loginWithWallet,
519→    completeRequiredShare,
520→    logout,
521→  };
522→}
