  1→/**
  2→ * @cipherbox/sdk - CipherBoxClient
  3→ *
  4→ * Stateful client orchestrating folder CRUD, file upload/download,
  5→ * and event-driven change notification. Wraps @cipherbox/sdk-core
  6→ * stateless functions with internal state management (FolderTree, KeyCache).
  7→ *
  8→ * Design principles:
  9→ * - Zero React/Zustand/browser dependencies
 10→ * - All state flows through typed events (SdkEvent)
 11→ * - Operations are wrapped with withOperation() for consistent
 12→ *   start/end/error event emission
 13→ * - Key material is cleared on destroy()
 14→ */
 15→
 16→import type { SdkContext, ProgressCallback, DownloadProgressCallback } from '@cipherbox/sdk-core';
 17→import * as sdkCore from '@cipherbox/sdk-core';
 18→import type { FolderChild } from '@cipherbox/core';
 19→import type { CipherBoxClientConfig, FolderState } from './types';
 20→import { SdkEventEmitter, type SdkEvent, type SdkEventHandler } from './events';
 21→import { FolderTree } from './state/folder-tree';
 22→import { KeyCache } from './state/key-cache';
 23→import * as binOps from './bin';
 24→import type { BinState } from './bin';
 25→import * as shareOps from './share';
 26→import type { SentShareInfo } from './share';
 27→
 28→export class CipherBoxClient {
 29→  private config: CipherBoxClientConfig;
 30→  private ctx: SdkContext;
 31→  private emitter: SdkEventEmitter;
 32→  private folderTree: FolderTree;
 33→  private keyCache: KeyCache;
 34→  private binState: BinState | null = null;
 35→
 36→  constructor(config: CipherBoxClientConfig) {
 37→    this.config = config;
 38→    this.ctx = {
 39→      apiUrl: config.apiUrl,
 40→      getAccessToken: config.getAccessToken,
 41→    };
 42→    this.emitter = new SdkEventEmitter();
 43→    this.folderTree = new FolderTree();
 44→    this.keyCache = new KeyCache();
 45→  }
 46→
 47→  // ---- Event subscription ----
 48→
 49→  /** Subscribe to SDK events. Returns an unsubscribe function. */
 50→  on(handler: SdkEventHandler): () => void {
 51→    return this.emitter.on(handler);
 52→  }
 53→
 54→  /** Unsubscribe a previously registered handler. */
 55→  off(handler: SdkEventHandler): void {
 56→    this.emitter.off(handler);
 57→  }
 58→
 59→  // ---- Lifecycle ----
 60→
 61→  /**
 62→   * Destroy the client, clearing all sensitive state.
 63→   * After calling destroy(), the client instance should not be reused.
 64→   */
 65→  destroy(): void {
 66→    this.folderTree.clear();
 67→    this.keyCache.clear();
 68→    this.emitter.removeAll();
 69→  }
 70→
 71→  // ---- Internal state access (for bin/share modules) ----
 72→
