 93→  // ---- Folder operations ----
 94→
 95→  /**
 96→   * Load a folder's metadata from IPNS.
 97→   *
 98→   * Resolves the folder's IPNS record, decrypts metadata, stores state
 99→   * internally, and emits a 'folder:loaded' event.
100→   *
101→   * @param ipnsName - Folder's IPNS name
102→   * @param folderKey - Decrypted AES-256 folder key
103→   * @param ipnsKeypair - Ed25519 keypair for IPNS signing
104→   * @returns The loaded folder state, or null if IPNS record not found
105→   */
106→  async loadFolder(
107→    ipnsName: string,
108→    folderKey: Uint8Array,
109→    ipnsKeypair: { publicKey: Uint8Array; privateKey: Uint8Array }
110→  ): Promise<FolderState | null> {
111→    return this.withOperation('loadFolder', async () => {
112→      const result = await sdkCore.loadFolderMetadata({
113→        ipnsName,
114→        folderKey,
115→        ctx: this.ctx,
116→      });
117→
118→      if (!result) return null;
119→
120→      const state: FolderState = {
121→        ipnsName,
122→        folderKey,
123→        ipnsKeypair,
124→        sequenceNumber: result.sequenceNumber,
125→        children: result.metadata.children,
126→        metadata: result.metadata,
127→        lastLoadedAt: Date.now(),
128→      };
129→
130→      this.folderTree.set(ipnsName, state);
131→
132→      this.emitter.emit({
133→        type: 'folder:loaded',
134→        folderId: ipnsName,
135→        ipnsName,
136→        children: result.metadata.children,
137→      });
138→
139→      return state;
140→    });
141→  }
142→
143→  /**
144→   * Create a new subfolder inside an existing folder.
145→   *
146→   * Generates IPNS keypair and folder key, wraps with user's public key,
147→   * adds folder entry to parent metadata, publishes parent IPNS record,
148→   * and publishes empty folder metadata for the new subfolder.
149→   *
150→   * @param parentIpnsName - IPNS name of the parent folder
151→   * @param name - Name for the new subfolder
152→   * @returns Created folder's IPNS name and folder key
153→   */
154→  async createFolder(
155→    parentIpnsName: string,
156→    name: string
157→  ): Promise<{ ipnsName: string; folderKey: Uint8Array }> {
158→    return this.withOperation('createFolder', async () => {
159→      const parent = this.folderTree.get(parentIpnsName);
160→      if (!parent) throw new Error('Parent folder not loaded');
161→
162→      // 1. Create subfolder (generates keys, wraps with user public key)
163→      const { folder, ipnsPrivateKey, folderKey, encryptedIpnsPrivateKey, keyEpoch } =
164→        await sdkCore.createSubfolder({
165→          name,
166→          userPublicKey: this.config.vaultKeypair.publicKey,
167→          teeKeys: this.config.teeKeys,
168→        });
169→
170→      // 2. Add folder entry to parent's children
171→      const updatedChildren: FolderChild[] = [...parent.children, folder];
172→
173→      // 3. Update parent metadata and publish
174→      const { newSequenceNumber } = await sdkCore.updateFolderMetadataAndPublish({
175→        children: updatedChildren,
176→        folderKey: parent.folderKey,
177→        ipnsPrivateKey: parent.ipnsKeypair.privateKey,
178→        ipnsName: parentIpnsName,
179→        sequenceNumber: parent.sequenceNumber,
180→        ctx: this.ctx,
181→        encryptedIpnsPrivateKey: encryptedIpnsPrivateKey,
182→        keyEpoch,
183→      });
184→
185→      // 4. Update parent state
186→      parent.children = updatedChildren;
187→      parent.sequenceNumber = newSequenceNumber;
188→      parent.lastLoadedAt = Date.now();
189→      this.folderTree.set(parentIpnsName, parent);
190→
191→      // 5. Publish empty metadata for the new subfolder
192→      await sdkCore.updateFolderMetadataAndPublish({
193→        children: [],
194→        folderKey,
195→        ipnsPrivateKey,
196→        ipnsName: folder.ipnsName,
197→        sequenceNumber: 0n,
198→        ctx: this.ctx,
199→        encryptedIpnsPrivateKey,
200→        keyEpoch,
201→      });
202→
203→      // 7. Emit parent folder updated event
204→      this.emitter.emit({
205→        type: 'folder:updated',
206→        folderId: parentIpnsName,
207→        ipnsName: parentIpnsName,
208→        children: updatedChildren,
209→      });
210→
211→      return { ipnsName: folder.ipnsName, folderKey };
212→    });
213→  }
