215→  /**
216→   * Rename a child entry (folder or file) in a folder.
217→   *
218→   * Updates the name in the folder's metadata and publishes the change.
219→   *
220→   * @param folderIpnsName - IPNS name of the folder containing the item
221→   * @param childId - ID of the child to rename
222→   * @param newName - New name for the child
223→   */
224→  async renameItem(folderIpnsName: string, childId: string, newName: string): Promise<void> {
225→    return this.withOperation('renameItem', async () => {
226→      const folder = this.folderTree.get(folderIpnsName);
227→      if (!folder) throw new Error('Folder not loaded');
228→
229→      // 1. Rename in metadata (pure operation)
230→      const { updatedChildren } = sdkCore.renameInFolder({
231→        children: folder.children,
232→        childId,
233→        newName,
234→      });
235→
236→      // 2. Publish updated metadata
237→      const { newSequenceNumber } = await sdkCore.updateFolderMetadataAndPublish({
238→        children: updatedChildren,
239→        folderKey: folder.folderKey,
240→        ipnsPrivateKey: folder.ipnsKeypair.privateKey,
241→        ipnsName: folderIpnsName,
242→        sequenceNumber: folder.sequenceNumber,
243→        ctx: this.ctx,
244→      });
245→
246→      // 3. Update internal state
247→      folder.children = updatedChildren;
248→      folder.sequenceNumber = newSequenceNumber;
249→      folder.lastLoadedAt = Date.now();
250→      this.folderTree.set(folderIpnsName, folder);
251→
252→      // 4. Emit update event
253→      this.emitter.emit({
254→        type: 'folder:updated',
255→        folderId: folderIpnsName,
256→        ipnsName: folderIpnsName,
257→        children: updatedChildren,
258→      });
259→    });
260→  }
