262→  /**
263→   * Move a child entry between two folders.
264→   *
265→   * Removes from source, adds to destination, publishes both IPNS records
266→   * (destination first for crash safety -- add-before-remove pattern).
267→   *
268→   * @param sourceIpnsName - IPNS name of the source folder
269→   * @param destIpnsName - IPNS name of the destination folder
270→   * @param childId - ID of the child to move
271→   */
272→  async moveItem(sourceIpnsName: string, destIpnsName: string, childId: string): Promise<void> {
273→    return this.withOperation('moveItem', async () => {
274→      const source = this.folderTree.get(sourceIpnsName);
275→      const dest = this.folderTree.get(destIpnsName);
276→      if (!source) throw new Error('Source folder not loaded');
277→      if (!dest) throw new Error('Destination folder not loaded');
278→
279→      // 1. Compute updated children for both folders (pure operation)
280→      const { updatedSourceChildren, updatedDestChildren } = sdkCore.moveItem({
281→        sourceChildren: source.children,
282→        destChildren: dest.children,
283→        childId,
284→      });
285→
286→      // 2. Publish destination first (add-before-remove for crash safety)
287→      const destResult = await sdkCore.updateFolderMetadataAndPublish({
288→        children: updatedDestChildren,
289→        folderKey: dest.folderKey,
290→        ipnsPrivateKey: dest.ipnsKeypair.privateKey,
291→        ipnsName: destIpnsName,
292→        sequenceNumber: dest.sequenceNumber,
293→        ctx: this.ctx,
294→      });
295→
296→      // 3. Publish source (remove)
297→      const sourceResult = await sdkCore.updateFolderMetadataAndPublish({
298→        children: updatedSourceChildren,
299→        folderKey: source.folderKey,
300→        ipnsPrivateKey: source.ipnsKeypair.privateKey,
301→        ipnsName: sourceIpnsName,
302→        sequenceNumber: source.sequenceNumber,
303→        ctx: this.ctx,
304→      });
305→
306→      // 4. Update internal state
307→      source.children = updatedSourceChildren;
308→      source.sequenceNumber = sourceResult.newSequenceNumber;
309→      dest.children = updatedDestChildren;
310→      dest.sequenceNumber = destResult.newSequenceNumber;
311→      this.folderTree.set(sourceIpnsName, source);
312→      this.folderTree.set(destIpnsName, dest);
313→
314→      // 5. Emit events for both folders
315→      this.emitter.emit({
316→        type: 'folder:updated',
317→        folderId: sourceIpnsName,
318→        ipnsName: sourceIpnsName,
319→        children: updatedSourceChildren,
320→      });
321→      this.emitter.emit({
322→        type: 'folder:updated',
323→        folderId: destIpnsName,
324→        ipnsName: destIpnsName,
325→        children: updatedDestChildren,
326→      });
327→    });
328→  }
