363→      folder.sequenceNumber = newSequenceNumber;
364→      folder.lastLoadedAt = Date.now();
365→      this.folderTree.set(folderIpnsName, folder);
366→
367→      // 4. Emit update event
368→      this.emitter.emit({
369→        type: 'folder:updated',
370→        folderId: folderIpnsName,
