381→  /**
382→   * Upload a file to a folder.
383→   *
384→   * Encrypts the file, uploads to IPFS, creates per-file IPNS metadata,
385→   * adds a FilePointer to the parent folder's metadata, and publishes.
386→   *
387→   * @param folderIpnsName - IPNS name of the target folder
388→   * @param data - Raw file content as Uint8Array
389→   * @param fileName - Display name for the file
390→   * @param mimeType - MIME type of the file
391→   * @param onProgress - Optional upload progress callback
392→   * @returns CID of the uploaded encrypted file
393→   */
394→  async uploadFile(
395→    folderIpnsName: string,
396→    data: Uint8Array,
397→    fileName: string,
398→    mimeType: string,
399→    onProgress?: ProgressCallback
400→  ): Promise<{ cid: string }> {
401→    return this.withOperation('uploadFile', async () => {
402→      const folder = this.folderTree.get(folderIpnsName);
403→      if (!folder) throw new Error('Folder not loaded');
404→
405→      const fileId = crypto.randomUUID();
406→
407→      // 1. Encrypt and upload file, create file metadata
408→      const uploadResult = await sdkCore.uploadFile({
409→        data,
410→        fileId,
411→        mimeType,
412→        folderKey: folder.folderKey,
413→        userPublicKey: this.config.vaultKeypair.publicKey,
414→        ctx: this.ctx,
415→        onProgress,
416→        teeKeys: this.config.teeKeys,
417→      });
418→
419→      // 2. Add FilePointer to folder's children
420→      const { updatedChildren } = sdkCore.addFilePointerToFolder({
421→        children: folder.children,
422→        fileId,
423→        fileName,
424→        fileMetaIpnsName: uploadResult.fileMetaIpnsName,
425→        ipnsPrivateKeyEncrypted: uploadResult.ipnsPrivateKeyEncrypted,
426→      });
427→
428→      // 3. Batch publish: file metadata IPNS + folder metadata IPNS
429→      await sdkCore.batchPublishIpnsRecords([uploadResult.ipnsRecord]);
430→
431→      const { newSequenceNumber } = await sdkCore.updateFolderMetadataAndPublish({
432→        children: updatedChildren,
433→        folderKey: folder.folderKey,
434→        ipnsPrivateKey: folder.ipnsKeypair.privateKey,
435→        ipnsName: folderIpnsName,
436→        sequenceNumber: folder.sequenceNumber,
437→        ctx: this.ctx,
438→      });
439→
440→      // 4. Update internal state
441→      folder.children = updatedChildren;
442→      folder.sequenceNumber = newSequenceNumber;
443→      folder.lastLoadedAt = Date.now();
444→      this.folderTree.set(folderIpnsName, folder);
445→
446→      // 5. Emit events
447→      this.emitter.emit({
448→        type: 'file:uploaded',
449→        folderId: folderIpnsName,
450→        fileName,
451→        cid: uploadResult.cid,
452→      });
453→      this.emitter.emit({
454→        type: 'folder:updated',
455→        folderId: folderIpnsName,
456→        ipnsName: folderIpnsName,
457→        children: updatedChildren,
458→      });
459→
460→      return { cid: uploadResult.cid };
461→    });
462→  }
