464→  /**
465→   * Download and decrypt a file from IPFS.
466→   *
467→   * Fetches the encrypted file content, unwraps the file key using the
468→   * user's private key, and decrypts the content.
469→   *
470→   * @param cid - IPFS CID of the encrypted file content
471→   * @param fileKeyEncrypted - Hex-encoded ECIES-wrapped file key
472→   * @param fileIv - Hex-encoded IV used for encryption
473→   * @param encryptionMode - 'GCM' (default) or 'CTR'
474→   * @param onProgress - Optional download progress callback
475→   * @returns Decrypted file content
476→   */
477→  async downloadFile(
478→    cid: string,
479→    fileKeyEncrypted: string,
480→    fileIv: string,
481→    encryptionMode?: 'GCM' | 'CTR',
482→    onProgress?: DownloadProgressCallback
483→  ): Promise<Uint8Array> {
484→    return this.withOperation('downloadFile', async () => {
485→      const plaintext = await sdkCore.downloadAndDecrypt({
486→        cid,
487→        fileKeyEncrypted,
488→        fileIv,
489→        userPrivateKey: this.config.vaultKeypair.privateKey,
490→        encryptionMode,
491→        ctx: this.ctx,
492→        onProgress,
493→      });
494→
495→      this.emitter.emit({ type: 'file:downloaded', cid });
496→
497→      return plaintext;
498→    });
499→  }
