714→  // ---- Operation wrapper ----
715→
716→  /**
717→   * Wrap an async operation with event emission and error handling.
718→   *
719→   * Emits 'operation:start' before, 'operation:end' on success (with duration),
720→   * and 'error' on failure. Also calls the config callbacks if provided.
721→   */
722→  private async withOperation<T>(name: string, fn: () => Promise<T>): Promise<T> {
723→    const start = Date.now();
724→    this.config.onOperationStart?.(name);
725→    this.emitter.emit({ type: 'operation:start', operation: name });
726→
727→    try {
728→      const result = await fn();
729→      const durationMs = Date.now() - start;
730→      this.config.onOperationEnd?.(name);
731→      this.emitter.emit({ type: 'operation:end', operation: name, durationMs });
732→      return result;
733→    } catch (error) {
734→      this.config.onError?.(error as Error);
735→      this.emitter.emit({ type: 'error', operation: name, error: error as Error });
736→      throw error;
737→    }
738→  }
