 1→/**
 2→ * Centralized cleanup of all user-scoped Zustand stores.
 3→ *
 4→ * Called from:
 5→ * - useAuth logout (normal logout flow)
 6→ * - apiClient 401 interceptor (forced logout on token refresh failure)
 7→ *
 8→ * Order matters: clear stores holding crypto keys BEFORE clearing auth state,
 9→ * so sensitive key material is zeroed from memory first. [SECURITY: HIGH-02]
10→ */
11→import { useFolderStore } from '../stores/folder.store';
12→import { useVaultStore } from '../stores/vault.store';
13→import { useSyncStore } from '../stores/sync.store';
14→import { useDeviceRegistryStore } from '../stores/device-registry.store';
15→import { useBinStore } from '../stores/bin.store';
16→import { useShareStore } from '../stores/share.store';
17→import { useQuotaStore } from '../stores/quota.store';
18→import { useMfaStore } from '../stores/mfa.store';
19→import { useNotificationStore } from '../stores/notification.store';
20→import { useAuthStore } from '../stores/auth.store';
21→import { clearFileSizeCache } from '../hooks/useFileSize';
22→
23→export function clearAllUserStores(): void {
24→  // 1. Clear stores with crypto key material first
25→  useFolderStore.getState().clearFolders();
26→  useVaultStore.getState().clearVaultKeys();
27→
28→  // 2. Clear remaining user-scoped stores
29→  useSyncStore.getState().reset();
30→  useDeviceRegistryStore.getState().clearRegistry();
31→  useBinStore.getState().clearBin();
32→  useShareStore.getState().clearShares();
33→  useQuotaStore.getState().reset();
34→  useMfaStore.getState().reset();
35→  useNotificationStore.getState().clearNotifications();
36→  clearFileSizeCache();
37→
38→  // 3. Clear auth state last (zeros keypair memory, sets isAuthenticated=false)
39→  useAuthStore.getState().logout();
40→}
