  1→import { useState, useCallback } from 'react';
  2→import { useFolderStore } from '../stores/folder.store';
  3→import { useVaultStore } from '../stores/vault.store';
  4→import { useAuthStore } from '../stores/auth.store';
  5→import * as folderService from '../services/folder.service';
  6→import { reWrapForRecipients } from '../services/share.service';
  7→import { addManyToBin } from '../services/bin.service';
  8→import type { FolderNode } from '../stores/folder.store';
  9→import type { FolderEntry, FolderChild } from '@cipherbox/crypto';
 10→import {
 11→  MAX_FOLDER_DEPTH,
 12→  getRootFolderState,
 13→  resyncFolder,
 14→  withConflictRetry,
 15→} from './folder-helpers';
 16→import type { FolderOperationState } from './folder-helpers';
 17→import { useNotificationStore } from '../stores/notification.store';
