 40→/**
 41→ * React hook for folder CRUD operations (create, rename, move, delete).
 42→ *
 43→ * Returns loading/error state and operation callbacks.
 44→ */
 45→export function useFolderMutations() {
 46→  const [state, setState] = useState<FolderOperationState>({
 47→    isLoading: false,
 48→    error: null,
 49→  });
 50→
 51→  /**
 52→   * Create a new folder.
 53→   *
 54→   * @param name - Folder name
 55→   * @param parentId - Parent folder ID (null for root, or folder UUID)
 56→   * @returns Created folder entry
 57→   * @throws Error if depth limit exceeded or creation fails
 58→   */
 59→  const handleCreate = useCallback(
 60→    async (name: string, parentId: string | null): Promise<FolderEntry> => {
 61→      setState({ isLoading: true, error: null });
 62→      try {
 63→        const folders = useFolderStore.getState().folders;
 64→        const vault = useVaultStore.getState();
 65→        const auth = useAuthStore.getState();
 66→
 67→        // Validate depth limit before creating (FOLD-03)
 68→        const parentDepth = folderService.getDepth(parentId, folders);
 69→        if (parentDepth >= MAX_FOLDER_DEPTH) {
 70→          throw new Error(`Cannot create folder: maximum depth of ${MAX_FOLDER_DEPTH} exceeded`);
 71→        }
 72→
 73→        // Get user's ECIES keypair for vault cryptographic operations (public + private keys stored in memory after login)
 74→        // The public key is used here for key wrapping; the private key remains client-side for decryption operations.
 75→        if (!auth.vaultKeypair) {
 76→          throw new Error('No ECIES keypair available - please log in again');
 77→        }
 78→        const userPublicKey = auth.vaultKeypair.publicKey;
 79→
 80→        // Create the folder (generates keys, wraps with user public key, TEE-encrypts IPNS key)
 81→        const { folder, ipnsPrivateKey, folderKey, encryptedIpnsPrivateKey, keyEpoch } =
 82→          await folderService.createFolder({
 83→            parentFolderId: parentId,
 84→            name,
 85→            userPublicKey,
 86→            folders,
 87→          });
 88→
 89→        // Get parent folder state
 90→        const parentFolder =
 91→          parentId && folders[parentId] ? folders[parentId] : getRootFolderState(vault, folders);
 92→
 93→        if (!parentFolder) {
 94→          throw new Error('Parent folder not found or vault not initialized');
 95→        }
 96→
 97→        // Update parent folder metadata and publish IPNS (with conflict retry)
 98→        const performParentUpdate = async () => {
 99→          const freshState = useFolderStore.getState();
100→          const freshParent =
101→            parentId && freshState.folders[parentId]
102→              ? freshState.folders[parentId]
103→              : getRootFolderState(useVaultStore.getState(), freshState.folders);
104→          if (!freshParent) throw new Error('Parent folder not found');
105→          const freshChildren = [...freshParent.children, folder];
106→          const { newSequenceNumber } = await folderService.updateFolderMetadata({
107→            folderId: freshParent.id,
108→            children: freshChildren,
109→            folderKey: freshParent.folderKey,
110→            ipnsPrivateKey: freshParent.ipnsPrivateKey,
111→            ipnsName: freshParent.ipnsName,
112→            sequenceNumber: freshParent.sequenceNumber,
113→          });
114→          return { children: freshChildren, newSequenceNumber };
115→        };
116→
117→        const parentResult = await withConflictRetry(performParentUpdate, () =>
118→          resyncFolder(parentFolder.ipnsName, parentFolder.id)
119→        );
120→
121→        // First publish for the new folder's own IPNS record with TEE-encrypted key
122→        // This sends encryptedIpnsPrivateKey to backend for TEE republish enrollment
123→        const { newSequenceNumber: newFolderSequence } = await folderService.updateFolderMetadata({
124→          folderId: folder.id,
125→          children: [],
126→          folderKey,
127→          ipnsPrivateKey,
128→          ipnsName: folder.ipnsName,
129→          sequenceNumber: 0n,
130→          encryptedIpnsPrivateKey,
131→          keyEpoch,
132→        });
133→
134→        // Update local state - add new folder to tree and persist sequence
135→        useFolderStore.getState().updateFolderChildren(parentFolder.id, parentResult.children);
136→        useFolderStore
137→          .getState()
138→          .updateFolderSequence(parentFolder.id, parentResult.newSequenceNumber);
139→
140→        // Also add the new folder node to the store (with its decrypted keys)
141→        const newFolderNode: FolderNode = {
142→          id: folder.id,
143→          name: folder.name,
144→          ipnsName: folder.ipnsName,
145→          parentId: parentFolder.id,
146→          children: [],
147→          isLoaded: true,
148→          isLoading: false,
149→          sequenceNumber: newFolderSequence,
150→          folderKey,
151→          ipnsPrivateKey,
152→        };
153→        useFolderStore.getState().setFolder(newFolderNode);
154→
155→        // Post-create: re-wrap new subfolder key for share recipients (fire-and-forget)
156→        reWrapForRecipients({
157→          folderIpnsName: parentFolder.ipnsName,
158→          folders: useFolderStore.getState().folders,
159→          currentFolderId: parentFolder.id,
160→          newItems: [{ keyType: 'folder', itemId: folder.id, plaintextKey: folderKey }],
161→        })
162→          .then(({ failedRecipients }) => {
163→            if (failedRecipients.length > 0) {
164→              useNotificationStore
165→                .getState()
166→                .addNotification(
167→                  'warning',
168→                  `Failed to update share keys for ${failedRecipients.length} recipient(s). They may not be able to access the new folder until you re-share.`
169→                );
170→            }
171→          })
172→          .catch((err) => {
173→            console.warn('[share] Post-create subfolder re-wrapping failed:', err);
174→          });
175→
176→        setState({ isLoading: false, error: null });
177→        return folder;
178→      } catch (err) {
179→        const error = err instanceof Error ? err.message : 'Failed to create folder';
180→        setState({ isLoading: false, error });
181→        throw err;
182→      }
183→    },
184→    []
185→  );
186→
187→  /**
188→   * Rename a file or folder.
189→   *
190→   * @param itemId - ID of item to rename
191→   * @param itemType - 'file' or 'folder'
192→   * @param newName - New name
193→   * @param parentId - Parent folder ID
194→   */
195→  const handleRename = useCallback(
196→    async (
197→      itemId: string,
198→      itemType: 'file' | 'folder',
199→      newName: string,
200→      parentId: string
201→    ): Promise<void> => {
202→      setState({ isLoading: true, error: null });
203→      try {
204→        const getParentFolder = () => {
205→          const freshState = useFolderStore.getState();
206→          return parentId === 'root'
207→            ? getRootFolderState(useVaultStore.getState(), freshState.folders)
208→            : freshState.folders[parentId];
209→        };
210→
211→        const parentFolder = getParentFolder();
212→        if (!parentFolder) throw new Error('Parent folder not found');
213→
214→        const performRename = async (): Promise<{ newSequenceNumber: bigint }> => {
215→          const freshParent = getParentFolder();
216→          if (!freshParent) throw new Error('Parent folder not found');
217→          if (itemType === 'folder') {
218→            return await folderService.renameFolder({
219→              folderId: itemId,
220→              newName,
221→              parentFolderState: freshParent,
222→            });
223→          } else {
224→            return await folderService.renameFile({
225→              fileId: itemId,
226→              newName,
227→              parentFolderState: freshParent,
228→            });
229→          }
230→        };
231→
232→        const renameResult = await withConflictRetry(performRename, () =>
233→          resyncFolder(parentFolder.ipnsName, parentFolder.id)
234→        );
235→
236→        if (itemType === 'folder') {
237→          // Update local folder state name
238→          useFolderStore.getState().updateFolderName(itemId, newName);
239→        }
240→
241→        // Update parent's children with new name using fresh state
242→        const freshParent = getParentFolder();
243→        if (freshParent) {
244→          const updatedChildren = freshParent.children.map((child) => {
245→            if (child.id === itemId) {
246→              return { ...child, name: newName, modifiedAt: Date.now() };
247→            }
248→            return child;
249→          });
250→          useFolderStore.getState().updateFolderChildren(parentId, updatedChildren);
251→        }
252→
253→        // Persist the new sequence number so subsequent operations use the correct value
254→        useFolderStore.getState().updateFolderSequence(parentId, renameResult.newSequenceNumber);
255→
256→        setState({ isLoading: false, error: null });
257→      } catch (err) {
258→        const error = err instanceof Error ? err.message : 'Failed to rename';
259→        setState({ isLoading: false, error });
260→        throw err;
261→      }
262→    },
263→    []
264→  );
265→
266→  /**
267→   * Move a file or folder to a different parent.
268→   *
269→   * @param itemId - ID of item to move
270→   * @param itemType - 'file' or 'folder'
271→   * @param sourceParentId - Current parent folder ID
272→   * @param destParentId - Destination parent folder ID
273→   */
274→  const handleMove = useCallback(
275→    async (
276→      itemId: string,
277→      itemType: 'file' | 'folder',
278→      sourceParentId: string,
279→      destParentId: string
280→    ): Promise<void> => {
281→      setState({ isLoading: true, error: null });
282→      try {
283→        const getSourceFolder = () => {
284→          const freshState = useFolderStore.getState();
285→          return sourceParentId === 'root'
286→            ? getRootFolderState(useVaultStore.getState(), freshState.folders)
287→            : freshState.folders[sourceParentId];
288→        };
289→
290→        const getDestFolder = () => {
291→          const freshState = useFolderStore.getState();
292→          return destParentId === 'root'
293→            ? getRootFolderState(useVaultStore.getState(), freshState.folders)
294→            : freshState.folders[destParentId];
295→        };
296→
297→        const sourceFolder = getSourceFolder();
298→        const destFolder = getDestFolder();
299→        if (!sourceFolder || !destFolder) {
300→          throw new Error('Source or destination folder not found');
301→        }
302→
303→        const performMove = async (): Promise<{
304→          destSequenceNumber: bigint;
305→          sourceSequenceNumber: bigint;
306→        }> => {
307→          const freshSource = getSourceFolder();
308→          const freshDest = getDestFolder();
309→          if (!freshSource || !freshDest) throw new Error('Source or destination folder not found');
310→          const folders = useFolderStore.getState().folders;
311→          if (itemType === 'folder') {
312→            return await folderService.moveFolder({
313→              folderId: itemId,
314→              sourceFolderState: freshSource,
315→              destFolderState: freshDest,
316→              folders,
317→            });
318→          } else {
319→            return await folderService.moveFile({
320→              fileId: itemId,
321→              sourceFolderState: freshSource,
322→              destFolderState: freshDest,
323→            });
324→          }
325→        };
326→
327→        const moveResult = await withConflictRetry(performMove, async () => {
328→          await Promise.all([
329→            resyncFolder(sourceFolder.ipnsName, sourceFolder.id),
330→            sourceFolder.id !== destFolder.id
331→              ? resyncFolder(destFolder.ipnsName, destFolder.id)
332→              : Promise.resolve(),
333→          ]);
334→        });
335→
336→        // Save the moved item BEFORE updating source children (otherwise it's already gone)
337→        const freshSourceBeforeUpdate = getSourceFolder();
338→        const movedItem = freshSourceBeforeUpdate?.children.find((c) => c.id === itemId);
339→
340→        if (itemType === 'folder') {
341→          // Update the moved folder's parentId in local state
342→          const freshFolders = useFolderStore.getState().folders;
343→          const movedFolder = freshFolders[itemId];
344→          if (movedFolder) {
345→            useFolderStore.getState().setFolder({
346→              ...movedFolder,
347→              parentId: destParentId,
348→            });
349→          }
350→        }
351→
352→        // Update source folder's children (remove item)
353→        if (freshSourceBeforeUpdate) {
354→          const updatedSourceChildren = freshSourceBeforeUpdate.children.filter(
355→            (c) => c.id !== itemId
356→          );
357→          useFolderStore.getState().updateFolderChildren(sourceParentId, updatedSourceChildren);
358→        }
359→
360→        // Update dest folder's children (add item)
361→        const freshDest = getDestFolder();
362→        if (movedItem && freshDest) {
363→          const updatedDestChildren = [
364→            ...freshDest.children,
365→            { ...movedItem, modifiedAt: Date.now() },
366→          ];
367→          useFolderStore.getState().updateFolderChildren(destParentId, updatedDestChildren);
368→        }
369→
370→        // Persist the new sequence numbers so subsequent operations use the correct values
371→        useFolderStore.getState().updateFolderSequence(destParentId, moveResult.destSequenceNumber);
372→        useFolderStore
373→          .getState()
374→          .updateFolderSequence(sourceParentId, moveResult.sourceSequenceNumber);
375→
376→        setState({ isLoading: false, error: null });
377→      } catch (err) {
378→        const error = err instanceof Error ? err.message : 'Failed to move';
379→        setState({ isLoading: false, error });
380→        throw err;
381→      }
382→    },
383→    []
384→  );
385→
386→  /**
387→   * Move multiple files/folders to a destination in a single batch.
388→   *
389→   * Uses add-before-remove pattern. Publishes IPNS once for the destination
390→   * and once for the source (2 total), regardless of how many items are moved.
391→   *
392→   * @param items - Array of { id, type } to move
393→   * @param sourceParentId - Current parent folder ID (all items must share the same parent)
394→   * @param destParentId - Destination parent folder ID
395→   */
396→  const handleMoveItems = useCallback(
397→    async (
398→      items: Array<{ id: string; type: 'file' | 'folder' }>,
399→      sourceParentId: string,
400→      destParentId: string
401→    ): Promise<void> => {
402→      setState({ isLoading: true, error: null });
403→      try {
404→        const getSourceFolder = () => {
405→          const freshState = useFolderStore.getState();
406→          return sourceParentId === 'root'
407→            ? getRootFolderState(useVaultStore.getState(), freshState.folders)
408→            : freshState.folders[sourceParentId];
409→        };
410→        const getDestFolder = () => {
411→          const freshState = useFolderStore.getState();
412→          return destParentId === 'root'
413→            ? getRootFolderState(useVaultStore.getState(), freshState.folders)
414→            : freshState.folders[destParentId];
415→        };
416→
417→        const sourceFolder = getSourceFolder();
418→        const destFolder = getDestFolder();
419→
420→        if (!sourceFolder || !destFolder) {
421→          throw new Error('Source or destination folder not found');
422→        }
423→
424→        const itemIds = new Set(items.map((i) => i.id));
425→        const now = Date.now();
426→
427→        // Validate batch move preconditions against current folder state.
428→        // Must be called before each attempt (initial + retry after resync)
429→        // because concurrent changes may introduce name collisions or depth violations.
430→        const validateBatchMove = () => {
431→          const currentSource = getSourceFolder();
432→          const currentDest = getDestFolder();
433→          if (!currentSource || !currentDest) {
434→            throw new Error('Source or destination folder not found');
435→          }
436→
437→          const currentMovedChildren = currentSource.children.filter((c) => itemIds.has(c.id));
438→          if (currentMovedChildren.length !== itemIds.size) {
439→            throw new Error(
440→              'One or more selected items no longer exist. Please refresh and retry.'
441→            );
442→          }
443→          const batchNames = new Set<string>();
444→          for (const child of currentMovedChildren) {
445→            // Intra-batch duplicate name check
446→            if (batchNames.has(child.name)) {
447→              throw new Error(`Multiple selected items share the name "${child.name}"`);
448→            }
449→            batchNames.add(child.name);
450→
451→            // Name collision check against destination
452→            const nameExists = currentDest.children.some((c) => c.name === child.name);
453→            if (nameExists) {
454→              throw new Error(`An item named "${child.name}" already exists in the destination`);
455→            }
456→
457→            if (child.type === 'folder') {
458→              // Prevent moving folder into itself or descendant
459→              const folders = useFolderStore.getState().folders;
460→              if (folderService.isDescendantOf(currentDest.id, child.id, folders)) {
461→                throw new Error(`Cannot move "${child.name}" into itself or its subfolder`);
462→              }
463→
464→              // Depth limit check
465→              const destDepth = folderService.getDepth(currentDest.id, folders);
466→              const subtreeDepth = folderService.calculateSubtreeDepth(child.id, folders);
467→              if (destDepth + 1 + subtreeDepth > MAX_FOLDER_DEPTH) {
468→                throw new Error(
469→                  `Cannot move "${child.name}": would exceed maximum folder depth of ${MAX_FOLDER_DEPTH}`
470→                );
471→              }
472→            }
473→          }
474→        };
475→
476→        validateBatchMove();
477→
478→        const performBatchMove = async (): Promise<{
479→          destSeq: bigint;
480→          sourceSeq: bigint;
481→          destChildren: FolderNode['children'];
482→          sourceChildren: FolderNode['children'];
483→        }> => {
484→          const freshSource = getSourceFolder();
485→          const freshDest = getDestFolder();
486→          if (!freshSource || !freshDest) throw new Error('Source or destination folder not found');
487→
488→          // Rebuild moved children from fresh source state
489→          const freshMoved = freshSource.children.filter((c) => itemIds.has(c.id));
490→          if (freshMoved.length !== itemIds.size) {
491→            throw new Error(
492→              'One or more selected items no longer exist. Please refresh and retry.'
493→            );
494→          }
495→
496→          // ADD all to destination FIRST (add-before-remove pattern)
497→          const destChildren = [
498→            ...freshDest.children,
499→            ...freshMoved.map((c) => ({ ...c, modifiedAt: now })),
500→          ];
501→
502→          const { newSequenceNumber: destSeq } = await folderService.updateFolderMetadata({
503→            folderId: freshDest.id,
504→            children: destChildren,
505→            folderKey: freshDest.folderKey,
506→            ipnsPrivateKey: freshDest.ipnsPrivateKey,
507→            ipnsName: freshDest.ipnsName,
508→            sequenceNumber: freshDest.sequenceNumber,
509→          });
510→
511→          // REMOVE all from source AFTER destination confirmed
512→          const sourceChildren = freshSource.children.filter((c) => !itemIds.has(c.id));
513→
514→          const { newSequenceNumber: sourceSeq } = await folderService.updateFolderMetadata({
515→            folderId: freshSource.id,
516→            children: sourceChildren,
517→            folderKey: freshSource.folderKey,
518→            ipnsPrivateKey: freshSource.ipnsPrivateKey,
519→            ipnsName: freshSource.ipnsName,
520→            // Re-read sequence in case source === dest parent was updated above
521→            sequenceNumber: freshSource.id === freshDest.id ? destSeq : freshSource.sequenceNumber,
522→          });
523→
524→          return { destSeq, sourceSeq, destChildren, sourceChildren };
525→        };
526→
527→        const result = await withConflictRetry(
528→          performBatchMove,
529→          async () => {
530→            await Promise.all([
531→              resyncFolder(sourceFolder.ipnsName, sourceFolder.id),
532→              sourceFolder.id !== destFolder.id
533→                ? resyncFolder(destFolder.ipnsName, destFolder.id)
534→                : Promise.resolve(),
535→            ]);
536→          },
537→          validateBatchMove
538→        );
539→
540→        // Update local state
541→        const store = useFolderStore.getState();
542→        store.updateFolderChildren(sourceParentId, result.sourceChildren);
543→        store.updateFolderChildren(destParentId, result.destChildren);
544→        store.updateFolderSequence(destParentId, result.destSeq);
545→        store.updateFolderSequence(sourceParentId, result.sourceSeq);
546→
547→        for (const item of items) {
548→          if (item.type === 'folder') {
549→            const movedFolder = useFolderStore.getState().folders[item.id];
550→            if (movedFolder) {
551→              store.setFolder({ ...movedFolder, parentId: destParentId });
552→            }
553→          }
554→        }
555→
556→        setState({ isLoading: false, error: null });
557→      } catch (err) {
558→        const error = err instanceof Error ? err.message : 'Failed to move items';
559→        setState({ isLoading: false, error });
560→        throw err;
561→      }
562→    },
563→    []
564→  );
565→
566→  /**
567→   * Delete a file or folder.
568→   *
569→   * @param itemId - ID of item to delete
570→   * @param itemType - 'file' or 'folder'
571→   * @param parentId - Parent folder ID
572→   */
573→  const handleDelete = useCallback(
574→    async (itemId: string, itemType: 'file' | 'folder', parentId: string): Promise<void> => {
575→      setState({ isLoading: true, error: null });
576→      try {
577→        const getParentFolder = () => {
578→          const freshState = useFolderStore.getState();
579→          return parentId === 'root'
580→            ? getRootFolderState(useVaultStore.getState(), freshState.folders)
581→            : freshState.folders[parentId];
582→        };
583→
584→        const parentFolder = getParentFolder();
585→        if (!parentFolder) throw new Error('Parent folder not found');
586→
587→        const performDelete = async (): Promise<{
588→          newSequenceNumber: bigint;
589→          removedChild: FolderChild;
590→        }> => {
591→          const freshParent = getParentFolder();
592→          if (!freshParent) throw new Error('Parent folder not found');
593→          if (itemType === 'folder') {
594→            const folders = useFolderStore.getState().folders;
595→            const { newSequenceNumber, removedChild } = await folderService.deleteFolder({
596→              folderId: itemId,
597→              parentFolderState: freshParent,
598→              getFolderState: (id) => folders[id],
599→            });
600→            return { newSequenceNumber, removedChild };
601→          } else {
602→            const { newSequenceNumber, removedChild } = await folderService.deleteFileFromFolder({
603→              fileId: itemId,
604→              parentFolderState: freshParent,
605→            });
606→            return { newSequenceNumber, removedChild };
607→          }
608→        };
609→
610→        const deleteResult = await withConflictRetry(performDelete, () =>
611→          resyncFolder(parentFolder.ipnsName, parentFolder.id)
612→        );
613→
614→        if (itemType === 'folder') {
615→          // Remove folder and all loaded descendants from local state
616→          const store = useFolderStore.getState();
617→          const removeRecursive = (folderId: string) => {
618→            const node = store.folders[folderId];
619→            if (node) {
620→              for (const child of node.children) {
621→                if (child.type === 'folder') removeRecursive(child.id);
622→              }
623→            }
624→            store.removeFolder(folderId);
625→          };
626→          removeRecursive(itemId);
627→        }
628→
629→        // Update parent's children (remove item) using fresh state
630→        const freshParent = getParentFolder();
631→        if (freshParent) {
632→          const updatedChildren = freshParent.children.filter((c) => c.id !== itemId);
633→          useFolderStore.getState().updateFolderChildren(parentId, updatedChildren);
634→        }
635→
636→        // Persist the new sequence number so subsequent operations use the correct value
637→        useFolderStore.getState().updateFolderSequence(parentId, deleteResult.newSequenceNumber);
638→
639→        // Fire-and-forget: add deleted item to recycle bin (CIDs stay pinned for recovery)
640→        const auth = useAuthStore.getState();
641→        if (auth.vaultKeypair) {
642→          void addManyToBin({
643→            items: [deleteResult.removedChild],
644→            parentIpnsName: parentFolder.ipnsName,
645→            parentPath: buildFolderPath(parentId),
646→            userPublicKey: auth.vaultKeypair.publicKey,
647→            userPrivateKey: auth.vaultKeypair.privateKey,
648→            folderKey: parentFolder.folderKey,
649→          }).catch(() => {
650→            console.error('[Delete] Failed to add to bin (non-blocking)');
651→          });
652→        }
653→
654→        setState({ isLoading: false, error: null });
655→      } catch (err) {
656→        const error = err instanceof Error ? err.message : 'Failed to delete';
657→        setState({ isLoading: false, error });
658→        throw err;
659→      }
660→    },
661→    []
662→  );
663→
664→  /**
665→   * Delete multiple files/folders in a single IPNS publish.
666→   *
667→   * Removes all items from parent's children array, collects CIDs to unpin,
668→   * then publishes metadata and IPNS once for the entire batch.
669→   *
670→   * @param items - Array of { id, type } to delete
671→   * @param parentId - Parent folder ID (all items must share the same parent)
672→   */
673→  const handleDeleteItems = useCallback(
674→    async (
675→      items: Array<{ id: string; type: 'file' | 'folder' }>,
676→      parentId: string
677→    ): Promise<void> => {
678→      setState({ isLoading: true, error: null });
679→      try {
680→        const getParentFolder = () => {
681→          const freshState = useFolderStore.getState();
682→          return parentId === 'root'
683→            ? getRootFolderState(useVaultStore.getState(), freshState.folders)
684→            : freshState.folders[parentId];
685→        };
686→
687→        const parentFolder = getParentFolder();
688→        if (!parentFolder) throw new Error('Parent folder not found');
689→
690→        const itemIds = new Set(items.map((i) => i.id));
691→
692→        // Collect nested folder IDs to remove from store
693→        // In v2, file children are FilePointers (no inline CID). File IPNS/TEE
694→        // enrollments will expire naturally (24h IPNS lifetime). Phase 14 adds cleanup.
695→        const folderIdsToRemove: string[] = [];
696→
697→        const collectFolderIds = (folderId: string) => {
698→          folderIdsToRemove.push(folderId);
699→          const folders = useFolderStore.getState().folders;
700→          const folder = folders[folderId];
701→          if (!folder) return;
702→          for (const child of folder.children) {
703→            if (child.type === 'folder') {
704→              collectFolderIds(child.id);
705→            }
706→          }
707→        };
708→
709→        for (const item of items) {
710→          if (item.type === 'folder') {
711→            collectFolderIds(item.id);
712→          }
713→        }
714→
715→        // Snapshot the items to be removed before batch delete
716→        // (needed for addToBin after successful deletion)
717→        let removedChildren: FolderChild[] = [];
718→
719→        const performBatchDelete = async (): Promise<{
720→          updatedChildren: typeof parentFolder.children;
721→          newSequenceNumber: bigint;
722→        }> => {
723→          const freshParent = getParentFolder();
724→          if (!freshParent) throw new Error('Parent folder not found');
725→
726→          // Capture removed children before filtering
727→          removedChildren = freshParent.children.filter((c) => itemIds.has(c.id));
728→
729→          // Remove all items from parent's children in one pass
730→          const updatedChildren = freshParent.children.filter((c) => !itemIds.has(c.id));
731→
732→          // Single IPNS publish for the entire batch
733→          const { newSequenceNumber } = await folderService.updateFolderMetadata({
734→            folderId: freshParent.id,
735→            children: updatedChildren,
736→            folderKey: freshParent.folderKey,
737→            ipnsPrivateKey: freshParent.ipnsPrivateKey,
738→            ipnsName: freshParent.ipnsName,
739→            sequenceNumber: freshParent.sequenceNumber,
740→          });
741→
742→          return { updatedChildren, newSequenceNumber };
743→        };
744→
745→        const { updatedChildren, newSequenceNumber } = await withConflictRetry(
746→          performBatchDelete,
747→          () => resyncFolder(parentFolder.ipnsName, parentFolder.id)
748→        );
749→
750→        // Update local state -- remove all nested folders from store
751→        const store = useFolderStore.getState();
752→        store.updateFolderChildren(parentId, updatedChildren);
753→        store.updateFolderSequence(parentId, newSequenceNumber);
754→        for (const folderId of folderIdsToRemove) {
755→          store.removeFolder(folderId);
756→        }
757→
758→        // Fire-and-forget: add all deleted items to recycle bin (single IPNS publish)
759→        const auth = useAuthStore.getState();
760→        if (auth.vaultKeypair && removedChildren.length > 0) {
761→          const parentPath = buildFolderPath(parentId);
762→          void addManyToBin({
763→            items: removedChildren,
764→            parentIpnsName: parentFolder.ipnsName,
765→            parentPath,
766→            userPublicKey: auth.vaultKeypair.publicKey,
767→            userPrivateKey: auth.vaultKeypair.privateKey,
768→            folderKey: parentFolder.folderKey,
769→          }).catch(() => {
770→            console.error('[Delete] Failed to add batch to bin (non-blocking)');
771→          });
772→        }
773→
774→        setState({ isLoading: false, error: null });
775→      } catch (err) {
776→        const error = err instanceof Error ? err.message : 'Failed to delete items';
777→        setState({ isLoading: false, error });
778→        throw err;
779→      }
780→    },
781→    []
782→  );
783→
784→  return {
785→    ...state,
786→    createFolder: handleCreate,
787→    renameItem: handleRename,
788→    moveItem: handleMove,
789→    moveItems: handleMoveItems,
790→    deleteItem: handleDelete,
791→    deleteItems: handleDeleteItems,
792→  };
793→}
