  1→import { useCallback } from 'react';
  2→import {
  3→  downloadAndSaveFile,
  4→  downloadFileFromIpns,
  5→  triggerBrowserDownload,
  6→  FileMetadata,
  7→} from '../services/download.service';
  8→import { useDownloadStore } from '../stores/download.store';
  9→import { useAuthStore } from '../stores/auth.store';
 10→
 11→export function useFileDownload() {
 12→  const {
 13→    status,
 14→    progress,
 15→    loadedBytes,
 16→    totalBytes,
 17→    currentFile,
 18→    error,
 19→    startDownload,
 20→    setProgress,
 21→    setDecrypting,
 22→    setSuccess,
 23→    setError,
 24→    reset,
 25→  } = useDownloadStore();
 26→
 27→  const { vaultKeypair } = useAuthStore();
 28→
 29→  const download = useCallback(
 30→    async (metadata: FileMetadata): Promise<void> => {
 31→      if (!vaultKeypair) {
 32→        throw new Error('No keypair available - please log in again');
 33→      }
 34→
 35→      try {
 36→        startDownload(metadata.originalName);
 37→
 38→        // Download with progress tracking
 39→        await downloadAndSaveFile(metadata, vaultKeypair.privateKey, (loaded, total) => {
 40→          setProgress(loaded, total);
 41→        });
 42→
 43→        setDecrypting();
 44→
 45→        // Small delay for UX - show decrypting state
 46→        await new Promise((resolve) => setTimeout(resolve, 100));
 47→
 48→        setSuccess();
 49→      } catch (err) {
 50→        const message = (err as Error).message || 'Download failed';
 51→        setError(message);
 52→        console.error('Download failed:', err);
 53→        throw err;
 54→      }
 55→    },
 56→    [vaultKeypair, startDownload, setProgress, setDecrypting, setSuccess, setError]
 57→  );
 58→
 59→  /**
 60→   * Download a file using per-file IPNS metadata (v2 flow).
 61→   *
 62→   * Resolves file IPNS, decrypts metadata with folderKey, fetches+decrypts content,
 63→   * and triggers browser download dialog.
 64→   */
 65→  const downloadFromIpns = useCallback(
 66→    async (params: {
 67→      fileMetaIpnsName: string;
 68→      folderKey: Uint8Array;
 69→      fileName: string;
 70→    }): Promise<void> => {
 71→      const auth = useAuthStore.getState();
 72→      if (!auth.vaultKeypair) {
 73→        throw new Error('No keypair available - please log in again');
 74→      }
 75→
 76→      try {
 77→        startDownload(params.fileName);
 78→
 79→        const plaintext = await downloadFileFromIpns({
 80→          fileMetaIpnsName: params.fileMetaIpnsName,
 81→          folderKey: params.folderKey,
 82→          privateKey: auth.vaultKeypair.privateKey,
 83→          fileName: params.fileName,
 84→        });
 85→
 86→        setDecrypting();
 87→        await new Promise((resolve) => setTimeout(resolve, 100));
 88→
 89→        triggerBrowserDownload(plaintext, params.fileName);
 90→        setSuccess();
 91→      } catch (err) {
 92→        const message = (err as Error).message || 'Download failed';
 93→        setError(message);
 94→        console.error('Download failed:', err);
 95→        throw err;
 96→      }
 97→    },
 98→    [startDownload, setDecrypting, setSuccess, setError]
 99→  );
100→
101→  return {
102→    // State
103→    status,
104→    progress,
105→    loadedBytes,
106→    totalBytes,
107→    currentFile,
108→    error,
109→    isDownloading: status === 'downloading' || status === 'decrypting',
110→
111→    // Actions
112→    download,
113→    downloadFromIpns,
114→    reset,
115→  };
116→}
