  1→import { useState, useCallback } from 'react';
  2→import { useBinStore } from '../stores/bin.store';
  3→import { useAuthStore } from '../stores/auth.store';
  4→import {
  5→  initializeBin,
  6→  restoreFromBin,
  7→  restoreFromBinBatch,
  8→  permanentlyDelete,
  9→  permanentlyDeleteBatch,
 10→  emptyBin,
 11→  purgeExpired,
 12→} from '../services/bin.service';
 13→import type { BinEntry } from '@cipherbox/crypto';
 14→
 15→/**
 16→ * React hook for recycle bin operations.
 17→ *
 18→ * Wraps bin service functions with loading/error state management.
 19→ * Provides single-item and batch operations for restore and permanent delete.
 20→ */
 21→export function useBin() {
 22→  const [state, setState] = useState<{ isLoading: boolean; error: string | null }>({
 23→    isLoading: false,
 24→    error: null,
 25→  });
 26→
 27→  const entries = useBinStore((s) => s.entries);
 28→  const isLoaded = useBinStore((s) => s.isLoaded);
 29→  const retentionDays = useBinStore((s) => s.retentionDays);
 30→
 31→  /**
 32→   * Load bin metadata from IPNS and trigger auto-purge of expired entries.
 33→   */
 34→  const loadBin = useCallback(async () => {
 35→    const auth = useAuthStore.getState();
