 99→    } catch (err) {
100→      const error = err instanceof Error ? err.message : 'Failed to permanently delete';
101→      setState({ isLoading: false, error });
102→      throw err;
103→    }
104→  }, []);
105→
106→  /**
107→   * Empty all bin entries permanently.
108→   */
109→  const emptyAll = useCallback(async () => {
110→    const auth = useAuthStore.getState();
111→    if (!auth.vaultKeypair) throw new Error('Not authenticated');
112→
113→    setState({ isLoading: true, error: null });
114→    try {
115→      await emptyBin({
