127→  /**
128→   * Restore multiple bin entries.
129→   */
130→  const restoreMultiple = useCallback(async (entryIds: string[]) => {
131→    const auth = useAuthStore.getState();
132→    if (!auth.vaultKeypair) throw new Error('Not authenticated');
133→
134→    setState({ isLoading: true, error: null });
135→    try {
136→      await restoreFromBinBatch({
137→        entryIds,
138→        userPublicKey: auth.vaultKeypair.publicKey,
139→        userPrivateKey: auth.vaultKeypair.privateKey,
140→      });
141→      setState({ isLoading: false, error: null });
142→    } catch (err) {
143→      const error = err instanceof Error ? err.message : 'Failed to restore items';
144→      setState({ isLoading: false, error });
145→      throw err;
146→    }
147→  }, []);
148→
149→  /**
150→   * Permanently delete multiple bin entries (single IPNS publish).
151→   */
152→  const permanentDeleteMultiple = useCallback(async (entryIds: string[]) => {
153→    const auth = useAuthStore.getState();
154→    if (!auth.vaultKeypair) throw new Error('Not authenticated');
155→
156→    setState({ isLoading: true, error: null });
157→    try {
158→      await permanentlyDeleteBatch({
159→        entryIds,
160→        userPublicKey: auth.vaultKeypair.publicKey,
161→        userPrivateKey: auth.vaultKeypair.privateKey,
162→      });
163→      setState({ isLoading: false, error: null });
164→    } catch (err) {
165→      const error = err instanceof Error ? err.message : 'Failed to permanently delete items';
166→      setState({ isLoading: false, error });
167→      throw err;
168→    }
169→  }, []);
170→
171→  /**
172→   * Calculate days remaining before a bin entry is auto-purged.
173→   */
174→  const daysRemaining = useCallback(
175→    (entry: BinEntry): number => {
176→      const elapsed = Date.now() - entry.deletedAt;
177→      const retentionMs = retentionDays * 24 * 60 * 60 * 1000;
178→      return Math.max(0, Math.ceil((retentionMs - elapsed) / (24 * 60 * 60 * 1000)));
179→    },
180→    [retentionDays]
181→  );
182→
183→  return {
