  clearFolders: () => {
    const state = get();

    // Unsubscribe from SDK events before clearing
    if (state._sdkUnsubscribe) {
      state._sdkUnsubscribe();
    }

    // Best-effort memory clearing - overwrite all folder keys with zeros
