 2→ * SDK Provider - CipherBoxClient lifecycle management
 3→ *
 4→ * Manages a singleton CipherBoxClient instance for the web app.
 5→ * Created after vault load (login complete), destroyed on logout.
 6→ *
 7→ * The SDK client is the single source of truth for all file operations.
 8→ * Hooks call client methods, and stores subscribe to client events.
 9→ */
10→import { CipherBoxClient, type CipherBoxClientConfig } from '@cipherbox/sdk';
11→
12→let _client: CipherBoxClient | null = null;
13→
14→/**
15→ * Initialize the SDK client. Called after vault is loaded (login complete).
16→ * The client persists for the session and is destroyed on logout.
17→ *
18→ * If a client already exists (e.g., session restoration), it is destroyed
19→ * before creating the new one.
20→ */
21→export function initSdkClient(config: CipherBoxClientConfig): CipherBoxClient {
22→  if (_client) {
23→    _client.destroy();
24→  }
25→  _client = new CipherBoxClient(config);
26→  return _client;
27→}
28→
29→/**
30→ * Get the current SDK client instance.
31→ * Throws if called before initSdkClient() (i.e., before login).
32→ */
33→export function getSdkClient(): CipherBoxClient {
34→  if (!_client) {
35→    throw new Error('SDK client not initialized. Call initSdkClient() after login.');
36→  }
37→  return _client;
38→}
39→
40→/**
41→ * Check if the SDK client is initialized (for conditional usage).
42→ */
43→export function hasSdkClient(): boolean {
44→  return _client !== null;
45→}
46→
47→/**
48→ * Destroy the SDK client. Called on logout.
49→ * Clears internal state, key caches, and event subscriptions.
50→ */
51→export function destroySdkClient(): void {
52→  if (_client) {
53→    _client.destroy();
54→    _client = null;
