import { useCallback } from 'react';
import {
  downloadFileFromIpns,
  triggerBrowserDownload,
  FileMetadata,
} from '../services/download.service';
import { useDownloadStore } from '../stores/download.store';
import { useAuthStore } from '../stores/auth.store';
import { getSdkClient, hasSdkClient } from '../lib/sdk-provider';

export function useFileDownload() {
  const {
    status,
    progress,
    loadedBytes,
    totalBytes,
    currentFile,
    error,
    startDownload,
    setProgress,
    setDecrypting,
    setSuccess,
    setError,
    reset,
  } = useDownloadStore();

  const { vaultKeypair } = useAuthStore();

  /**
   * Download a file using SDK client (v1: CID + encrypted key + IV).
   *
   * The SDK handles fetching, key unwrapping, and decryption.
   * Browser download dialog is triggered after decryption completes.
   */
  const download = useCallback(
    async (metadata: FileMetadata): Promise<void> => {
      if (!vaultKeypair) {
        throw new Error('No keypair available - please log in again');
      }

      try {
        startDownload(metadata.originalName);

        let decryptedBytes: Uint8Array;

        if (hasSdkClient()) {
          // Use SDK for download + decrypt
          const client = getSdkClient();
          decryptedBytes = await client.downloadFile(
            metadata.cid,
            metadata.wrappedKey,
            metadata.iv,
            metadata.encryptionMode,
            (loaded, total) => {
              setProgress(loaded, total);
            }
          );
        } else {
          // Fallback to direct service call (SDK not initialized)
          const { downloadFile } = await import('../services/download.service');
          decryptedBytes = await downloadFile(metadata, vaultKeypair.privateKey, (loaded, total) => {
            setProgress(loaded, total);
          });
        }

        setDecrypting();

        // Small delay for UX - show decrypting state
        await new Promise((resolve) => setTimeout(resolve, 100));

        // Browser-specific: trigger download dialog (stays in hook, NOT in SDK)
        triggerBrowserDownload(decryptedBytes, metadata.originalName);

        setSuccess();
      } catch (err) {
        const message = (err as Error).message || 'Download failed';
        setError(message);
        console.error('Download failed:', err);
        throw err;
      }
    },
    [vaultKeypair, startDownload, setProgress, setDecrypting, setSuccess, setError]
  );

  /**
   * Download a file using per-file IPNS metadata (v2 flow).
   *
   * Resolves file IPNS, decrypts metadata with folderKey, fetches+decrypts content,
   * and triggers browser download dialog.
   */
  const downloadFromIpns = useCallback(
    async (params: {
      fileMetaIpnsName: string;
      folderKey: Uint8Array;
      fileName: string;
    }): Promise<void> => {
      const auth = useAuthStore.getState();
      if (!auth.vaultKeypair) {
        throw new Error('No keypair available - please log in again');
      }

      try {
        startDownload(params.fileName);

        const plaintext = await downloadFileFromIpns({
          fileMetaIpnsName: params.fileMetaIpnsName,
          folderKey: params.folderKey,
          privateKey: auth.vaultKeypair.privateKey,
          fileName: params.fileName,
        });

        setDecrypting();
        await new Promise((resolve) => setTimeout(resolve, 100));

        triggerBrowserDownload(plaintext, params.fileName);
        setSuccess();
      } catch (err) {
        const message = (err as Error).message || 'Download failed';
        setError(message);
        console.error('Download failed:', err);
        throw err;
      }
    },
    [startDownload, setDecrypting, setSuccess, setError]
  );

  return {
    // State
    status,
    progress,
    loadedBytes,
    totalBytes,
    currentFile,
    error,
    isDownloading: status === 'downloading' || status === 'decrypting',

    // Actions
    download,
    downloadFromIpns,
    reset,
  };
}

import { useCallback, useState } from 'react';
import { deleteFile, deleteFiles } from '../services/delete.service';
// Note: delete.service.ts handles IPFS unpin + quota update.
// SDK's permanentDelete handles bin-level deletion (different concern).
// Both services are needed: delete.service for CID cleanup, SDK for bin operations.

export function useFileDelete() {
  const [isDeleting, setIsDeleting] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const deleteSingle = useCallback(async (cid: string, sizeBytes: number): Promise<void> => {
    setIsDeleting(true);
    setError(null);

    try {
      await deleteFile(cid, sizeBytes);
    } catch (err) {
      const message = (err as Error).message || 'Delete failed';
      setError(message);
      throw err;
    } finally {
      setIsDeleting(false);
    }
  }, []);

  const deleteMultiple = useCallback(
    async (
      files: Array<{ cid: string; size: number }>
    ): Promise<{ succeeded: string[]; failed: string[] }> => {
      setIsDeleting(true);
      setError(null);

      try {
        const result = await deleteFiles(files);
        if (result.failed.length > 0) {
          setError(`Failed to delete ${result.failed.length} file(s)`);
        }
        return result;
      } finally {
        setIsDeleting(false);
      }
    },
    []
  );

  return {
    isDeleting,
    error,
    deleteFile: deleteSingle,
    deleteFiles: deleteMultiple,
    clearError: () => setError(null),
  };
}

import { useCallback } from 'react';
import { uploadFiles, UploadedFile } from '../services/upload.service';
import { useUploadStore } from '../stores/upload.store';
import { useQuotaStore } from '../stores/quota.store';
import { useAuthStore } from '../stores/auth.store';
// Note: Upload uses upload.service.ts which has its own encryption, progress tracking,
// cancellation, and retry logic tightly coupled to useUploadStore. The SDK's uploadFile()
// combines encryption + upload + metadata in one call, which is a different flow.
// Full migration to SDK upload will happen when useFileOperations.addFile() is also migrated.

/**
 * React hook for file upload with encryption, progress tracking, and quota management.
 *
 * Currently uses upload.service.ts for the upload flow. The SDK client is used
 * for post-upload operations (adding files to folders) via useFileOperations.
 */
export function useFileUpload() {
  const { status, progress, currentFile, totalFiles, completedFiles, error, cancel, reset } =
    useUploadStore();

  const { usedBytes, limitBytes, remainingBytes, canUpload, fetchQuota } = useQuotaStore();
  const { vaultKeypair } = useAuthStore();

  const upload = useCallback(
    async (files: File[]): Promise<UploadedFile[]> => {
      if (!vaultKeypair) {
        throw new Error('No keypair available - please log in again');
      }

      // Refresh quota before upload
      await fetchQuota();

      return uploadFiles(files, vaultKeypair.publicKey);
    },
    [vaultKeypair, fetchQuota]
  );

  return {
    // State
    status,
    progress,
    currentFile,
    totalFiles,
    completedFiles,
    error,
    isUploading: status === 'encrypting' || status === 'uploading' || status === 'registering',

    // Quota
    usedBytes,
    limitBytes,
    remainingBytes,
    canUpload,

    // Actions
    upload,
    cancel,
    reset,
  };
}

