  1→/**
  2→ * @cipherbox/sdk - CipherBoxClient
  3→ *
  4→ * Stateful client orchestrating folder CRUD, file upload/download,
  5→ * and event-driven change notification. Wraps @cipherbox/sdk-core
  6→ * stateless functions with internal state management (FolderTree, KeyCache).
  7→ *
  8→ * Design principles:
  9→ * - Zero React/Zustand/browser dependencies
 10→ * - All state flows through typed events (SdkEvent)
 11→ * - Operations are wrapped with withOperation() for consistent
 12→ *   start/end/error event emission
 13→ * - Key material is cleared on destroy()
 14→ */
 15→
 16→import type { SdkContext, ProgressCallback, DownloadProgressCallback } from '@cipherbox/sdk-core';
 17→import * as sdkCore from '@cipherbox/sdk-core';
 18→import type { FolderChild } from '@cipherbox/core';
 19→import type { CipherBoxClientConfig, FolderState } from './types';
 20→import { SdkEventEmitter, type SdkEvent, type SdkEventHandler } from './events';
 21→import { FolderTree } from './state/folder-tree';
 22→import { KeyCache } from './state/key-cache';
 23→import * as binOps from './bin';
 24→import type { BinState } from './bin';
 25→import * as shareOps from './share';
 26→import type { SentShareInfo } from './share';
 27→
 28→export class CipherBoxClient {
 29→  private config: CipherBoxClientConfig;
 30→  private ctx: SdkContext;
 31→  private emitter: SdkEventEmitter;
 32→  private folderTree: FolderTree;
 33→  private keyCache: KeyCache;
 34→  private binState: BinState | null = null;
 35→
 36→  constructor(config: CipherBoxClientConfig) {
 37→    this.config = config;
 38→    this.ctx = {
 39→      apiUrl: config.apiUrl,
 40→      getAccessToken: config.getAccessToken,
 41→    };
 42→    this.emitter = new SdkEventEmitter();
 43→    this.folderTree = new FolderTree();
 44→    this.keyCache = new KeyCache();
 45→  }
 46→
 47→  // ---- Event subscription ----
 48→
 49→  /** Subscribe to SDK events. Returns an unsubscribe function. */
 50→  on(handler: SdkEventHandler): () => void {
 51→    return this.emitter.on(handler);
 52→  }
 53→
 54→  /** Unsubscribe a previously registered handler. */
 55→  off(handler: SdkEventHandler): void {
 56→    this.emitter.off(handler);
 57→  }
 58→
 59→  // ---- Lifecycle ----
 60→
 61→  /**
 62→   * Destroy the client, clearing all sensitive state.
 63→   * After calling destroy(), the client instance should not be reused.
 64→   */
 65→  destroy(): void {
 66→    this.folderTree.clear();
 67→    this.keyCache.clear();
 68→    this.emitter.removeAll();
 69→  }
 70→
 71→  /**
 72→   * Register an externally-loaded folder into the SDK's internal state.
 73→   *
 74→   * Used when folder metadata is loaded outside the SDK (e.g., by a navigation
 75→   * hook) but the SDK needs to know about the folder for mutation operations
 76→   * (create, rename, move, delete, upload).
 77→   *
 78→   * This is a bridge method for gradual SDK adoption -- eventually all folder
 79→   * loading should go through client.loadFolder().
 80→   *
 81→   * @param ipnsName - Folder's IPNS name
 82→   * @param folderKey - Decrypted AES-256 folder key
 83→   * @param ipnsKeypair - Ed25519 keypair for IPNS signing
 84→   * @param children - Current folder children
 85→   * @param sequenceNumber - Current IPNS sequence number
 86→   */
 87→  registerFolder(
 88→    ipnsName: string,
 89→    folderKey: Uint8Array,
 90→    ipnsKeypair: { publicKey: Uint8Array; privateKey: Uint8Array },
 91→    children: FolderChild[],
 92→    sequenceNumber: bigint
 93→  ): void {
 94→    this.folderTree.set(ipnsName, {
 95→      ipnsName,
 96→      folderKey,
 97→      ipnsKeypair,
 98→      sequenceNumber,
 99→      children,
100→      metadata: null,
101→      lastLoadedAt: Date.now(),
102→    });
103→  }
104→
105→  // ---- Internal state access (for bin/share modules) ----
106→
107→  /** @internal Get the folder tree for bin/share operations */
108→  getFolderTree(): FolderTree {
109→    return this.folderTree;
110→  }
111→
112→  /** @internal Get the SDK context */
113→  getContext(): SdkContext {
114→    return this.ctx;
115→  }
116→
117→  /** @internal Get the client config */
118→  getConfig(): CipherBoxClientConfig {
119→    return this.config;
120→  }
121→
122→  /** @internal Emit an event (used by bin/share modules) */
123→  emitEvent(event: SdkEvent): void {
124→    this.emitter.emit(event);
125→  }
126→
127→  // ---- Folder operations ----
128→
129→  /**
130→   * Load a folder's metadata from IPNS.
131→   *
132→   * Resolves the folder's IPNS record, decrypts metadata, stores state
133→   * internally, and emits a 'folder:loaded' event.
134→   *
135→   * @param ipnsName - Folder's IPNS name
136→   * @param folderKey - Decrypted AES-256 folder key
137→   * @param ipnsKeypair - Ed25519 keypair for IPNS signing
138→   * @returns The loaded folder state, or null if IPNS record not found
139→   */
140→  async loadFolder(
141→    ipnsName: string,
142→    folderKey: Uint8Array,
143→    ipnsKeypair: { publicKey: Uint8Array; privateKey: Uint8Array }
144→  ): Promise<FolderState | null> {
145→    return this.withOperation('loadFolder', async () => {
146→      const result = await sdkCore.loadFolderMetadata({
147→        ipnsName,
148→        folderKey,
149→        ctx: this.ctx,
150→      });
151→
152→      if (!result) return null;
153→
154→      const state: FolderState = {
155→        ipnsName,
156→        folderKey,
157→        ipnsKeypair,
158→        sequenceNumber: result.sequenceNumber,
159→        children: result.metadata.children,
160→        metadata: result.metadata,
161→        lastLoadedAt: Date.now(),
162→      };
163→
164→      this.folderTree.set(ipnsName, state);
165→
166→      this.emitter.emit({
167→        type: 'folder:loaded',
168→        folderId: ipnsName,
169→        ipnsName,
170→        children: result.metadata.children,
171→      });
172→
173→      return state;
174→    });
175→  }
176→
177→  /**
178→   * Create a new subfolder inside an existing folder.
179→   *
180→   * Generates IPNS keypair and folder key, wraps with user's public key,
181→   * adds folder entry to parent metadata, publishes parent IPNS record,
182→   * and publishes empty folder metadata for the new subfolder.
183→   *
184→   * @param parentIpnsName - IPNS name of the parent folder
185→   * @param name - Name for the new subfolder
186→   * @returns Created folder's IPNS name and folder key
187→   */
188→  async createFolder(
189→    parentIpnsName: string,
190→    name: string
191→  ): Promise<{ ipnsName: string; folderKey: Uint8Array }> {
192→    return this.withOperation('createFolder', async () => {
193→      const parent = this.folderTree.get(parentIpnsName);
194→      if (!parent) throw new Error('Parent folder not loaded');
195→
196→      // 1. Create subfolder (generates keys, wraps with user public key)
197→      const { folder, ipnsPrivateKey, folderKey, encryptedIpnsPrivateKey, keyEpoch } =
198→        await sdkCore.createSubfolder({
199→          name,
200→          userPublicKey: this.config.vaultKeypair.publicKey,
201→          teeKeys: this.config.teeKeys,
202→        });
203→
204→      // 2. Add folder entry to parent's children
205→      const updatedChildren: FolderChild[] = [...parent.children, folder];
206→
207→      // 3. Update parent metadata and publish
208→      const { newSequenceNumber } = await sdkCore.updateFolderMetadataAndPublish({
209→        children: updatedChildren,
210→        folderKey: parent.folderKey,
211→        ipnsPrivateKey: parent.ipnsKeypair.privateKey,
212→        ipnsName: parentIpnsName,
213→        sequenceNumber: parent.sequenceNumber,
214→        ctx: this.ctx,
215→        encryptedIpnsPrivateKey: encryptedIpnsPrivateKey,
216→        keyEpoch,
217→      });
218→
219→      // 4. Update parent state
220→      parent.children = updatedChildren;
221→      parent.sequenceNumber = newSequenceNumber;
222→      parent.lastLoadedAt = Date.now();
223→      this.folderTree.set(parentIpnsName, parent);
224→
225→      // 5. Publish empty metadata for the new subfolder
226→      await sdkCore.updateFolderMetadataAndPublish({
227→        children: [],
228→        folderKey,
229→        ipnsPrivateKey,
230→        ipnsName: folder.ipnsName,
231→        sequenceNumber: 0n,
232→        ctx: this.ctx,
233→        encryptedIpnsPrivateKey,
234→        keyEpoch,
235→      });
236→
237→      // 7. Emit parent folder updated event
238→      this.emitter.emit({
239→        type: 'folder:updated',
240→        folderId: parentIpnsName,
241→        ipnsName: parentIpnsName,
242→        children: updatedChildren,
243→      });
244→
245→      return { ipnsName: folder.ipnsName, folderKey };
246→    });
247→  }
248→
249→  /**
250→   * Rename a child entry (folder or file) in a folder.
251→   *
252→   * Updates the name in the folder's metadata and publishes the change.
253→   *
254→   * @param folderIpnsName - IPNS name of the folder containing the item
255→   * @param childId - ID of the child to rename
256→   * @param newName - New name for the child
257→   */
258→  async renameItem(folderIpnsName: string, childId: string, newName: string): Promise<void> {
259→    return this.withOperation('renameItem', async () => {
260→      const folder = this.folderTree.get(folderIpnsName);
261→      if (!folder) throw new Error('Folder not loaded');
262→
263→      // 1. Rename in metadata (pure operation)
264→      const { updatedChildren } = sdkCore.renameInFolder({
265→        children: folder.children,
266→        childId,
267→        newName,
268→      });
269→
270→      // 2. Publish updated metadata
271→      const { newSequenceNumber } = await sdkCore.updateFolderMetadataAndPublish({
272→        children: updatedChildren,
273→        folderKey: folder.folderKey,
274→        ipnsPrivateKey: folder.ipnsKeypair.privateKey,
275→        ipnsName: folderIpnsName,
276→        sequenceNumber: folder.sequenceNumber,
277→        ctx: this.ctx,
278→      });
279→
280→      // 3. Update internal state
281→      folder.children = updatedChildren;
282→      folder.sequenceNumber = newSequenceNumber;
283→      folder.lastLoadedAt = Date.now();
284→      this.folderTree.set(folderIpnsName, folder);
285→
286→      // 4. Emit update event
287→      this.emitter.emit({
288→        type: 'folder:updated',
289→        folderId: folderIpnsName,
290→        ipnsName: folderIpnsName,
291→        children: updatedChildren,
292→      });
293→    });
294→  }
295→
296→  /**
297→   * Move a child entry between two folders.
298→   *
299→   * Removes from source, adds to destination, publishes both IPNS records
300→   * (destination first for crash safety -- add-before-remove pattern).
301→   *
302→   * @param sourceIpnsName - IPNS name of the source folder
303→   * @param destIpnsName - IPNS name of the destination folder
304→   * @param childId - ID of the child to move
305→   */
306→  async moveItem(sourceIpnsName: string, destIpnsName: string, childId: string): Promise<void> {
307→    return this.withOperation('moveItem', async () => {
308→      const source = this.folderTree.get(sourceIpnsName);
309→      const dest = this.folderTree.get(destIpnsName);
310→      if (!source) throw new Error('Source folder not loaded');
311→      if (!dest) throw new Error('Destination folder not loaded');
312→
313→      // 1. Compute updated children for both folders (pure operation)
314→      const { updatedSourceChildren, updatedDestChildren } = sdkCore.moveItem({
315→        sourceChildren: source.children,
316→        destChildren: dest.children,
317→        childId,
318→      });
319→
320→      // 2. Publish destination first (add-before-remove for crash safety)
321→      const destResult = await sdkCore.updateFolderMetadataAndPublish({
322→        children: updatedDestChildren,
323→        folderKey: dest.folderKey,
324→        ipnsPrivateKey: dest.ipnsKeypair.privateKey,
325→        ipnsName: destIpnsName,
326→        sequenceNumber: dest.sequenceNumber,
327→        ctx: this.ctx,
328→      });
329→
330→      // 3. Publish source (remove)
331→      const sourceResult = await sdkCore.updateFolderMetadataAndPublish({
332→        children: updatedSourceChildren,
333→        folderKey: source.folderKey,
334→        ipnsPrivateKey: source.ipnsKeypair.privateKey,
335→        ipnsName: sourceIpnsName,
336→        sequenceNumber: source.sequenceNumber,
337→        ctx: this.ctx,
338→      });
339→
340→      // 4. Update internal state
341→      source.children = updatedSourceChildren;
342→      source.sequenceNumber = sourceResult.newSequenceNumber;
343→      dest.children = updatedDestChildren;
344→      dest.sequenceNumber = destResult.newSequenceNumber;
345→      this.folderTree.set(sourceIpnsName, source);
346→      this.folderTree.set(destIpnsName, dest);
347→
348→      // 5. Emit events for both folders
349→      this.emitter.emit({
350→        type: 'folder:updated',
351→        folderId: sourceIpnsName,
352→        ipnsName: sourceIpnsName,
353→        children: updatedSourceChildren,
354→      });
355→      this.emitter.emit({
356→        type: 'folder:updated',
357→        folderId: destIpnsName,
358→        ipnsName: destIpnsName,
359→        children: updatedDestChildren,
360→      });
361→    });
362→  }
363→
364→  /**
365→   * Delete a child entry from a folder's metadata.
366→   *
367→   * This is a simple metadata delete -- it does NOT move to bin.
368→   * Use deleteToBin() for soft-delete with bin support.
369→   *
370→   * @param folderIpnsName - IPNS name of the folder containing the item
371→   * @param childId - ID of the child to delete
372→   * @returns The removed child entry
373→   */
374→  async deleteItem(folderIpnsName: string, childId: string): Promise<{ removedItem: FolderChild }> {
375→    return this.withOperation('deleteItem', async () => {
376→      const folder = this.folderTree.get(folderIpnsName);
377→      if (!folder) throw new Error('Folder not loaded');
378→
379→      // 1. Remove from metadata (pure operation)
380→      const { updatedChildren, removedItem } = sdkCore.deleteFromFolder({
381→        children: folder.children,
382→        childId,
383→      });
384→
385→      // 2. Publish updated metadata
386→      const { newSequenceNumber } = await sdkCore.updateFolderMetadataAndPublish({
387→        children: updatedChildren,
388→        folderKey: folder.folderKey,
389→        ipnsPrivateKey: folder.ipnsKeypair.privateKey,
390→        ipnsName: folderIpnsName,
391→        sequenceNumber: folder.sequenceNumber,
392→        ctx: this.ctx,
393→      });
394→
395→      // 3. Update internal state
396→      folder.children = updatedChildren;
397→      folder.sequenceNumber = newSequenceNumber;
398→      folder.lastLoadedAt = Date.now();
399→      this.folderTree.set(folderIpnsName, folder);
400→
401→      // 4. Emit update event
402→      this.emitter.emit({
403→        type: 'folder:updated',
404→        folderId: folderIpnsName,
405→        ipnsName: folderIpnsName,
406→        children: updatedChildren,
407→      });
408→
409→      return { removedItem };
410→    });
411→  }
412→
413→  // ---- File operations ----
414→
415→  /**
416→   * Upload a file to a folder.
417→   *
418→   * Encrypts the file, uploads to IPFS, creates per-file IPNS metadata,
419→   * adds a FilePointer to the parent folder's metadata, and publishes.
420→   *
421→   * @param folderIpnsName - IPNS name of the target folder
422→   * @param data - Raw file content as Uint8Array
423→   * @param fileName - Display name for the file
424→   * @param mimeType - MIME type of the file
425→   * @param onProgress - Optional upload progress callback
426→   * @returns CID of the uploaded encrypted file
427→   */
428→  async uploadFile(
429→    folderIpnsName: string,
430→    data: Uint8Array,
431→    fileName: string,
432→    mimeType: string,
433→    onProgress?: ProgressCallback
434→  ): Promise<{ cid: string }> {
435→    return this.withOperation('uploadFile', async () => {
436→      const folder = this.folderTree.get(folderIpnsName);
437→      if (!folder) throw new Error('Folder not loaded');
438→
439→      const fileId = crypto.randomUUID();
440→
441→      // 1. Encrypt and upload file, create file metadata
442→      const uploadResult = await sdkCore.uploadFile({
443→        data,
444→        fileId,
445→        mimeType,
446→        folderKey: folder.folderKey,
447→        userPublicKey: this.config.vaultKeypair.publicKey,
448→        ctx: this.ctx,
449→        onProgress,
450→        teeKeys: this.config.teeKeys,
451→      });
452→
453→      // 2. Add FilePointer to folder's children
454→      const { updatedChildren } = sdkCore.addFilePointerToFolder({
455→        children: folder.children,
456→        fileId,
457→        fileName,
458→        fileMetaIpnsName: uploadResult.fileMetaIpnsName,
459→        ipnsPrivateKeyEncrypted: uploadResult.ipnsPrivateKeyEncrypted,
460→      });
461→
462→      // 3. Batch publish: file metadata IPNS + folder metadata IPNS
463→      await sdkCore.batchPublishIpnsRecords([uploadResult.ipnsRecord]);
464→
465→      const { newSequenceNumber } = await sdkCore.updateFolderMetadataAndPublish({
466→        children: updatedChildren,
467→        folderKey: folder.folderKey,
468→        ipnsPrivateKey: folder.ipnsKeypair.privateKey,
469→        ipnsName: folderIpnsName,
470→        sequenceNumber: folder.sequenceNumber,
471→        ctx: this.ctx,
472→      });
473→
474→      // 4. Update internal state
475→      folder.children = updatedChildren;
476→      folder.sequenceNumber = newSequenceNumber;
477→      folder.lastLoadedAt = Date.now();
478→      this.folderTree.set(folderIpnsName, folder);
479→
480→      // 5. Emit events
481→      this.emitter.emit({
482→        type: 'file:uploaded',
483→        folderId: folderIpnsName,
484→        fileName,
485→        cid: uploadResult.cid,
486→      });
487→      this.emitter.emit({
488→        type: 'folder:updated',
489→        folderId: folderIpnsName,
490→        ipnsName: folderIpnsName,
491→        children: updatedChildren,
492→      });
493→
494→      return { cid: uploadResult.cid };
495→    });
496→  }
497→
498→  /**
499→   * Download and decrypt a file from IPFS.
500→   *
501→   * Fetches the encrypted file content, unwraps the file key using the
502→   * user's private key, and decrypts the content.
503→   *
504→   * @param cid - IPFS CID of the encrypted file content
505→   * @param fileKeyEncrypted - Hex-encoded ECIES-wrapped file key
506→   * @param fileIv - Hex-encoded IV used for encryption
507→   * @param encryptionMode - 'GCM' (default) or 'CTR'
508→   * @param onProgress - Optional download progress callback
509→   * @returns Decrypted file content
510→   */
511→  async downloadFile(
512→    cid: string,
513→    fileKeyEncrypted: string,
514→    fileIv: string,
515→    encryptionMode?: 'GCM' | 'CTR',
516→    onProgress?: DownloadProgressCallback
517→  ): Promise<Uint8Array> {
518→    return this.withOperation('downloadFile', async () => {
519→      const plaintext = await sdkCore.downloadAndDecrypt({
520→        cid,
521→        fileKeyEncrypted,
522→        fileIv,
523→        userPrivateKey: this.config.vaultKeypair.privateKey,
524→        encryptionMode,
525→        ctx: this.ctx,
526→        onProgress,
527→      });
528→
529→      this.emitter.emit({ type: 'file:downloaded', cid });
530→
531→      return plaintext;
532→    });
533→  }
534→
535→  // ---- Bin operations ----
536→
537→  /**
538→   * Load the recycle bin metadata.
539→   *
540→   * @returns Current bin state, or null if no bin exists yet
541→   */
542→  async loadBin(): Promise<BinState | null> {
543→    return this.withOperation('loadBin', async () => {
544→      const result = await binOps.loadBin({
545→        binCtx: this.getBinContext(),
546→      });
547→
548→      if (result) {
549→        this.binState = result;
550→        this.emitter.emit({ type: 'bin:updated', entries: result.entries });
551→      }
552→
553→      return result;
554→    });
555→  }
556→
557→  /**
558→   * Soft-delete an item by moving it to the recycle bin.
559→   *
560→   * Removes the item from the folder's metadata, adds a BinEntry,
561→   * and publishes both folder and bin IPNS records.
562→   *
563→   * @param folderIpnsName - IPNS name of the folder containing the item
564→   * @param childId - ID of the child to delete
565→   * @param parentPath - Breadcrumb path for restore (e.g., "My Vault / Documents")
566→   */
567→  async deleteToBin(folderIpnsName: string, childId: string, parentPath: string): Promise<void> {
568→    return this.withOperation('deleteToBin', async () => {
569→      if (!this.binState) throw new Error('Bin not loaded');
570→
571→      const { updatedBinState } = await binOps.addToBin({
572→        folderIpnsName,
573→        childId,
574→        parentPath,
575→        folderTree: this.folderTree,
576→        binState: this.binState,
577→        binCtx: this.getBinContext(),
578→      });
579→
580→      this.binState = updatedBinState;
581→
582→      // Emit events
583→      this.emitter.emit({
584→        type: 'folder:updated',
585→        folderId: folderIpnsName,
586→        ipnsName: folderIpnsName,
587→        children: this.folderTree.get(folderIpnsName)?.children ?? [],
588→      });
589→      this.emitter.emit({ type: 'bin:updated', entries: updatedBinState.entries });
590→    });
591→  }
592→
593→  /**
594→   * Restore an item from the recycle bin to its target folder.
595→   *
596→   * @param entryId - ID of the bin entry to restore
597→   * @param targetFolderIpnsName - IPNS name of the folder to restore to
598→   */
599→  async restoreFromBin(entryId: string, targetFolderIpnsName: string): Promise<void> {
600→    return this.withOperation('restoreFromBin', async () => {
601→      if (!this.binState) throw new Error('Bin not loaded');
602→
603→      const { updatedBinState } = await binOps.restoreFromBin({
604→        entryId,
605→        targetFolderIpnsName,
606→        folderTree: this.folderTree,
607→        binState: this.binState,
608→        binCtx: this.getBinContext(),
609→      });
610→
611→      this.binState = updatedBinState;
612→
613→      // Emit events
614→      this.emitter.emit({
615→        type: 'folder:updated',
616→        folderId: targetFolderIpnsName,
617→        ipnsName: targetFolderIpnsName,
618→        children: this.folderTree.get(targetFolderIpnsName)?.children ?? [],
619→      });
620→      this.emitter.emit({ type: 'bin:updated', entries: updatedBinState.entries });
621→    });
622→  }
623→
624→  /**
625→   * Permanently delete a bin entry (unpin CIDs, remove from bin).
626→   *
627→   * @param entryId - ID of the bin entry to permanently delete
628→   */
629→  async permanentDelete(entryId: string): Promise<void> {
630→    return this.withOperation('permanentDelete', async () => {
631→      if (!this.binState) throw new Error('Bin not loaded');
632→
633→      const { updatedBinState } = await binOps.permanentDeleteFromBin({
634→        entryId,
635→        binState: this.binState,
636→        binCtx: this.getBinContext(),
637→      });
638→
639→      this.binState = updatedBinState;
640→      this.emitter.emit({ type: 'bin:updated', entries: updatedBinState.entries });
641→    });
642→  }
643→
644→  /**
645→   * Permanently delete all bin entries.
646→   */
647→  async emptyBin(): Promise<void> {
648→    return this.withOperation('emptyBin', async () => {
649→      if (!this.binState) throw new Error('Bin not loaded');
650→
651→      const { updatedBinState } = await binOps.emptyBin({
652→        binState: this.binState,
653→        binCtx: this.getBinContext(),
654→      });
655→
656→      this.binState = updatedBinState;
657→      this.emitter.emit({ type: 'bin:updated', entries: [] });
658→    });
659→  }
660→
661→  // ---- Share operations ----
662→
663→  /**
664→   * Create an ECIES-wrapped key for sharing a folder with a recipient.
665→   *
666→   * @param folderIpnsName - IPNS name of the folder to share
667→   * @param recipientPublicKey - Recipient's secp256k1 public key
668→   * @returns Hex-encoded wrapped key for the recipient
669→   */
670→  async shareFolder(
671→    folderIpnsName: string,
672→    recipientPublicKey: Uint8Array
673→  ): Promise<{ encryptedKey: string }> {
674→    return this.withOperation('shareFolder', async () => {
675→      const folder = this.folderTree.get(folderIpnsName);
676→      if (!folder) throw new Error('Folder not loaded');
677→
678→      return shareOps.createShareKey({
679→        folderKey: folder.folderKey,
680→        recipientPublicKey,
681→        folderIpnsName,
682→        shareCtx: this.getShareContext(),
683→      });
684→    });
685→  }
686→
687→  /**
688→   * Revoke a share (soft-delete).
689→   *
690→   * @param shareId - Share ID to revoke
691→   * @param revokeShareFn - Function to call the API revoke endpoint
692→   */
693→  async revokeShare(
694→    shareId: string,
695→    revokeShareFn: (shareId: string) => Promise<void>
696→  ): Promise<void> {
697→    return this.withOperation('revokeShare', async () => {
698→      await shareOps.revokeShare({ shareId, revokeShareFn });
699→    });
700→  }
701→
702→  /**
703→   * Re-wrap keys for share recipients after adding items to a shared folder.
704→   *
705→   * @param coveringShares - Active shares covering the folder
706→   * @param newItems - New items whose keys need re-wrapping
707→   * @param addShareKeysFn - Function to add wrapped keys to a share via API
708→   */
709→  async reWrapForRecipients(
710→    coveringShares: SentShareInfo[],
711→    newItems: Array<{ keyType: 'file' | 'folder'; itemId: string; plaintextKey: Uint8Array }>,
712→    addShareKeysFn: (
713→      shareId: string,
714→      keys: Array<{ keyType: 'file' | 'folder'; itemId: string; encryptedKey: string }>
715→    ) => Promise<void>
716→  ): Promise<{ failedRecipients: string[] }> {
717→    return this.withOperation('reWrapForRecipients', async () => {
718→      return shareOps.reWrapForRecipients({
719→        coveringShares,
720→        newItems,
721→        addShareKeysFn,
722→      });
723→    });
724→  }
725→
726→  // ---- Private helpers ----
727→
728→  /** Build bin operation context from client config */
729→  private getBinContext(): binOps.BinOperationContext {
730→    return {
731→      ctx: this.ctx,
732→      userPrivateKey: this.config.vaultKeypair.privateKey,
733→      userPublicKey: this.config.vaultKeypair.publicKey,
734→      rootFolderKey: this.config.rootFolderKey,
735→      teeKeys: this.config.teeKeys,
736→    };
737→  }
738→
739→  /** Build share operation context from client config */
740→  private getShareContext(): shareOps.ShareOperationContext {
741→    return {
742→      ctx: this.ctx,
743→      userPrivateKey: this.config.vaultKeypair.privateKey,
744→      userPublicKey: this.config.vaultKeypair.publicKey,
745→    };
746→  }
747→
748→  // ---- Operation wrapper ----
749→
750→  /**
751→   * Wrap an async operation with event emission and error handling.
752→   *
753→   * Emits 'operation:start' before, 'operation:end' on success (with duration),
754→   * and 'error' on failure. Also calls the config callbacks if provided.
755→   */
756→  private async withOperation<T>(name: string, fn: () => Promise<T>): Promise<T> {
757→    const start = Date.now();
758→    this.config.onOperationStart?.(name);
759→    this.emitter.emit({ type: 'operation:start', operation: name });
760→
761→    try {
762→      const result = await fn();
763→      const durationMs = Date.now() - start;
764→      this.config.onOperationEnd?.(name);
765→      this.emitter.emit({ type: 'operation:end', operation: name, durationMs });
766→      return result;
767→    } catch (error) {
768→      this.config.onError?.(error as Error);
769→      this.emitter.emit({ type: 'error', operation: name, error: error as Error });
770→      throw error;
771→    }
772→  }
773→}
