  1→/**
  2→ * Folder operations - Stateless folder CRUD with encryption
  3→ *
  4→ * Extracted from: apps/web/src/services/folder.service.ts
  5→ * All store access replaced with explicit parameters.
  6→ * Functions take metadata in, return updated metadata out.
  7→ */
  8→
  9→import {
 10→  generateEd25519Keypair,
 11→  deriveIpnsName,
 12→  generateRandomBytes,
 13→  wrapKey,
 14→  bytesToHex,
 15→  hexToBytes,
 16→} from '@cipherbox/crypto';
 17→import {
 18→  encryptFolderMetadata,
 19→  decryptFolderMetadata,
 20→  type FolderMetadata,
 21→  type EncryptedFolderMetadata,
 22→  type FolderEntry,
 23→  type FolderChild,
 24→  type FilePointer,
 25→} from '@cipherbox/core';
 26→import type { SdkContext, TeeKeys } from '../types';
 27→import { addToIpfs, fetchFromIpfs } from '../ipfs';
 28→import { createAndPublishIpnsRecord, resolveIpnsRecord } from '../ipns';
 29→
 30→/**
 31→ * Fetch and decrypt folder metadata from IPFS.
 32→ *
 33→ * @param cid - IPFS CID of the encrypted metadata blob
 34→ * @param folderKey - Decrypted AES-256 folder key
 35→ * @param ctx - SDK context for IPFS access
 36→ * @returns Decrypted folder metadata (v2)
 37→ */
 38→export async function fetchAndDecryptMetadata(
 39→  cid: string,
 40→  folderKey: Uint8Array,
 41→  ctx: SdkContext
 42→): Promise<FolderMetadata> {
 43→  const encryptedBytes = await fetchFromIpfs(ctx, cid);
 44→  const encryptedJson = new TextDecoder().decode(encryptedBytes);
 45→  const encrypted: EncryptedFolderMetadata = JSON.parse(encryptedJson);
 46→  return decryptFolderMetadata(encrypted, folderKey);
 47→}
 48→
 49→/**
 50→ * Load a folder's metadata from IPNS.
 51→ *
 52→ * Resolves the folder's IPNS name to get the current metadata CID,
 53→ * fetches and decrypts the metadata.
 54→ *
 55→ * @returns Decrypted folder metadata, sequence number, and CID, or null if IPNS not found
 56→ */
 57→export async function loadFolderMetadata(params: {
 58→  ipnsName: string;
 59→  folderKey: Uint8Array;
 60→  ctx: SdkContext;
 61→}): Promise<{
 62→  metadata: FolderMetadata;
 63→  sequenceNumber: bigint;
 64→  cid: string;
 65→} | null> {
 66→  const resolved = await resolveIpnsRecord(params.ipnsName);
 67→  if (!resolved) return null;
 68→
 69→  const metadata = await fetchAndDecryptMetadata(resolved.cid, params.folderKey, params.ctx);
 70→
 71→  return {
 72→    metadata,
 73→    sequenceNumber: resolved.sequenceNumber,
 74→    cid: resolved.cid,
 75→  };
 76→}
 77→
 78→/**
 79→ * Create a new subfolder with generated keys.
 80→ *
 81→ * Generates new Ed25519 IPNS keypair and AES-256 folder key,
 82→ * wraps them with the user's public key for storage.
 83→ *
 84→ * @returns Created folder entry and decrypted keys
 85→ */
 86→export async function createSubfolder(params: {
 87→  name: string;
 88→  userPublicKey: Uint8Array;
 89→  teeKeys?: TeeKeys;
 90→}): Promise<{
 91→  folder: FolderEntry;
 92→  ipnsPrivateKey: Uint8Array;
 93→  folderKey: Uint8Array;
 94→  encryptedIpnsPrivateKey?: string;
 95→  keyEpoch?: number;
 96→}> {
 97→  // 1. Generate Ed25519 keypair for folder IPNS
 98→  const ipnsKeypair = await generateEd25519Keypair();
 99→  const ipnsName = await deriveIpnsName(ipnsKeypair.publicKey);
100→
101→  // 2. Generate random AES-256 folder key
102→  const folderKey = generateRandomBytes(32);
103→
104→  // 3. Wrap keys with user's public key (ECIES encryption)
105→  const ipnsPrivateKeyEncrypted = bytesToHex(
106→    await wrapKey(ipnsKeypair.privateKey, params.userPublicKey)
107→  );
108→  const folderKeyEncrypted = bytesToHex(await wrapKey(folderKey, params.userPublicKey));
109→
110→  // 4. TEE-02: Encrypt IPNS private key with TEE public key for republishing
111→  let encryptedIpnsPrivateKey: string | undefined;
112→  let keyEpoch: number | undefined;
113→
114→  if (params.teeKeys?.currentPublicKey) {
115→    const teePublicKey = hexToBytes(params.teeKeys.currentPublicKey);
116→    const encryptedKey = await wrapKey(ipnsKeypair.privateKey, teePublicKey);
117→    encryptedIpnsPrivateKey = bytesToHex(encryptedKey);
118→    keyEpoch = params.teeKeys.currentEpoch;
119→  }
120→
121→  // 5. Create folder entry for parent's metadata
122→  const now = Date.now();
123→  const folder: FolderEntry = {
124→    type: 'folder',
125→    id: crypto.randomUUID(),
126→    name: params.name,
127→    ipnsName,
128→    ipnsPrivateKeyEncrypted,
129→    folderKeyEncrypted,
130→    createdAt: now,
131→    modifiedAt: now,
132→  };
133→
134→  return {
135→    folder,
136→    ipnsPrivateKey: ipnsKeypair.privateKey,
137→    folderKey,
138→    encryptedIpnsPrivateKey,
139→    keyEpoch,
140→  };
141→}
142→
143→/**
144→ * Update folder metadata and publish to IPNS.
145→ *
146→ * Encrypts the metadata with the folder key, uploads to IPFS,
147→ * and publishes an updated IPNS record pointing to the new CID.
148→ *
149→ * @returns New CID and sequence number
150→ */
151→export async function updateFolderMetadataAndPublish(params: {
152→  children: FolderChild[];
153→  folderKey: Uint8Array;
154→  ipnsPrivateKey: Uint8Array;
155→  ipnsName: string;
156→  sequenceNumber: bigint;
157→  ctx: SdkContext;
158→  encryptedIpnsPrivateKey?: string;
159→  keyEpoch?: number;
160→}): Promise<{ cid: string; newSequenceNumber: bigint }> {
161→  // 1. Create v2 folder metadata
162→  const metadata: FolderMetadata = {
163→    version: 'v2',
164→    children: params.children,
165→  };
166→
167→  // 2. Encrypt metadata with folder key
168→  const encrypted = await encryptFolderMetadata(metadata, params.folderKey);
169→
170→  // 3. Upload to IPFS via backend relay
171→  const jsonStr = JSON.stringify(encrypted);
172→  const encryptedBytes = new TextEncoder().encode(jsonStr);
173→  const { cid } = await addToIpfs(params.ctx, encryptedBytes);
174→
175→  // 4. Publish IPNS record pointing to new CID
176→  const newSeq = params.sequenceNumber + 1n;
177→  await createAndPublishIpnsRecord({
178→    ipnsPrivateKey: params.ipnsPrivateKey,
179→    ipnsName: params.ipnsName,
180→    metadataCid: cid,
181→    sequenceNumber: newSeq,
182→    encryptedIpnsPrivateKey: params.encryptedIpnsPrivateKey,
183→    keyEpoch: params.keyEpoch,
184→    expectedSequenceNumber: params.sequenceNumber.toString(),
185→  });
186→
187→  return { cid, newSequenceNumber: newSeq };
188→}
189→
190→/**
191→ * Rename a child entry (folder or file) in folder metadata.
192→ *
193→ * Pure metadata operation: returns updated children array without publishing.
194→ */
195→export function renameInFolder(params: {
196→  children: FolderChild[];
197→  childId: string;
198→  newName: string;
199→}): { updatedChildren: FolderChild[]; renamedChild: FolderChild } {
200→  const children = [...params.children];
201→  const index = children.findIndex((c) => c.id === params.childId);
202→
203→  if (index === -1) throw new Error('Item not found');
204→
205→  const nameExists = children.some((c) => c.name === params.newName && c.id !== params.childId);
206→  if (nameExists) throw new Error('An item with this name already exists');
207→
208→  const renamedChild = {
209→    ...children[index],
210→    name: params.newName,
211→    modifiedAt: Date.now(),
212→  };
213→  children[index] = renamedChild;
214→
215→  return { updatedChildren: children, renamedChild };
216→}
217→
218→/**
219→ * Remove a child entry (folder or file) from folder metadata.
220→ *
221→ * Pure metadata operation: returns updated children array and the removed item.
222→ */
223→export function deleteFromFolder(params: { children: FolderChild[]; childId: string }): {
224→  updatedChildren: FolderChild[];
225→  removedItem: FolderChild;
226→} {
227→  const index = params.children.findIndex((c) => c.id === params.childId);
228→  if (index === -1) throw new Error('Item not found');
229→
230→  const removedItem = params.children[index];
231→  const updatedChildren = params.children.filter((c) => c.id !== params.childId);
232→
233→  return { updatedChildren, removedItem };
234→}
235→
236→/**
237→ * Add a file pointer to folder children.
238→ *
239→ * Pure metadata operation: returns updated children array with the new file pointer.
240→ */
241→export function addFilePointerToFolder(params: {
242→  children: FolderChild[];
243→  fileId: string;
244→  fileName: string;
245→  fileMetaIpnsName: string;
246→  ipnsPrivateKeyEncrypted: string;
247→}): { updatedChildren: FolderChild[]; filePointer: FilePointer } {
248→  const nameExists = params.children.some((c) => c.name === params.fileName);
249→  if (nameExists) throw new Error('A file with this name already exists');
250→
251→  const now = Date.now();
252→  const filePointer: FilePointer = {
253→    type: 'file',
254→    id: params.fileId,
255→    name: params.fileName,
256→    fileMetaIpnsName: params.fileMetaIpnsName,
257→    ipnsPrivateKeyEncrypted: params.ipnsPrivateKeyEncrypted,
258→    createdAt: now,
259→    modifiedAt: now,
260→  };
261→
262→  return {
263→    updatedChildren: [...params.children, filePointer],
264→    filePointer,
265→  };
266→}
267→
268→/**
269→ * Move a child entry between folders.
270→ *
271→ * Pure metadata operation: returns updated source and dest children arrays.
272→ * Uses add-before-remove pattern conceptually (caller publishes dest first, then source).
273→ */
274→export function moveItem(params: {
275→  sourceChildren: FolderChild[];
276→  destChildren: FolderChild[];
277→  childId: string;
278→}): {
279→  updatedSourceChildren: FolderChild[];
280→  updatedDestChildren: FolderChild[];
281→  movedItem: FolderChild;
282→} {
283→  const index = params.sourceChildren.findIndex((c) => c.id === params.childId);
284→  if (index === -1) throw new Error('Item not found');
285→
286→  const movedItem = {
287→    ...params.sourceChildren[index],
288→    modifiedAt: Date.now(),
289→  };
290→
291→  // Check name collision in destination
292→  const nameExists = params.destChildren.some((c) => c.name === movedItem.name);
293→  if (nameExists) {
294→    throw new Error('An item with this name already exists in destination');
295→  }
296→
297→  const updatedSourceChildren = params.sourceChildren.filter((c) => c.id !== params.childId);
298→  const updatedDestChildren = [...params.destChildren, movedItem];
299→
300→  return { updatedSourceChildren, updatedDestChildren, movedItem };
301→}
