  1→/**
  2→ * SDK Integration Debug Test
  3→ *
  4→ * Tests folder create/rename/delete operations after SDK rewiring (Plan 19.1-05).
  5→ * Captures console errors for diagnosis.
  6→ */
  7→import { test, expect } from '@playwright/test';
  8→import { readFileSync, readdirSync } from 'fs';
  9→import { resolve } from 'path';
 10→
 11→// Find the latest OTP from the API dev logs by scanning the pnpm dev task output
 12→function getLatestOtp(email: string): string | null {
 13→  // Search for the task output file in Claude's tmp directory
 14→  const tmpBase = '/private/tmp/claude-501/-Users-michael-Code-cipher-box';
 15→  try {
 16→    const sessions = readdirSync(tmpBase);
 17→    for (const session of sessions.reverse()) {
 18→      const tasksDir = resolve(tmpBase, session, 'tasks');
 19→      try {
 20→        const taskFiles = readdirSync(tasksDir);
 21→        for (const file of taskFiles) {
 22→          if (!file.endsWith('.output')) continue;
 23→          const content = readFileSync(resolve(tasksDir, file), 'utf-8');
 24→          const regex = new RegExp(`DEV OTP for ${email.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}: (\\d{6})`, 'g');
 25→          const matches = [...content.matchAll(regex)];
 26→          if (matches.length > 0) {
 27→            return matches[matches.length - 1][1];
 28→          }
 29→        }
 30→      } catch {
 31→        continue;
 32→      }
 33→    }
 34→  } catch {
 35→    // ignore
 36→  }
 37→  return null;
 38→}
 39→
 40→test.describe('SDK Integration Debug', () => {
 41→  const testEmail = 'myankelev@gmail.com';
 42→  const consoleErrors: string[] = [];
 43→  const consoleWarnings: string[] = [];
 44→
 45→  test('login, create folder, rename, delete - capture errors', async ({ page }) => {
 46→    // Capture ALL console messages
 47→    page.on('console', (msg) => {
 48→      if (msg.type() === 'error') {
 49→        consoleErrors.push(`[ERROR] ${msg.text()}`);
 50→      }
 51→      if (msg.type() === 'warning') {
 52→        consoleWarnings.push(`[WARN] ${msg.text()}`);
 53→      }
 54→    });
 55→
 56→    // Capture uncaught exceptions
 57→    page.on('pageerror', (err) => {
 58→      consoleErrors.push(`[PAGEERROR] ${err.message}`);
 59→    });
 60→
 61→    // --- LOGIN ---
 62→    console.log('Step 1: Navigate to app');
 63→    await page.goto('/');
 64→
 65→    console.log('Step 2: Enter email');
 66→    const emailInput = page.locator('[data-testid="email-input"]');
 67→    await emailInput.waitFor({ state: 'visible', timeout: 15000 });
