/**
 * SDK Integration Debug Test
 *
 * Tests folder create/rename/delete operations after SDK rewiring (Plan 19.1-05).
 * Captures console errors for diagnosis.
 */
import { test, expect } from '@playwright/test';
import { readFileSync, readdirSync } from 'fs';
import { resolve } from 'path';

// Find the latest OTP from the API dev logs by scanning the pnpm dev task output
function getLatestOtp(email: string): string | null {
  // Search for the task output file in Claude's tmp directory
  const tmpBase = '/private/tmp/claude-501/-Users-michael-Code-cipher-box';
  try {
    const sessions = readdirSync(tmpBase);
    for (const session of sessions.reverse()) {
      const tasksDir = resolve(tmpBase, session, 'tasks');
      try {
        const taskFiles = readdirSync(tasksDir);
        for (const file of taskFiles) {
          if (!file.endsWith('.output')) continue;
          const content = readFileSync(resolve(tasksDir, file), 'utf-8');
          const regex = new RegExp(`DEV OTP for ${email.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}: (\\d{6})`, 'g');
          const matches = [...content.matchAll(regex)];
          if (matches.length > 0) {
            return matches[matches.length - 1][1];
          }
        }
      } catch {
        continue;
      }
    }
  } catch {
    // ignore
  }
  return null;
}

test.describe('SDK Integration Debug', () => {
  const testEmail = 'myankelev@gmail.com';
  const consoleErrors: string[] = [];
  const consoleWarnings: string[] = [];

  test('login, create folder, rename, delete - capture errors', async ({ page }) => {
    // Capture ALL console messages
    page.on('console', (msg) => {
      if (msg.type() === 'error') {
        consoleErrors.push(`[ERROR] ${msg.text()}`);
      }
      if (msg.type() === 'warning') {
        consoleWarnings.push(`[WARN] ${msg.text()}`);
      }
    });

    // Capture uncaught exceptions
    page.on('pageerror', (err) => {
      consoleErrors.push(`[PAGEERROR] ${err.message}`);
    });

    // --- LOGIN ---
    console.log('Step 1: Navigate to app');
    await page.goto('/');

    console.log('Step 2: Enter email');
    const emailInput = page.locator('[data-testid="email-input"]');
    await emailInput.waitFor({ state: 'visible', timeout: 15000 });
    await emailInput.fill(testEmail);

    console.log('Step 3: Send OTP');
    await page.locator('[data-testid="send-otp-button"]').click();

    // Wait for OTP to arrive in API logs
    console.log('Step 4: Waiting for OTP from API logs...');
    await page.waitForTimeout(3000);

    // Get OTP from API log file
    const otpBefore = getLatestOtp(testEmail);
    console.log(`OTP found: ${otpBefore}`);

    if (!otpBefore) {
      // If we can't auto-detect, pause for manual entry
      console.log('Could not auto-detect OTP. Pausing for manual entry...');
      await page.pause();
    } else {
      const otpInput = page.locator('[data-testid="otp-input"]');
      await otpInput.waitFor({ state: 'visible', timeout: 15000 });
      await otpInput.fill(otpBefore);
      await page.locator('[data-testid="verify-button"]').click();
    }

    console.log('Step 5: Wait for login complete');
    await page.waitForURL('**/files', { timeout: 60000 });
    console.log('Login complete!');

    // Wait for vault to fully load
    await page.waitForTimeout(5000);

    // Take a screenshot of initial state
    await page.screenshot({ path: 'test-results/sdk-debug-01-initial.png', fullPage: true });

    // Clear console errors from login phase
    const loginErrors = [...consoleErrors];
    consoleErrors.length = 0;
    console.log(`Login phase errors: ${loginErrors.length}`);
    for (const e of loginErrors) console.log(e);

    // --- TEST 1: CREATE FOLDER in root ---
    console.log('\n=== TEST 1: Create folder in root ===');

    // The new folder button text is "+folder" with class "file-browser-new-folder-button"
    const newFolderBtn = page.locator('.file-browser-new-folder-button');
    await newFolderBtn.waitFor({ state: 'visible', timeout: 5000 });
    console.log('Found +folder button');
    await newFolderBtn.click();

    // Wait for create folder dialog
    const createDialog = page.locator('.dialog-content').filter({
      has: page.locator('#folder-name-input'),
    });

    const folderName = `test-sdk-${Date.now()}`;

    if (await createDialog.isVisible({ timeout: 3000 }).catch(() => false)) {
      console.log('Create folder dialog opened');
      await page.locator('#folder-name-input').fill(folderName);
      await page.locator('.dialog-button--primary[type="submit"]').click();

      // Wait for result
      await page.waitForTimeout(5000);
      await page.screenshot({ path: 'test-results/sdk-debug-02-after-create.png', fullPage: true });

      console.log(`Create folder errors: ${consoleErrors.length}`);
      for (const e of consoleErrors) console.log(e);
      consoleErrors.length = 0;

      // Check if folder appeared
      const folderItem = page.locator('.file-list-item', { hasText: folderName });
      const created = await folderItem.isVisible().catch(() => false);
      console.log(`Folder "${folderName}" visible: ${created}`);

      if (created) {
        // --- TEST 2: RENAME folder ---
        console.log('\n=== TEST 2: Rename folder ===');
        await folderItem.click({ button: 'right' });

        const renameOption = page.locator('.context-menu[role="menu"] button[role="menuitem"]', { hasText: 'Rename' });
        await renameOption.waitFor({ state: 'visible', timeout: 3000 });
        await renameOption.click();

        const renameDialog = page.locator('.dialog-content').filter({
          has: page.locator('#rename-input'),
        });
        await renameDialog.waitFor({ state: 'visible', timeout: 3000 });

        const newName = `renamed-${Date.now()}`;
        await page.locator('#rename-input').clear();
        await page.locator('#rename-input').fill(newName);
        await page.locator('.dialog-button--primary[type="submit"]').click();

        // Wait for result
        await page.waitForTimeout(5000);
        await page.screenshot({ path: 'test-results/sdk-debug-03-after-rename.png', fullPage: true });

        console.log(`Rename errors: ${consoleErrors.length}`);
        for (const e of consoleErrors) console.log(e);
        consoleErrors.length = 0;

        // Check if rename worked
        const renamedItem = page.locator('.file-list-item', { hasText: newName });
        const renamed = await renamedItem.isVisible().catch(() => false);
        console.log(`Folder "${newName}" visible after rename: ${renamed}`);

        // Check if rename dialog is still open (indicates error)
        const dialogStillOpen = await renameDialog.isVisible().catch(() => false);
        console.log(`Rename dialog still open: ${dialogStillOpen}`);
        if (dialogStillOpen) {
          const errorMsg = await page.locator('.dialog-error').textContent().catch(() => null);
          console.log(`Dialog error message: ${errorMsg}`);
          // Close it
          await page.keyboard.press('Escape');
        }

        // --- TEST 3: DELETE folder ---
        console.log('\n=== TEST 3: Delete folder ===');
        const targetItem = renamed ? renamedItem : folderItem;
        const targetName = renamed ? newName : folderName;

        await targetItem.click({ button: 'right' });
        const deleteOption = page.locator('.context-menu[role="menu"] button[role="menuitem"]', { hasText: 'Delete' });
        await deleteOption.waitFor({ state: 'visible', timeout: 3000 });
        await deleteOption.click();

        // Confirm dialog might appear
        const confirmDialog = page.locator('.dialog-content').filter({
          has: page.locator('button', { hasText: /delete|confirm/i }),
        });
        if (await confirmDialog.isVisible({ timeout: 2000 }).catch(() => false)) {
          const confirmBtn = confirmDialog.locator('button', { hasText: /delete|confirm/i });
          await confirmBtn.click();
        }

        // Wait for result
        await page.waitForTimeout(5000);
        await page.screenshot({ path: 'test-results/sdk-debug-04-after-delete.png', fullPage: true });

        console.log(`Delete errors: ${consoleErrors.length}`);
        for (const e of consoleErrors) console.log(e);
        consoleErrors.length = 0;

        const deleted = !(await page.locator('.file-list-item', { hasText: targetName }).isVisible().catch(() => true));
        console.log(`Folder "${targetName}" deleted: ${deleted}`);
      }
    } else {
      console.log('Create folder dialog did NOT open');
      await page.screenshot({ path: 'test-results/sdk-debug-02-no-dialog.png', fullPage: true });
    }

    // --- FINAL SUMMARY ---
    console.log('\n=== FINAL STATE ===');
    console.log(`Total remaining console errors: ${consoleErrors.length}`);
    for (const e of consoleErrors) console.log(e);
    console.log(`Total remaining console warnings: ${consoleWarnings.length}`);
    for (const w of consoleWarnings) console.log(w);

    await page.screenshot({ path: 'test-results/sdk-debug-final.png', fullPage: true });
  });
});

