      console.log('⊘ Skipping file move (file not found)');
    }

    // =========================================
    // TEST 8: Navigate back to root, move FolderA-Renamed into FolderB
    // =========================================
    // Go back to root
    const rootCrumb = page.locator('.breadcrumbs a, .breadcrumbs button, .breadcrumb-item').first();
    await rootCrumb.click();
    await page.waitForTimeout(2000);

    if (await page.locator('.file-list-item', { hasText: folderARenamed }).isVisible()) {
      await page.locator('.file-list-item', { hasText: folderARenamed }).click({ button: 'right' });
      await menuItem('Move to').waitFor({ state: 'visible', timeout: 3000 });
      await menuItem('Move to').click();

      const moveDialog = page.locator('.dialog-content').filter({
        has: page.locator('.move-dialog-folder-list'),
      });
      await moveDialog.waitFor({ state: 'visible', timeout: 3000 });

      const folderBOption = moveDialog.locator('.move-dialog-folder-item', { hasText: folderB });
      if (await folderBOption.isVisible({ timeout: 2000 }).catch(() => false)) {
        await folderBOption.click();
        await page.locator('.dialog-button--primary', { hasText: 'Move' }).click();
        await page.waitForTimeout(3000);
        const folderMoved = !(await page.locator('.file-list-item', { hasText: folderARenamed }).isVisible());
        logResult(`Move "${folderARenamed}" into "${folderB}"`, folderMoved, drainErrors(consoleErrors));

        // Verify it appears inside FolderB
        await page.locator('.file-list-item', { hasText: folderB }).dblclick();
        await page.waitForTimeout(2000);
        const movedFolderVisible = await page.locator('.file-list-item', { hasText: folderARenamed }).isVisible();
        logResult(`"${folderARenamed}" visible inside "${folderB}"`, movedFolderVisible, drainErrors(consoleErrors));
      } else {
        console.log(`⊘ FolderB not in move dialog, skipping folder move`);
        await page.keyboard.press('Escape');
        drainErrors(consoleErrors);
      }
    } else {
      console.log('⊘ Skipping folder move (FolderA-Renamed not found)');
    }

    // =========================================
    // TEST 9: Navigate into SubfolderC, verify moved file, delete it
    // =========================================
    // Ensure we're in FolderB first
    if (!(await page.locator('.file-list-item', { hasText: folderC }).isVisible().catch(() => false))) {
      // Navigate to FolderB from root
      const rootCrumb2 = page.locator('.breadcrumbs a, .breadcrumbs button, .breadcrumb-item').first();
      await rootCrumb2.click();
      await page.waitForTimeout(2000);
      await page.locator('.file-list-item', { hasText: folderB }).dblclick();
      await page.waitForTimeout(2000);
    }

    if (await page.locator('.file-list-item', { hasText: folderC }).isVisible().catch(() => false)) {
      await page.locator('.file-list-item', { hasText: folderC }).dblclick();
      await page.waitForTimeout(2000);

      const fileInSubfolder = await page.locator('.file-list-item', { hasText: currentFileName }).isVisible().catch(() => false);
      logResult(`File "${currentFileName}" visible in SubfolderC`, fileInSubfolder, drainErrors(consoleErrors));

      if (fileInSubfolder) {
        // Delete the file
        await page.locator('.file-list-item', { hasText: currentFileName }).click({ button: 'right' });
        await menuItem('Delete').waitFor({ state: 'visible', timeout: 3000 });
        await menuItem('Delete').click();
        await page.waitForTimeout(3000);
        const fileDeleted = !(await page.locator('.file-list-item', { hasText: currentFileName }).isVisible().catch(() => true));
        logResult(`Delete file "${currentFileName}"`, fileDeleted, drainErrors(consoleErrors));
      }
    }

    // =========================================
    // TEST 10: Go to root, delete FolderB (with children)
    // =========================================
    const rootCrumb3 = page.locator('.breadcrumbs a, .breadcrumbs button, .breadcrumb-item').first();
    await rootCrumb3.click();
    await page.waitForTimeout(2000);

    if (await page.locator('.file-list-item', { hasText: folderB }).isVisible().catch(() => false)) {
      await page.locator('.file-list-item', { hasText: folderB }).click({ button: 'right' });
      await menuItem('Delete').waitFor({ state: 'visible', timeout: 3000 });
      await menuItem('Delete').click();
      await page.waitForTimeout(3000);
      const folderBDeleted = !(await page.locator('.file-list-item', { hasText: folderB }).isVisible().catch(() => true));
      logResult(`Delete folder "${folderB}" (with children)`, folderBDeleted, drainErrors(consoleErrors));
    }

    // =========================================
    // SUMMARY
    // =========================================
    console.log('\n=== TEST COMPLETE ===');
    await page.screenshot({ path: 'test-results/sdk-debug-final.png', fullPage: true });
  });
});

