  const sdkSeqNum = client.getFolderSequenceNumber(folder.ipnsName);
  const sequenceNumber = sdkSeqNum !== undefined ? sdkSeqNum : folder.sequenceNumber;

  client.registerFolder(
    folder.ipnsName,
    folder.folderKey,
    {
      publicKey: new Uint8Array(0), // Public key derived from private key when needed
      privateKey: folder.ipnsPrivateKey,
    },
    folder.children,
    sequenceNumber
  );
}

