/**
 * Ensure a folder from the Zustand store is registered in the SDK's
 * internal FolderTree. This bridges the gap between folder navigation
 * (which loads folders into Zustand) and SDK operations (which require
 * folders in the SDK's internal state).
 *
 * Always syncs children from the store (may include items added by non-SDK
 * code paths like file upload). Preserves the SDK's sequence number if the
 * folder is already known (SDK may have incremented it after mutations).
 */
export function ensureFolderRegistered(folder: FolderNode): void {
  const client = getSdkClient();

  // Use the highest known sequence number between SDK and store.
  // SDK may have incremented it via mutations (create, rename, delete).
  // Store may have a higher value from non-SDK code paths (file upload service).
  const sdkSeqNum = client.getFolderSequenceNumber(folder.ipnsName);
  const sequenceNumber = sdkSeqNum !== undefined
    ? (sdkSeqNum > folder.sequenceNumber ? sdkSeqNum : folder.sequenceNumber)
    : folder.sequenceNumber;

  // Preserve SDK's IPNS private key if it has one — SDK-created folders
  // store their keys internally while the Zustand store has an empty placeholder.
  const sdkPrivateKey = client.getFolderIpnsPrivateKey(folder.ipnsName);
  const ipnsPrivateKey = sdkPrivateKey ?? folder.ipnsPrivateKey;

  client.registerFolder(
    folder.ipnsName,
    folder.folderKey,
    {
      publicKey: new Uint8Array(0), // Public key derived from private key when needed
      privateKey: ipnsPrivateKey,
    },
    folder.children,
    sequenceNumber
  );
}

