/**
 * SDK Integration Debug Test
 *
 * Comprehensive test of folder/file operations after SDK rewiring (Plan 19.1-05).
 * Tests: create folder, rename folder, create subfolder, move folder,
 *        upload file, rename file, move file, delete file, delete folder.
 */
import { test } from '@playwright/test';
import { readFileSync, readdirSync, writeFileSync, mkdirSync } from 'fs';
import { resolve, dirname } from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);

function getLatestOtp(email: string): string | null {
  const tmpBase = '/private/tmp/claude-501/-Users-michael-Code-cipher-box';
  try {
    const sessions = readdirSync(tmpBase);
    for (const session of sessions.reverse()) {
      const tasksDir = resolve(tmpBase, session, 'tasks');
      try {
        const taskFiles = readdirSync(tasksDir);
        for (const file of taskFiles) {
          if (!file.endsWith('.output')) continue;
          const content = readFileSync(resolve(tasksDir, file), 'utf-8');
          const regex = new RegExp(
            `DEV OTP for ${email.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}: (\\d{6})`,
            'g'
          );
          const matches = [...content.matchAll(regex)];
          if (matches.length > 0) {
            return matches[matches.length - 1][1];
          }
        }
      } catch {
        continue;
      }
    }
  } catch {
    // ignore
  }
  return null;
}

/** Helper: clear errors array and return count + details */
function drainErrors(errors: string[]): { count: number; details: string[] } {
  const details = [...errors];
  errors.length = 0;
  return { count: details.length, details };
}

/** Helper: log test result */
function logResult(testName: string, passed: boolean, errors: { count: number; details: string[] }) {
  const icon = passed ? '✓' : '✗';
  console.log(`${icon} ${testName}${errors.count > 0 ? ` (${errors.count} errors)` : ''}`);
  for (const e of errors.details) console.log(`    ${e}`);
}

test.describe('SDK Integration - Full Operations', () => {
  const testEmail = 'myankelev@gmail.com';
  const consoleErrors: string[] = [];
  const ts = Date.now();

  test('folder CRUD, file upload, move, rename, delete', async ({ page }) => {
    // Capture console errors
    page.on('console', (msg) => {
      if (msg.type() === 'error') consoleErrors.push(`[ERROR] ${msg.text()}`);
    });
    page.on('pageerror', (err) => consoleErrors.push(`[PAGEERROR] ${err.message}`));

    // --- LOGIN ---
    await page.goto('/');
    const emailInput = page.locator('[data-testid="email-input"]');
    await emailInput.waitFor({ state: 'visible', timeout: 15000 });
    await emailInput.fill(testEmail);
    await page.locator('[data-testid="send-otp-button"]').click();
    await page.waitForTimeout(3000);

    const otp = getLatestOtp(testEmail);
    console.log(`OTP: ${otp}`);
    if (!otp) {
      console.log('No OTP found, pausing...');
      await page.pause();
    } else {
      const otpInput = page.locator('[data-testid="otp-input"]');
      await otpInput.waitFor({ state: 'visible', timeout: 15000 });
      await otpInput.fill(otp);
      await page.locator('[data-testid="verify-button"]').click();
    }
    await page.waitForURL('**/files', { timeout: 60000 });
    await page.waitForTimeout(5000);
    consoleErrors.length = 0; // Clear login-phase errors
    console.log('\n=== LOGGED IN — Starting SDK operations ===\n');

    // Selectors
    const newFolderBtn = page.locator('.file-browser-new-folder-button');
    const folderNameInput = page.locator('#folder-name-input');
    const renameInput = page.locator('#rename-input');
    const submitBtn = page.locator('.dialog-button--primary[type="submit"]');
    const contextMenu = page.locator('.context-menu[role="menu"]');
    const menuItem = (text: string) => contextMenu.locator('button[role="menuitem"]', { hasText: text });

    // =========================================
    // TEST 1: Create folder A in root
    // =========================================
    const folderA = `FolderA-${ts}`;
    await newFolderBtn.click();
    await folderNameInput.waitFor({ state: 'visible', timeout: 3000 });
    await folderNameInput.fill(folderA);
    await submitBtn.click();
    await page.waitForTimeout(3000);
    const aVisible = await page.locator('.file-list-item', { hasText: folderA }).isVisible();
    logResult(`Create folder "${folderA}" in root`, aVisible, drainErrors(consoleErrors));

    // =========================================
    // TEST 2: Create folder B in root
    // =========================================
    const folderB = `FolderB-${ts}`;
    await newFolderBtn.click();
    await folderNameInput.waitFor({ state: 'visible', timeout: 3000 });
    await folderNameInput.fill(folderB);
    await submitBtn.click();
    await page.waitForTimeout(3000);
    const bVisible = await page.locator('.file-list-item', { hasText: folderB }).isVisible();
    logResult(`Create folder "${folderB}" in root`, bVisible, drainErrors(consoleErrors));

    // =========================================
    // TEST 3: Rename folder A
    // =========================================
    const folderARenamed = `FolderA-Renamed-${ts}`;
    await page.locator('.file-list-item', { hasText: folderA }).click({ button: 'right' });
    await menuItem('Rename').waitFor({ state: 'visible', timeout: 3000 });
    await menuItem('Rename').click();
    await renameInput.waitFor({ state: 'visible', timeout: 3000 });
    await renameInput.clear();
    await renameInput.fill(folderARenamed);
    await submitBtn.click();
    await page.waitForTimeout(3000);
    const aRenamed = await page.locator('.file-list-item', { hasText: folderARenamed }).isVisible();
    logResult(`Rename folder to "${folderARenamed}"`, aRenamed, drainErrors(consoleErrors));

    // =========================================
    // TEST 4: Navigate into folder B, create subfolder C
    // =========================================
    await page.locator('.file-list-item', { hasText: folderB }).dblclick();
    await page.waitForTimeout(3000);
    const folderC = `SubfolderC-${ts}`;
    await newFolderBtn.click();
    await folderNameInput.waitFor({ state: 'visible', timeout: 3000 });
    await folderNameInput.fill(folderC);
    await submitBtn.click();
    await page.waitForTimeout(5000);
    const cVisible = await page.locator('.file-list-item', { hasText: folderC }).isVisible();
    logResult(`Create subfolder "${folderC}" inside FolderB`, cVisible, drainErrors(consoleErrors));

    // =========================================
    // TEST 5: Upload a test file into folder B
    // =========================================
    // Create a temp file
    const tmpDir = resolve(__dirname, '..', 'test-results');
    mkdirSync(tmpDir, { recursive: true });
    const testFilePath = resolve(tmpDir, `test-upload-${ts}.txt`);
    writeFileSync(testFilePath, `Test file content for SDK debug - ${ts}`);
    const testFileName = `test-upload-${ts}.txt`;

    const fileInput = page.locator('.upload-zone input[type="file"], .empty-state input[type="file"]').first();
    await fileInput.evaluate((el: HTMLInputElement) => { el.value = ''; });
    await fileInput.setInputFiles(testFilePath);
    await page.waitForTimeout(5000);
    const fileUploaded = await page.locator('.file-list-item', { hasText: testFileName }).isVisible();
    logResult(`Upload file "${testFileName}" into FolderB`, fileUploaded, drainErrors(consoleErrors));

    // =========================================
    // TEST 6: Rename the uploaded file
    // =========================================
    const renamedFileName = `renamed-file-${ts}.txt`;
    if (fileUploaded) {
      await page.locator('.file-list-item', { hasText: testFileName }).click({ button: 'right' });
      await menuItem('Rename').waitFor({ state: 'visible', timeout: 3000 });
      await menuItem('Rename').click();
      await renameInput.waitFor({ state: 'visible', timeout: 3000 });
      await renameInput.clear();
      await renameInput.fill(renamedFileName);
      await submitBtn.click();
      await page.waitForTimeout(3000);
      const fileRenamed = await page.locator('.file-list-item', { hasText: renamedFileName }).isVisible();
      logResult(`Rename file to "${renamedFileName}"`, fileRenamed, drainErrors(consoleErrors));
    } else {
      console.log('⊘ Skipping file rename (upload failed)');
    }

    // =========================================
    // TEST 7: Move file from FolderB to SubfolderC
    // =========================================
    const currentFileName = (await page.locator('.file-list-item', { hasText: renamedFileName }).isVisible())
      ? renamedFileName : testFileName;
    if (await page.locator('.file-list-item', { hasText: currentFileName }).isVisible()) {
      await page.locator('.file-list-item', { hasText: currentFileName }).click({ button: 'right' });
      await menuItem('Move to').waitFor({ state: 'visible', timeout: 3000 });
      await menuItem('Move to').click();

      // Move dialog
      const moveDialog = page.locator('.dialog-content').filter({
        has: page.locator('.move-dialog-folder-list'),
      });
      await moveDialog.waitFor({ state: 'visible', timeout: 3000 });

      // Select SubfolderC
      const subfolderOption = moveDialog.locator('.move-dialog-folder-item', { hasText: folderC });
      if (await subfolderOption.isVisible({ timeout: 2000 }).catch(() => false)) {
