    writeFileSync(testFilePath, `Test file content for SDK debug - ${ts}`);
    const testFileName = `test-upload-${ts}.txt`;

    const fileInput = page.locator('.upload-zone input[type="file"], .empty-state input[type="file"]').first();
    await fileInput.evaluate((el: HTMLInputElement) => { el.value = ''; });
