      await page.locator('[data-testid="otp-input"]').waitFor({ state: 'visible', timeout: 10000 });
      await page.locator('[data-testid="otp-input"]').fill(otp);
      await page.locator('[data-testid="verify-button"]').click();
    }
    await page.waitForURL('**/files', { timeout: 60000 });
    await page.waitForTimeout(2000); // vault init
    consoleErrors.length = 0;
    console.log(`\n=== LOGGED IN as ${testEmail} ===\n`);

    // Helpers
    const W = 500; // standard wait after operations
    const btn = page.locator('.file-browser-new-folder-button');
    const nameInput = page.locator('#folder-name-input');
    const renameInput = page.locator('#rename-input');
    const submit = page.locator('.dialog-button--primary[type="submit"]');
    const ctx = page.locator('.context-menu[role="menu"]');
    const mi = (t: string) => ctx.locator('button[role="menuitem"]', { hasText: t });
    const item = (n: string) => page.locator('.file-list-item', { hasText: n });

    // ========== 1. Create FolderA ==========
    await btn.click();
    await nameInput.waitFor({ state: 'visible' });
    await nameInput.fill('FolderA');
    await submit.click();
    await page.waitForTimeout(W);
    log(await item('FolderA').isVisible() ? '✓' : '✗', 'Create FolderA in root', drainErrors(consoleErrors));

    // ========== 2. Create FolderB ==========
    await btn.click();
    await nameInput.waitFor({ state: 'visible' });
    await nameInput.fill('FolderB');
    await submit.click();
    await page.waitForTimeout(W);
    log(await item('FolderB').isVisible() ? '✓' : '✗', 'Create FolderB in root', drainErrors(consoleErrors));

    // ========== 3. Rename FolderA → FolderA-Renamed ==========
    await item('FolderA').click({ button: 'right' });
    await mi('Rename').click();
    await renameInput.waitFor({ state: 'visible' });
    await renameInput.clear();
    await renameInput.fill('FolderA-Renamed');
    await submit.click();
    await page.waitForTimeout(W);
    log(await item('FolderA-Renamed').isVisible() ? '✓' : '✗', 'Rename FolderA → FolderA-Renamed', drainErrors(consoleErrors));

    // ========== 4. Navigate into FolderB, create SubfolderC ==========
    await item('FolderB').dblclick();
    await page.waitForTimeout(W);
    await btn.click();
    await nameInput.waitFor({ state: 'visible' });
    await nameInput.fill('SubfolderC');
    await submit.click();
    await page.waitForTimeout(W);
    log(await item('SubfolderC').isVisible() ? '✓' : '✗', 'Create SubfolderC inside FolderB', drainErrors(consoleErrors));

    // ========== 5. Upload file into FolderB ==========
    const tmpDir = resolve(__dirname, '..', 'test-results');
    mkdirSync(tmpDir, { recursive: true });
    const testFilePath = resolve(tmpDir, 'sdk-test-file.txt');
    writeFileSync(testFilePath, `SDK test content ${Date.now()}`);

    const fileInput = page.locator('.upload-zone input[type="file"], .empty-state input[type="file"]').first();
    await fileInput.evaluate((el: HTMLInputElement) => { el.value = ''; });
    await fileInput.setInputFiles(testFilePath);
    await page.waitForTimeout(2000); // upload needs more time
    const uploaded = await item('sdk-test-file.txt').isVisible();
    log(uploaded ? '✓' : '✗', 'Upload file into FolderB', drainErrors(consoleErrors));

    // ========== 6. Rename file ==========
    if (uploaded) {
      await item('sdk-test-file.txt').click({ button: 'right' });
      await mi('Rename').click();
      await renameInput.waitFor({ state: 'visible' });
      await renameInput.clear();
      await renameInput.fill('renamed-file.txt');
      await submit.click();
      await page.waitForTimeout(W);
      const renamed = await item('renamed-file.txt').isVisible();
      log(renamed ? '✓' : '✗', 'Rename file → renamed-file.txt', drainErrors(consoleErrors));

      // ========== 7. Move file to SubfolderC ==========
      const currentFile = renamed ? 'renamed-file.txt' : 'sdk-test-file.txt';
      await item(currentFile).click({ button: 'right' });
      await mi('Move to').click();
      const moveDialog = page.locator('.move-dialog-folder-list');
      await moveDialog.waitFor({ state: 'visible' });
      const subfolderOpt = page.locator('.move-dialog-folder-item', { hasText: 'SubfolderC' });
      if (await subfolderOpt.isVisible()) {
        await subfolderOpt.click();
        await page.locator('.dialog-button--primary', { hasText: 'Move' }).click();
        await page.waitForTimeout(W);
        const moved = !(await item(currentFile).isVisible());
        log(moved ? '✓' : '✗', 'Move file to SubfolderC', drainErrors(consoleErrors));
      } else {
        console.log('⊘ SubfolderC not in move dialog');
        await page.keyboard.press('Escape');
        drainErrors(consoleErrors);
      }
    } else {
      console.log('⊘ Skipping file rename/move (upload failed)');
    }

    // ========== 8. Navigate to root, move FolderA-Renamed into FolderB ==========
    await page.locator('.breadcrumb-item').first().click();
    await page.waitForTimeout(W);

    if (await item('FolderA-Renamed').isVisible()) {
      await item('FolderA-Renamed').click({ button: 'right' });
      await mi('Move to').click();
      const moveDialog = page.locator('.move-dialog-folder-list');
      await moveDialog.waitFor({ state: 'visible' });
      const fbOpt = page.locator('.move-dialog-folder-item', { hasText: 'FolderB' });
      if (await fbOpt.isVisible()) {
        await fbOpt.click();
        await page.locator('.dialog-button--primary', { hasText: 'Move' }).click();
        await page.waitForTimeout(W);
        const moved = !(await item('FolderA-Renamed').isVisible());
        log(moved ? '✓' : '✗', 'Move FolderA-Renamed into FolderB', drainErrors(consoleErrors));

        // Verify inside FolderB
        await item('FolderB').dblclick();
        await page.waitForTimeout(W);
        log(await item('FolderA-Renamed').isVisible() ? '✓' : '✗', 'FolderA-Renamed visible inside FolderB', drainErrors(consoleErrors));
      } else {
        console.log('⊘ FolderB not in move dialog');
        await page.keyboard.press('Escape');
        drainErrors(consoleErrors);
      }
    } else {
      console.log('⊘ FolderA-Renamed not found in root');
    }

    // ========== 9. Delete FolderB from root ==========
    await page.locator('.breadcrumb-item').first().click();
    await page.waitForTimeout(W);
    if (await item('FolderB').isVisible()) {
      await item('FolderB').click({ button: 'right' });
      await mi('Delete').click();
      await page.waitForTimeout(W);
      log(!(await item('FolderB').isVisible()) ? '✓' : '✗', 'Delete FolderB', drainErrors(consoleErrors));
    }

    console.log('\n=== TEST COMPLETE ===');
    await page.screenshot({ path: 'test-results/sdk-debug-final.png', fullPage: true });
  });
});

