/**
 * SDK operations test — no UI, direct API + SDK calls.
 * Tests: create folder, upload file, download file, rename, delete, bin.
 * Run: npx tsx tests/e2e/tests/sdk-unit-test.ts
 */
import { CipherBoxClient } from '@cipherbox/sdk';
import { setApiClientConfig } from '@cipherbox/api-client';
import {
  initializeVault,
  encryptVaultKeys,
  decryptVaultKeys,
  deriveIpnsName,
  hexToBytes,
  bytesToHex,
} from '@cipherbox/crypto';
import * as ed from '@noble/ed25519';

const API = 'http://localhost:3000';
const EMAIL = `sdk-test-${Date.now()}@example.com`;

async function getOtp(email: string): Promise<string> {
  // Send OTP
  await fetch(`${API}/auth/identity/email/send-otp`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ email }),
  });

  // Read from API logs
  const { readFileSync, readdirSync } = await import('fs');
  const { resolve } = await import('path');
  await new Promise((r) => setTimeout(r, 1000));

  const tmpBase = '/private/tmp/claude-501/-Users-michael-Code-cipher-box';
  for (const session of readdirSync(tmpBase).reverse()) {
    const tasksDir = resolve(tmpBase, session, 'tasks');
    try {
      for (const file of readdirSync(tasksDir)) {
        if (!file.endsWith('.output')) continue;
        const content = readFileSync(resolve(tasksDir, file), 'utf-8');
        const regex = new RegExp(`DEV OTP for ${email.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}: (\\d{6})`, 'g');
        const matches = [...content.matchAll(regex)];
        if (matches.length > 0) return matches[matches.length - 1][1];
      }
    } catch { continue; }
  }
  throw new Error('OTP not found in API logs');
}

async function login(email: string): Promise<{ accessToken: string; publicKey: Uint8Array; privateKey: Uint8Array }> {
  const otp = await getOtp(email);
  console.log(`  OTP: ${otp}`);

  const verifyRes = await fetch(`${API}/auth/identity/email/verify-otp`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ email, otp }),
  });
  if (!verifyRes.ok) throw new Error(`OTP verify failed: ${verifyRes.status}`);
  const { token: identityToken } = await verifyRes.json();

  // Exchange identity token for access token
  const loginRes = await fetch(`${API}/auth/login`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ idToken: identityToken }),
  });
  if (!loginRes.ok) throw new Error(`Login failed: ${loginRes.status}`);
  const { accessToken, publicKeyHex, privateKeyHex } = await loginRes.json();

  return {
    accessToken,
    publicKey: hexToBytes(publicKeyHex),
    privateKey: hexToBytes(privateKeyHex),
  };
}

async function initVault(accessToken: string, publicKey: Uint8Array, privateKey: Uint8Array) {
  // Check if vault exists
  const vaultRes = await fetch(`${API}/vault`, {
    headers: { Authorization: `Bearer ${accessToken}` },
  });

  if (vaultRes.ok) {
    const vault = await vaultRes.json();
    const decrypted = await decryptVaultKeys(
      {
        encryptedRootFolderKey: hexToBytes(vault.encryptedRootFolderKey),
        encryptedIpnsPrivateKey: hexToBytes(vault.encryptedRootIpnsPrivateKey),
      },
      privateKey
    );
    const rootIpnsPublicKey = await ed.getPublicKeyAsync(decrypted.rootIpnsKeypair.privateKey);
    return {
      rootFolderKey: decrypted.rootFolderKey,
      rootIpnsKeypair: {
        publicKey: rootIpnsPublicKey,
        privateKey: decrypted.rootIpnsKeypair.privateKey,
      },
      rootIpnsName: vault.rootIpnsName,
    };
  }

  // Create new vault
  const newVault = await initializeVault(privateKey);
  const encrypted = await encryptVaultKeys(newVault, publicKey);
  const rootIpnsName = await deriveIpnsName(newVault.rootIpnsKeypair.publicKey);

  const initRes = await fetch(`${API}/vault/init`, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${accessToken}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify({
      ownerPublicKey: bytesToHex(publicKey),
      encryptedRootFolderKey: bytesToHex(encrypted.encryptedRootFolderKey),
      encryptedRootIpnsPrivateKey: bytesToHex(encrypted.encryptedIpnsPrivateKey),
      rootIpnsName,
    }),
  });
  if (!initRes.ok) throw new Error(`Vault init failed: ${initRes.status}`);

  return {
    rootFolderKey: newVault.rootFolderKey,
    rootIpnsKeypair: newVault.rootIpnsKeypair,
    rootIpnsName,
  };
}

function ok(msg: string) { console.log(`  ✓ ${msg}`); }
function fail(msg: string, err?: unknown) { console.log(`  ✗ ${msg}: ${err instanceof Error ? err.message : err}`); }

async function main() {
  console.log(`\n=== SDK Direct Test (${EMAIL}) ===\n`);

  // 1. Login
  console.log('1. Login...');
  const auth = await login(EMAIL);
  ok(`Logged in (token: ${auth.accessToken.slice(0, 20)}...)`);

  // 2. Init vault
  console.log('2. Init vault...');
  const vault = await initVault(auth.accessToken, auth.publicKey, auth.privateKey);
  ok(`Vault ready (rootIpns: ${vault.rootIpnsName.slice(0, 30)}...)`);

  // 3. Configure api-client
  setApiClientConfig({
    baseUrl: API,
    getAccessToken: async () => auth.accessToken,
  });

  // 4. Create SDK client
  const client = new CipherBoxClient({
    apiUrl: API,
    getAccessToken: async () => auth.accessToken,
    vaultKeypair: { publicKey: auth.publicKey, privateKey: auth.privateKey },
    rootIpnsName: vault.rootIpnsName,
    rootFolderKey: vault.rootFolderKey,
  });

  // Register root folder
  client.registerFolder(
    vault.rootIpnsName,
    vault.rootFolderKey,
    vault.rootIpnsKeypair,
    [],
    0n
  );

  // 5. Create folder
  console.log('3. Create folder...');
  try {
    const folder = await client.createFolder(vault.rootIpnsName, 'TestFolder');
    ok(`Created folder (id: ${folder.id}, ipns: ${folder.ipnsName.slice(0, 30)}...)`);

    // 6. Upload file
    console.log('4. Upload file...');
    const fileContent = new TextEncoder().encode('Hello from SDK test! ' + Date.now());
    try {
      const upload = await client.uploadFile(
        vault.rootIpnsName,
        fileContent,
        'test-file.txt',
        'text/plain'
      );
      ok(`Uploaded (cid: ${upload.cid})`);

      // 7. Download file
      console.log('5. Download file...');
      // Need to get the FilePointer from the root folder's children
      const rootState = client['folderTree'].get(vault.rootIpnsName);
      const fileChild = rootState?.children.find(c => c.type === 'file' && c.name === 'test-file.txt');
      if (!fileChild || fileChild.type !== 'file') {
        fail('Download', 'FilePointer not found in children');
      } else {
        try {
          // Resolve per-file IPNS to get metadata
          const { resolveFileMetadata } = await import('@cipherbox/sdk-core');
          const ctx = { apiUrl: API, getAccessToken: async () => auth.accessToken };
          const { metadata: fileMeta } = await resolveFileMetadata(
            fileChild.fileMetaIpnsName,
            vault.rootFolderKey,
            ctx
          );
          ok(`Resolved file metadata (cid: ${fileMeta.cid}, iv: ${fileMeta.fileIv.slice(0, 16)}...)`);

          // Download via SDK
          const downloaded = await client.downloadFile(
            fileMeta.cid,
            fileMeta.fileKeyEncrypted,
            fileMeta.fileIv,
            fileMeta.encryptionMode,
          );
          const downloadedText = new TextDecoder().decode(downloaded);
          const originalText = new TextDecoder().decode(fileContent);
          if (downloadedText === originalText) {
            ok(`Downloaded and verified (${downloaded.length} bytes match)`);
          } else {
            fail('Download', `Content mismatch: got "${downloadedText.slice(0, 50)}..." expected "${originalText.slice(0, 50)}..."`);
          }
        } catch (err) {
          fail('Download', err);
        }
      }

      // 8. Rename file
      console.log('6. Rename file...');
      if (fileChild && fileChild.type === 'file') {
        try {
          await client.renameItem(vault.rootIpnsName, fileChild.id, 'renamed-file.txt');
          ok('Renamed file to "renamed-file.txt"');
        } catch (err) {
          fail('Rename file', err);
        }
      }

      // 9. Delete file
      console.log('7. Delete file (hard)...');
      if (fileChild && fileChild.type === 'file') {
        try {
          await client.deleteItem(vault.rootIpnsName, fileChild.id);
          ok('Deleted file');
        } catch (err) {
          fail('Delete file', err);
        }
      }
    } catch (err) {
      fail('Upload file', err);
    }

    // 10. Rename folder
    console.log('8. Rename folder...');
    try {
      await client.renameItem(vault.rootIpnsName, folder.id, 'RenamedFolder');
      ok('Renamed folder to "RenamedFolder"');
    } catch (err) {
      fail('Rename folder', err);
    }

    // 11. Delete folder
    console.log('9. Delete folder...');
    try {
      await client.deleteItem(vault.rootIpnsName, folder.id);
      ok('Deleted folder');
    } catch (err) {
      fail('Delete folder', err);
    }

  } catch (err) {
    fail('Create folder', err);
  }

  client.destroy();
  console.log('\n=== Done ===\n');
}

main().catch(console.error);

