/**
 * SDK Integration Test — tests real API operations (requires running API).
 *
 * Tests create folder, upload, download, rename, delete.
 * Skipped in CI (needs running API + IPFS).
 * Run: pnpm --filter @cipherbox/sdk test -- --testPathPattern=integration
 */
import { describe, it, expect, beforeAll, afterAll } from 'vitest';
import { CipherBoxClient } from '../client';
import { setApiClientConfig } from '@cipherbox/api-client';
import {
  initializeVault,
  encryptVaultKeys,
  decryptVaultKeys,
  deriveIpnsName,
  hexToBytes,
  bytesToHex,
} from '@cipherbox/crypto';
import * as ed from '@noble/ed25519';
import { readFileSync, readdirSync } from 'fs';
import { resolve } from 'path';

const API = 'http://localhost:3000';
const EMAIL = `sdk-int-${Date.now()}@example.com`;
const TEST_LOGIN_SECRET = 'e2e-test-secret-do-not-use-in-production';

// Skip in CI
const describeIf = process.env.CI ? describe.skip : describe;

describeIf('SDK Integration (live API)', () => {
  let client: CipherBoxClient;
  let accessToken: string;
  let publicKey: Uint8Array;
  let privateKey: Uint8Array;
  let rootFolderKey: Uint8Array;
  let rootIpnsName: string;
  let rootIpnsKeypair: { publicKey: Uint8Array; privateKey: Uint8Array };

  beforeAll(async () => {
    // Check API is running
    try {
      const health = await fetch(`${API}/health`);
      if (!health.ok) throw new Error('API not healthy');
    } catch {
      console.log('API not running, skipping integration tests');
      return;
    }

    // Send OTP
    await fetch(`${API}/auth/identity/email/send-otp`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ email: EMAIL }),
    });
    await new Promise((r) => setTimeout(r, 1500));

    const otp = getLatestOtp(EMAIL);
    if (!otp) throw new Error('OTP not found');

    // Verify OTP
    const verifyRes = await fetch(`${API}/auth/identity/email/verify-otp`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ email: EMAIL, otp }),
    });
    const { token: idToken } = await verifyRes.json();

    // Login
    const loginRes = await fetch(`${API}/auth/login`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ idToken }),
    });
    const loginData = await loginRes.json();
    accessToken = loginData.accessToken;
    publicKey = hexToBytes(loginData.publicKeyHex);
    privateKey = hexToBytes(loginData.privateKeyHex);

    // Init vault
    const newVault = await initializeVault(privateKey);
    const encrypted = await encryptVaultKeys(newVault, publicKey);
    rootIpnsName = await deriveIpnsName(newVault.rootIpnsKeypair.publicKey);

    await fetch(`${API}/vault/init`, {
      method: 'POST',
      headers: {
        Authorization: `Bearer ${accessToken}`,
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        ownerPublicKey: bytesToHex(publicKey),
        encryptedRootFolderKey: bytesToHex(encrypted.encryptedRootFolderKey),
        encryptedRootIpnsPrivateKey: bytesToHex(encrypted.encryptedIpnsPrivateKey),
        rootIpnsName,
      }),
    });

    rootFolderKey = newVault.rootFolderKey;
    rootIpnsKeypair = newVault.rootIpnsKeypair;

    // Configure api-client
    setApiClientConfig({
      baseUrl: API,
      getAccessToken: async () => accessToken,
    });

    // Create client
    client = new CipherBoxClient({
      apiUrl: API,
      getAccessToken: async () => accessToken,
      vaultKeypair: { publicKey, privateKey },
      rootIpnsName,
      rootFolderKey,
    });

    // Register root folder
    client.registerFolder(rootIpnsName, rootFolderKey, rootIpnsKeypair, [], 0n);
  }, 30000);

  afterAll(() => {
    client?.destroy();
  });

  it('creates a folder', async () => {
    const result = await client.createFolder(rootIpnsName, 'TestFolder');
    expect(result.id).toBeTruthy();
    expect(result.ipnsName).toMatch(/^k51/);
    expect(result.folderKey.length).toBe(32);
    expect(result.ipnsPrivateKey.length).toBeGreaterThan(0);
  });

  it('uploads a file', async () => {
    const content = new TextEncoder().encode('Hello SDK! ' + Date.now());
    const result = await client.uploadFile(rootIpnsName, content, 'test.txt', 'text/plain');
    expect(result.cid).toBeTruthy();
  });

  it('downloads and decrypts the uploaded file', async () => {
    // Get file from root children
    const root = (client as any).folderTree.get(rootIpnsName);
    const fileChild = root?.children.find((c: any) => c.type === 'file' && c.name === 'test.txt');
    expect(fileChild).toBeTruthy();

    // Resolve per-file IPNS metadata
    const { resolveFileMetadata } = await import('../../sdk-core/src/file');
    const ctx = { apiUrl: API, getAccessToken: async () => accessToken };
    const { metadata: fileMeta } = await resolveFileMetadata(fileChild.fileMetaIpnsName, rootFolderKey, ctx);

    expect(fileMeta.cid).toBeTruthy();
    expect(fileMeta.fileKeyEncrypted).toBeTruthy();
    expect(fileMeta.fileIv).toBeTruthy();

    // Download via SDK
    const downloaded = await client.downloadFile(
      fileMeta.cid,
      fileMeta.fileKeyEncrypted,
      fileMeta.fileIv,
      fileMeta.encryptionMode
    );

    const text = new TextDecoder().decode(downloaded);
    expect(text).toContain('Hello SDK!');
  });

  it('renames a file', async () => {
    const root = (client as any).folderTree.get(rootIpnsName);
    const fileChild = root?.children.find((c: any) => c.type === 'file' && c.name === 'test.txt');
    expect(fileChild).toBeTruthy();

    await client.renameItem(rootIpnsName, fileChild.id, 'renamed.txt');

    const updated = (client as any).folderTree.get(rootIpnsName);
    const renamed = updated?.children.find((c: any) => c.name === 'renamed.txt');
    expect(renamed).toBeTruthy();
  });

  it('renames a folder', async () => {
    const root = (client as any).folderTree.get(rootIpnsName);
    const folder = root?.children.find((c: any) => c.type === 'folder' && c.name === 'TestFolder');
    expect(folder).toBeTruthy();

    await client.renameItem(rootIpnsName, folder.id, 'RenamedFolder');

    const updated = (client as any).folderTree.get(rootIpnsName);
    const renamed = updated?.children.find((c: any) => c.name === 'RenamedFolder');
    expect(renamed).toBeTruthy();
  });

  it('deletes a file', async () => {
    const root = (client as any).folderTree.get(rootIpnsName);
    const file = root?.children.find((c: any) => c.type === 'file');
    expect(file).toBeTruthy();

    const result = await client.deleteItem(rootIpnsName, file.id);
    expect(result.removedItem.id).toBe(file.id);

    const updated = (client as any).folderTree.get(rootIpnsName);
    const stillThere = updated?.children.find((c: any) => c.id === file.id);
    expect(stillThere).toBeUndefined();
  });

  it('deletes a folder', async () => {
    const root = (client as any).folderTree.get(rootIpnsName);
    const folder = root?.children.find((c: any) => c.type === 'folder');
    expect(folder).toBeTruthy();

    const result = await client.deleteItem(rootIpnsName, folder.id);
    expect(result.removedItem.id).toBe(folder.id);
  });
});

