 17→import type { SdkContext, TeeKeys } from '@cipherbox/sdk-core';
 18→import * as sdkCore from '@cipherbox/sdk-core';
 19→import {
 20→  encryptBinMetadata,
 21→  decryptBinMetadata,
 22→  deriveBinIpnsKeypair,
 23→  type BinEntry,
 24→  type RecycleBinMetadata,
 25→  type FolderChild,
 26→  type FilePointer,
 27→  type FolderEntry,
 28→} from '@cipherbox/core';
 29→import { bytesToHex, hexToBytes, wrapKey } from '@cipherbox/crypto';
 30→import type { FolderTree } from '../state/folder-tree';
 31→
 32→/** Current bin metadata version. */
 33→const BIN_METADATA_VERSION = 'v1' as const;
 34→
 35→/**
 36→ * Context for bin operations. Replaces Zustand store access.
 37→ */
 38→export type BinOperationContext = {
 39→  ctx: SdkContext;
 40→  userPrivateKey: Uint8Array;
 41→  userPublicKey: Uint8Array;
 42→  rootFolderKey: Uint8Array;
 43→  teeKeys?: TeeKeys;
 44→};
 45→
 46→/**
 47→ * Internal state for the bin (replaces useBinStore).
 48→ */
 49→export type BinState = {
 50→  entries: BinEntry[];
 51→  sequenceNumber: number;
 52→  ipnsName: string;
 53→};
 54→
 55→// ---------------------------------------------------------------------------
 56→// Internal helpers: load / save bin metadata
 57→// ---------------------------------------------------------------------------
 58→
 59→/**
 60→ * Load and decrypt bin metadata from IPNS.
 61→ */
 62→async function loadBinMetadataInternal(params: {
 63→  userPrivateKey: Uint8Array;
 64→  ctx: SdkContext;
 65→}): Promise<{
 66→  metadata: RecycleBinMetadata;
 67→  ipnsName: string;
 68→  sequenceNumber: bigint;
 69→} | null> {
 70→  const binIpns = await deriveBinIpnsKeypair(params.userPrivateKey);
 71→  const resolved = await sdkCore.resolveIpnsRecord(binIpns.ipnsName);
 72→
 73→  if (!resolved) return null;
 74→
 75→  const encryptedBytes = await sdkCore.fetchFromIpfs(params.ctx, resolved.cid);
 76→  const metadata = await decryptBinMetadata(encryptedBytes, params.userPrivateKey);
 77→
 78→  return {
 79→    metadata,
 80→    ipnsName: binIpns.ipnsName,
 81→    sequenceNumber: resolved.sequenceNumber,
 82→  };
 83→}
 84→
 85→/**
 86→ * Encrypt and publish bin metadata to IPNS.
 87→ */
 88→async function saveBinMetadata(params: {
 89→  metadata: RecycleBinMetadata;
 90→  userPublicKey: Uint8Array;
 91→  userPrivateKey: Uint8Array;
 92→  ctx: SdkContext;
 93→  teeKeys?: TeeKeys;
 94→}): Promise<void> {
 95→  const binIpns = await deriveBinIpnsKeypair(params.userPrivateKey);
 96→
 97→  // Encrypt metadata with user's public key (ECIES)
 98→  const encryptedBytes = await encryptBinMetadata(params.metadata, params.userPublicKey);
 99→
100→  // Pin to IPFS
101→  const { cid } = await sdkCore.addToIpfs(params.ctx, encryptedBytes);
102→
103→  // TEE enrollment (optional)
104→  let encryptedIpnsKey: string | undefined;
105→  let keyEpoch: number | undefined;
106→
107→  if (params.teeKeys?.currentPublicKey) {
108→    try {
109→      const teePublicKey = hexToBytes(params.teeKeys.currentPublicKey);
110→      const wrappedKey = await wrapKey(binIpns.privateKey, teePublicKey);
111→      encryptedIpnsKey = bytesToHex(wrappedKey);
112→      keyEpoch = params.teeKeys.currentEpoch;
113→    } catch {
114→      // TEE enrollment failure is non-blocking
115→    }
116→  }
117→
118→  // Publish IPNS record
119→  await sdkCore.createAndPublishIpnsRecord({
120→    ipnsPrivateKey: binIpns.privateKey,
121→    ipnsName: binIpns.ipnsName,
122→    metadataCid: cid,
123→    sequenceNumber: BigInt(params.metadata.sequenceNumber),
124→    encryptedIpnsPrivateKey: encryptedIpnsKey,
125→    keyEpoch,
126→  });
127→}
128→
129→// ---------------------------------------------------------------------------
130→// Public API
131→// ---------------------------------------------------------------------------
132→
133→/**
134→ * Load the recycle bin metadata from IPNS.
135→ *
136→ * @returns Current bin state, or null if no bin exists yet
137→ */
138→export async function loadBin(params: { binCtx: BinOperationContext }): Promise<BinState | null> {
139→  const loaded = await loadBinMetadataInternal({
140→    userPrivateKey: params.binCtx.userPrivateKey,
141→    ctx: params.binCtx.ctx,
142→  });
143→
144→  if (!loaded) return null;
145→
146→  return {
147→    entries: loaded.metadata.entries,
148→    sequenceNumber: loaded.metadata.sequenceNumber,
149→    ipnsName: loaded.ipnsName,
150→  };
