153→/**
154→ * Add item to recycle bin.
155→ *
156→ * Removes the item from the folder metadata (via deleteFromFolder),
157→ * creates a BinEntry, appends to bin metadata, and publishes both.
158→ *
159→ * @returns The removed item from the folder
160→ */
161→export async function addToBin(params: {
162→  folderIpnsName: string;
163→  childId: string;
164→  parentPath: string;
165→  folderTree: FolderTree;
166→  binState: BinState;
167→  binCtx: BinOperationContext;
168→}): Promise<{ removedItem: FolderChild; updatedBinState: BinState }> {
169→  const folder = params.folderTree.get(params.folderIpnsName);
170→  if (!folder) throw new Error('Folder not loaded');
171→
172→  // 1. Remove item from folder metadata
173→  const { updatedChildren, removedItem } = sdkCore.deleteFromFolder({
174→    children: folder.children,
175→    childId: params.childId,
176→  });
177→
178→  // 2. Publish updated folder metadata
179→  const { newSequenceNumber } = await sdkCore.updateFolderMetadataAndPublish({
180→    children: updatedChildren,
181→    folderKey: folder.folderKey,
182→    ipnsPrivateKey: folder.ipnsKeypair.privateKey,
183→    ipnsName: params.folderIpnsName,
184→    sequenceNumber: folder.sequenceNumber,
185→    ctx: params.binCtx.ctx,
186→  });
187→
188→  // 3. Update folder state
189→  folder.children = updatedChildren;
190→  folder.sequenceNumber = newSequenceNumber;
191→  folder.lastLoadedAt = Date.now();
192→  params.folderTree.set(params.folderIpnsName, folder);
193→
194→  // 4. Build bin entry
195→  const isFile = removedItem.type === 'file';
196→  const entry: BinEntry = {
197→    id: crypto.randomUUID(),
198→    itemType: isFile ? 'file' : 'folder',
199→    name: removedItem.name,
200→    originalParentIpnsName: params.folderIpnsName,
201→    originalPath: params.parentPath,
202→    deletedAt: Date.now(),
203→    size: 0,
204→    mimeType: '',
205→    filePointer: isFile ? (removedItem as FilePointer) : undefined,
206→    folderEntry: !isFile ? (removedItem as FolderEntry) : undefined,
207→  };
208→
209→  // 5. Update bin metadata and publish
210→  const updatedEntries = [...params.binState.entries, entry];
211→  const newBinSeq = params.binState.sequenceNumber + 1;
212→
213→  const metadata: RecycleBinMetadata = {
214→    version: BIN_METADATA_VERSION,
215→    sequenceNumber: newBinSeq,
216→    entries: updatedEntries,
217→  };
218→
219→  await saveBinMetadata({
220→    metadata,
221→    userPublicKey: params.binCtx.userPublicKey,
222→    userPrivateKey: params.binCtx.userPrivateKey,
223→    ctx: params.binCtx.ctx,
224→    teeKeys: params.binCtx.teeKeys,
225→  });
226→
227→  const updatedBinState: BinState = {
228→    entries: updatedEntries,
229→    sequenceNumber: newBinSeq,
230→    ipnsName: params.binState.ipnsName,
231→  };
232→
233→  return { removedItem, updatedBinState };
234→}
235→
236→/**
237→ * Restore an item from the recycle bin back to a folder.
238→ *
239→ * Removes the entry from bin metadata, adds the preserved FolderChild
240→ * back to the target folder's children, and publishes both.
241→ */
242→export async function restoreFromBin(params: {
243→  entryId: string;
244→  targetFolderIpnsName: string;
245→  folderTree: FolderTree;
246→  binState: BinState;
247→  binCtx: BinOperationContext;
248→}): Promise<{ restoredItem: FolderChild; updatedBinState: BinState }> {
249→  // 1. Find the bin entry
250→  const entry = params.binState.entries.find((e) => e.id === params.entryId);
251→  if (!entry) throw new Error('Bin entry not found');
252→
253→  // 2. Get the FolderChild to restore
254→  let child: FolderChild;
255→  if (entry.itemType === 'file' && entry.filePointer) {
256→    child = { ...entry.filePointer, modifiedAt: Date.now() };
257→  } else if (entry.itemType === 'folder' && entry.folderEntry) {
258→    child = { ...entry.folderEntry, modifiedAt: Date.now() };
259→  } else {
260→    throw new Error('Bin entry has no stored item reference');
261→  }
262→
263→  // 3. Add child back to target folder
264→  const targetFolder = params.folderTree.get(params.targetFolderIpnsName);
265→  if (!targetFolder) throw new Error('Target folder not loaded');
266→
267→  // Handle name collisions
268→  const existingNames = new Set(targetFolder.children.map((c) => c.name));
269→  if (existingNames.has(child.name)) {
270→    let newName = `${child.name} (restored)`;
271→    let counter = 2;
272→    while (existingNames.has(newName)) {
273→      newName = `${child.name} (restored ${counter})`;
274→      counter++;
275→    }
276→    child = { ...child, name: newName };
277→  }
278→
279→  const updatedFolderChildren = [...targetFolder.children, child];
280→
281→  // 4. Publish updated folder metadata
282→  const { newSequenceNumber } = await sdkCore.updateFolderMetadataAndPublish({
283→    children: updatedFolderChildren,
284→    folderKey: targetFolder.folderKey,
285→    ipnsPrivateKey: targetFolder.ipnsKeypair.privateKey,
286→    ipnsName: params.targetFolderIpnsName,
287→    sequenceNumber: targetFolder.sequenceNumber,
288→    ctx: params.binCtx.ctx,
289→  });
290→
291→  // 5. Update folder state
292→  targetFolder.children = updatedFolderChildren;
293→  targetFolder.sequenceNumber = newSequenceNumber;
294→  targetFolder.lastLoadedAt = Date.now();
295→  params.folderTree.set(params.targetFolderIpnsName, targetFolder);
296→
297→  // 6. Remove entry from bin and publish
298→  const remainingEntries = params.binState.entries.filter((e) => e.id !== params.entryId);
299→  const newBinSeq = params.binState.sequenceNumber + 1;
300→
301→  const metadata: RecycleBinMetadata = {
302→    version: BIN_METADATA_VERSION,
303→    sequenceNumber: newBinSeq,
304→    entries: remainingEntries,
305→  };
306→
307→  await saveBinMetadata({
308→    metadata,
309→    userPublicKey: params.binCtx.userPublicKey,
310→    userPrivateKey: params.binCtx.userPrivateKey,
311→    ctx: params.binCtx.ctx,
312→    teeKeys: params.binCtx.teeKeys,
313→  });
314→
315→  const updatedBinState: BinState = {
316→    entries: remainingEntries,
317→    sequenceNumber: newBinSeq,
318→    ipnsName: params.binState.ipnsName,
319→  };
320→
321→  return { restoredItem: child, updatedBinState };
322→}
323→
324→/**
325→ * Permanently delete a bin entry (unpin CIDs, remove from bin metadata).
326→ *
327→ * For files: unpins the content CID if available.
328→ * Does NOT handle recursive folder cleanup (that requires deep IPNS traversal).
329→ */
330→export async function permanentDeleteFromBin(params: {
331→  entryId: string;
332→  binState: BinState;
333→  binCtx: BinOperationContext;
334→}): Promise<{ updatedBinState: BinState }> {
335→  const entry = params.binState.entries.find((e) => e.id === params.entryId);
336→  if (!entry) throw new Error('Bin entry not found');
337→
338→  // Unpin content CID if available (best-effort)
339→  if (entry.contentCid) {
340→    try {
341→      await sdkCore.unpinFromIpfs(params.binCtx.ctx, entry.contentCid);
342→    } catch {
343→      // Best-effort CID cleanup
344→    }
345→  }
346→
347→  // Remove from bin metadata and publish
348→  const remainingEntries = params.binState.entries.filter((e) => e.id !== params.entryId);
349→  const newBinSeq = params.binState.sequenceNumber + 1;
350→
351→  const metadata: RecycleBinMetadata = {
352→    version: BIN_METADATA_VERSION,
353→    sequenceNumber: newBinSeq,
354→    entries: remainingEntries,
355→  };
356→
357→  await saveBinMetadata({
358→    metadata,
359→    userPublicKey: params.binCtx.userPublicKey,
360→    userPrivateKey: params.binCtx.userPrivateKey,
361→    ctx: params.binCtx.ctx,
362→    teeKeys: params.binCtx.teeKeys,
363→  });
364→
365→  return {
366→    updatedBinState: {
367→      entries: remainingEntries,
368→      sequenceNumber: newBinSeq,
369→      ipnsName: params.binState.ipnsName,
370→    },
371→  };
372→}
373→
374→/**
375→ * Empty the bin by permanently deleting all entries.
376→ *
377→ * Cleans up CIDs (best-effort) and publishes empty bin metadata.
378→ */
379→export async function emptyBin(params: {
380→  binState: BinState;
381→  binCtx: BinOperationContext;
382→}): Promise<{ updatedBinState: BinState }> {
383→  // Best-effort CID cleanup for each entry
384→  for (const entry of params.binState.entries) {
385→    if (entry.contentCid) {
386→      try {
387→        await sdkCore.unpinFromIpfs(params.binCtx.ctx, entry.contentCid);
388→      } catch {
389→        // Non-blocking
390→      }
391→    }
392→  }
393→
394→  // Publish empty bin metadata
395→  const newBinSeq = params.binState.sequenceNumber + 1;
396→  const metadata: RecycleBinMetadata = {
397→    version: BIN_METADATA_VERSION,
398→    sequenceNumber: newBinSeq,
399→    entries: [],
400→  };
401→
402→  await saveBinMetadata({
403→    metadata,
404→    userPublicKey: params.binCtx.userPublicKey,
405→    userPrivateKey: params.binCtx.userPrivateKey,
406→    ctx: params.binCtx.ctx,
407→    teeKeys: params.binCtx.teeKeys,
408→  });
409→
410→  return {
411→    updatedBinState: {
412→      entries: [],
413→      sequenceNumber: newBinSeq,
414→      ipnsName: params.binState.ipnsName,
415→    },
416→  };
417→}
