  1→// DEPRECATED: Use @cipherbox/sdk instead. Will be removed in 19.1-06.
  2→// Hooks now delegate to CipherBoxClient SDK methods for bin operations.
  3→// Remaining usages: initializeBin (useAuth login flow), purgeExpired (useBin).
  4→/**
  5→ * Bin Service - Recycle bin metadata IPNS lifecycle
  6→ *
  7→ * Manages the encrypted bin metadata: initialize on login, add entries on delete,
  8→ * restore items, permanent delete (with CID unpin + quota update), empty bin,
  9→ * and auto-purge expired entries.
 10→ *
 11→ * Follows the same IPFS/IPNS patterns as device-registry.service.ts.
 12→ *
 13→ * IMPORTANT: Bin operations must NEVER block login or the delete UI.
 14→ * initializeBin is fire-and-forget; addToBin is fire-and-forget from the
 15→ * delete flow. Errors are caught and logged, not thrown to callers.
 16→ */
 17→
 18→import {
 19→  deriveBinIpnsKeypair,
 20→  encryptBinMetadata,
 21→  decryptBinMetadata,
 22→  bytesToHex,
 23→  hexToBytes,
 24→  wrapKey,
 25→  unwrapKey,
 26→  decryptFileMetadata,
 27→  decryptFolderMetadata,
 28→  type RecycleBinMetadata,
 29→  type BinEntry,
 30→  type FolderChild,
 31→  type FilePointer,
 32→  type FolderEntry,
 33→  type EncryptedFileMetadata,
 34→  type EncryptedFolderMetadata,
 35→} from '@cipherbox/crypto';
 36→import { addToIpfs, fetchFromIpfs, unpinFromIpfs } from '../lib/api/ipfs';
 37→import { createAndPublishIpnsRecord, resolveIpnsRecord } from './ipns.service';
 38→import { resolveFileMetadata } from './file-metadata.service';
 39→import { useAuthStore } from '../stores/auth.store';
 40→import { useBinStore } from '../stores/bin.store';
 41→import { useFolderStore } from '../stores/folder.store';
 42→import { useVaultStore } from '../stores/vault.store';
 43→import { useQuotaStore } from '../stores/quota.store';
 44→import type { FolderNode } from '../stores/folder.store';
 45→
 46→// Track whether TEE enrollment has been done for this session
 47→let binTeeEnrolled = false;
 48→
 49→/** Current bin metadata version. */
 50→const BIN_METADATA_VERSION = 'v1' as const;
 51→
 52→// ---------------------------------------------------------------------------
 53→// Internal helpers: load / save bin metadata
 54→// ---------------------------------------------------------------------------
 55→
 56→/**
 57→ * Load and decrypt bin metadata from IPNS.
 58→ *
 59→ * @returns Decrypted metadata and IPNS resolution data, or null if no bin exists yet
 60→ */
 61→async function loadBinMetadata(params: { userPrivateKey: Uint8Array }): Promise<{
 62→  metadata: RecycleBinMetadata;
 63→  ipnsName: string;
 64→  sequenceNumber: bigint;
 65→} | null> {
 66→  const binIpns = await deriveBinIpnsKeypair(params.userPrivateKey);
 67→  const resolved = await resolveIpnsRecord(binIpns.ipnsName);
 68→
 69→  if (!resolved) {
 70→    return null;
 71→  }
 72→
 73→  const encryptedBytes = await fetchFromIpfs(resolved.cid);
 74→  const metadata = await decryptBinMetadata(encryptedBytes, params.userPrivateKey);
 75→
 76→  return {
 77→    metadata,
 78→    ipnsName: binIpns.ipnsName,
 79→    sequenceNumber: resolved.sequenceNumber,
 80→  };
 81→}
 82→
 83→/**
 84→ * Encrypt and publish bin metadata to IPNS.
 85→ *
 86→ * Handles TEE enrollment on first write.
 87→ */
 88→async function saveBinMetadata(params: {
 89→  metadata: RecycleBinMetadata;
 90→  userPublicKey: Uint8Array;
 91→  userPrivateKey: Uint8Array;
 92→}): Promise<void> {
 93→  const binIpns = await deriveBinIpnsKeypair(params.userPrivateKey);
 94→
 95→  // Encrypt metadata with user's public key (ECIES)
 96→  const encryptedBytes = await encryptBinMetadata(params.metadata, params.userPublicKey);
 97→
 98→  // Pin to IPFS
 99→  const { cid } = await addToIpfs(new Blob([encryptedBytes as BlobPart]));
100→
101→  // TEE enrollment on first write (fire-and-forget)
102→  let encryptedIpnsKey: string | undefined;
103→  let keyEpoch: number | undefined;
104→
105→  const enrollingTee = !binTeeEnrolled;
106→  if (enrollingTee) {
107→    const teeKeys = useAuthStore.getState().teeKeys;
108→    if (teeKeys?.currentPublicKey) {
109→      try {
110→        const wrappedKey = await wrapKey(binIpns.privateKey, hexToBytes(teeKeys.currentPublicKey));
111→        encryptedIpnsKey = bytesToHex(wrappedKey);
112→        keyEpoch = teeKeys.currentEpoch;
113→      } catch (err) {
114→        console.error('[Bin] TEE enrollment failed (non-blocking):', err);
115→      }
116→    }
117→  }
118→
119→  // Publish IPNS record
120→  await createAndPublishIpnsRecord({
121→    ipnsPrivateKey: binIpns.privateKey,
122→    ipnsName: binIpns.ipnsName,
123→    metadataCid: cid,
124→    sequenceNumber: BigInt(params.metadata.sequenceNumber),
125→    encryptedIpnsPrivateKey: encryptedIpnsKey,
126→    keyEpoch,
127→  });
128→
129→  // Mark TEE enrolled only after successful publish
130→  if (enrollingTee && encryptedIpnsKey) {
131→    binTeeEnrolled = true;
132→  }
133→}
134→
135→// ---------------------------------------------------------------------------
136→// Public API: initializeBin
137→// ---------------------------------------------------------------------------
138→
139→/**
140→ * Initialize or load the recycle bin on login.
141→ *
142→ * Derives the deterministic IPNS keypair, resolves existing bin metadata
143→ * from IPNS (or creates empty state), and populates the bin store.
144→ *
145→ * Non-blocking: errors are logged, not thrown.
146→ */
147→export async function initializeBin(params: {
148→  userPrivateKey: Uint8Array;
149→  userPublicKey: Uint8Array;
150→}): Promise<void> {
151→  const store = useBinStore.getState();
152→  store.setLoading(true);
153→
154→  try {
155→    // Reset TEE enrollment tracking for new session
156→    binTeeEnrolled = false;
157→
158→    // Try to load existing bin metadata (derives IPNS keypair internally)
159→    const loaded = await loadBinMetadata({ userPrivateKey: params.userPrivateKey });
160→
161→    // Set IPNS name from loaded result, or derive if no bin exists yet
162→    if (loaded) {
163→      store.setBinIpnsName(loaded.ipnsName);
164→    } else {
165→      const binIpns = await deriveBinIpnsKeypair(params.userPrivateKey);
166→      store.setBinIpnsName(binIpns.ipnsName);
167→    }
168→
169→    if (loaded) {
170→      store.setEntries(loaded.metadata.entries, loaded.metadata.sequenceNumber);
171→    } else {
172→      // No bin exists yet -- initialize with empty state
173→      store.setEntries([], 0);
174→    }
175→  } catch (error) {
176→    console.error('[Bin] Failed to initialize bin:', error);
177→    store.setError(error instanceof Error ? error.message : 'Failed to initialize bin');
178→    store.setLoading(false);
179→  }
180→}
181→
182→/**
183→ * Resolve file metadata and enrich a bin entry with content CID, size, and version CIDs.
184→ * Best-effort: errors are caught and logged, the entry is left un-enriched.
185→ */
186→async function enrichBinEntryWithFileMetadata(
187→  entry: BinEntry,
188→  item: FolderChild,
189→  folderKey: Uint8Array
190→): Promise<void> {
191→  try {
192→    const fp = item as FilePointer;
193→    const { metadata: fileMeta } = await resolveFileMetadata(fp.fileMetaIpnsName, folderKey);
194→    entry.contentCid = fileMeta.cid;
195→    entry.contentSize = fileMeta.size;
196→    if (Number.isFinite(fileMeta.size)) {
197→      entry.size = fileMeta.size;
198→    }
199→    if (fileMeta.mimeType) {
200→      entry.mimeType = fileMeta.mimeType;
201→    }
202→    if (Array.isArray(fileMeta.versions) && fileMeta.versions.length > 0) {
203→      entry.versionCids = fileMeta.versions
204→        .filter((v) => v.cid)
205→        .map((v) => ({ cid: v.cid, size: v.size ?? 0 }));
206→    }
207→  } catch (err) {
208→    console.warn('[Bin] Failed to resolve file CID for bin entry (non-blocking):', err);
209→  }
210→}
211→
212→// ---------------------------------------------------------------------------
213→// Public API: addToBin
214→// ---------------------------------------------------------------------------
215→
216→/**
217→ * Add a deleted item to the recycle bin.
218→ *
219→ * Creates a BinEntry from the FolderChild that was removed from its parent,
220→ * appends it to the bin metadata, encrypts, and publishes.
221→ *
222→ * @param params.item - The FolderChild (FilePointer or FolderEntry) that was removed
223→ * @param params.parentIpnsName - IPNS name of the original parent folder
224→ * @param params.parentPath - Breadcrumb path at deletion time (e.g., "My Vault / Documents")
225→ * @param params.userPublicKey - User's secp256k1 public key for ECIES encryption
226→ * @param params.userPrivateKey - User's secp256k1 private key for IPNS derivation
227→ */
228→export async function addToBin(params: {
229→  item: FolderChild;
230→  parentIpnsName: string;
231→  parentPath: string;
232→  userPublicKey: Uint8Array;
233→  userPrivateKey: Uint8Array;
234→  folderKey?: Uint8Array;
235→}): Promise<void> {
236→  const { item, parentIpnsName, parentPath, userPublicKey, userPrivateKey, folderKey } = params;
237→
238→  // Build bin entry
239→  const isFile = item.type === 'file';
240→  const entry: BinEntry = {
241→    id: crypto.randomUUID(),
242→    itemType: isFile ? 'file' : 'folder',
243→    name: item.name,
244→    originalParentIpnsName: parentIpnsName,
245→    originalPath: parentPath,
246→    deletedAt: Date.now(),
247→    size: 0,
248→    mimeType: '',
249→    filePointer: isFile ? (item as FilePointer) : undefined,
250→    folderEntry: !isFile ? (item as FolderEntry) : undefined,
251→  };
252→
253→  // Resolve file CID+size at soft-delete time (when folderKey is available)
254→  if (isFile && folderKey) {
255→    await enrichBinEntryWithFileMetadata(entry, item, folderKey);
256→  }
257→
258→  // Read current bin state and build updated metadata
259→  const store = useBinStore.getState();
260→  const currentEntries = [...store.entries, entry];
261→  const newSeq = store.sequenceNumber + 1;
262→
263→  const metadata: RecycleBinMetadata = {
264→    version: BIN_METADATA_VERSION,
265→    sequenceNumber: newSeq,
266→    entries: currentEntries,
267→  };
268→
269→  // Encrypt and publish (non-blocking: folder delete already committed, bin is best-effort)
270→  try {
271→    await saveBinMetadata({ metadata, userPublicKey, userPrivateKey });
272→    store.setEntries(currentEntries, newSeq);
273→  } catch {
274→    console.error('[Bin] addToBin publish failed (non-blocking)');
275→  }
276→}
277→
278→// ---------------------------------------------------------------------------
279→// Public API: addManyToBin
280→// ---------------------------------------------------------------------------
281→
282→/**
283→ * Add multiple deleted items to the recycle bin in a single IPNS publish.
284→ *
285→ * Unlike calling addToBin in a loop (which publishes per-item), this batches
286→ * all entries into one metadata update.
287→ */
288→export async function addManyToBin(params: {
289→  items: FolderChild[];
290→  parentIpnsName: string;
291→  parentPath: string;
292→  userPublicKey: Uint8Array;
293→  userPrivateKey: Uint8Array;
294→  folderKey?: Uint8Array;
295→}): Promise<void> {
296→  const { items, parentIpnsName, parentPath, userPublicKey, userPrivateKey, folderKey } = params;
297→  if (items.length === 0) return;
298→
299→  const now = Date.now();
300→  const newEntries: BinEntry[] = [];
301→  for (const item of items) {
302→    const isFile = item.type === 'file';
303→    const entry: BinEntry = {
304→      id: crypto.randomUUID(),
305→      itemType: isFile ? 'file' : 'folder',
306→      name: item.name,
307→      originalParentIpnsName: parentIpnsName,
308→      originalPath: parentPath,
309→      deletedAt: now,
310→      size: 0,
311→      mimeType: '',
312→      filePointer: isFile ? (item as FilePointer) : undefined,
313→      folderEntry: !isFile ? (item as FolderEntry) : undefined,
314→    };
315→
316→    // Resolve file CID+size at soft-delete time (when folderKey is available)
317→    if (isFile && folderKey) {
318→      await enrichBinEntryWithFileMetadata(entry, item, folderKey);
319→    }
320→
321→    newEntries.push(entry);
322→  }
323→
324→  const store = useBinStore.getState();
325→  const currentEntries = [...store.entries, ...newEntries];
326→  const newSeq = store.sequenceNumber + 1;
327→
328→  const metadata: RecycleBinMetadata = {
329→    version: BIN_METADATA_VERSION,
330→    sequenceNumber: newSeq,
331→    entries: currentEntries,
332→  };
333→
334→  // Non-blocking: folder delete already committed, bin is best-effort
335→  try {
336→    await saveBinMetadata({ metadata, userPublicKey, userPrivateKey });
337→    store.setEntries(currentEntries, newSeq);
338→  } catch {
339→    console.error('[Bin] addManyToBin publish failed (non-blocking)');
340→  }
341→}
342→
343→// ---------------------------------------------------------------------------
344→// Public API: restoreFromBin
345→// ---------------------------------------------------------------------------
346→
347→/**
348→ * Restore a bin entry to its original folder.
349→ *
350→ * Looks up the target folder by IPNS name. If found, re-adds the preserved
351→ * FolderChild. Handles name collisions (appends " (restored)"). If original
352→ * parent is also in the bin, attempts recursive parent restore (max depth 5).
353→ * Falls back to root folder if parent is gone.
354→ */
355→export async function restoreFromBin(params: {
356→  entryId: string;
357→  userPublicKey: Uint8Array;
358→  userPrivateKey: Uint8Array;
359→}): Promise<void> {
360→  return restoreFromBinInternal(params, 0);
361→}
362→
363→async function restoreFromBinInternal(
364→  params: { entryId: string; userPublicKey: Uint8Array; userPrivateKey: Uint8Array },
365→  depth: number
366→): Promise<void> {
367→  const { entryId, userPublicKey, userPrivateKey } = params;
368→
369→  const binStore = useBinStore.getState();
370→  const entry = binStore.entries.find((e) => e.id === entryId);
371→  if (!entry) throw new Error('Bin entry not found');
372→
373→  // Resolve original parent folder
374→  const targetFolder = await resolveTargetFolder(entry.originalParentIpnsName, depth, {
375→    userPublicKey,
376→    userPrivateKey,
377→  });
378→
379→  // Get the FolderChild to restore
380→  const child = getRestoredChild(entry);
381→
382→  // Check for name collisions in target folder and rename if needed
383→  const finalChild = resolveNameCollision(child, targetFolder.children);
384→
385→  // Add child back to target folder
386→  const { updateFolderMetadata } = await import('./folder.service');
387→  const updatedChildren = [...targetFolder.children, finalChild];
388→  const { newSequenceNumber } = await updateFolderMetadata({
389→    folderId: targetFolder.id,
390→    children: updatedChildren,
391→    folderKey: targetFolder.folderKey,
392→    ipnsPrivateKey: targetFolder.ipnsPrivateKey,
393→    ipnsName: targetFolder.ipnsName,
394→    sequenceNumber: targetFolder.sequenceNumber,
395→  });
396→
397→  // Update folder store
398→  const folderStore = useFolderStore.getState();
399→  folderStore.updateFolderChildren(targetFolder.id, updatedChildren);
400→  folderStore.updateFolderSequence(targetFolder.id, newSequenceNumber);
401→
402→  // If restoring a folder, re-add the folder node to the store
403→  if (entry.itemType === 'folder' && entry.folderEntry) {
404→    const existingNode = folderStore.folders[entry.folderEntry.id];
405→    if (!existingNode) {
406→      // Create a placeholder node -- it will be fully loaded on next navigation
407→      folderStore.setFolder({
408→        id: entry.folderEntry.id,
409→        name: finalChild.name,
410→        ipnsName: entry.folderEntry.ipnsName,
411→        parentId: targetFolder.id,
412→        children: [],
413→        isLoaded: false,
414→        isLoading: false,
415→        sequenceNumber: 0n,
416→        // These will be populated when the folder is loaded
417→        folderKey: new Uint8Array(32),
418→        ipnsPrivateKey: new Uint8Array(64),
419→      });
420→    }
421→  }
422→
423→  // Remove entry from bin metadata and publish
424→  await removeEntriesFromBin([entryId], { userPublicKey, userPrivateKey });
425→}
426→
427→// ---------------------------------------------------------------------------
428→// Public API: restoreFromBinBatch
429→// ---------------------------------------------------------------------------
430→
431→/**
432→ * Restore multiple bin entries, publishing to the bin IPNS only once at the end.
433→ *
434→ * Each item is restored to its target folder (which may each require a folder
435→ * publish), but the bin metadata is updated in a single publish.
436→ */
437→export async function restoreFromBinBatch(params: {
438→  entryIds: string[];
439→  userPublicKey: Uint8Array;
440→  userPrivateKey: Uint8Array;
441→}): Promise<void> {
442→  const { entryIds, userPublicKey, userPrivateKey } = params;
443→  if (entryIds.length === 0) return;
444→
445→  const { updateFolderMetadata } = await import('./folder.service');
446→
447→  const restoredIds: string[] = [];
448→
449→  for (const entryId of entryIds) {
450→    // Read fresh state each iteration — recursive restores may mutate the store
451→    const entry = useBinStore.getState().entries.find((e) => e.id === entryId);
452→    if (!entry) continue;
453→
454→    try {
455→      const targetFolder = await resolveTargetFolder(entry.originalParentIpnsName, 0, {
456→        userPublicKey,
457→        userPrivateKey,
458→      });
459→
460→      const child = getRestoredChild(entry);
461→      const finalChild = resolveNameCollision(child, targetFolder.children);
462→
463→      const updatedChildren = [...targetFolder.children, finalChild];
464→      const { newSequenceNumber } = await updateFolderMetadata({
465→        folderId: targetFolder.id,
466→        children: updatedChildren,
467→        folderKey: targetFolder.folderKey,
468→        ipnsPrivateKey: targetFolder.ipnsPrivateKey,
469→        ipnsName: targetFolder.ipnsName,
470→        sequenceNumber: targetFolder.sequenceNumber,
471→      });
472→
473→      const folderStore = useFolderStore.getState();
474→      folderStore.updateFolderChildren(targetFolder.id, updatedChildren);
475→      folderStore.updateFolderSequence(targetFolder.id, newSequenceNumber);
476→
477→      if (entry.itemType === 'folder' && entry.folderEntry) {
478→        const existingNode = folderStore.folders[entry.folderEntry.id];
479→        if (!existingNode) {
480→          folderStore.setFolder({
481→            id: entry.folderEntry.id,
482→            name: finalChild.name,
483→            ipnsName: entry.folderEntry.ipnsName,
484→            parentId: targetFolder.id,
485→            children: [],
486→            isLoaded: false,
487→            isLoading: false,
488→            sequenceNumber: 0n,
489→            folderKey: new Uint8Array(32),
490→            ipnsPrivateKey: new Uint8Array(64),
491→          });
492→        }
493→      }
494→
495→      restoredIds.push(entryId);
496→    } catch (err) {
497→      console.error(`[Bin] Failed to restore entry ${entry.id}:`, err);
498→    }
499→  }
500→
501→  // Single bin IPNS publish for all restored entries
502→  if (restoredIds.length > 0) {
503→    await removeEntriesFromBin(restoredIds, { userPublicKey, userPrivateKey });
504→  }
505→}
506→
507→// ---------------------------------------------------------------------------
508→// Public API: permanentlyDelete
509→// ---------------------------------------------------------------------------
510→
511→/**
512→ * Permanently delete a bin entry: unpin CIDs and update quota.
513→ *
514→ * For files: resolves file IPNS -> gets CID -> unpins.
515→ * For folders: recursively resolves all descendant file CIDs -> unpins all.
516→ */
517→export async function permanentlyDelete(params: {
518→  entryId: string;
519→  userPublicKey: Uint8Array;
520→  userPrivateKey: Uint8Array;
521→}): Promise<void> {
522→  const { entryId, userPublicKey, userPrivateKey } = params;
523→
524→  const binStore = useBinStore.getState();
525→  const entry = binStore.entries.find((e) => e.id === entryId);
526→  if (!entry) throw new Error('Bin entry not found');
527→
528→  // Perform CID cleanup
529→  await cleanupEntryCids(entry, userPrivateKey);
530→
531→  // Remove from bin metadata and publish
532→  await removeEntriesFromBin([entryId], { userPublicKey, userPrivateKey });
533→}
534→
535→// ---------------------------------------------------------------------------
536→// Public API: permanentlyDeleteBatch
537→// ---------------------------------------------------------------------------
538→
539→/**
540→ * Permanently delete multiple bin entries in a single IPNS publish.
541→ *
542→ * Cleans up CIDs for all entries (best-effort), then publishes once.
543→ */
544→export async function permanentlyDeleteBatch(params: {
545→  entryIds: string[];
546→  userPublicKey: Uint8Array;
547→  userPrivateKey: Uint8Array;
548→}): Promise<void> {
549→  const { entryIds, userPublicKey, userPrivateKey } = params;
550→  if (entryIds.length === 0) return;
551→
552→  const binStore = useBinStore.getState();
553→  const idsSet = new Set(entryIds);
554→  const entriesToDelete = binStore.entries.filter((e) => idsSet.has(e.id));
555→
556→  // Cleanup CIDs for all entries (best-effort, continue on individual failures)
557→  for (const entry of entriesToDelete) {
558→    try {
559→      await cleanupEntryCids(entry, userPrivateKey);
560→    } catch (err) {
561→      console.error(`[Bin] CID cleanup failed for entry ${entry.id}:`, err);
562→    }
563→  }
564→
565→  // Remove all from bin metadata in a single publish
566→  await removeEntriesFromBin(entryIds, { userPublicKey, userPrivateKey });
567→}
568→
569→// ---------------------------------------------------------------------------
570→// Public API: emptyBin
571→// ---------------------------------------------------------------------------
572→
573→/**
574→ * Permanently delete all bin entries.
575→ *
576→ * Processes each entry's CID cleanup, then publishes empty bin metadata.
577→ */
578→export async function emptyBin(params: {
579→  userPublicKey: Uint8Array;
580→  userPrivateKey: Uint8Array;
581→}): Promise<void> {
582→  const { userPublicKey, userPrivateKey } = params;
583→
584→  const binStore = useBinStore.getState();
585→  const entries = [...binStore.entries];
586→
587→  // Cleanup CIDs for all entries (best-effort, continue on individual failures)
588→  for (const entry of entries) {
589→    try {
590→      await cleanupEntryCids(entry, userPrivateKey);
591→    } catch (err) {
592→      console.error(`[Bin] Failed to cleanup CIDs for entry ${entry.id}:`, err);
593→    }
594→  }
595→
596→  // Publish empty bin metadata
597→  const newSeq = binStore.sequenceNumber + 1;
598→  const metadata: RecycleBinMetadata = {
599→    version: BIN_METADATA_VERSION,
600→    sequenceNumber: newSeq,
601→    entries: [],
602→  };
603→
604→  await saveBinMetadata({ metadata, userPublicKey, userPrivateKey });
605→
606→  // Update local store
607→  binStore.setEntries([], newSeq);
608→}
609→
610→// ---------------------------------------------------------------------------
611→// Public API: purgeExpired
612→// ---------------------------------------------------------------------------
613→
614→/**
615→ * Purge expired bin entries based on retention period.
616→ *
617→ * Filters entries past their retention, cleans up CIDs, and publishes
618→ * updated bin metadata in a single IPNS publish.
619→ */
620→export async function purgeExpired(params: {
621→  retentionDays: number;
622→  userPublicKey: Uint8Array;
623→  userPrivateKey: Uint8Array;
624→}): Promise<void> {
625→  const { retentionDays, userPublicKey, userPrivateKey } = params;
626→
627→  const binStore = useBinStore.getState();
628→  const retentionMs = retentionDays * 24 * 60 * 60 * 1000;
629→  const now = Date.now();
630→
631→  const expired = binStore.entries.filter((e) => now - e.deletedAt > retentionMs);
632→  if (expired.length === 0) return;
633→
634→  console.log(`[Bin] Purging ${expired.length} expired entries`);
635→
636→  // Cleanup CIDs for expired entries (best-effort)
637→  for (const entry of expired) {
638→    try {
639→      await cleanupEntryCids(entry, userPrivateKey);
640→    } catch (err) {
641→      console.error(`[Bin] Failed to cleanup CIDs for expired entry ${entry.id}:`, err);
642→    }
643→  }
644→
645→  // Remove expired entries and publish
646→  const expiredIds = expired.map((e) => e.id);
647→  await removeEntriesFromBin(expiredIds, { userPublicKey, userPrivateKey });
648→}
649→
650→// ---------------------------------------------------------------------------
651→// Internal helpers
652→// ---------------------------------------------------------------------------
653→
654→/**
655→ * Remove entries from bin metadata and publish the updated metadata.
656→ */
657→async function removeEntriesFromBin(
658→  entryIds: string[],
659→  params: { userPublicKey: Uint8Array; userPrivateKey: Uint8Array }
660→): Promise<void> {
661→  const binStore = useBinStore.getState();
662→  const idsToRemove = new Set(entryIds);
663→  const remainingEntries = binStore.entries.filter((e) => !idsToRemove.has(e.id));
664→  const newSeq = binStore.sequenceNumber + 1;
665→
666→  const metadata: RecycleBinMetadata = {
667→    version: BIN_METADATA_VERSION,
668→    sequenceNumber: newSeq,
669→    entries: remainingEntries,
670→  };
671→
672→  await saveBinMetadata({
673→    metadata,
674→    userPublicKey: params.userPublicKey,
675→    userPrivateKey: params.userPrivateKey,
676→  });
677→
678→  // Update local store (use setEntries with explicit seq to avoid double-increment)
679→  binStore.setEntries(remainingEntries, newSeq);
680→}
681→
682→/**
683→ * Cleanup CIDs for a bin entry (unpin from IPFS + update quota).
684→ *
685→ * Files: use stored contentCid if available, else fall back to IPNS resolution.
686→ * Folders: unwrap folderKey, decrypt folder metadata, decrypt each nested file's
687→ * metadata to get CID for unpinning. Recurses for subfolders.
688→ */
689→async function cleanupEntryCids(entry: BinEntry, userPrivateKey: Uint8Array): Promise<void> {
690→  if (entry.itemType === 'file') {
691→    await unpinFileCids(entry);
692→  } else if (entry.itemType === 'folder' && entry.folderEntry) {
693→    await cleanupFolderCids(entry.folderEntry, userPrivateKey);
694→  }
695→}
696→
697→/**
698→ * Unpin a single file's content and metadata CIDs, and update quota.
699→ *
700→ * Prefers stored contentCid (captured at soft-delete time) to avoid
701→ * re-decrypting encrypted file metadata (which was the GAP-1 bug).
702→ * Falls back to legacy IPNS resolution for old entries without contentCid.
703→ */
704→async function unpinFileCids(entry: BinEntry): Promise<void> {
705→  try {
706→    // Preferred path: use stored contentCid from soft-delete time
707→    if (entry.contentCid) {
708→      await unpinFromIpfs(entry.contentCid);
709→      if (Number.isFinite(entry.contentSize)) {
710→        useQuotaStore.getState().removeUsage(entry.contentSize!);
711→      }
712→      // Unpin version CIDs captured at soft-delete time
713→      if (entry.versionCids?.length) {
714→        await unpinVersionCids({ versions: entry.versionCids });
715→      }
716→      // Also unpin the file metadata IPNS record CID
717→      if (entry.filePointer) {
718→        const resolved = await resolveIpnsRecord(entry.filePointer.fileMetaIpnsName);
719→        if (resolved?.cid) {
720→          await unpinFromIpfs(resolved.cid).catch(() => {});
721→        }
722→      }
723→      return;
724→    }
725→
726→    // Fallback for legacy entries without contentCid:
727→    // Resolve IPNS and attempt to interpret file metadata as plaintext JSON.
728→    // NOTE: For encrypted file metadata ({ iv, data }), JSON.parse will usually
729→    // succeed, but the parsed object will not have cid/size, so no content unpin
730→    // or quota reclaim happens (the original GAP-1 bug). Entries that hit this
731→    // path may log an error but will not crash the delete flow.
732→    if (!entry.filePointer) return;
733→    const fileIpnsName = entry.filePointer.fileMetaIpnsName;
734→    if (!fileIpnsName) return;
735→
736→    const resolved = await resolveIpnsRecord(fileIpnsName);
737→    if (!resolved?.cid) return;
738→
739→    const metaBytes = await fetchFromIpfs(resolved.cid);
740→    const metaJson = new TextDecoder().decode(metaBytes);
741→    const fileMeta = JSON.parse(metaJson);
742→
743→    if (fileMeta.cid) {
744→      await unpinFromIpfs(fileMeta.cid);
745→      if (Number.isFinite(fileMeta.size)) {
746→        useQuotaStore.getState().removeUsage(fileMeta.size);
747→      }
748→    }
749→    await unpinVersionCids(fileMeta);
750→
751→    await unpinFromIpfs(resolved.cid).catch(() => {});
752→  } catch (err) {
753→    console.error(`[Bin] CID cleanup failed for file ${entry.id}:`, err);
754→  }
755→}
756→
757→/**
758→ * Unpin version CIDs from a decrypted/parsed file metadata object and reclaim quota.
759→ * Best-effort: errors on individual versions are caught and logged.
760→ */
761→async function unpinVersionCids(fileMeta: {
762→  versions?: Array<{ cid?: string; size?: number }>;
763→}): Promise<void> {
764→  if (!Array.isArray(fileMeta.versions)) return;
765→  for (const version of fileMeta.versions) {
766→    try {
767→      if (version.cid) {
768→        await unpinFromIpfs(version.cid);
769→      }
770→      if (Number.isFinite(version.size)) {
771→        useQuotaStore.getState().removeUsage(version.size!);
772→      }
773→    } catch {
774→      // Best-effort for individual version cleanup
775→    }
776→  }
777→}
778→
779→/**
780→ * Recursively unpin all CIDs in a folder tree.
781→ *
782→ * Unwraps the folder's AES key using the user's private key, then decrypts
783→ * the folder metadata to enumerate children. For each file child, decrypts
784→ * the file metadata to extract the content CID for unpinning.
785→ * For subfolder children, recurses with the user's private key.
786→ */
787→async function cleanupFolderCids(
788→  folderEntry: FolderEntry,
789→  userPrivateKey: Uint8Array
790→): Promise<void> {
791→  let folderMetadataCid: string | null = null;
792→  try {
793→    // Step 1: Unwrap the folder's AES key using user's private key (ECIES)
794→    const wrappedFolderKey = hexToBytes(folderEntry.folderKeyEncrypted);
795→    const folderKey = await unwrapKey(wrappedFolderKey, userPrivateKey);
796→
797→    // Step 2: Resolve folder's IPNS to get its metadata CID
798→    const resolved = await resolveIpnsRecord(folderEntry.ipnsName);
799→    if (!resolved?.cid) return;
800→    folderMetadataCid = resolved.cid;
801→
802→    // Step 3: Fetch and decrypt the folder metadata
803→    const metaBytes = await fetchFromIpfs(resolved.cid);
804→    const metaJson = new TextDecoder().decode(metaBytes);
805→    const encrypted = JSON.parse(metaJson) as EncryptedFolderMetadata;
806→    const folderMeta = await decryptFolderMetadata(encrypted, folderKey);
807→
808→    // Step 4: For each child, unpin CIDs
809→    for (const child of folderMeta.children) {
810→      try {
811→        if (child.type === 'file') {
812→          const fp = child as FilePointer;
813→          // Decrypt file metadata to get content CID
814→          const fileResolved = await resolveIpnsRecord(fp.fileMetaIpnsName);
815→          if (fileResolved?.cid) {
816→            const fileMetaBytes = await fetchFromIpfs(fileResolved.cid);
817→            const fileMetaJson = new TextDecoder().decode(fileMetaBytes);
818→            const encryptedFileMeta = JSON.parse(fileMetaJson) as EncryptedFileMetadata;
819→            const fileMeta = await decryptFileMetadata(encryptedFileMeta, folderKey);
820→            if (fileMeta.cid) {
821→              await unpinFromIpfs(fileMeta.cid);
822→              if (Number.isFinite(fileMeta.size)) {
823→                useQuotaStore.getState().removeUsage(fileMeta.size);
824→              }
825→            }
826→            // Unpin any historical version CIDs
827→            await unpinVersionCids(fileMeta);
828→            // Also unpin the file metadata CID
829→            await unpinFromIpfs(fileResolved.cid).catch(() => {});
830→          }
831→        } else if (child.type === 'folder') {
832→          // Subfolder: folderKeyEncrypted is ECIES-wrapped with the user's publicKey
833→          const subFe = child as FolderEntry;
834→          await cleanupFolderCids(subFe, userPrivateKey);
835→        }
836→      } catch (childErr) {
837→        console.error(`[Bin] Failed to cleanup CIDs for child ${child.name}:`, childErr);
838→      }
839→    }
840→  } catch (err) {
841→    console.error(`[Bin] Folder CID cleanup failed for ${folderEntry.ipnsName}:`, err);
842→  } finally {
843→    // Always unpin the folder metadata CID, even if child cleanup threw
844→    if (folderMetadataCid) {
845→      await unpinFromIpfs(folderMetadataCid).catch(() => {});
846→    }
847→  }
848→}
849→
850→/**
851→ * Resolve the target folder for a restore operation.
852→ *
853→ * Walks the folder store to find a folder with the given IPNS name.
854→ * If not found, checks if the parent is in the bin (recursive restore).
855→ * Falls back to root folder.
856→ */
857→async function resolveTargetFolder(
858→  parentIpnsName: string,
859→  depth: number,
860→  params: { userPublicKey: Uint8Array; userPrivateKey: Uint8Array }
861→): Promise<FolderNode> {
862→  // Max recursion depth to prevent infinite loops
863→  if (depth > 5) {
864→    console.warn('[Bin] Max restore depth reached, falling back to root');
865→    return getRootFolder();
866→  }
867→
868→  // Look up folder by IPNS name in folder store
869→  const folders = useFolderStore.getState().folders;
870→  const targetFolder = Object.values(folders).find((f) => f.ipnsName === parentIpnsName);
871→
872→  if (targetFolder) {
873→    return targetFolder;
874→  }
875→
876→  // Check if parent is in the bin
877→  const binStore = useBinStore.getState();
878→  const parentBinEntry = binStore.entries.find(
879→    (e) => e.itemType === 'folder' && e.folderEntry && e.folderEntry.ipnsName === parentIpnsName
880→  );
881→
882→  if (parentBinEntry) {
883→    // Restore parent first (recursive, depth incremented)
884→    console.log(`[Bin] Restoring parent folder (id: ${parentBinEntry.id}) first`);
885→    await restoreFromBinInternal(
886→      {
887→        entryId: parentBinEntry.id,
888→        userPublicKey: params.userPublicKey,
889→        userPrivateKey: params.userPrivateKey,
890→      },
891→      depth + 1
892→    );
893→
894→    // After restoring parent, try to find it again
895→    const updatedFolders = useFolderStore.getState().folders;
896→    const restoredParent = Object.values(updatedFolders).find((f) => f.ipnsName === parentIpnsName);
897→    if (restoredParent) {
898→      return restoredParent;
899→    }
900→  }
901→
902→  // Parent truly gone -- restore to root
903→  console.warn(`[Bin] Original parent not found (${parentIpnsName}), restoring to root`);
904→  return getRootFolder();
905→}
906→
907→/**
908→ * Get the root folder from the folder store.
909→ */
910→function getRootFolder(): FolderNode {
911→  const folders = useFolderStore.getState().folders;
912→  const root = folders['root'];
913→  if (root) return root;
914→
915→  // Fallback: construct from vault store
916→  const vault = useVaultStore.getState();
917→  if (!vault.rootFolderKey || !vault.rootIpnsKeypair || !vault.rootIpnsName) {
918→    throw new Error('Vault not initialized - cannot restore to root');
919→  }
920→
921→  return {
922→    id: 'root',
923→    name: 'My Vault',
924→    ipnsName: vault.rootIpnsName,
925→    parentId: null,
926→    children: folders['root']?.children ?? [],
927→    isLoaded: true,
928→    isLoading: false,
929→    sequenceNumber: 0n,
930→    folderKey: vault.rootFolderKey,
931→    ipnsPrivateKey: vault.rootIpnsKeypair.privateKey,
932→  };
933→}
934→
935→/**
936→ * Get the FolderChild to restore from a bin entry.
937→ */
938→function getRestoredChild(entry: BinEntry): FolderChild {
939→  if (entry.itemType === 'file' && entry.filePointer) {
940→    return { ...entry.filePointer, modifiedAt: Date.now() };
941→  } else if (entry.itemType === 'folder' && entry.folderEntry) {
942→    return { ...entry.folderEntry, modifiedAt: Date.now() };
943→  }
944→  throw new Error(`Bin entry ${entry.id} has no stored item reference`);
945→}
946→
947→/**
948→ * Check for name collisions and rename if needed.
949→ */
950→function resolveNameCollision(child: FolderChild, existingChildren: FolderChild[]): FolderChild {
951→  const existingNames = new Set(existingChildren.map((c) => c.name));
952→  if (!existingNames.has(child.name)) {
953→    return child;
954→  }
955→
956→  // Append " (restored)" suffix, incrementing if needed
957→  let newName = `${child.name} (restored)`;
958→  let counter = 2;
959→  while (existingNames.has(newName)) {
960→    newName = `${child.name} (restored ${counter})`;
961→    counter++;
962→  }
963→
964→  return { ...child, name: newName };
965→}
966→

