import { create } from 'zustand';
import type { FolderChild } from '@cipherbox/crypto';
import type { CipherBoxClient } from '@cipherbox/sdk';

/**
 * A folder node in the in-memory folder tree.
 * Contains decrypted folder data and navigation state.
 */
export type FolderNode = {
  /** UUID for internal reference (null string 'root' for root folder) */
  id: string;
  /** Folder name */
  name: string;
  /** IPNS name for this folder (k51.../bafzaa... format) */
  ipnsName: string;
  /** Parent folder ID (null for root) */
  parentId: string | null;
  /** Decrypted children (files and subfolders) */
  children: FolderChild[];
  /** Has metadata been fetched and decrypted? */
  isLoaded: boolean;
  /** Is metadata currently being fetched? */
  isLoading: boolean;
  /** Current IPNS sequence number */
  sequenceNumber: bigint;
  /** Decrypted AES-256 folder key */
  folderKey: Uint8Array;
  /** Decrypted Ed25519 IPNS private key */
  ipnsPrivateKey: Uint8Array;
};

/**
 * Breadcrumb entry for navigation.
 */
type Breadcrumb = {
  id: string;
  name: string;
};

type FolderState = {
  // Folder tree indexed by id
  folders: Record<string, FolderNode>;

  // Current navigation
  currentFolderId: string | null; // null = root
  breadcrumbs: Breadcrumb[];

  // Publishing state
  pendingPublishes: Set<string>; // folder IDs with pending IPNS publishes

  // Actions
  setFolder: (folder: FolderNode) => void;
  updateFolderChildren: (folderId: string, children: FolderChild[]) => void;
  updateFolderSequence: (folderId: string, sequenceNumber: bigint) => void;
  setCurrentFolder: (folderId: string | null) => void;
  setBreadcrumbs: (breadcrumbs: Breadcrumb[]) => void;
  addPendingPublish: (folderId: string) => void;
  removePendingPublish: (folderId: string) => void;
  removeFolder: (folderId: string) => void;
  updateFolderName: (folderId: string, newName: string) => void;
  clearFolders: () => void;

  // SDK event subscription
  subscribeToSdk: (client: CipherBoxClient) => void;
};

// Module-level unsubscribe callback — not part of Zustand state to avoid spurious re-renders
let _folderSdkUnsubscribe: (() => void) | null = null;

/**
 * Folder store for managing folder tree state.
 *
 * Maintains the in-memory representation of the folder hierarchy
 * with decrypted folder keys and metadata.
 *
 * SECURITY: All folder keys are memory-only - never persisted to storage.
 * Call clearFolders() on logout to zero-fill all key material.
 */
export const useFolderStore = create<FolderState>((set, get) => ({
  // State
  folders: {},
  currentFolderId: null,
  breadcrumbs: [],
  pendingPublishes: new Set<string>(),

  // Actions
  setFolder: (folder) =>
    set((state) => ({
      folders: { ...state.folders, [folder.id]: folder },
    })),

  updateFolderChildren: (folderId, children) =>
    set((state) => {
      const folder = state.folders[folderId];
      if (!folder) return state;

      return {
        folders: {
          ...state.folders,
          [folderId]: { ...folder, children, isLoaded: true, isLoading: false },
        },
      };
    }),

  updateFolderSequence: (folderId, sequenceNumber) =>
    set((state) => {
      const folder = state.folders[folderId];
      if (!folder) return state;

      return {
        folders: {
          ...state.folders,
          [folderId]: { ...folder, sequenceNumber },
        },
      };
    }),

  setCurrentFolder: (folderId) => set({ currentFolderId: folderId }),

  setBreadcrumbs: (breadcrumbs) => set({ breadcrumbs }),

  addPendingPublish: (folderId) =>
    set((state) => {
      const newPending = new Set(state.pendingPublishes);
      newPending.add(folderId);
      return { pendingPublishes: newPending };
    }),

  removePendingPublish: (folderId) =>
    set((state) => {
      const newPending = new Set(state.pendingPublishes);
      newPending.delete(folderId);
      return { pendingPublishes: newPending };
    }),

  // Remove a folder from local state (after deletion)
  // Also clears the folder's key material from memory
  removeFolder: (folderId) =>
    set((state) => {
      const folder = state.folders[folderId];
      if (!folder) return state;

      // Zero-fill keys before removing
      if (folder.folderKey) folder.folderKey.fill(0);
      if (folder.ipnsPrivateKey) folder.ipnsPrivateKey.fill(0);

      const { [folderId]: _removed, ...remainingFolders } = state.folders;
      void _removed; // Intentionally destructured to remove from object
      return { folders: remainingFolders };
    }),

  // Update a folder's name in local state
  updateFolderName: (folderId, newName) =>
    set((state) => {
      const folder = state.folders[folderId];
      if (!folder) return state;

      return {
        folders: {
          ...state.folders,
          [folderId]: { ...folder, name: newName },
        },
      };
    }),

  // [SECURITY: MEDIUM-02] Zero-fill sensitive key material before clearing
  clearFolders: () => {
    const state = get();

    // Unsubscribe from SDK events before clearing
    if (_folderSdkUnsubscribe) {
      _folderSdkUnsubscribe();
      _folderSdkUnsubscribe = null;
    }

    // Best-effort memory clearing - overwrite all folder keys with zeros
    for (const folder of Object.values(state.folders)) {
      if (folder.folderKey) {
        folder.folderKey.fill(0);
      }
      if (folder.ipnsPrivateKey) {
        folder.ipnsPrivateKey.fill(0);
      }
    }

    set({
      folders: {},
      currentFolderId: null,
      breadcrumbs: [],
      pendingPublishes: new Set<string>(),
      _sdkUnsubscribe: null,
    });
  },

  /**
   * Subscribe to SDK folder events. Called after SDK client is initialized.
   *
   * Maps SDK events (keyed by ipnsName) to store updates (keyed by folder id).
   * The SDK emits folderId = ipnsName, so we reverse-lookup to find the store's folder id.
   */
  subscribeToSdk: (client: CipherBoxClient) => {
    // Unsubscribe any existing subscription
    if (_folderSdkUnsubscribe) {
      _folderSdkUnsubscribe();
    }

    _folderSdkUnsubscribe = client.on((event) => {
      switch (event.type) {
        case 'folder:loaded':
        case 'folder:updated': {
          // SDK uses ipnsName as folderId; find the matching store entry
          const folders = get().folders;
          const matchingFolder = Object.values(folders).find((f) => f.ipnsName === event.ipnsName);
          if (matchingFolder) {
            get().updateFolderChildren(matchingFolder.id, event.children);
          }
          break;
        }
        case 'folder:deleted': {
          // SDK uses ipnsName as folderId
          const folders = get().folders;
          const matchingFolder = Object.values(folders).find((f) => f.ipnsName === event.folderId);
          if (matchingFolder) {
            get().removeFolder(matchingFolder.id);
          }
          break;
        }
      }
    });
  },
}));

// Expose store on window for E2E testing (development only)
if (typeof window !== 'undefined' && import.meta.env.DEV) {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  (window as any).__ZUSTAND_FOLDER_STORE__ = useFolderStore;
}

import { useCallback } from 'react';
import { useUploadStore } from '../stores/upload.store';
import { useQuotaStore } from '../stores/quota.store';
import { useFolderStore } from '../stores/folder.store';
import { useVaultStore } from '../stores/vault.store';
import { useAuthStore } from '../stores/auth.store';
import { getSdkClient, hasSdkClient, ensureFolderRegistered } from '../lib/sdk-provider';
import { getRootFolderState } from './folder-helpers';
import type { PendingReplacement } from '../stores/upload.store';

export const MAX_FILE_SIZE = 100 * 1024 * 1024; // 100MB per FILE-01

/**
 * Check whether a drag event carries external files from the OS (Finder/Explorer)
 * rather than an internal app drag (which sets application/json).
 */
export function isExternalFileDrag(dataTransfer: DataTransfer): boolean {
  return dataTransfer.types.includes('Files') && !dataTransfer.types.includes('application/json');
}

/**
 * Hook for handling external file drops (from Finder/Explorer) anywhere in the app.
 *
 * Uses the SDK's uploadFile() for atomic encrypt → upload → register flow.
 * All IPNS state is managed by the SDK — no dual-path conflicts.
 */
export function useDropUpload() {
  const uploadStatus = useUploadStore((s) => s.status);
  const isUploading =
    uploadStatus === 'encrypting' || uploadStatus === 'uploading' || uploadStatus === 'registering';

  const handleFileDrop = useCallback(async (files: File[], folderId: string): Promise<boolean> => {
    // Filter out oversized files
    const oversized = files.filter((f) => f.size > MAX_FILE_SIZE);
    if (oversized.length > 0) {
      useUploadStore
        .getState()
        .setError(`Files exceed 100MB limit: ${oversized.map((f) => f.name).join(', ')}`);
      return false;
    }

    if (files.length === 0) return false;

    // Check quota
    const totalSize = files.reduce((sum, f) => sum + f.size, 0);
    const quotaStore = useQuotaStore.getState();
    if (!quotaStore.canUpload(totalSize)) {
      useUploadStore.getState().setError('Not enough storage space for these files');
      return false;
    }

    // Check for duplicates within batch
    const batchNames = new Set<string>();
    for (const f of files) {
      if (batchNames.has(f.name)) {
        useUploadStore.getState().setError(`Duplicate file name in selection: ${f.name}`);
        return false;
      }
      batchNames.add(f.name);
    }

    // Identify which files already exist in the target folder
    const folder = useFolderStore.getState().folders[folderId];
    const existingByName = new Map<string, string>(); // name → fileId
    const existingFolderNames = new Set<string>();
    if (folder) {
      for (const child of folder.children) {
        if (child.type === 'file') {
          existingByName.set(child.name, child.id);
        } else if (child.type === 'folder') {
          existingFolderNames.add(child.name);
        }
      }
    }

    // Fail fast on file–folder name collisions
    const folderNameConflicts = files.filter((f) => existingFolderNames.has(f.name));
    if (folderNameConflicts.length > 0) {
      useUploadStore
        .getState()
        .setError(
          `Cannot upload file(s) with the same name as an existing folder: ${folderNameConflicts.map((f) => f.name).join(', ')}`
        );
      return false;
    }

    const newFiles = files.filter((f) => !existingByName.has(f.name));
    const duplicateFiles = files.filter((f) => existingByName.has(f.name));

    if (!hasSdkClient()) {
      useUploadStore.getState().setError('SDK not initialized — please log in again');
      return false;
    }

    const client = getSdkClient();

    // Resolve parent folder and ensure it's registered in the SDK
    const folders = useFolderStore.getState().folders;
    const vault = useVaultStore.getState();
    const parentFolder =
      folderId === 'root' ? getRootFolderState(vault, folders) : folders[folderId];
    if (!parentFolder) {
      useUploadStore.getState().setError('Parent folder not found');
      return false;
    }
    ensureFolderRegistered(parentFolder);

    const uploadStore = useUploadStore.getState();
    // Start with all files (new + duplicates) since we encrypt all upfront
    uploadStore.startUpload(files.length);

    const uploadedCids: string[] = []; // Track for cleanup on failure

    try {
      // Upload new files via SDK (atomic: encrypt → IPFS → FilePointer → IPNS publish)
      for (const file of newFiles) {
        if (useUploadStore.getState().status === 'cancelled') {
          throw new Error('Upload cancelled by user');
        }

        useUploadStore.getState().setUploading(file.name, 0);

        // Read File to Uint8Array
        const data = new Uint8Array(await file.arrayBuffer());

        const result = await client.uploadFile(
          parentFolder.ipnsName,
          data,
          file.name,
          file.type || 'application/octet-stream',
          (percent) => useUploadStore.getState().setUploading(file.name, percent)
        );

        uploadedCids.push(result.cid);
        useUploadStore.getState().fileComplete();
      }

      // Handle duplicate files: encrypt + upload to IPFS, then surface as pending replacements
      // (These don't get registered in the folder — the user decides via the Replace dialog)
      if (duplicateFiles.length > 0) {
        const replacements: PendingReplacement[] = [];

        // Hoist dynamic imports before the loop to avoid per-iteration async overhead
        const { encryptFile } = await import('../services/file-crypto.service');
        const { addToIpfs } = await import('../lib/api/ipfs');

        for (const file of duplicateFiles) {
          if (useUploadStore.getState().status === 'cancelled') {
            throw new Error('Upload cancelled by user');
          }

          useUploadStore.getState().setUploading(file.name, 0);

          // For duplicates, we only encrypt + upload to IPFS (don't register in folder)
          // Use the old upload service for this since SDK's uploadFile registers in folder
          const userPublicKey = useAuthStore.getState().vaultKeypair?.publicKey;
          if (!userPublicKey) throw new Error('No keypair available');
          const encrypted = await encryptFile(file, userPublicKey);
          // Pass Uint8Array directly — never use .buffer (may include extra bytes)
          const blob = new Blob([encrypted.ciphertext], {
            type: 'application/octet-stream',
          });
          const ipfsResult = await addToIpfs(blob, (percent) =>
            useUploadStore.getState().setUploading(file.name, percent)
          );

          uploadedCids.push(ipfsResult.cid);
          useUploadStore.getState().fileComplete();

          const existingFileId = existingByName.get(file.name);
          if (existingFileId) {
            replacements.push({
              fileName: file.name,
              fileId: existingFileId,
              parentId: folderId,
              encryptedData: {
                cid: ipfsResult.cid,
                wrappedKey: encrypted.wrappedKey,
                iv: encrypted.iv,
                size: file.size,
                encryptionMode: encrypted.encryptionMode,
              },
            });
          }
        }

        if (replacements.length > 0) {
          useUploadStore.getState().setPendingReplacements(replacements);
        }
      }

      useUploadStore.getState().setSuccess();
      return true;
    } catch (err) {
      const message = (err as Error).message;
      if (message !== 'Upload cancelled by user') {
        useUploadStore.getState().setError(message);
      }
      // Best-effort cleanup: unpin orphaned CIDs from failed upload
      if (uploadedCids.length > 0) {
        import('../lib/api/ipfs').then(({ unpinFromIpfs }) => {
          for (const cid of uploadedCids) {
            unpinFromIpfs(cid).catch(() => {});
          }
        }).catch(() => {});
      }
      return false;
    } finally {
      // Refresh quota from server
      await useQuotaStore.getState().fetchQuota();
    }
  }, []);

  return { handleFileDrop, isUploading };
}

