  1→/**
  2→ * @cipherbox/sdk - CipherBoxClient
  3→ *
  4→ * Stateful client orchestrating folder CRUD, file upload/download,
  5→ * and event-driven change notification. Wraps @cipherbox/sdk-core
  6→ * stateless functions with internal state management (FolderTree, KeyCache).
  7→ *
  8→ * Design principles:
  9→ * - Zero React/Zustand/browser dependencies
 10→ * - All state flows through typed events (SdkEvent)
 11→ * - Operations are wrapped with withOperation() for consistent
 12→ *   start/end/error event emission
 13→ * - Key material is cleared on destroy()
 14→ */
 15→
 16→import type { SdkContext, ProgressCallback, DownloadProgressCallback } from '@cipherbox/sdk-core';
 17→import * as sdkCore from '@cipherbox/sdk-core';
 18→import type { FolderChild } from '@cipherbox/core';
 19→import type { CipherBoxClientConfig, FolderState } from './types';
 20→import { SdkEventEmitter, type SdkEvent, type SdkEventHandler } from './events';
 21→import { FolderTree } from './state/folder-tree';
 22→import { KeyCache } from './state/key-cache';
 23→import * as binOps from './bin';
 24→import type { BinState } from './bin';
 25→import * as shareOps from './share';
 26→import type { SentShareInfo } from './share';
 27→
 28→/** Thrown when a bin operation is attempted before loadBin() has been called. */
 29→export class BinNotLoadedError extends Error {
 30→  constructor() {
 31→    super('Bin not loaded');
 32→    this.name = 'BinNotLoadedError';
 33→  }
 34→}
 35→
 36→export class CipherBoxClient {
 37→  private config: CipherBoxClientConfig;
 38→  private ctx: SdkContext;
 39→  private emitter: SdkEventEmitter;
 40→  private folderTree: FolderTree;
 41→  private keyCache: KeyCache;
 42→  private binState: BinState | null = null;
 43→
 44→  constructor(config: CipherBoxClientConfig) {
 45→    this.config = config;
 46→    this.ctx = {
 47→      apiUrl: config.apiUrl,
 48→      getAccessToken: config.getAccessToken,
 49→    };
 50→    this.emitter = new SdkEventEmitter();
 51→    this.folderTree = new FolderTree();
 52→    this.keyCache = new KeyCache();
 53→  }
 54→
 55→  // ---- Event subscription ----
 56→
 57→  /** Subscribe to SDK events. Returns an unsubscribe function. */
 58→  on(handler: SdkEventHandler): () => void {
 59→    return this.emitter.on(handler);
 60→  }
 61→
 62→  /** Unsubscribe a previously registered handler. */
 63→  off(handler: SdkEventHandler): void {
 64→    this.emitter.off(handler);
 65→  }
 66→
 67→  // ---- Lifecycle ----
 68→
 69→  /**
 70→   * Destroy the client, clearing all sensitive state.
 71→   * After calling destroy(), the client instance should not be reused.
 72→   */
 73→  destroy(): void {
 74→    this.folderTree.clear();
 75→    this.keyCache.clear();
 76→    this.emitter.removeAll();
 77→  }
 78→
 79→  /**
 80→   * Check if the SDK already has state for a folder.
 81→   *
 82→   * @param ipnsName - Folder's IPNS name
 83→   * @returns true if the folder is registered in the SDK's FolderTree
 84→   */
 85→  hasFolder(ipnsName: string): boolean {
 86→    return this.folderTree.has(ipnsName);
 87→  }
 88→
 89→  /**
 90→   * Get the current sequence number for a folder in the SDK's internal state.
 91→   * Returns undefined if the folder is not registered.
 92→   */
 93→  getFolderSequenceNumber(ipnsName: string): bigint | undefined {
 94→    return this.folderTree.get(ipnsName)?.sequenceNumber;
 95→  }
 96→
 97→  /**
 98→   * Get the IPNS private key for a folder in the SDK's internal state.
 99→   * Returns undefined if the folder is not registered or has no key.
100→   *
101→   * Used by ensureFolderRegistered to preserve SDK's correct IPNS key
102→   * when the store has an empty placeholder (SDK-created folders store
103→   * keys internally, not in Zustand).
104→   */
105→  getFolderIpnsPrivateKey(ipnsName: string): Uint8Array | undefined {
106→    const key = this.folderTree.get(ipnsName)?.ipnsKeypair?.privateKey;
107→    return key && key.length > 0 ? key : undefined;
108→  }
109→
110→  /**
111→   * Register an externally-loaded folder into the SDK's internal state.
112→   *
113→   * Used when folder metadata is loaded outside the SDK (e.g., by a navigation
114→   * hook) but the SDK needs to know about the folder for mutation operations
115→   * (create, rename, move, delete, upload).
116→   *
117→   * This is a bridge method for gradual SDK adoption -- eventually all folder
118→   * loading should go through client.loadFolder().
119→   *
120→   * @param ipnsName - Folder's IPNS name
121→   * @param folderKey - Decrypted AES-256 folder key
122→   * @param ipnsKeypair - Ed25519 keypair for IPNS signing
123→   * @param children - Current folder children
124→   * @param sequenceNumber - Current IPNS sequence number
125→   */
126→  registerFolder(
127→    ipnsName: string,
128→    folderKey: Uint8Array,
129→    ipnsKeypair: { publicKey: Uint8Array; privateKey: Uint8Array },
130→    children: FolderChild[],
131→    sequenceNumber: bigint
132→  ): void {
133→    this.folderTree.set(ipnsName, {
134→      ipnsName,
135→      folderKey,
136→      ipnsKeypair,
137→      sequenceNumber,
138→      children,
139→      metadata: null,
140→      lastLoadedAt: Date.now(),
141→    });
142→  }
143→
144→  // ---- Internal state access (for bin/share modules) ----
145→
146→  /** @internal Get the folder tree for bin/share operations */
147→  getFolderTree(): FolderTree {
148→    return this.folderTree;
149→  }
150→
151→  /** @internal Get the SDK context */
152→  getContext(): SdkContext {
153→    return this.ctx;
154→  }
155→
156→  /** @internal Get the client config */
157→  getConfig(): CipherBoxClientConfig {
158→    return this.config;
159→  }
160→
161→  /** @internal Emit an event (used by bin/share modules) */
162→  emitEvent(event: SdkEvent): void {
163→    this.emitter.emit(event);
164→  }
165→
166→  // ---- Folder operations ----
167→
168→  /**
169→   * Load a folder's metadata from IPNS.
170→   *
171→   * Resolves the folder's IPNS record, decrypts metadata, stores state
172→   * internally, and emits a 'folder:loaded' event.
173→   *
174→   * @param ipnsName - Folder's IPNS name
175→   * @param folderKey - Decrypted AES-256 folder key
176→   * @param ipnsKeypair - Ed25519 keypair for IPNS signing
177→   * @returns The loaded folder state, or null if IPNS record not found
178→   */
179→  async loadFolder(
180→    ipnsName: string,
181→    folderKey: Uint8Array,
182→    ipnsKeypair: { publicKey: Uint8Array; privateKey: Uint8Array }
183→  ): Promise<FolderState | null> {
184→    return this.withOperation('loadFolder', async () => {
185→      const result = await sdkCore.loadFolderMetadata({
186→        ipnsName,
187→        folderKey,
188→        ctx: this.ctx,
189→      });
190→
191→      if (!result) return null;
192→
193→      const state: FolderState = {
194→        ipnsName,
195→        folderKey,
196→        ipnsKeypair,
197→        sequenceNumber: result.sequenceNumber,
198→        children: result.metadata.children,
199→        metadata: result.metadata,
200→        lastLoadedAt: Date.now(),
201→      };
202→
203→      this.folderTree.set(ipnsName, state);
204→
205→      this.emitter.emit({
206→        type: 'folder:loaded',
207→        folderId: ipnsName,
208→        ipnsName,
209→        children: result.metadata.children,
210→      });
211→
212→      return state;
213→    });
214→  }
215→
216→  /**
217→   * Create a new subfolder inside an existing folder.
218→   *
219→   * Generates IPNS keypair and folder key, wraps with user's public key,
220→   * adds folder entry to parent metadata, publishes parent IPNS record,
221→   * and publishes empty folder metadata for the new subfolder.
222→   *
223→   * @param parentIpnsName - IPNS name of the parent folder
224→   * @param name - Name for the new subfolder
225→   * @returns Created folder's UUID, IPNS name, folder key, and IPNS private key
226→   */
227→  async createFolder(
228→    parentIpnsName: string,
229→    name: string
230→  ): Promise<{ id: string; ipnsName: string; folderKey: Uint8Array; ipnsPrivateKey: Uint8Array }> {
231→    return this.withOperation('createFolder', async () => {
232→      const parent = this.folderTree.get(parentIpnsName);
233→      if (!parent) throw new Error('Parent folder not loaded');
234→
235→      // 1. Create subfolder (generates keys, wraps with user public key)
236→      const { folder, ipnsPrivateKey, folderKey, encryptedIpnsPrivateKey, keyEpoch } =
237→        await sdkCore.createSubfolder({
238→          name,
239→          userPublicKey: this.config.vaultKeypair.publicKey,
240→          teeKeys: this.config.teeKeys,
241→        });
242→
243→      // 2. Add folder entry to parent's children
244→      const updatedChildren: FolderChild[] = [...parent.children, folder];
245→
246→      // 3. Update parent metadata and publish
247→      const { newSequenceNumber } = await sdkCore.updateFolderMetadataAndPublish({
248→        children: updatedChildren,
249→        folderKey: parent.folderKey,
250→        ipnsPrivateKey: parent.ipnsKeypair.privateKey,
251→        ipnsName: parentIpnsName,
252→        sequenceNumber: parent.sequenceNumber,
253→        ctx: this.ctx,
254→        encryptedIpnsPrivateKey: encryptedIpnsPrivateKey,
255→        keyEpoch,
256→      });
257→
258→      // 4. Update parent state
259→      parent.children = updatedChildren;
260→      parent.sequenceNumber = newSequenceNumber;
261→      parent.lastLoadedAt = Date.now();
262→      this.folderTree.set(parentIpnsName, parent);
263→
264→      // 5. Publish empty metadata for the new subfolder
265→      await sdkCore.updateFolderMetadataAndPublish({
266→        children: [],
267→        folderKey,
268→        ipnsPrivateKey,
269→        ipnsName: folder.ipnsName,
270→        sequenceNumber: 0n,
271→        ctx: this.ctx,
272→        encryptedIpnsPrivateKey,
273→        keyEpoch,
274→      });
275→
276→      // 7. Emit parent folder updated event
277→      this.emitter.emit({
278→        type: 'folder:updated',
279→        folderId: parentIpnsName,
280→        ipnsName: parentIpnsName,
281→        children: updatedChildren,
282→      });
283→
284→      return { id: folder.id, ipnsName: folder.ipnsName, folderKey, ipnsPrivateKey };
285→    });
286→  }
287→
288→  /**
289→   * Rename a child entry (folder or file) in a folder.
290→   *
291→   * Updates the name in the folder's metadata and publishes the change.
292→   *
293→   * @param folderIpnsName - IPNS name of the folder containing the item
294→   * @param childId - ID of the child to rename
295→   * @param newName - New name for the child
296→   */
297→  async renameItem(folderIpnsName: string, childId: string, newName: string): Promise<void> {
298→    return this.withOperation('renameItem', async () => {
299→      const folder = this.folderTree.get(folderIpnsName);
300→      if (!folder) throw new Error('Folder not loaded');
301→
302→      // 1. Rename in metadata (pure operation)
303→      const { updatedChildren } = sdkCore.renameInFolder({
304→        children: folder.children,
305→        childId,
306→        newName,
307→      });
308→
309→      // 2. Publish updated metadata
310→      const { newSequenceNumber } = await sdkCore.updateFolderMetadataAndPublish({
311→        children: updatedChildren,
312→        folderKey: folder.folderKey,
313→        ipnsPrivateKey: folder.ipnsKeypair.privateKey,
314→        ipnsName: folderIpnsName,
315→        sequenceNumber: folder.sequenceNumber,
316→        ctx: this.ctx,
317→      });
318→
319→      // 3. Update internal state
320→      folder.children = updatedChildren;
321→      folder.sequenceNumber = newSequenceNumber;
322→      folder.lastLoadedAt = Date.now();
323→      this.folderTree.set(folderIpnsName, folder);
324→
325→      // 4. Emit update event
326→      this.emitter.emit({
327→        type: 'folder:updated',
328→        folderId: folderIpnsName,
329→        ipnsName: folderIpnsName,
330→        children: updatedChildren,
331→      });
332→    });
333→  }
334→
335→  /**
336→   * Move a child entry between two folders.
337→   *
338→   * Removes from source, adds to destination, publishes both IPNS records
339→   * (destination first for crash safety -- add-before-remove pattern).
340→   *
341→   * @param sourceIpnsName - IPNS name of the source folder
342→   * @param destIpnsName - IPNS name of the destination folder
343→   * @param childId - ID of the child to move
344→   */
345→  async moveItem(sourceIpnsName: string, destIpnsName: string, childId: string): Promise<void> {
346→    return this.withOperation('moveItem', async () => {
347→      const source = this.folderTree.get(sourceIpnsName);
348→      const dest = this.folderTree.get(destIpnsName);
349→      if (!source) throw new Error('Source folder not loaded');
350→      if (!dest) throw new Error('Destination folder not loaded');
351→
352→      // 1. Compute updated children for both folders (pure operation)
353→      const { updatedSourceChildren, updatedDestChildren } = sdkCore.moveItem({
354→        sourceChildren: source.children,
355→        destChildren: dest.children,
356→        childId,
357→      });
358→
359→      // 2. Publish destination first (add-before-remove for crash safety)
360→      const destResult = await sdkCore.updateFolderMetadataAndPublish({
361→        children: updatedDestChildren,
362→        folderKey: dest.folderKey,
363→        ipnsPrivateKey: dest.ipnsKeypair.privateKey,
364→        ipnsName: destIpnsName,
365→        sequenceNumber: dest.sequenceNumber,
366→        ctx: this.ctx,
367→      });
368→
369→      // 3. Publish source (remove)
370→      const sourceResult = await sdkCore.updateFolderMetadataAndPublish({
371→        children: updatedSourceChildren,
372→        folderKey: source.folderKey,
373→        ipnsPrivateKey: source.ipnsKeypair.privateKey,
374→        ipnsName: sourceIpnsName,
375→        sequenceNumber: source.sequenceNumber,
376→        ctx: this.ctx,
377→      });
378→
379→      // 4. Update internal state
380→      source.children = updatedSourceChildren;
381→      source.sequenceNumber = sourceResult.newSequenceNumber;
382→      dest.children = updatedDestChildren;
383→      dest.sequenceNumber = destResult.newSequenceNumber;
384→      this.folderTree.set(sourceIpnsName, source);
385→      this.folderTree.set(destIpnsName, dest);
386→
387→      // 5. Emit events for both folders
388→      this.emitter.emit({
389→        type: 'folder:updated',
390→        folderId: sourceIpnsName,
391→        ipnsName: sourceIpnsName,
392→        children: updatedSourceChildren,
393→      });
394→      this.emitter.emit({
395→        type: 'folder:updated',
396→        folderId: destIpnsName,
397→        ipnsName: destIpnsName,
398→        children: updatedDestChildren,
399→      });
400→    });
401→  }
