454→  /**
455→   * Upload a file to a folder.
456→   *
457→   * Encrypts the file, uploads to IPFS, creates per-file IPNS metadata,
458→   * adds a FilePointer to the parent folder's metadata, and publishes.
459→   *
460→   * @param folderIpnsName - IPNS name of the target folder
461→   * @param data - Raw file content as Uint8Array
462→   * @param fileName - Display name for the file
463→   * @param mimeType - MIME type of the file
464→   * @param onProgress - Optional upload progress callback
465→   * @returns CID of the uploaded encrypted file
466→   */
467→  async uploadFile(
468→    folderIpnsName: string,
469→    data: Uint8Array,
470→    fileName: string,
471→    mimeType: string,
472→    onProgress?: ProgressCallback
473→  ): Promise<{ cid: string }> {
474→    return this.withOperation('uploadFile', async () => {
475→      const folder = this.folderTree.get(folderIpnsName);
476→      if (!folder) throw new Error('Folder not loaded');
477→
478→      const fileId = crypto.randomUUID();
479→
480→      // 1. Encrypt and upload file, create file metadata
481→      const uploadResult = await sdkCore.uploadFile({
482→        data,
483→        fileId,
484→        mimeType,
485→        folderKey: folder.folderKey,
486→        userPublicKey: this.config.vaultKeypair.publicKey,
487→        ctx: this.ctx,
488→        onProgress,
489→        teeKeys: this.config.teeKeys,
490→      });
491→
492→      // 2. Add FilePointer to folder's children
493→      const { updatedChildren } = sdkCore.addFilePointerToFolder({
494→        children: folder.children,
495→        fileId,
496→        fileName,
497→        fileMetaIpnsName: uploadResult.fileMetaIpnsName,
498→        ipnsPrivateKeyEncrypted: uploadResult.ipnsPrivateKeyEncrypted,
499→      });
500→
501→      // 3. Batch publish: file metadata IPNS + folder metadata IPNS
502→      await sdkCore.batchPublishIpnsRecords([uploadResult.ipnsRecord]);
503→
504→      const { newSequenceNumber } = await sdkCore.updateFolderMetadataAndPublish({
505→        children: updatedChildren,
506→        folderKey: folder.folderKey,
507→        ipnsPrivateKey: folder.ipnsKeypair.privateKey,
508→        ipnsName: folderIpnsName,
509→        sequenceNumber: folder.sequenceNumber,
510→        ctx: this.ctx,
511→      });
512→
513→      // 4. Update internal state
514→      folder.children = updatedChildren;
515→      folder.sequenceNumber = newSequenceNumber;
516→      folder.lastLoadedAt = Date.now();
517→      this.folderTree.set(folderIpnsName, folder);
518→
519→      // 5. Emit events
520→      this.emitter.emit({
521→        type: 'file:uploaded',
522→        folderId: folderIpnsName,
523→        fileName,
524→        cid: uploadResult.cid,
525→      });
526→      this.emitter.emit({
527→        type: 'folder:updated',
528→        folderId: folderIpnsName,
529→        ipnsName: folderIpnsName,
530→        children: updatedChildren,
531→      });
532→
533→      return { cid: uploadResult.cid };
534→    });
535→  }
