584→   * @param onProgress - Optional download progress callback
585→   * @returns Decrypted file content
586→   */
587→  async downloadFile(
588→    cid: string,
589→    fileKeyEncrypted: string,
590→    fileIv: string,
591→    encryptionMode?: 'GCM' | 'CTR',
