823→  // ---- Operation wrapper ----
824→
825→  /**
826→   * Wrap an async operation with event emission and error handling.
827→   *
828→   * Emits 'operation:start' before, 'operation:end' on success (with duration),
829→   * and 'error' on failure. Also calls the config callbacks if provided.
830→   */
831→  private async withOperation<T>(name: string, fn: () => Promise<T>): Promise<T> {
832→    const start = Date.now();
833→    this.config.onOperationStart?.(name);
834→    this.emitter.emit({ type: 'operation:start', operation: name });
835→
836→    try {
837→      const result = await fn();
838→      const durationMs = Date.now() - start;
839→      this.config.onOperationEnd?.(name);
840→      this.emitter.emit({ type: 'operation:end', operation: name, durationMs });
841→      return result;
842→    } catch (error) {
843→      this.config.onError?.(error as Error);
844→      this.emitter.emit({ type: 'error', operation: name, error: error as Error });
845→      throw error;
846→    }
847→  }
848→}
