126→// ---------------------------------------------------------------------------
127→// Public API
128→// ---------------------------------------------------------------------------
129→
130→/**
131→ * Load the recycle bin metadata from IPNS.
132→ *
133→ * If no bin IPNS record exists yet (first login / never deleted anything),
134→ * returns an empty BinState so that deleteToBin can create the first record.
135→ * The old bin service handled this by creating in-memory-only empty state;
136→ * the SDK must do the same to avoid "Bin not loaded" errors on first delete.
137→ *
138→ * @returns Current bin state (never null — empty state if no record exists)
139→ */
140→export async function loadBin(params: { binCtx: BinOperationContext }): Promise<BinState> {
141→  const loaded = await loadBinMetadataInternal({
142→    userPrivateKey: params.binCtx.userPrivateKey,
143→    ctx: params.binCtx.ctx,
144→  });
145→
146→  if (!loaded) {
147→    // No bin IPNS record exists yet — return empty state.
148→    // The first addToBin call will create the IPNS record.
149→    const binIpns = await deriveBinIpnsKeypair(params.binCtx.userPrivateKey);
150→    return {
151→      entries: [],
152→      sequenceNumber: 0,
153→      ipnsName: binIpns.ipnsName,
154→    };
155→  }
156→
157→  return {
158→    entries: loaded.metadata.entries,
159→    sequenceNumber: loaded.metadata.sequenceNumber,
160→    ipnsName: loaded.ipnsName,
161→  };
162→}
163→
164→/**
165→ * Add item to recycle bin.
166→ *
167→ * Removes the item from the folder metadata (via deleteFromFolder),
168→ * creates a BinEntry, appends to bin metadata, and publishes both.
169→ *
170→ * @returns The removed item from the folder
171→ */
172→export async function addToBin(params: {
173→  folderIpnsName: string;
174→  childId: string;
175→  parentPath: string;
176→  folderTree: FolderTree;
177→  binState: BinState;
178→  binCtx: BinOperationContext;
179→}): Promise<{ removedItem: FolderChild; updatedBinState: BinState }> {
180→  const folder = params.folderTree.get(params.folderIpnsName);
181→  if (!folder) throw new Error('Folder not loaded');
182→
183→  // 1. Remove item from folder metadata
184→  const { updatedChildren, removedItem } = sdkCore.deleteFromFolder({
185→    children: folder.children,
186→    childId: params.childId,
187→  });
188→
189→  // 2. Publish updated folder metadata
190→  const { newSequenceNumber } = await sdkCore.updateFolderMetadataAndPublish({
191→    children: updatedChildren,
192→    folderKey: folder.folderKey,
193→    ipnsPrivateKey: folder.ipnsKeypair.privateKey,
194→    ipnsName: params.folderIpnsName,
195→    sequenceNumber: folder.sequenceNumber,
196→    ctx: params.binCtx.ctx,
197→  });
198→
199→  // 3. Update folder state
200→  folder.children = updatedChildren;
201→  folder.sequenceNumber = newSequenceNumber;
202→  folder.lastLoadedAt = Date.now();
203→  params.folderTree.set(params.folderIpnsName, folder);
204→
205→  // 4. Build bin entry
206→  const isFile = removedItem.type === 'file';
207→  const entry: BinEntry = {
208→    id: crypto.randomUUID(),
209→    itemType: isFile ? 'file' : 'folder',
210→    name: removedItem.name,
211→    originalParentIpnsName: params.folderIpnsName,
212→    originalPath: params.parentPath,
213→    deletedAt: Date.now(),
214→    size: 0,
215→    mimeType: '',
216→    filePointer: isFile ? (removedItem as FilePointer) : undefined,
217→    folderEntry: !isFile ? (removedItem as FolderEntry) : undefined,
218→  };
219→
220→  // 5. Update bin metadata and publish
221→  const updatedEntries = [...params.binState.entries, entry];
222→  const newBinSeq = params.binState.sequenceNumber + 1;
223→
224→  const metadata: RecycleBinMetadata = {
225→    version: BIN_METADATA_VERSION,
226→    sequenceNumber: newBinSeq,
227→    entries: updatedEntries,
228→  };
229→
230→  await saveBinMetadata({ metadata, binCtx: params.binCtx });
231→
232→  const updatedBinState: BinState = {
233→    entries: updatedEntries,
234→    sequenceNumber: newBinSeq,
235→    ipnsName: params.binState.ipnsName,
236→  };
237→
238→  return { removedItem, updatedBinState };
239→}
240→
241→/**
242→ * Restore an item from the recycle bin back to a folder.
243→ *
244→ * Removes the entry from bin metadata, adds the preserved FolderChild
245→ * back to the target folder's children, and publishes both.
246→ */
247→export async function restoreFromBin(params: {
248→  entryId: string;
249→  targetFolderIpnsName: string;
250→  folderTree: FolderTree;
251→  binState: BinState;
252→  binCtx: BinOperationContext;
253→}): Promise<{ restoredItem: FolderChild; updatedBinState: BinState }> {
254→  // 1. Find the bin entry
255→  const entry = params.binState.entries.find((e) => e.id === params.entryId);
256→  if (!entry) throw new Error('Bin entry not found');
257→
258→  // 2. Get the FolderChild to restore
259→  let child: FolderChild;
260→  if (entry.itemType === 'file' && entry.filePointer) {
261→    child = { ...entry.filePointer, modifiedAt: Date.now() };
262→  } else if (entry.itemType === 'folder' && entry.folderEntry) {
263→    child = { ...entry.folderEntry, modifiedAt: Date.now() };
264→  } else {
265→    throw new Error('Bin entry has no stored item reference');
266→  }
267→
268→  // 3. Add child back to target folder
269→  const targetFolder = params.folderTree.get(params.targetFolderIpnsName);
270→  if (!targetFolder) throw new Error('Target folder not loaded');
271→
272→  // Handle name collisions
273→  const existingNames = new Set(targetFolder.children.map((c) => c.name));
274→  if (existingNames.has(child.name)) {
275→    let newName = `${child.name} (restored)`;
276→    let counter = 2;
277→    while (existingNames.has(newName)) {
278→      newName = `${child.name} (restored ${counter})`;
279→      counter++;
280→    }
281→    child = { ...child, name: newName };
282→  }
283→
284→  const updatedFolderChildren = [...targetFolder.children, child];
285→
286→  // 4. Publish updated folder metadata
287→  const { newSequenceNumber } = await sdkCore.updateFolderMetadataAndPublish({
288→    children: updatedFolderChildren,
289→    folderKey: targetFolder.folderKey,
290→    ipnsPrivateKey: targetFolder.ipnsKeypair.privateKey,
291→    ipnsName: params.targetFolderIpnsName,
292→    sequenceNumber: targetFolder.sequenceNumber,
293→    ctx: params.binCtx.ctx,
294→  });
295→
296→  // 5. Update folder state
297→  targetFolder.children = updatedFolderChildren;
298→  targetFolder.sequenceNumber = newSequenceNumber;
299→  targetFolder.lastLoadedAt = Date.now();
300→  params.folderTree.set(params.targetFolderIpnsName, targetFolder);
301→
302→  // 6. Remove entry from bin and publish
303→  const remainingEntries = params.binState.entries.filter((e) => e.id !== params.entryId);
304→  const newBinSeq = params.binState.sequenceNumber + 1;
305→
306→  const metadata: RecycleBinMetadata = {
307→    version: BIN_METADATA_VERSION,
308→    sequenceNumber: newBinSeq,
309→    entries: remainingEntries,
310→  };
311→
312→  await saveBinMetadata({ metadata, binCtx: params.binCtx });
313→
314→  const updatedBinState: BinState = {
315→    entries: remainingEntries,
316→    sequenceNumber: newBinSeq,
317→    ipnsName: params.binState.ipnsName,
318→  };
319→
320→  return { restoredItem: child, updatedBinState };
321→}
322→
323→/**
324→ * Permanently delete a bin entry (unpin CIDs, remove from bin metadata).
325→ *
326→ * For files: unpins the content CID if available.
327→ * Does NOT handle recursive folder cleanup (that requires deep IPNS traversal).
328→ */
329→export async function permanentDeleteFromBin(params: {
330→  entryId: string;
331→  binState: BinState;
332→  binCtx: BinOperationContext;
333→}): Promise<{ updatedBinState: BinState }> {
334→  const entry = params.binState.entries.find((e) => e.id === params.entryId);
335→  if (!entry) throw new Error('Bin entry not found');
336→
337→  // Unpin content CID if available (best-effort)
338→  if (entry.contentCid) {
339→    try {
340→      await sdkCore.unpinFromIpfs(params.binCtx.ctx, entry.contentCid);
341→    } catch {
342→      // Best-effort CID cleanup
343→    }
344→  }
345→
346→  // Remove from bin metadata and publish
347→  const remainingEntries = params.binState.entries.filter((e) => e.id !== params.entryId);
348→  const newBinSeq = params.binState.sequenceNumber + 1;
349→
350→  const metadata: RecycleBinMetadata = {
351→    version: BIN_METADATA_VERSION,
352→    sequenceNumber: newBinSeq,
353→    entries: remainingEntries,
354→  };
355→
356→  await saveBinMetadata({ metadata, binCtx: params.binCtx });
357→
358→  return {
359→    updatedBinState: {
360→      entries: remainingEntries,
361→      sequenceNumber: newBinSeq,
362→      ipnsName: params.binState.ipnsName,
363→    },
364→  };
365→}
366→
367→/**
368→ * Empty the bin by permanently deleting all entries.
369→ *
370→ * Cleans up CIDs (best-effort) and publishes empty bin metadata.
371→ */
372→export async function emptyBin(params: {
373→  binState: BinState;
374→  binCtx: BinOperationContext;
375→}): Promise<{ updatedBinState: BinState }> {
376→  // Best-effort CID cleanup for each entry
377→  for (const entry of params.binState.entries) {
378→    if (entry.contentCid) {
379→      try {
380→        await sdkCore.unpinFromIpfs(params.binCtx.ctx, entry.contentCid);
381→      } catch {
382→        // Non-blocking
383→      }
384→    }
385→  }
386→
387→  // Publish empty bin metadata
388→  const newBinSeq = params.binState.sequenceNumber + 1;
389→  const metadata: RecycleBinMetadata = {
390→    version: BIN_METADATA_VERSION,
391→    sequenceNumber: newBinSeq,
392→    entries: [],
393→  };
394→
395→  await saveBinMetadata({ metadata, binCtx: params.binCtx });
396→
397→  return {
398→    updatedBinState: {
399→      entries: [],
400→      sequenceNumber: newBinSeq,
401→      ipnsName: params.binState.ipnsName,
402→    },
403→  };
404→}
