 29→export function useAuth() {
 30→  const navigate = useNavigate();
 31→  const {
 32→    isLoggedIn: coreKitLoggedIn,
 33→    isInitialized: coreKitInitialized,
 34→    isRequiredShare,
 35→    loginWithGoogle: coreKitLoginGoogle,
 36→    loginWithEmailOtp: coreKitLoginEmail,
 37→    loginWithWallet: coreKitLoginWallet,
 38→    getVaultKeypair,
 39→    getPublicKeyHex,
 40→    logout: coreKitLogout,
 41→  } = useCoreKitAuth();
 42→  const { syncStatus } = useCoreKit();
 43→  const {
 44→    accessToken,
 45→    isAuthenticated,
 46→    lastAuthMethod,
 47→    userEmail,
 48→    setAccessToken,
 49→    setLastAuthMethod,
 50→    setUserEmail,
 51→    setVaultKeypair,
 52→  } = useAuthStore();
 53→
 54→  const [isLoggingIn, setIsLoggingIn] = useState(false);
 55→  const [isLoggingOut, setIsLoggingOut] = useState(false);
 56→  const restoringRef = useRef(false);
 57→
 58→  // Stable refs for functions used in the session restoration effect.
 59→  // This prevents the effect from re-firing when function references change.
 60→  const initializeOrLoadVaultRef = useRef<(() => Promise<void>) | null>(null);
 61→  const coreKitLogoutRef = useRef<(() => Promise<void>) | null>(null);
 62→
 63→  // Pending auth state for REQUIRED_SHARE flow.
 64→  // Stored in Zustand (not useState) so the state is shared across all
 65→  // useAuth() hook instances — Login.tsx sets it, useDeviceApproval reads it
 66→  // via its own useAuth() call.
 67→  const pendingAuthMethod = useAuthStore((s) => s.pendingAuthMethod);
 68→  const setPendingAuth = useAuthStore((s) => s.setPendingAuth);
 69→
 70→  const isLoading = !coreKitInitialized || isLoggingIn || isLoggingOut;
 71→
 72→  // Get vault store actions
 73→  const setVaultKeys = useVaultStore((state) => state.setVaultKeys);
 74→
 75→  /**
 76→   * Initialize vault for new users or load existing vault keys.
 77→   * Called after successful backend authentication.
 78→   * Uses Core Kit's getVaultKeypair() instead of PnP provider.
 79→   */
 80→  const initializeOrLoadVault = useCallback(async (): Promise<void> => {
 81→    // Get user's secp256k1 keypair from Core Kit TSS export
 82→    const userKeypair = await getVaultKeypair();
 83→
 84→    if (!userKeypair) {
 85→      throw new Error('Failed to get vault keypair from Core Kit');
 86→    }
 87→
 88→    // Store keypair in auth store for crypto operations
 89→    setVaultKeypair(userKeypair);
 90→
 91→    try {
 92→      // Try to fetch existing vault
 93→      const existingVault = await vaultApi.getVault();
 94→
 95→      // Store TEE keys if available
 96→      if (existingVault.teeKeys) {
 97→        useAuthStore.getState().setTeeKeys(existingVault.teeKeys);
 98→      }
 99→
100→      // Vault exists - decrypt keys and load into store
101→      // decryptVaultKeys derives the IPNS public key internally from the decrypted private key
102→      const decryptedVault = await decryptVaultKeys(
103→        {
104→          encryptedRootFolderKey: hexToBytes(existingVault.encryptedRootFolderKey),
105→          encryptedIpnsPrivateKey: hexToBytes(existingVault.encryptedRootIpnsPrivateKey),
106→        },
107→        userKeypair.privateKey
108→      );
109→
110→      setVaultKeys({
111→        rootFolderKey: decryptedVault.rootFolderKey,
112→        rootIpnsKeypair: decryptedVault.rootIpnsKeypair,
113→        rootIpnsName: existingVault.rootIpnsName,
114→        vaultId: existingVault.id,
115→      });
116→    } catch (error) {
117→      const is404 = (error as { response?: { status?: number } })?.response?.status === 404;
118→
119→      if (is404) {
120→        // New user - initialize vault
121→        console.log(
122→          '[Auth] New user on Core Kit. If migrating from PnP, vault re-initialization may be needed.'
123→        );
124→        const newVault = await initializeVault(userKeypair.privateKey);
125→        const encryptedVault = await encryptVaultKeys(newVault, userKeypair.publicKey);
126→        const rootIpnsName = await deriveIpnsName(newVault.rootIpnsKeypair.publicKey);
127→
128→        const storedVault = await vaultApi.initVault({
129→          ownerPublicKey: bytesToHex(userKeypair.publicKey),
130→          encryptedRootFolderKey: bytesToHex(encryptedVault.encryptedRootFolderKey),
131→          encryptedRootIpnsPrivateKey: bytesToHex(encryptedVault.encryptedIpnsPrivateKey),
132→          rootIpnsName,
133→        });
134→
135→        if (storedVault.teeKeys) {
136→          useAuthStore.getState().setTeeKeys(storedVault.teeKeys);
137→        }
138→
139→        setVaultKeys({
140→          rootFolderKey: newVault.rootFolderKey,
141→          rootIpnsKeypair: newVault.rootIpnsKeypair,
142→          rootIpnsName,
143→          vaultId: storedVault.id,
144→          isNewVault: true,
145→        });
146→      } else {
147→        console.error('[useAuth] Failed to load vault:', error);
148→        throw error;
149→      }
150→    }
151→
152→    // Initialize SDK client with decrypted vault keys
153→    const vaultState = useVaultStore.getState();
154→    const authState = useAuthStore.getState();
155→    if (vaultState.rootFolderKey && vaultState.rootIpnsKeypair && vaultState.rootIpnsName) {
156→      const apiUrl = import.meta.env.VITE_API_URL || window.location.origin + '/api';
157→      const getAccessToken = async () => {
158→        const state = useAuthStore.getState();
159→        return state.accessToken || '';
160→      };
161→
162→      // Configure @cipherbox/api-client for SDK-core IPNS operations
163→      setApiClientConfig({ baseUrl: apiUrl, getAccessToken });
164→
165→      const sdkClient = initSdkClient({
166→        apiUrl,
167→        getAccessToken,
168→        vaultKeypair: {
169→          publicKey: userKeypair.publicKey,
170→          privateKey: userKeypair.privateKey,
171→        },
172→        rootIpnsName: vaultState.rootIpnsName,
173→        rootFolderKey: vaultState.rootFolderKey,
174→        teeKeys: authState.teeKeys ?? undefined,
175→      });
176→
177→      // Subscribe folder store to SDK events
178→      useFolderStore.getState().subscribeToSdk(sdkClient);
179→
180→      // Subscribe bin store to SDK events
181→      useBinStore.getState().subscribeToSdk(sdkClient);
182→    }
183→
184→    // Non-blocking device registry initialization (fire-and-forget)
185→    // Placed after vault load so registry failures never block login
186→    void (async () => {
187→      try {
188→        const deviceKeypair = await getOrCreateDeviceIdentity({
189→          mode: 'persisted',
190→          vaultPrivateKey: userKeypair.privateKey,
191→        });
192→        const deviceInfo = detectDeviceInfo();
193→        const result = await initializeOrSyncRegistry({
194→          userPrivateKey: userKeypair.privateKey,
195→          userPublicKey: userKeypair.publicKey,
196→          deviceKeypair,
197→          deviceInfo: { ...deviceInfo, ipHash: '' },
198→        });
199→        if (result) {
200→          useDeviceRegistryStore
201→            .getState()
202→            .setRegistry(result.registry, result.ipnsName, deviceKeypair.deviceId);
203→        }
204→      } catch (error) {
205→        console.error('[Auth] Device registry init failed (non-blocking):', error);
206→      }
207→    })();
208→
209→    // Non-blocking bin initialization (fire-and-forget)
210→    // After old service creates/loads bin, also load into SDK for deleteToBin support
211→    void (async () => {
212→      try {
213→        await initializeBin({
214→          userPrivateKey: userKeypair.privateKey,
215→          userPublicKey: userKeypair.publicKey,
216→        });
217→        // Now load bin into SDK (old service ensures bin IPNS record exists)
218→        const { getSdkClient, hasSdkClient } = await import('../lib/sdk-provider');
219→        if (hasSdkClient()) {
220→          await getSdkClient().loadBin();
221→        }
222→      } catch (error) {
223→        console.error('[Auth] Bin initialization failed (non-blocking):', error);
224→      }
225→    })();
226→
227→    // Non-blocking: fetch retention config from API
228→    void (async () => {
229→      try {
230→        const config = await vaultControllerGetConfig();
231→        if (config.recycleBinRetentionDays != null) {
232→          useBinStore.getState().setRetentionDays(config.recycleBinRetentionDays);
233→        }
234→      } catch (error) {
235→        console.error('[Auth] Failed to fetch vault config (non-blocking):', error);
236→      }
237→    })();
238→  }, [getVaultKeypair, setVaultKeypair, setVaultKeys]);
239→
240→  /**
241→   * Complete backend authentication after Core Kit login.
242→   * Sends the CipherBox-issued JWT (which we used for Core Kit loginWithJWT)
243→   * to the backend with loginType 'corekit'. The backend verifies it against
244→   * its own JWKS since CipherBox is the identity provider.
245→   */
246→  const completeBackendAuth = useCallback(
247→    async (authMethod: string, cipherboxJwt: string): Promise<void> => {
248→      // 1. Get real publicKey from Core Kit TSS export
249→      const publicKey = await getPublicKeyHex();
250→      if (!publicKey) {
251→        throw new Error('Failed to get publicKey from Core Kit');
252→      }
253→
254→      // publicKey available for debugging via DevTools if needed
255→
256→      // 2. Authenticate with CipherBox backend
257→      // Backend verifies our CipherBox JWT and resolves placeholder publicKey
258→      const response = await authApi.login({
259→        idToken: cipherboxJwt,
260→        publicKey,
261→        loginType: 'corekit',
262→      });
263→
264→      // 3. Store access token (refresh token in HTTP-only cookie)
265→      setAccessToken(response.accessToken);
266→
267→      // 4. Remember auth method for UX
268→      setLastAuthMethod(authMethod);
269→
270→      // 5. Initialize or load vault
271→      await initializeOrLoadVault();
272→    },
273→    [getPublicKeyHex, setAccessToken, setLastAuthMethod, initializeOrLoadVault]
274→  );
275→
276→  /**
277→   * Complete the login flow after REQUIRED_SHARE is resolved.
278→   * Called after inputFactorKey() succeeds (from recovery phrase or cross-device approval).
279→   * Uses the stored pendingCipherboxJwt to call completeBackendAuth with the REAL publicKey
280→   * (since Core Kit is now LOGGED_IN), then navigates to /files.
281→   */
282→  const completeRequiredShare = useCallback(async (): Promise<void> => {
283→    // Read directly from Zustand store to get fresh values — this callback
284→    // may be called from useDeviceApproval's useAuth() instance, so we
285→    // can't rely on closure-captured selector values.
286→    const { pendingCipherboxJwt: jwt, pendingAuthMethod: method } = useAuthStore.getState();
287→
288→    if (!jwt || !method) {
289→      throw new Error('No pending auth info for REQUIRED_SHARE completion');
290→    }
291→
292→    // Core Kit should now be LOGGED_IN after inputFactorKey()
293→    // Complete backend auth with the REAL publicKey (replaces the placeholder session)
294→    await completeBackendAuth(method, jwt);
295→
296→    // NOW sync Core Kit React state to LOGGED_IN.
297→    // We deliberately delayed this from inputFactorKey() to prevent the session
298→    // restoration effect from firing before backend auth completed.
299→    // At this point isAuthenticated is true (from completeBackendAuth -> setAccessToken),
300→    // so the session restore guard (coreKitLoggedIn && !isAuthenticated) won't trigger.
301→    syncStatus();
302→
303→    // Clear pending state
304→    setPendingAuth(null, null);
305→
306→    // Navigate to files
307→    navigate('/files');
308→  }, [completeBackendAuth, syncStatus, setPendingAuth, navigate]);
309→
310→  /**
311→   * Login with Google OAuth token.
312→   * Flow: Google idToken -> CipherBox backend -> CipherBox JWT ->
313→   * Core Kit loginWithJWT -> backend /auth/login (corekit type)
314→   */
315→  const loginWithGoogle = useCallback(
316→    async (googleIdToken: string): Promise<void> => {
317→      if (isLoggingIn) return;
318→      setIsLoggingIn(true);
319→      try {
320→        // 1. Core Kit login via CipherBox identity provider
321→        const {
322→          cipherboxJwt,
323→          email,
324→          userId,
325→          status: coreKitStatus,
326→        } = await coreKitLoginGoogle(googleIdToken);
327→
328→        if (coreKitStatus === 'required_share') {
329→          // MFA enabled but device factor missing.
330→          // Store pending auth info for later completion after factor input.
331→          setPendingAuth(cipherboxJwt, 'google');
332→
333→          // Obtain temporary backend access token so the new device can
334→          // call bulletin board API endpoints (device-approval/*).
335→          // Uses placeholder publicKey since Core Kit is in REQUIRED_SHARE
336→          // state and we can't export the TSS key yet.
337→          const tempLoginResponse = await authApi.login({
338→            idToken: cipherboxJwt,
339→            publicKey: `pending-core-kit-${userId}`,
340→            loginType: 'corekit',
341→          });
342→          setAccessToken(tempLoginResponse.accessToken);
343→
344→          if (email) {
345→            setUserEmail(email);
346→          }
347→
348→          // Do NOT call completeBackendAuth() or navigate('/files')
349→          // The component tree will see isRequiredShare === true and
350→          // render recovery/approval UI.
351→          return;
352→        }
353→
354→        // Normal path: Core Kit logged in, proceed as before
355→        // 2. Complete backend auth + vault init
356→        await completeBackendAuth('google', cipherboxJwt);
357→
358→        // 3. Store email for UI display (returned from identity endpoint)
359→        if (email) {
360→          setUserEmail(email);
361→        }
362→
363→        // Navigation handled by Login.tsx redirect effect (isAuthenticated → /files)
364→      } catch (error) {
365→        console.error('[useAuth] Google login failed:', error);
366→        throw error;
367→      } finally {
368→        setIsLoggingIn(false);
369→      }
370→    },
371→    [isLoggingIn, coreKitLoginGoogle, completeBackendAuth, setAccessToken, setUserEmail]
372→  );
373→
374→  /**
375→   * Login with Email OTP.
376→   * Flow: email+otp -> CipherBox backend -> CipherBox JWT ->
377→   * Core Kit loginWithJWT -> backend /auth/login (corekit type)
378→   */
379→  const loginWithEmail = useCallback(
380→    async (email: string, otp: string): Promise<void> => {
381→      if (isLoggingIn) return;
382→      setIsLoggingIn(true);
383→      try {
384→        // 1. Core Kit login via CipherBox identity provider
385→        const { cipherboxJwt, userId, status: coreKitStatus } = await coreKitLoginEmail(email, otp);
386→
387→        if (coreKitStatus === 'required_share') {
388→          setPendingAuth(cipherboxJwt, 'email');
389→
390→          const tempLoginResponse = await authApi.login({
391→            idToken: cipherboxJwt,
392→            publicKey: `pending-core-kit-${userId}`,
393→            loginType: 'corekit',
394→          });
395→          setAccessToken(tempLoginResponse.accessToken);
396→          setUserEmail(email);
397→          return;
398→        }
399→
400→        // Normal path
401→        await completeBackendAuth('email', cipherboxJwt);
402→        setUserEmail(email);
403→        // Navigation handled by Login.tsx redirect effect (isAuthenticated → /files)
404→      } catch (error) {
405→        console.error('[useAuth] Email login failed:', error);
406→        throw error;
407→      } finally {
408→        setIsLoggingIn(false);
409→      }
410→    },
411→    [isLoggingIn, coreKitLoginEmail, completeBackendAuth, setAccessToken, setUserEmail]
412→  );
413→
414→  /**
415→   * Login with Wallet (SIWE).
416→   * Flow: Wallet connects + signs SIWE message -> backend verifies ->
417→   * CipherBox JWT -> Core Kit loginWithJWT -> backend /auth/login (corekit type)
418→   */
419→  const loginWithWallet = useCallback(
420→    async (cipherboxJwt: string, userId: string): Promise<void> => {
421→      if (isLoggingIn) return;
422→      setIsLoggingIn(true);
423→      try {
424→        // 1. Core Kit login via CipherBox identity provider
425→        const { status: coreKitStatus } = await coreKitLoginWallet(cipherboxJwt, userId);
426→
427→        if (coreKitStatus === 'required_share') {
428→          setPendingAuth(cipherboxJwt, 'wallet');
429→
430→          const tempLoginResponse = await authApi.login({
431→            idToken: cipherboxJwt,
432→            publicKey: `pending-core-kit-${userId}`,
433→            loginType: 'corekit',
434→          });
435→          setAccessToken(tempLoginResponse.accessToken);
436→          return;
437→        }
438→
439→        // Normal path
440→        await completeBackendAuth('wallet', cipherboxJwt);
441→        // Navigation is handled by Login.tsx's redirect effect (isAuthenticated → /files).
442→        // completeBackendAuth sets the access token early, but initializeOrLoadVault()
443→        // inside it may still be pending. An explicit navigate here would fire AFTER
444→        // vault init completes — by which point the user may have navigated away from
445→        // the login page, causing a disruptive late redirect.
446→      } catch (error) {
447→        console.error('[useAuth] Wallet login failed:', error);
448→        throw error;
449→      } finally {
450→        setIsLoggingIn(false);
451→      }
452→    },
453→    [isLoggingIn, coreKitLoginWallet, completeBackendAuth, setAccessToken]
454→  );
455→
456→  /**
457→   * Legacy login() for backward compatibility with AuthButton.
458→   * With Core Kit, login requires specifying the auth method.
459→   * This will be replaced by the new Login UI in Plan 04.
460→   */
461→  const login = useCallback(async () => {
462→    // Plan 04 will build the new login UI with method selection.
463→    // For now, this is a no-op placeholder that AuthButton calls.
464→    console.warn(
465→      '[useAuth] login() called without method -- ' +
466→        'use loginWithGoogle() or loginWithEmail() instead. ' +
467→        'Plan 04 will provide the new Login UI.'
468→    );
469→  }, []);
470→
471→  // Complete logout: Backend -> Core Kit -> Clear state
472→  const logout = useCallback(async () => {
473→    if (isLoggingOut) return;
474→
475→    setIsLoggingOut(true);
476→    try {
477→      // 1. Call backend logout (clears cookie)
478→      if (accessToken) {
479→        try {
480→          await authApi.logout();
481→        } catch {
482→          // Ignore errors -- we'll clear state anyway
483→        }
484→      }
485→
486→      // 2. Logout Core Kit (clears session from localStorage)
487→      await coreKitLogout();
488→
489→      // 3. Clear all user-scoped stores (centralized helper)
490→      clearAllUserStores();
491→
492→      // 4. Navigate to login
493→      navigate('/');
494→    } catch (error) {
495→      console.error('[useAuth] Logout failed:', error);
496→      // Still clear state even if backend fails
497→      clearAllUserStores();
498→      navigate('/');
499→    } finally {
500→      setIsLoggingOut(false);
501→    }
502→  }, [accessToken, coreKitLogout, navigate, isLoggingOut]);
503→
504→  // Keep function refs up-to-date for use in session restoration effect.
505→  // Using refs prevents the effect from re-firing when function identities change.
506→  initializeOrLoadVaultRef.current = initializeOrLoadVault;
507→  coreKitLogoutRef.current = coreKitLogout;
508→
509→  // Session restoration: if Core Kit restores a session from localStorage
510→  // on init, we have LOGGED_IN status without going through login flow.
511→  // Complete backend auth + vault loading.
512→  useEffect(() => {
513→    const restoreSession = async () => {
514→      // Only restore if Core Kit has a session but we don't have
515→      // a backend access token yet
516→      if (coreKitLoggedIn && !isAuthenticated && !isLoggingIn && !restoringRef.current) {
517→        restoringRef.current = true;
518→        setIsLoggingIn(true);
519→        try {
520→          // Try to refresh using the HTTP-only cookie first
521→          const response = await authApi.refresh();
522→          setAccessToken(response.accessToken);
523→
524→          // Restore email from backend if available
525→          if (response.email) {
526→            setUserEmail(response.email);
527→          }
528→
529→          // Load vault keys from Core Kit keypair
530→          await initializeOrLoadVaultRef.current?.();
531→        } catch {
532→          // No valid backend session -- user needs to re-login
533→          // Core Kit session exists but backend cookie expired
534→          // Clear Core Kit session to avoid inconsistent state
535→          try {
536→            await coreKitLogoutRef.current?.();
537→          } catch {
538→            // Ignore logout errors during cleanup
539→          }
540→        } finally {
541→          restoringRef.current = false;
542→          setIsLoggingIn(false);
543→        }
544→      }
545→    };
546→    restoreSession();
547→  }, [coreKitLoggedIn, isAuthenticated, isLoggingIn, setAccessToken, setUserEmail]);
548→
549→  return {
550→    isLoading,
551→    isAuthenticated,
552→    isRequiredShare,
553→    lastAuthMethod,
554→    userEmail,
555→    pendingAuthMethod,
556→    login,
557→    loginWithGoogle,
558→    loginWithEmail,
559→    loginWithWallet,
560→    completeRequiredShare,
561→    logout,
562→  };
563→}
