  1→import { useState, useCallback } from 'react';
  2→import { useFolderStore } from '../stores/folder.store';
  3→import { useVaultStore } from '../stores/vault.store';
  4→import * as folderService from '../services/folder.service';
  5→import { reWrapForRecipients } from '../services/share.service';
  6→import type { FolderNode } from '../stores/folder.store';
  7→import { getSdkClient, ensureFolderRegistered } from '../lib/sdk-provider';
  8→import { BinNotLoadedError } from '@cipherbox/sdk';
  9→import { MAX_FOLDER_DEPTH, getRootFolderState } from './folder-helpers';
 10→import type { FolderOperationState } from './folder-helpers';
 11→import { useNotificationStore } from '../stores/notification.store';
