 44→/**
 45→ * React hook for folder CRUD operations (create, rename, move, delete).
 46→ *
 47→ * Operations delegate to CipherBoxClient SDK methods. The SDK handles
 48→ * crypto, metadata construction, and IPNS publishing internally. SDK
 49→ * events update the folder store via event subscriptions.
 50→ *
 51→ * The hook manages UI concerns: loading state, error handling, toasts,
 52→ * and store-level coordination (folder node management, share re-wrapping).
 53→ */
 54→export function useFolderMutations() {
 55→  const [state, setState] = useState<FolderOperationState>({
 56→    isLoading: false,
 57→    error: null,
 58→  });
 59→
 60→  /**
 61→   * Create a new folder via SDK.
 62→   *
 63→   * @param name - Folder name
 64→   * @param parentId - Parent folder ID (null for root, or folder UUID)
 65→   * @returns Created folder IPNS name and key
 66→   */
 67→  const handleCreate = useCallback(
 68→    async (name: string, parentId: string | null): Promise<{ ipnsName: string }> => {
 69→      setState({ isLoading: true, error: null });
 70→      try {
 71→        const folders = useFolderStore.getState().folders;
 72→
 73→        // Validate depth limit before creating (FOLD-03)
 74→        const parentDepth = folderService.getDepth(parentId, folders);
 75→        if (parentDepth >= MAX_FOLDER_DEPTH) {
 76→          throw new Error(`Cannot create folder: maximum depth of ${MAX_FOLDER_DEPTH} exceeded`);
 77→        }
 78→
 79→        // Resolve parent folder
 80→        const actualParentId = parentId ?? 'root';
 81→        const parentFolder = getParentFolder(actualParentId);
 82→        if (!parentFolder) {
 83→          throw new Error('Parent folder not found or vault not initialized');
 84→        }
 85→
 86→        // Ensure parent is registered in SDK's FolderTree
 87→        ensureFolderRegistered(parentFolder);
 88→
 89→        // Create folder via SDK (handles key gen, metadata update, IPNS publish)
 90→        const client = getSdkClient();
 91→        const result = await client.createFolder(parentFolder.ipnsName, name);
 92→
 93→        // SDK emits folder:updated -> store subscription updates parent's children
 94→        // But we also need to add the new folder as a store node so navigation works
 95→        const newFolderNode: FolderNode = {
 96→          id: result.id, // UUID from the FolderEntry in parent's children
 97→          name,
 98→          ipnsName: result.ipnsName,
 99→          parentId: actualParentId,
100→          children: [],
101→          isLoaded: true,
102→          isLoading: false,
103→          sequenceNumber: 0n,
104→          folderKey: result.folderKey,
105→          ipnsPrivateKey: result.ipnsPrivateKey,
106→        };
107→        useFolderStore.getState().setFolder(newFolderNode);
108→
109→        // Post-create: re-wrap new subfolder key for share recipients (fire-and-forget)
110→        reWrapForRecipients({
111→          folderIpnsName: parentFolder.ipnsName,
112→          folders: useFolderStore.getState().folders,
113→          currentFolderId: actualParentId,
114→          newItems: [
115→            { keyType: 'folder', itemId: result.ipnsName, plaintextKey: result.folderKey },
116→          ],
117→        })
118→          .then(({ failedRecipients }) => {
119→            if (failedRecipients.length > 0) {
120→              useNotificationStore
121→                .getState()
122→                .addNotification(
123→                  'warning',
124→                  `Failed to update share keys for ${failedRecipients.length} recipient(s). They may not be able to access the new folder until you re-share.`
125→                );
126→            }
127→          })
128→          .catch((err) => {
129→            console.warn('[share] Post-create subfolder re-wrapping failed:', err);
130→          });
131→
132→        setState({ isLoading: false, error: null });
133→        return { ipnsName: result.ipnsName };
134→      } catch (err) {
135→        const error = err instanceof Error ? err.message : 'Failed to create folder';
136→        setState({ isLoading: false, error });
137→        throw err;
138→      }
139→    },
140→    []
141→  );
142→
143→  /**
144→   * Rename a file or folder via SDK.
145→   *
146→   * @param itemId - ID of item to rename
147→   * @param itemType - 'file' or 'folder'
148→   * @param newName - New name
149→   * @param parentId - Parent folder ID
150→   */
151→  const handleRename = useCallback(
152→    async (
153→      itemId: string,
154→      itemType: 'file' | 'folder',
155→      newName: string,
156→      parentId: string
157→    ): Promise<void> => {
158→      setState({ isLoading: true, error: null });
159→      try {
160→        const parentFolder = getParentFolder(parentId);
161→        if (!parentFolder) throw new Error('Parent folder not found');
162→
163→        // Ensure parent is registered in SDK
164→        ensureFolderRegistered(parentFolder);
165→
166→        // Rename via SDK (handles metadata update, IPNS publish)
167→        const client = getSdkClient();
168→        await client.renameItem(parentFolder.ipnsName, itemId, newName);
169→
170→        // SDK emits folder:updated -> store subscription updates children
171→        // Also update the folder name in the store if renaming a folder
172→        if (itemType === 'folder') {
173→          useFolderStore.getState().updateFolderName(itemId, newName);
174→        }
175→
176→        setState({ isLoading: false, error: null });
177→      } catch (err) {
178→        const error = err instanceof Error ? err.message : 'Failed to rename';
179→        setState({ isLoading: false, error });
180→        throw err;
181→      }
182→    },
183→    []
184→  );
185→
186→  /**
187→   * Move a file or folder via SDK.
188→   *
189→   * @param itemId - ID of item to move
190→   * @param itemType - 'file' or 'folder'
191→   * @param sourceParentId - Current parent folder ID
192→   * @param destParentId - Destination parent folder ID
193→   */
194→  const handleMove = useCallback(
195→    async (
196→      itemId: string,
197→      itemType: 'file' | 'folder',
198→      sourceParentId: string,
199→      destParentId: string
200→    ): Promise<void> => {
201→      setState({ isLoading: true, error: null });
202→      try {
203→        const sourceFolder = getParentFolder(sourceParentId);
204→        const destFolder = getParentFolder(destParentId);
205→        if (!sourceFolder || !destFolder) {
206→          throw new Error('Source or destination folder not found');
207→        }
208→
209→        // Ensure both folders are registered in SDK
210→        ensureFolderRegistered(sourceFolder);
211→        ensureFolderRegistered(destFolder);
212→
213→        // Move via SDK (handles add-before-remove, both IPNS publishes)
214→        const client = getSdkClient();
215→        await client.moveItem(sourceFolder.ipnsName, destFolder.ipnsName, itemId);
216→
217→        // SDK emits folder:updated for both folders -> store subscription updates children
218→        // Also update parentId for moved folders
219→        if (itemType === 'folder') {
220→          const movedFolder = useFolderStore.getState().folders[itemId];
221→          if (movedFolder) {
222→            useFolderStore.getState().setFolder({
223→              ...movedFolder,
224→              parentId: destParentId,
225→            });
226→          }
227→        }
228→
229→        setState({ isLoading: false, error: null });
230→      } catch (err) {
231→        const error = err instanceof Error ? err.message : 'Failed to move';
232→        setState({ isLoading: false, error });
233→        throw err;
234→      }
235→    },
236→    []
237→  );
238→
239→  /**
240→   * Move multiple files/folders to a destination.
241→   *
242→   * Uses SDK moveItem for each item sequentially to preserve event ordering.
243→   *
244→   * @param items - Array of { id, type } to move
245→   * @param sourceParentId - Current parent folder ID
246→   * @param destParentId - Destination parent folder ID
247→   */
248→  const handleMoveItems = useCallback(
249→    async (
250→      items: Array<{ id: string; type: 'file' | 'folder' }>,
251→      sourceParentId: string,
252→      destParentId: string
253→    ): Promise<void> => {
254→      setState({ isLoading: true, error: null });
255→      try {
256→        const sourceFolder = getParentFolder(sourceParentId);
257→        const destFolder = getParentFolder(destParentId);
258→        if (!sourceFolder || !destFolder) {
259→          throw new Error('Source or destination folder not found');
260→        }
261→
262→        // Validate batch move preconditions
263→        const folders = useFolderStore.getState().folders;
264→        const itemIds = new Set(items.map((i) => i.id));
265→
266→        for (const item of items) {
267→          if (item.type === 'folder') {
268→            // Prevent moving folder into itself or descendant
269→            if (folderService.isDescendantOf(destFolder.id, item.id, folders)) {
270→              throw new Error(`Cannot move folder into itself or its subfolder`);
271→            }
272→
273→            // Depth limit check
274→            const destDepth = folderService.getDepth(destFolder.id, folders);
275→            const subtreeDepth = folderService.calculateSubtreeDepth(item.id, folders);
276→            if (destDepth + 1 + subtreeDepth > MAX_FOLDER_DEPTH) {
277→              throw new Error(
278→                `Cannot move: would exceed maximum folder depth of ${MAX_FOLDER_DEPTH}`
279→              );
280→            }
281→          }
282→        }
283→
284→        // Name collision check against destination
285→        const movedChildren = sourceFolder.children.filter((c) => itemIds.has(c.id));
286→        for (const child of movedChildren) {
287→          const nameExists = destFolder.children.some((c) => c.name === child.name);
288→          if (nameExists) {
289→            throw new Error(`An item named "${child.name}" already exists in the destination`);
290→          }
291→        }
292→
293→        // Ensure both folders are registered in SDK
294→        ensureFolderRegistered(sourceFolder);
295→        ensureFolderRegistered(destFolder);
296→
297→        // Move each item via SDK
298→        const client = getSdkClient();
299→        for (const item of items) {
300→          await client.moveItem(sourceFolder.ipnsName, destFolder.ipnsName, item.id);
301→
302→          if (item.type === 'folder') {
303→            const movedFolder = useFolderStore.getState().folders[item.id];
304→            if (movedFolder) {
305→              useFolderStore.getState().setFolder({ ...movedFolder, parentId: destParentId });
306→            }
307→          }
308→        }
309→
310→        setState({ isLoading: false, error: null });
311→      } catch (err) {
312→        const error = err instanceof Error ? err.message : 'Failed to move items';
313→        setState({ isLoading: false, error });
314→        throw err;
315→      }
316→    },
317→    []
318→  );
319→
320→  /**
321→   * Delete a file or folder via SDK.
322→   *
323→   * Uses deleteToBin for soft-delete (moves to recycle bin) when the SDK's
324→   * bin state is loaded, otherwise falls back to deleteItem (hard metadata delete)
325→   * with a fire-and-forget bin service call.
326→   *
327→   * @param itemId - ID of item to delete
328→   * @param itemType - 'file' or 'folder'
329→   * @param parentId - Parent folder ID
330→   */
331→  const handleDelete = useCallback(
332→    async (itemId: string, itemType: 'file' | 'folder', parentId: string): Promise<void> => {
333→      setState({ isLoading: true, error: null });
334→      try {
335→        const parentFolder = getParentFolder(parentId);
336→        if (!parentFolder) throw new Error('Parent folder not found');
337→
338→        // Ensure parent is registered in SDK
339→        ensureFolderRegistered(parentFolder);
340→
341→        const client = getSdkClient();
342→        const parentPath = buildFolderPath(parentId);
343→
344→        // Try soft-delete (move to bin) first; fall back to hard delete if bin not loaded
345→        try {
346→          await client.deleteToBin(parentFolder.ipnsName, itemId, parentPath);
347→        } catch (binErr) {
348→          // Bin not loaded -- fall back to hard metadata delete
349→          if (binErr instanceof BinNotLoadedError) {
350→            await client.deleteItem(parentFolder.ipnsName, itemId);
351→          } else {
352→            throw binErr;
353→          }
354→        }
355→
356→        // SDK emits folder:updated -> store subscription updates children
357→        // Remove folder subtree from store if deleting a folder
358→        if (itemType === 'folder') {
359→          const store = useFolderStore.getState();
360→          const removeRecursive = (folderId: string) => {
361→            const node = store.folders[folderId];
362→            if (node) {
363→              for (const child of node.children) {
364→                if (child.type === 'folder') removeRecursive(child.id);
365→              }
366→            }
367→            store.removeFolder(folderId);
368→          };
369→          removeRecursive(itemId);
370→        }
371→
372→        setState({ isLoading: false, error: null });
373→      } catch (err) {
374→        const error = err instanceof Error ? err.message : 'Failed to delete';
375→        setState({ isLoading: false, error });
376→        throw err;
377→      }
378→    },
379→    []
380→  );
381→
382→  /**
383→   * Delete multiple files/folders.
384→   *
385→   * @param items - Array of { id, type } to delete
386→   * @param parentId - Parent folder ID
387→   */
388→  const handleDeleteItems = useCallback(
389→    async (
390→      items: Array<{ id: string; type: 'file' | 'folder' }>,
391→      parentId: string
392→    ): Promise<void> => {
393→      setState({ isLoading: true, error: null });
394→      try {
395→        const parentFolder = getParentFolder(parentId);
396→        if (!parentFolder) throw new Error('Parent folder not found');
397→
398→        // Ensure parent is registered in SDK
399→        ensureFolderRegistered(parentFolder);
400→
401→        // Collect nested folder IDs to remove from store
402→        const folderIdsToRemove: string[] = [];
403→        const collectFolderIds = (folderId: string) => {
404→          folderIdsToRemove.push(folderId);
405→          const folders = useFolderStore.getState().folders;
406→          const folder = folders[folderId];
407→          if (!folder) return;
408→          for (const child of folder.children) {
409→            if (child.type === 'folder') {
410→              collectFolderIds(child.id);
411→            }
412→          }
413→        };
414→
415→        for (const item of items) {
416→          if (item.type === 'folder') {
417→            collectFolderIds(item.id);
418→          }
419→        }
420→
421→        // Delete each item via SDK (sequentially to maintain consistency)
422→        const client = getSdkClient();
423→        const parentPath = buildFolderPath(parentId);
424→
425→        for (const item of items) {
426→          // Re-register parent between deletes since SDK updates its internal state
427→          const freshParent = getParentFolder(parentId);
428→          if (freshParent) ensureFolderRegistered(freshParent);
429→
430→          // Try soft-delete (bin) first; fall back to hard delete
431→          try {
432→            await client.deleteToBin(parentFolder.ipnsName, item.id, parentPath);
433→          } catch (binErr) {
434→            if (binErr instanceof BinNotLoadedError) {
435→              await client.deleteItem(parentFolder.ipnsName, item.id);
436→            } else {
437→              throw binErr;
438→            }
439→          }
440→        }
441→
442→        // Remove nested folders from store
443→        const store = useFolderStore.getState();
444→        for (const folderId of folderIdsToRemove) {
445→          store.removeFolder(folderId);
446→        }
447→
448→        setState({ isLoading: false, error: null });
449→      } catch (err) {
450→        const error = err instanceof Error ? err.message : 'Failed to delete items';
451→        setState({ isLoading: false, error });
452→        throw err;
453→      }
454→    },
455→    []
456→  );
457→
458→  return {
459→    ...state,
460→    createFolder: handleCreate,
461→    renameItem: handleRename,
462→    moveItem: handleMove,
463→    moveItems: handleMoveItems,
464→    deleteItem: handleDelete,
465→    deleteItems: handleDeleteItems,
466→  };
467→}
