 1→import { useCallback } from 'react';
 2→import { triggerBrowserDownload } from '../services/download.service';
 3→import { useDownloadStore } from '../stores/download.store';
 4→import { getSdkClient, hasSdkClient } from '../lib/sdk-provider';
 5→
 6→export function useFileDownload() {
 7→  const {
 8→    status,
 9→    progress,
10→    loadedBytes,
11→    totalBytes,
12→    currentFile,
13→    error,
14→    startDownload,
15→    setProgress,
16→    setDecrypting,
17→    setSuccess,
18→    setError,
19→    reset,
20→  } = useDownloadStore();
21→
22→  /**
23→   * Download a file using per-file IPNS metadata (v2 flow) via SDK.
24→   *
25→   * The SDK resolves file IPNS, decrypts metadata with folderKey,
26→   * fetches + decrypts content. Browser download dialog triggered after.
27→   */
28→  const downloadFromIpns = useCallback(
29→    async (params: {
30→      fileMetaIpnsName: string;
31→      folderKey: Uint8Array;
32→      fileName: string;
33→    }): Promise<void> => {
34→      try {
35→        startDownload(params.fileName);
36→
37→        if (!hasSdkClient()) {
38→          throw new Error('SDK not initialized — please log in again');
39→        }
40→
41→        const client = getSdkClient();
42→        const decryptedBytes = await client.downloadFromIpns(
43→          params.fileMetaIpnsName,
44→          params.folderKey,
45→          (loaded, total) => setProgress(loaded, total)
46→        );
47→
48→        setDecrypting();
49→        await new Promise((resolve) => setTimeout(resolve, 100));
50→
51→        triggerBrowserDownload(decryptedBytes, params.fileName);
52→        setSuccess();
53→      } catch (err) {
54→        const message = (err as Error).message || 'Download failed';
55→        setError(message);
56→        console.error('Download failed:', err);
57→        throw err;
58→      }
59→    },
60→    [startDownload, setProgress, setDecrypting, setSuccess, setError]
61→  );
62→
63→  return {
64→    status,
65→    progress,
66→    loadedBytes,
67→    totalBytes,
68→    currentFile,
69→    error,
70→    isDownloading: status === 'downloading' || status === 'decrypting',
71→    downloadFromIpns,
72→    reset,
73→  };
74→}
