  1→import { useState, useEffect, useCallback, useRef } from 'react';
  2→import type { FilePointer } from '@cipherbox/crypto';
  3→import { Modal } from '../ui/Modal';
  4→import { useAuthStore } from '../../stores/auth.store';
  5→import { useFolder } from '../../hooks/useFolder';
  6→import { downloadFile, triggerBrowserDownload } from '../../services/download.service';
  7→import { resolveFileMetadata } from '../../services/file-metadata.service';
  8→import { fetchShareKeys } from '../../services/share.service';
  9→import { getSdkClient, hasSdkClient } from '../../lib/sdk-provider';
 10→import { encryptFile } from '../../services/file-crypto.service';
 11→import { addToIpfs } from '../../lib/api/ipfs';
 12→import '../../styles/text-editor-dialog.css';
 13→
 14→type TextEditorDialogProps = {
 15→  open: boolean;
 16→  onClose: () => void;
 17→  item: FilePointer | null;
 18→  parentFolderId: string;
 19→  /** Parent folder's decrypted AES-256 key (needed to decrypt file metadata) */
 20→  folderKey: Uint8Array | null;
 21→  /** When true, textarea is read-only and save is hidden */
 22→  readOnly?: boolean;
 23→  /** Share ID when viewing from a shared folder — uses re-wrapped file keys */
 24→  shareId?: string | null;
 25→};
 26→
 27→/**
 28→ * Modal dialog for viewing/editing text files in-browser.
 29→ *
 30→ * In edit mode (default): full crypto round-trip with save.
 31→ * In read-only mode: decrypt and display only (used for shared files).
 32→ */
 33→export function TextEditorDialog({
 34→  open,
 35→  onClose,
 36→  item,
 37→  parentFolderId,
 38→  folderKey,
 39→  readOnly,
 40→  shareId,
 41→}: TextEditorDialogProps) {
 42→  const [loading, setLoading] = useState(false);
 43→  const [saving, setSaving] = useState(false);
 44→  const [content, setContent] = useState('');
 45→  const [originalContent, setOriginalContent] = useState('');
 46→  const [error, setError] = useState<string | null>(null);
 47→  const textareaRef = useRef<HTMLTextAreaElement>(null);
 48→
 49→  const { updateFile } = useFolder();
 50→
 51→  const isDirty = content !== originalContent;
 52→  const lineCount = content.split('\n').length;
 53→
 54→  // Load file content when dialog opens
 55→  useEffect(() => {
 56→    if (!open || !item) {
 57→      setContent('');
 58→      setOriginalContent('');
 59→      setError(null);
 60→      setLoading(false);
 61→      setSaving(false);
 62→      return;
 63→    }
 64→
 65→    if (!folderKey) {
 66→      setLoading(false);
 67→      setError('Folder key not available');
 68→      return;
 69→    }
 70→
 71→    if (!item.fileMetaIpnsName) {
 72→      setLoading(false);
 73→      setError('File metadata IPNS name not available (legacy v1 file?)');
 74→      return;
 75→    }
 76→
 77→    let cancelled = false;
 78→    setLoading(true);
 79→    setError(null);
 80→
 81→    (async () => {
 82→      try {
 83→        const auth = useAuthStore.getState();
 84→        if (!auth.vaultKeypair) {
 85→          throw new Error('No keypair available - please log in again');
 86→        }
 87→
 88→        let plaintext: Uint8Array;
 89→
 90→        if (shareId) {
 91→          // Shared file path: use re-wrapped file key from share_keys
 92→          const [{ metadata: fileMeta }, keys] = await Promise.all([
 93→            resolveFileMetadata(item.fileMetaIpnsName, folderKey!),
 94→            fetchShareKeys(shareId),
 95→          ]);
 96→
 97→          const fileKeyRecord = keys.find((k) => k.keyType === 'file' && k.itemId === item.id);
 98→          if (!fileKeyRecord) {
 99→            throw new Error('No re-wrapped file key available for this file');
100→          }
101→
102→          plaintext = await downloadFile(
103→            {
104→              cid: fileMeta.cid,
105→              iv: fileMeta.fileIv,
106→              wrappedKey: fileKeyRecord.encryptedKey,
107→              originalName: item.name,
108→              encryptionMode: fileMeta.encryptionMode,
109→            },
110→            auth.vaultKeypair.privateKey
111→          );
112→        } else if (hasSdkClient()) {
113→          // Owner path via SDK: resolves IPNS, decrypts metadata, downloads + decrypts content
114→          const client = getSdkClient();
115→          plaintext = await client.downloadFromIpns(item.fileMetaIpnsName, folderKey!);
116→        } else {
117→          throw new Error('SDK not initialized — please log in again');
118→        }
119→
120→        if (cancelled) return;
121→
122→        const text = new TextDecoder().decode(plaintext);
123→        setContent(text);
124→        setOriginalContent(text);
125→        setLoading(false);
126→
127→        // Focus textarea after content loads (only in edit mode)
128→        if (!readOnly) {
129→          requestAnimationFrame(() => {
130→            textareaRef.current?.focus();
131→          });
132→        }
133→      } catch (err) {
134→        if (cancelled) return;
135→        setError(err instanceof Error ? err.message : 'Failed to load file');
136→        setLoading(false);
137→      }
138→    })();
139→
140→    return () => {
141→      cancelled = true;
142→    };
143→  }, [open, item, folderKey, shareId, readOnly]);
144→
145→  const handleSave = useCallback(async () => {
146→    if (!item || !isDirty) return;
147→
148→    setSaving(true);
149→    setError(null);
150→
151→    try {
152→      const auth = useAuthStore.getState();
153→      if (!auth.vaultKeypair) {
154→        throw new Error('No keypair available - please log in again');
155→      }
156→
157→      // 1. Encode content
158→      const encoded = new TextEncoder().encode(content);
159→      const file = new File([encoded], item.name);
160→
161→      // 2. Encrypt with new key/IV
162→      const encrypted = await encryptFile(file, auth.vaultKeypair.publicKey);
163→
164→      // 3. Upload to IPFS
165→      // Use .slice() to get a clean copy with its own ArrayBuffer,
166→      // avoiding sub-view issues if ciphertext is an offset view.
167→      const ciphertextBytes = encrypted.ciphertext.slice();
168→      const blob = new Blob([ciphertextBytes.buffer as ArrayBuffer]);
169→      const { cid } = await addToIpfs(blob);
170→
171→      // 4. Update folder metadata
172→      await updateFile(parentFolderId, {
173→        fileId: item.id,
174→        newCid: cid,
175→        newFileKeyEncrypted: encrypted.wrappedKey,
176→        newFileIv: encrypted.iv,
177→        newSize: encrypted.originalSize,
178→      });
179→
180→      onClose();
181→    } catch (err) {
182→      setError(err instanceof Error ? err.message : 'Failed to save file');
183→      setSaving(false);
184→    }
185→  }, [item, content, isDirty, parentFolderId, updateFile, onClose]);
186→
187→  // Handle Ctrl/Cmd+S to save (edit mode only)
188→  useEffect(() => {
189→    if (!open || readOnly) return;
190→
191→    const handleKeyDown = (e: KeyboardEvent) => {
192→      if ((e.metaKey || e.ctrlKey) && e.key === 's') {
193→        e.preventDefault();
194→        if (isDirty && !saving && !loading) {
195→          handleSave();
196→        }
197→      }
198→    };
199→
200→    document.addEventListener('keydown', handleKeyDown);
201→    return () => document.removeEventListener('keydown', handleKeyDown);
202→  }, [open, readOnly, isDirty, saving, loading, handleSave]);
203→
204→  const handleDownload = useCallback(() => {
205→    if (!item || !content) return;
206→    const encoded = new TextEncoder().encode(content);
207→    triggerBrowserDownload(encoded, item.name, 'text/plain');
208→  }, [item, content]);
209→
210→  if (!item) return null;
211→
212→  const title = readOnly ? `View: ${item.name}` : `Edit: ${item.name}`;
213→  const isDisabled = saving || loading;
214→
215→  return (
216→    <Modal
217→      open={open}
218→      onClose={isDisabled ? undefined : onClose}
219→      title={title}
220→      className="text-editor-modal"
221→    >
222→      {loading ? (
223→        <div className="text-editor-loading">decrypting...</div>
224→      ) : (
225→        <div className="text-editor-body">
226→          <textarea
227→            ref={textareaRef}
228→            className="text-editor-textarea"
229→            value={content}
230→            onChange={readOnly ? undefined : (e) => setContent(e.target.value)}
231→            disabled={isDisabled}
232→            readOnly={readOnly}
233→            spellCheck={false}
234→            aria-label={`Content of ${item.name}`}
235→          />
236→          <div className={`text-editor-status${isDirty ? ' text-editor-status--modified' : ''}`}>
237→            <span>
238→              {'// '}
239→              {lineCount} {lineCount === 1 ? 'line' : 'lines'}
240→              {' | utf-8'}
241→              {readOnly ? ' | read-only' : ''}
242→              {isDirty ? ' | modified' : ''}
243→            </span>
244→          </div>
245→          {error && (
246→            <div className="text-editor-error">
247→              {'> '}
248→              {error}
249→            </div>
250→          )}
251→          <div className="text-editor-footer">
252→            {readOnly ? (
253→              <>
254→                <button
255→                  type="button"
256→                  className="dialog-button dialog-button--secondary"
257→                  onClick={handleDownload}
258→                >
259→                  --download
260→                </button>
261→                <button
262→                  type="button"
263→                  className="dialog-button dialog-button--primary"
264→                  onClick={onClose}
265→                >
266→                  close
267→                </button>
268→              </>
269→            ) : (
270→              <>
271→                <button
272→                  type="button"
273→                  className="dialog-button dialog-button--secondary"
274→                  onClick={onClose}
275→                  disabled={isDisabled}
276→                >
277→                  cancel
278→                </button>
279→                <button
280→                  type="button"
281→                  className="dialog-button dialog-button--primary"
282→                  onClick={handleSave}
283→                  disabled={isDisabled || !isDirty}
284→                >
285→                  {saving ? 'encrypting...' : '--save'}
286→                </button>
287→              </>
288→            )}
289→          </div>
290→        </div>
291→      )}
292→    </Modal>
293→  );
294→}
