  1→import { create } from 'zustand';
  2→import type { FolderChild } from '@cipherbox/crypto';
  3→import type { CipherBoxClient } from '@cipherbox/sdk';
  4→
  5→/**
  6→ * A folder node in the in-memory folder tree.
  7→ * Contains decrypted folder data and navigation state.
  8→ */
  9→export type FolderNode = {
 10→  /** UUID for internal reference (null string 'root' for root folder) */
 11→  id: string;
 12→  /** Folder name */
 13→  name: string;
 14→  /** IPNS name for this folder (k51.../bafzaa... format) */
