 40→type FolderState = {
 41→  // Folder tree indexed by id
 42→  folders: Record<string, FolderNode>;
 43→
 44→  // Current navigation
 45→  currentFolderId: string | null; // null = root
 46→  breadcrumbs: Breadcrumb[];
 47→
 48→  // Publishing state
 49→  pendingPublishes: Set<string>; // folder IDs with pending IPNS publishes
 50→
 51→  // Actions
 52→  setFolder: (folder: FolderNode) => void;
 53→  updateFolderChildren: (folderId: string, children: FolderChild[]) => void;
 54→  updateFolderSequence: (folderId: string, sequenceNumber: bigint) => void;
