 56→
 57→  // Actions
 58→  setEntries: (entries, seq) =>
 59→    set({
 60→      entries,
 61→      sequenceNumber: seq,
 62→      isLoaded: true,
 63→      isLoading: false,
 64→      error: null,
 65→    }),
 66→
 67→  setLoading: (loading) => set({ isLoading: loading }),
 68→
 69→  setError: (error) => set({ error }),
 70→
 71→  setBinIpnsName: (name) => set({ binIpnsName: name }),
 72→
 73→  setRetentionDays: (days) =>
 74→    set({
 75→      retentionDays: Number.isFinite(days) ? Math.max(0, Math.floor(days)) : 30,
 76→    }),
 77→
