 79→    // Unsubscribe from SDK events before clearing
 80→    if (_binSdkUnsubscribe) {
 81→      _binSdkUnsubscribe();
 82→      _binSdkUnsubscribe = null;
 83→    }
 84→
 85→    set({
 86→      entries: [],
 87→      isLoading: false,
 88→      isLoaded: false,
 89→      error: null,
 90→      sequenceNumber: 0,
 91→      binIpnsName: null,
 92→      retentionDays: 30,
 93→    });
 94→  },
 95→
 96→  /**
