  1→/**
  2→ * @cipherbox/crypto - Vault IPNS Derivation Tests
  3→ *
  4→ * Tests for deterministic vault IPNS keypair derivation and
  5→ * domain separation from registry IPNS derivation.
  6→ */
  7→
  8→import { describe, it, expect } from 'vitest';
  9→import * as secp256k1 from '@noble/secp256k1';
 10→import { deriveVaultIpnsKeypair } from '../vault/derive-ipns';
 11→import { deriveRegistryIpnsKeypair, initializeVault } from '@cipherbox/core';
 12→import { CryptoError } from '../types';
 13→
 14→/**
 15→ * Generate a random secp256k1 private key for testing.
 16→ */
 17→function randomPrivateKey(): Uint8Array {
 18→  return secp256k1.utils.randomPrivateKey();
 19→}
 20→
 21→describe('deriveVaultIpnsKeypair', () => {
 22→  it('produces the same keypair and IPNS name for the same privateKey (determinism)', async () => {
 23→    const privateKey = randomPrivateKey();
 24→
 25→    const result1 = await deriveVaultIpnsKeypair(privateKey);
 26→    const result2 = await deriveVaultIpnsKeypair(privateKey);
 27→
 28→    expect(result1.privateKey).toEqual(result2.privateKey);
 29→    expect(result1.publicKey).toEqual(result2.publicKey);
 30→    expect(result1.ipnsName).toBe(result2.ipnsName);
 31→  });
 32→
 33→  it('produces different results for different private keys', async () => {
 34→    const privateKey1 = randomPrivateKey();
 35→    const privateKey2 = randomPrivateKey();
 36→
 37→    const result1 = await deriveVaultIpnsKeypair(privateKey1);
 38→    const result2 = await deriveVaultIpnsKeypair(privateKey2);
 39→
 40→    expect(result1.ipnsName).not.toBe(result2.ipnsName);
 41→    expect(result1.privateKey).not.toEqual(result2.privateKey);
 42→    expect(result1.publicKey).not.toEqual(result2.publicKey);
 43→  });
 44→
 45→  it('produces a different IPNS name than deriveRegistryIpnsKeypair for the same key (domain separation)', async () => {
 46→    const privateKey = randomPrivateKey();
 47→
 48→    const vaultResult = await deriveVaultIpnsKeypair(privateKey);
 49→    const registryResult = await deriveRegistryIpnsKeypair(privateKey);
 50→
 51→    expect(vaultResult.ipnsName).not.toBe(registryResult.ipnsName);
 52→    expect(vaultResult.privateKey).not.toEqual(registryResult.privateKey);
 53→    expect(vaultResult.publicKey).not.toEqual(registryResult.publicKey);
 54→  });
 55→
 56→  it('throws CryptoError with INVALID_KEY_SIZE for 31-byte key', async () => {
 57→    const shortKey = new Uint8Array(31);
 58→
 59→    await expect(deriveVaultIpnsKeypair(shortKey)).rejects.toThrow(
 60→      'Invalid private key size for vault derivation'
 61→    );
 62→
 63→    try {
 64→      await deriveVaultIpnsKeypair(shortKey);
 65→    } catch (error) {
 66→      expect(error).toBeInstanceOf(CryptoError);
 67→      expect((error as CryptoError).code).toBe('INVALID_KEY_SIZE');
 68→    }
 69→  });
 70→
 71→  it('produces an IPNS name starting with k51', async () => {
 72→    const privateKey = randomPrivateKey();
 73→
 74→    const result = await deriveVaultIpnsKeypair(privateKey);
 75→
 76→    expect(result.ipnsName).toMatch(/^k51/);
 77→  });
 78→});
 79→
 80→describe('initializeVault with deterministic IPNS', () => {
 81→  it('produces the same rootIpnsKeypair for the same privateKey (deterministic IPNS)', async () => {
 82→    const privateKey = randomPrivateKey();
 83→
 84→    const vault1 = await initializeVault(privateKey);
 85→    const vault2 = await initializeVault(privateKey);
 86→
 87→    expect(vault1.rootIpnsKeypair.publicKey).toEqual(vault2.rootIpnsKeypair.publicKey);
 88→    expect(vault1.rootIpnsKeypair.privateKey).toEqual(vault2.rootIpnsKeypair.privateKey);
 89→  });
 90→
 91→  it('produces a DIFFERENT rootFolderKey each time (random)', async () => {
 92→    const privateKey = randomPrivateKey();
 93→
 94→    const vault1 = await initializeVault(privateKey);
 95→    const vault2 = await initializeVault(privateKey);
 96→
 97→    expect(vault1.rootFolderKey).not.toEqual(vault2.rootFolderKey);
 98→  });
 99→
100→  it('rootIpnsKeypair matches deriveVaultIpnsKeypair output for the same key', async () => {
101→    const privateKey = randomPrivateKey();
102→
103→    const vault = await initializeVault(privateKey);
104→    const derived = await deriveVaultIpnsKeypair(privateKey);
105→
106→    expect(vault.rootIpnsKeypair.publicKey).toEqual(derived.publicKey);
107→    expect(vault.rootIpnsKeypair.privateKey).toEqual(derived.privateKey);
108→  });
109→});
