373→       import type { SdkContext, TeeKeys, ProgressCallback, DownloadProgressCallback } from '@cipherbox/sdk-core';
374→       import * as sdkCore from '@cipherbox/sdk-core';
375→       import type { FolderChild, FolderMetadata } from '@cipherbox/core';
376→       import type { CipherBoxClientConfig, FolderState } from './types';
377→       import { SdkEventEmitter, type SdkEvent, type SdkEventHandler } from './events';
378→       import { FolderTree } from './state/folder-tree';
379→       import { KeyCache } from './state/key-cache';
380→
381→       export class CipherBoxClient {
382→         private config: CipherBoxClientConfig;
383→         private ctx: SdkContext;
384→         private emitter: SdkEventEmitter;
385→         private folderTree: FolderTree;
386→         private keyCache: KeyCache;
387→
388→         constructor(config: CipherBoxClientConfig) {
389→           this.config = config;
390→           this.ctx = { apiUrl: config.apiUrl, getAccessToken: config.getAccessToken };
391→           this.emitter = new SdkEventEmitter();
392→           this.folderTree = new FolderTree();
393→           this.keyCache = new KeyCache();
394→         }
395→
396→         // Event subscription
397→         on(handler: SdkEventHandler): () => void { return this.emitter.on(handler); }
398→         off(handler: SdkEventHandler): void { this.emitter.off(handler); }
399→
400→         // Lifecycle
401→         destroy(): void {
402→           this.folderTree.clear();
403→           this.keyCache.clear();
404→           this.emitter.removeAll();
405→         }
406→
407→         // ---- Folder operations ----
408→         async loadFolder(ipnsName: string, folderKey: Uint8Array, ipnsKeypair: {...}): Promise<FolderState> { ... }
409→         async createFolder(parentIpnsName: string, name: string): Promise<{ ipnsName: string }> { ... }
410→         async renameItem(folderIpnsName: string, childId: string, newName: string): Promise<void> { ... }
411→         async moveItem(sourceIpnsName: string, destIpnsName: string, childId: string): Promise<void> { ... }
412→         async deleteItem(folderIpnsName: string, childId: string): Promise<void> { ... }
