416→         async downloadFile(cid: string, fileKey: Uint8Array, fileIv: Uint8Array, encryptionMode: string, onProgress?: DownloadProgressCallback): Promise<Uint8Array> { ... }
417→
418→         // Helper: wrap operation with event emission + error handling
419→         private async withOperation<T>(name: string, fn: () => Promise<T>): Promise<T> {
420→           const start = Date.now();
421→           this.config.onOperationStart?.(name);
422→           this.emitter.emit({ type: 'operation:start', operation: name });
423→           try {
424→             const result = await fn();
425→             const durationMs = Date.now() - start;
426→             this.config.onOperationEnd?.(name);
427→             this.emitter.emit({ type: 'operation:end', operation: name, durationMs });
428→             return result;
429→           } catch (error) {
430→             this.config.onError?.(error as Error);
431→             this.emitter.emit({ type: 'error', operation: name, error: error as Error });
432→             throw error;
433→           }
434→         }
435→       }
