159→  keyEpoch?: number;
160→}): Promise<{ cid: string; newSequenceNumber: bigint }> {
161→  // 1. Create v2 folder metadata
162→  const metadata: FolderMetadata = {
163→    version: 'v2',
164→    children: params.children,
165→  };
166→
167→  // 2. Encrypt metadata with folder key
168→  const encrypted = await encryptFolderMetadata(metadata, params.folderKey);
169→
170→  // 3. Upload to IPFS via backend relay
171→  const jsonStr = JSON.stringify(encrypted);
172→  const encryptedBytes = new TextEncoder().encode(jsonStr);
173→  const { cid } = await addToIpfs(params.ctx, encryptedBytes);
174→
175→  // 4. Publish IPNS record with conflict retry
176→  //    On 409, resolve current seq from IPNS and retry once
177→  let currentSeq = params.sequenceNumber;
178→
179→  for (let attempt = 0; attempt < 2; attempt++) {
180→    const newSeq = currentSeq + 1n;
181→    try {
182→      await createAndPublishIpnsRecord({
183→        ipnsPrivateKey: params.ipnsPrivateKey,
184→        ipnsName: params.ipnsName,
185→        metadataCid: cid,
186→        sequenceNumber: newSeq,
187→        encryptedIpnsPrivateKey: params.encryptedIpnsPrivateKey,
188→        keyEpoch: params.keyEpoch,
189→        expectedSequenceNumber: currentSeq.toString(),
190→      });
191→      return { cid, newSequenceNumber: newSeq };
192→    } catch (err) {
193→      const is409 =
194→        (err as Error & { status?: number }).status === 409 ||
195→        (err as Error & { response?: { status?: number } }).response?.status === 409;
196→      if (!is409 || attempt > 0) throw err;
197→
198→      // Re-sync: resolve current seq from IPNS
199→      const resolved = await resolveIpnsRecord(params.ipnsName);
200→      if (resolved) {
201→        currentSeq = resolved.sequenceNumber;
202→      } else {
203→        throw err; // Can't resolve → give up
204→      }
205→    }
206→  }
207→
208→  // Should not reach here, but TypeScript needs it
209→  throw new Error('Publish failed after retry');
210→}
211→
212→/**
213→ * Rename a child entry (folder or file) in folder metadata.
214→ *
215→ * Pure metadata operation: returns updated children array without publishing.
216→ */
217→export function renameInFolder(params: {
218→  children: FolderChild[];
219→  childId: string;
220→  newName: string;
221→}): { updatedChildren: FolderChild[]; renamedChild: FolderChild } {
222→  const children = [...params.children];
223→  const index = children.findIndex((c) => c.id === params.childId);
224→
225→  if (index === -1) throw new Error('Item not found');
226→
227→  const nameExists = children.some((c) => c.name === params.newName && c.id !== params.childId);
228→  if (nameExists) throw new Error('An item with this name already exists');
229→
230→  const renamedChild = {
231→    ...children[index],
232→    name: params.newName,
233→    modifiedAt: Date.now(),
234→  };
235→  children[index] = renamedChild;
236→
237→  return { updatedChildren: children, renamedChild };
238→}
239→
240→/**
241→ * Remove a child entry (folder or file) from folder metadata.
242→ *
243→ * Pure metadata operation: returns updated children array and the removed item.
244→ */
245→export function deleteFromFolder(params: { children: FolderChild[]; childId: string }): {
246→  updatedChildren: FolderChild[];
247→  removedItem: FolderChild;
248→} {
249→  const index = params.children.findIndex((c) => c.id === params.childId);
250→  if (index === -1) throw new Error('Item not found');
251→
252→  const removedItem = params.children[index];
253→  const updatedChildren = params.children.filter((c) => c.id !== params.childId);
254→
255→  return { updatedChildren, removedItem };
256→}
257→
258→/**
259→ * Add a file pointer to folder children.
260→ *
261→ * Pure metadata operation: returns updated children array with the new file pointer.
262→ */
263→export function addFilePointerToFolder(params: {
264→  children: FolderChild[];
265→  fileId: string;
266→  fileName: string;
267→  fileMetaIpnsName: string;
268→  ipnsPrivateKeyEncrypted: string;
269→}): { updatedChildren: FolderChild[]; filePointer: FilePointer } {
270→  const nameExists = params.children.some((c) => c.name === params.fileName);
271→  if (nameExists) throw new Error('A file with this name already exists');
272→
273→  const now = Date.now();
274→  const filePointer: FilePointer = {
275→    type: 'file',
276→    id: params.fileId,
277→    name: params.fileName,
278→    fileMetaIpnsName: params.fileMetaIpnsName,
279→    ipnsPrivateKeyEncrypted: params.ipnsPrivateKeyEncrypted,
280→    createdAt: now,
281→    modifiedAt: now,
282→  };
283→
284→  return {
285→    updatedChildren: [...params.children, filePointer],
286→    filePointer,
287→  };
288→}
289→
290→/**
291→ * Move a child entry between folders.
292→ *
293→ * Pure metadata operation: returns updated source and dest children arrays.
294→ * Uses add-before-remove pattern conceptually (caller publishes dest first, then source).
295→ */
296→export function moveItem(params: {
297→  sourceChildren: FolderChild[];
298→  destChildren: FolderChild[];
299→  childId: string;
300→}): {
301→  updatedSourceChildren: FolderChild[];
302→  updatedDestChildren: FolderChild[];
303→  movedItem: FolderChild;
304→} {
305→  const index = params.sourceChildren.findIndex((c) => c.id === params.childId);
306→  if (index === -1) throw new Error('Item not found');
307→
308→  const movedItem = {
309→    ...params.sourceChildren[index],
310→    modifiedAt: Date.now(),
311→  };
312→
313→  // Check name collision in destination
314→  const nameExists = params.destChildren.some((c) => c.name === movedItem.name);
315→  if (nameExists) {
316→    throw new Error('An item with this name already exists in destination');
317→  }
318→
319→  const updatedSourceChildren = params.sourceChildren.filter((c) => c.id !== params.childId);
320→  const updatedDestChildren = [...params.destChildren, movedItem];
321→
322→  return { updatedSourceChildren, updatedDestChildren, movedItem };
323→}
