  1→/**
  2→ * File Metadata Service - Per-file IPNS operations
  3→ *
  4→ * Extracted from: apps/web/src/services/file-metadata.service.ts
  5→ * Change: teeKeys passed explicitly instead of read from useAuthStore.
  6→ * Change: IPFS/IPNS operations use sdk-core internal modules instead of web app imports.
  7→ */
  8→
  9→import {
 10→  generateFileIpnsKeypair,
 11→  encryptFileMetadata,
 12→  decryptFileMetadata,
 13→  createIpnsRecord,
 14→  marshalIpnsRecord,
 15→  type FileMetadata,
 16→  type EncryptedFileMetadata,
 17→  type VersionEntry,
 18→} from '@cipherbox/core';
 19→import { wrapKey, bytesToHex, hexToBytes } from '@cipherbox/crypto';
 20→import type { SdkContext, TeeKeys } from '../types';
 21→import { addToIpfs, fetchFromIpfs } from '../ipfs';
 22→import { resolveIpnsRecord } from '../ipns';
 23→
 24→/** IPNS record lifetime: 24 hours in milliseconds */
 25→const IPNS_LIFETIME_MS = 24 * 60 * 60 * 1000;
 26→
 27→/** Maximum number of past versions retained per file (VER-04) */
 28→const MAX_VERSIONS_PER_FILE = 10;
 29→
 30→/** Safe base64 encoding that avoids call stack overflow from spread operator */
 31→function uint8ToBase64(bytes: Uint8Array): string {
 32→  let binary = '';
 33→  for (let i = 0; i < bytes.length; i++) {
 34→    binary += String.fromCharCode(bytes[i]);
 35→  }
 36→  return btoa(binary);
 37→}
 38→
 39→/** Record payload ready for batch publish */
 40→export type FileIpnsRecordPayload = {
 41→  ipnsName: string;
 42→  recordBase64: string;
 43→  metadataCid: string;
 44→  encryptedIpnsPrivateKey?: string;
 45→  keyEpoch?: number;
 46→};
 47→
 48→/**
 49→ * Create a per-file IPNS metadata record.
 50→ *
 51→ * Generates a random Ed25519 IPNS keypair for the file, encrypts file metadata
 52→ * with the parent folder's key, uploads to IPFS, and creates a signed IPNS record.
 53→ *
 54→ * @returns File IPNS name, record payload for batch publish, and ECIES-wrapped IPNS private key
 55→ */
 56→export async function createFileMetadata(params: {
 57→  fileId: string;
 58→  cid: string;
 59→  fileKeyEncrypted: string;
 60→  fileIv: string;
 61→  size: number;
 62→  mimeType: string;
 63→  folderKey: Uint8Array;
 64→  userPublicKey: Uint8Array;
 65→  ctx: SdkContext;
 66→  teeKeys?: TeeKeys;
 67→  encryptionMode?: 'GCM' | 'CTR';
 68→}): Promise<{
 69→  fileMetaIpnsName: string;
 70→  ipnsRecord: FileIpnsRecordPayload;
 71→  ipnsPrivateKeyEncrypted: string;
 72→}> {
 73→  // 1. Generate random Ed25519 IPNS keypair for this file
 74→  const ipnsKeypair = await generateFileIpnsKeypair();
 75→
 76→  // 2. ECIES-wrap the IPNS private key with user's public key for storage in FilePointer
 77→  const wrappedIpnsKey = await wrapKey(ipnsKeypair.privateKey, params.userPublicKey);
 78→  const ipnsPrivateKeyEncrypted = bytesToHex(wrappedIpnsKey);
 79→
 80→  // 3. Create FileMetadata object
 81→  const now = Date.now();
 82→  const metadata: FileMetadata = {
 83→    version: 'v1',
 84→    cid: params.cid,
 85→    fileKeyEncrypted: params.fileKeyEncrypted,
 86→    fileIv: params.fileIv,
 87→    size: params.size,
 88→    mimeType: params.mimeType,
 89→    encryptionMode: params.encryptionMode ?? 'GCM',
 90→    createdAt: now,
 91→    modifiedAt: now,
 92→  };
 93→
 94→  // 4. Encrypt with parent folderKey
 95→  const encrypted: EncryptedFileMetadata = await encryptFileMetadata(metadata, params.folderKey);
 96→
 97→  // 5. Upload encrypted metadata to IPFS
 98→  const jsonStr = JSON.stringify(encrypted);
 99→  const encryptedBytes = new TextEncoder().encode(jsonStr);
100→  const { cid: metadataCid } = await addToIpfs(params.ctx, encryptedBytes);
101→
102→  // 6. Create IPNS record (sequence number 1 for new records)
103→  const record = await createIpnsRecord(
104→    ipnsKeypair.privateKey,
105→    `/ipfs/${metadataCid}`,
106→    1n,
107→    IPNS_LIFETIME_MS
108→  );
109→
110→  // 7. Marshal and base64 encode the record
111→  const recordBytes = marshalIpnsRecord(record);
112→  const recordBase64 = uint8ToBase64(recordBytes);
113→
114→  // 8. TEE enrollment: encrypt IPNS private key with TEE public key
115→  let teeEncryptedIpnsPrivateKey: string | undefined;
116→  let keyEpoch: number | undefined;
117→
118→  if (params.teeKeys?.currentPublicKey) {
119→    const teePublicKey = hexToBytes(params.teeKeys.currentPublicKey);
120→    const encryptedKey = await wrapKey(ipnsKeypair.privateKey, teePublicKey);
121→    teeEncryptedIpnsPrivateKey = bytesToHex(encryptedKey);
122→    keyEpoch = params.teeKeys.currentEpoch;
123→  }
124→
125→  // Zero the private key now that wrapping, signing, and TEE enrollment are done
126→  ipnsKeypair.privateKey.fill(0);
127→
128→  return {
129→    fileMetaIpnsName: ipnsKeypair.ipnsName,
130→    ipnsRecord: {
131→      ipnsName: ipnsKeypair.ipnsName,
132→      recordBase64,
133→      metadataCid,
134→      encryptedIpnsPrivateKey: teeEncryptedIpnsPrivateKey,
135→      keyEpoch,
136→    },
137→    ipnsPrivateKeyEncrypted,
138→  };
139→}
140→
141→/**
142→ * Resolve a file's per-IPNS metadata record.
143→ *
144→ * Resolves the file's IPNS name to get the current metadata CID,
145→ * fetches the encrypted metadata from IPFS, and decrypts with the
146→ * parent folder's key.
147→ *
148→ * @returns Decrypted file metadata and the resolved metadata CID
149→ */
150→export async function resolveFileMetadata(
151→  fileMetaIpnsName: string,
152→  folderKey: Uint8Array,
153→  ctx: SdkContext
154→): Promise<{ metadata: FileMetadata; metadataCid: string }> {
155→  const resolved = await resolveIpnsRecord(fileMetaIpnsName);
156→
157→  if (!resolved) {
158→    throw new Error('File metadata IPNS not found');
159→  }
160→
161→  const encryptedBytes = await fetchFromIpfs(ctx, resolved.cid);
162→  const encryptedJson = new TextDecoder().decode(encryptedBytes);
163→  const encrypted: EncryptedFileMetadata = JSON.parse(encryptedJson);
164→  const metadata = await decryptFileMetadata(encrypted, folderKey);
165→
166→  return { metadata, metadataCid: resolved.cid };
167→}
168→
169→/**
170→ * Update an existing file's per-IPNS metadata record.
171→ *
172→ * Merges updates into the current metadata, re-encrypts, uploads to IPFS,
173→ * and creates a new IPNS record with an incremented sequence number.
174→ *
175→ * @returns Updated IPNS record payload for publish, plus CIDs of pruned versions to unpin
176→ */
177→export async function updateFileMetadata(params: {
178→  fileIpnsPrivateKey: Uint8Array;
179→  fileMetaIpnsName: string;
180→  folderKey: Uint8Array;
181→  currentMetadata: FileMetadata;
182→  updates: Partial<
183→    Pick<FileMetadata, 'cid' | 'fileKeyEncrypted' | 'fileIv' | 'size' | 'encryptionMode'>
184→  >;
185→  createVersion: boolean;
186→  ctx: SdkContext;
187→}): Promise<{
188→  ipnsRecord: FileIpnsRecordPayload;
189→  prunedCids: string[];
190→}> {
191→  // 1. Build version history
192→  let versions: VersionEntry[] | undefined;
193→  let prunedCids: string[] = [];
194→
195→  if (params.createVersion) {
196→    const versionEntry: VersionEntry = {
197→      cid: params.currentMetadata.cid,
198→      fileKeyEncrypted: params.currentMetadata.fileKeyEncrypted,
199→      fileIv: params.currentMetadata.fileIv,
200→      size: params.currentMetadata.size,
201→      timestamp: Date.now(),
202→      encryptionMode: params.currentMetadata.encryptionMode ?? 'GCM',
203→    };
204→    const allVersions = [versionEntry, ...(params.currentMetadata.versions ?? [])];
205→
206→    versions = allVersions.slice(0, MAX_VERSIONS_PER_FILE);
207→    prunedCids = allVersions.slice(MAX_VERSIONS_PER_FILE).map((v) => v.cid);
208→  } else {
209→    versions = params.currentMetadata.versions;
210→  }
211→
212→  // 2. Merge updates into current metadata
213→  const updatedMetadata: FileMetadata = {
214→    ...params.currentMetadata,
215→    ...params.updates,
216→    ...(versions && versions.length > 0 ? { versions } : { versions: undefined }),
217→    modifiedAt: Date.now(),
218→  };
219→
220→  // 3. Resolve current IPNS to get sequence number
221→  const resolved = await resolveIpnsRecord(params.fileMetaIpnsName);
222→  if (!resolved) {
223→    throw new Error(
224→      `Cannot update file metadata: existing IPNS record not found for ${params.fileMetaIpnsName}`
225→    );
226→  }
227→  const newSeq = resolved.sequenceNumber + 1n;
228→
229→  // 4. Encrypt updated metadata with folderKey
230→  const encrypted = await encryptFileMetadata(updatedMetadata, params.folderKey);
231→
232→  // 5. Upload to IPFS
233→  const jsonStr = JSON.stringify(encrypted);
234→  const encryptedBytes = new TextEncoder().encode(jsonStr);
235→  const { cid: metadataCid } = await addToIpfs(params.ctx, encryptedBytes);
236→
237→  // 6. Create new IPNS record with incremented sequence number
238→  const record = await createIpnsRecord(
239→    params.fileIpnsPrivateKey,
240→    `/ipfs/${metadataCid}`,
241→    newSeq,
242→    IPNS_LIFETIME_MS
243→  );
244→
245→  const recordBytes = marshalIpnsRecord(record);
246→  const recordBase64 = uint8ToBase64(recordBytes);
247→
248→  return {
249→    ipnsRecord: {
250→      ipnsName: params.fileMetaIpnsName,
251→      recordBase64,
252→      metadataCid,
253→    },
254→    prunedCids,
255→  };
256→}
257→

  1→/**
  2→ * @cipherbox/sdk - CipherBoxClient
  3→ *
  4→ * Stateful client orchestrating folder CRUD, file upload/download,
  5→ * and event-driven change notification. Wraps @cipherbox/sdk-core
  6→ * stateless functions with internal state management (FolderTree, KeyCache).
  7→ *
  8→ * Design principles:
  9→ * - Zero React/Zustand/browser dependencies
 10→ * - All state flows through typed events (SdkEvent)
 11→ * - Operations are wrapped with withOperation() for consistent
 12→ *   start/end/error event emission
 13→ * - Key material is cleared on destroy()
 14→ */
 15→
 16→import type { SdkContext, ProgressCallback, DownloadProgressCallback } from '@cipherbox/sdk-core';
 17→import * as sdkCore from '@cipherbox/sdk-core';
 18→import type { FolderChild } from '@cipherbox/core';
 19→import type { CipherBoxClientConfig, FolderState } from './types';
 20→import { SdkEventEmitter, type SdkEvent, type SdkEventHandler } from './events';
 21→import { FolderTree } from './state/folder-tree';
 22→import { KeyCache } from './state/key-cache';
 23→import * as binOps from './bin';
 24→import type { BinState } from './bin';
 25→import * as shareOps from './share';
 26→import type { SentShareInfo } from './share';
 27→
 28→/** Thrown when a bin operation is attempted before loadBin() has been called. */
 29→export class BinNotLoadedError extends Error {
 30→  constructor() {
 31→    super('Bin not loaded');
 32→    this.name = 'BinNotLoadedError';
 33→  }
 34→}
 35→
 36→export class CipherBoxClient {
 37→  private config: CipherBoxClientConfig;
 38→  private ctx: SdkContext;
 39→  private emitter: SdkEventEmitter;
 40→  private folderTree: FolderTree;
 41→  private keyCache: KeyCache;
 42→  private binState: BinState | null = null;
 43→
 44→  constructor(config: CipherBoxClientConfig) {
 45→    this.config = config;
 46→    this.ctx = {
 47→      apiUrl: config.apiUrl,
 48→      getAccessToken: config.getAccessToken,
 49→    };
 50→    this.emitter = new SdkEventEmitter();
 51→    this.folderTree = new FolderTree();
 52→    this.keyCache = new KeyCache();
 53→  }
 54→
 55→  // ---- Event subscription ----
 56→
 57→  /** Subscribe to SDK events. Returns an unsubscribe function. */
 58→  on(handler: SdkEventHandler): () => void {
 59→    return this.emitter.on(handler);
 60→  }
 61→
 62→  /** Unsubscribe a previously registered handler. */
 63→  off(handler: SdkEventHandler): void {
 64→    this.emitter.off(handler);
 65→  }
