 89→  /**
 90→   * Get the current sequence number for a folder in the SDK's internal state.
 91→   * Returns undefined if the folder is not registered.
 92→   */
 93→  getFolderSequenceNumber(ipnsName: string): bigint | undefined {
 94→    return this.folderTree.get(ipnsName)?.sequenceNumber;
 95→  }
 96→
 97→  /**
 98→   * Get the IPNS private key for a folder in the SDK's internal state.
 99→   * Returns undefined if the folder is not registered or has no key.
100→   *
101→   * Used by ensureFolderRegistered to preserve SDK's correct IPNS key
102→   * when the store has an empty placeholder (SDK-created folders store
103→   * keys internally, not in Zustand).
104→   */
105→  getFolderIpnsPrivateKey(ipnsName: string): Uint8Array | undefined {
106→    const key = this.folderTree.get(ipnsName)?.ipnsKeypair?.privateKey;
107→    return key && key.length > 0 ? key : undefined;
