288→  /**
289→   * Rename a child entry (folder or file) in a folder.
290→   *
291→   * Updates the name in the folder's metadata and publishes the change.
292→   *
293→   * @param folderIpnsName - IPNS name of the folder containing the item
294→   * @param childId - ID of the child to rename
295→   * @param newName - New name for the child
296→   */
297→  async renameItem(folderIpnsName: string, childId: string, newName: string): Promise<void> {
298→    return this.withOperation('renameItem', async () => {
299→      const folder = this.folderTree.get(folderIpnsName);
300→      if (!folder) throw new Error('Folder not loaded');
301→
302→      // 1. Rename in metadata (pure operation)
303→      const { updatedChildren } = sdkCore.renameInFolder({
304→        children: folder.children,
305→        childId,
306→        newName,
307→      });
308→
309→      // 2. Publish updated metadata
310→      const { newSequenceNumber } = await sdkCore.updateFolderMetadataAndPublish({
311→        children: updatedChildren,
312→        folderKey: folder.folderKey,
313→        ipnsPrivateKey: folder.ipnsKeypair.privateKey,
314→        ipnsName: folderIpnsName,
315→        sequenceNumber: folder.sequenceNumber,
316→        ctx: this.ctx,
317→      });
318→
319→      // 3. Update internal state
320→      folder.children = updatedChildren;
321→      folder.sequenceNumber = newSequenceNumber;
322→      folder.lastLoadedAt = Date.now();
323→      this.folderTree.set(folderIpnsName, folder);
324→
325→      // 4. Emit update event
326→      this.emitter.emit({
327→        type: 'folder:updated',
328→        folderId: folderIpnsName,
329→        ipnsName: folderIpnsName,
330→        children: updatedChildren,
331→      });
332→    });
333→  }
