403→  /**
404→   * Delete a child entry from a folder's metadata.
405→   *
406→   * This is a simple metadata delete -- it does NOT move to bin.
407→   * Use deleteToBin() for soft-delete with bin support.
408→   *
409→   * @param folderIpnsName - IPNS name of the folder containing the item
410→   * @param childId - ID of the child to delete
411→   * @returns The removed child entry
412→   */
413→  async deleteItem(folderIpnsName: string, childId: string): Promise<{ removedItem: FolderChild }> {
414→    return this.withOperation('deleteItem', async () => {
415→      const folder = this.folderTree.get(folderIpnsName);
416→      if (!folder) throw new Error('Folder not loaded');
417→
418→      // 1. Remove from metadata (pure operation)
419→      const { updatedChildren, removedItem } = sdkCore.deleteFromFolder({
420→        children: folder.children,
421→        childId,
422→      });
423→
424→      // 2. Publish updated metadata
425→      const { newSequenceNumber } = await sdkCore.updateFolderMetadataAndPublish({
426→        children: updatedChildren,
427→        folderKey: folder.folderKey,
428→        ipnsPrivateKey: folder.ipnsKeypair.privateKey,
429→        ipnsName: folderIpnsName,
430→        sequenceNumber: folder.sequenceNumber,
431→        ctx: this.ctx,
432→      });
433→
434→      // 3. Update internal state
435→      folder.children = updatedChildren;
436→      folder.sequenceNumber = newSequenceNumber;
437→      folder.lastLoadedAt = Date.now();
438→      this.folderTree.set(folderIpnsName, folder);
439→
440→      // 4. Emit update event
441→      this.emitter.emit({
442→        type: 'folder:updated',
443→        folderId: folderIpnsName,
444→        ipnsName: folderIpnsName,
445→        children: updatedChildren,
446→      });
447→
448→      return { removedItem };
449→    });
450→  }
