537→  /**
538→   * Download a file using its per-file IPNS metadata.
539→   *
540→   * Resolves the file's IPNS record, decrypts the metadata with the
541→   * folder key, then downloads and decrypts the file content.
542→   * This is the primary download path for v2 folder metadata.
543→   *
544→   * @param fileMetaIpnsName - IPNS name of the file's metadata record
545→   * @param folderKey - Parent folder's decrypted AES-256 key
546→   * @param onProgress - Optional download progress callback
547→   * @returns Decrypted file content
548→   */
549→  async downloadFromIpns(
550→    fileMetaIpnsName: string,
551→    folderKey: Uint8Array,
552→    onProgress?: DownloadProgressCallback
553→  ): Promise<Uint8Array> {
554→    return this.withOperation('downloadFromIpns', async () => {
555→      // 1. Resolve per-file IPNS to get FileMetadata
556→      const resolved = await sdkCore.resolveFileMetadata(fileMetaIpnsName, folderKey, this.ctx);
557→
558→      // 2. Download and decrypt file content
559→      const plaintext = await sdkCore.downloadAndDecrypt({
560→        cid: resolved.metadata.cid,
561→        fileKeyEncrypted: resolved.metadata.fileKeyEncrypted,
562→        fileIv: resolved.metadata.fileIv,
563→        userPrivateKey: this.config.vaultKeypair.privateKey,
564→        encryptionMode: resolved.metadata.encryptionMode,
565→        ctx: this.ctx,
566→        onProgress,
567→      });
568→
569→      this.emitter.emit({ type: 'file:downloaded', cid: resolved.metadata.cid });
570→      return plaintext;
571→    });
572→  }
573→
574→  /**
575→   * Download and decrypt a file from IPFS.
576→   *
577→   * Fetches the encrypted file content, unwraps the file key using the
578→   * user's private key, and decrypts the content.
579→   *
580→   * @param cid - IPFS CID of the encrypted file content
581→   * @param fileKeyEncrypted - Hex-encoded ECIES-wrapped file key
582→   * @param fileIv - Hex-encoded IV used for encryption
583→   * @param encryptionMode - 'GCM' (default) or 'CTR'
584→   * @param onProgress - Optional download progress callback
585→   * @returns Decrypted file content
586→   */
587→  async downloadFile(
588→    cid: string,
589→    fileKeyEncrypted: string,
590→    fileIv: string,
591→    encryptionMode?: 'GCM' | 'CTR',
592→    onProgress?: DownloadProgressCallback
593→  ): Promise<Uint8Array> {
594→    return this.withOperation('downloadFile', async () => {
595→      const plaintext = await sdkCore.downloadAndDecrypt({
596→        cid,
597→        fileKeyEncrypted,
598→        fileIv,
599→        userPrivateKey: this.config.vaultKeypair.privateKey,
600→        encryptionMode,
601→        ctx: this.ctx,
602→        onProgress,
603→      });
604→
605→      this.emitter.emit({ type: 'file:downloaded', cid });
606→
607→      return plaintext;
608→    });
609→  }
