632→  /**
633→   * Soft-delete an item by moving it to the recycle bin.
634→   *
635→   * Removes the item from the folder's metadata, adds a BinEntry,
636→   * and publishes both folder and bin IPNS records.
637→   *
638→   * @param folderIpnsName - IPNS name of the folder containing the item
639→   * @param childId - ID of the child to delete
640→   * @param parentPath - Breadcrumb path for restore (e.g., "My Vault / Documents")
641→   */
642→  async deleteToBin(folderIpnsName: string, childId: string, parentPath: string): Promise<void> {
643→    return this.withOperation('deleteToBin', async () => {
644→      if (!this.binState) throw new BinNotLoadedError();
645→
646→      const { updatedBinState } = await binOps.addToBin({
647→        folderIpnsName,
648→        childId,
649→        parentPath,
650→        folderTree: this.folderTree,
651→        binState: this.binState,
652→        binCtx: this.getBinContext(),
653→      });
654→
655→      this.binState = updatedBinState;
656→
657→      // Emit events
658→      this.emitter.emit({
659→        type: 'folder:updated',
660→        folderId: folderIpnsName,
661→        ipnsName: folderIpnsName,
662→        children: this.folderTree.get(folderIpnsName)?.children ?? [],
663→      });
664→      this.emitter.emit({ type: 'bin:updated', entries: updatedBinState.entries });
665→    });
666→  }
