699→  /**
700→   * Permanently delete a bin entry (unpin CIDs, remove from bin).
701→   *
702→   * @param entryId - ID of the bin entry to permanently delete
703→   */
704→  async permanentDelete(entryId: string): Promise<void> {
705→    return this.withOperation('permanentDelete', async () => {
706→      if (!this.binState) throw new BinNotLoadedError();
707→
