323→/**
324→ * Permanently delete a bin entry (unpin CIDs, remove from bin metadata).
325→ *
326→ * For files: unpins the content CID if available.
327→ * Does NOT handle recursive folder cleanup (that requires deep IPNS traversal).
328→ */
329→export async function permanentDeleteFromBin(params: {
330→  entryId: string;
331→  binState: BinState;
332→  binCtx: BinOperationContext;
333→}): Promise<{ updatedBinState: BinState }> {
334→  const entry = params.binState.entries.find((e) => e.id === params.entryId);
335→  if (!entry) throw new Error('Bin entry not found');
336→
337→  // Unpin content CID if available (best-effort)
338→  if (entry.contentCid) {
339→    try {
340→      await sdkCore.unpinFromIpfs(params.binCtx.ctx, entry.contentCid);
341→    } catch {
342→      // Best-effort CID cleanup
343→    }
344→  }
345→
346→  // Remove from bin metadata and publish
347→  const remainingEntries = params.binState.entries.filter((e) => e.id !== params.entryId);
348→  const newBinSeq = params.binState.sequenceNumber + 1;
349→
350→  const metadata: RecycleBinMetadata = {
351→    version: BIN_METADATA_VERSION,
352→    sequenceNumber: newBinSeq,
353→    entries: remainingEntries,
354→  };
355→
356→  await saveBinMetadata({ metadata, binCtx: params.binCtx });
357→
358→  return {
359→    updatedBinState: {
360→      entries: remainingEntries,
361→      sequenceNumber: newBinSeq,
362→      ipnsName: params.binState.ipnsName,
363→    },
364→  };
365→}
366→
367→/**
368→ * Empty the bin by permanently deleting all entries.
369→ *
370→ * Cleans up CIDs (best-effort) and publishes empty bin metadata.
371→ */
372→export async function emptyBin(params: {
373→  binState: BinState;
374→  binCtx: BinOperationContext;
375→}): Promise<{ updatedBinState: BinState }> {
376→  // Best-effort CID cleanup for each entry
377→  for (const entry of params.binState.entries) {
378→    if (entry.contentCid) {
379→      try {
380→        await sdkCore.unpinFromIpfs(params.binCtx.ctx, entry.contentCid);
381→      } catch {
382→        // Non-blocking
383→      }
384→    }
385→  }
386→
387→  // Publish empty bin metadata
388→  const newBinSeq = params.binState.sequenceNumber + 1;
389→  const metadata: RecycleBinMetadata = {
390→    version: BIN_METADATA_VERSION,
391→    sequenceNumber: newBinSeq,
392→    entries: [],
393→  };
394→
395→  await saveBinMetadata({ metadata, binCtx: params.binCtx });
396→
397→  return {
398→    updatedBinState: {
399→      entries: [],
400→      sequenceNumber: newBinSeq,
401→      ipnsName: params.binState.ipnsName,
402→    },
403→  };
404→}
