  1→import { useState, useCallback } from 'react';
  2→import { useBinStore } from '../stores/bin.store';
  3→import { useAuthStore } from '../stores/auth.store';
  4→import { getSdkClient, hasSdkClient } from '../lib/sdk-provider';
  5→import { initializeBin, purgeExpired } from '../services/bin.service';
  6→import type { BinEntry } from '@cipherbox/core';
  7→
  8→/**
  9→ * React hook for recycle bin operations.
 10→ *
 11→ * Delegates to CipherBoxClient SDK methods for bin CRUD operations.
 12→ * The SDK handles bin metadata, IPNS publishing, and event emission.
 13→ * Loading/error state and purge logic remain in the hook.
 14→ */
 15→export function useBin() {
 16→  const [state, setState] = useState<{ isLoading: boolean; error: string | null }>({
 17→    isLoading: false,
 18→    error: null,
 19→  });
 20→
 21→  const entries = useBinStore((s) => s.entries);
 22→  const isLoaded = useBinStore((s) => s.isLoaded);
 23→  const retentionDays = useBinStore((s) => s.retentionDays);
 24→
 25→  /**
 26→   * Load bin metadata from IPNS and trigger auto-purge of expired entries.
 27→   *
 28→   * Uses initializeBin from bin.service for initial load (populates SDK bin state
 29→   * via useBinStore), then triggers purge as fire-and-forget.
 30→   */
 31→  const loadBin = useCallback(async () => {
 32→    const auth = useAuthStore.getState();
 33→    if (!auth.vaultKeypair) return;
 34→
 35→    setState({ isLoading: true, error: null });
 36→    try {
 37→      // Initialize bin via service (sets up bin IPNS, populates store)
 38→      await initializeBin({
 39→        userPrivateKey: auth.vaultKeypair.privateKey,
 40→        userPublicKey: auth.vaultKeypair.publicKey,
 41→      });
 42→
 43→      // Also load bin into SDK client for subsequent operations
 44→      if (hasSdkClient()) {
 45→        try {
 46→          await getSdkClient().loadBin();
 47→        } catch {
 48→          // SDK bin load is non-blocking -- bin service already populated the store
 49→        }
 50→      }
 51→
 52→      // Non-blocking: purge expired entries after loading
 53→      const currentRetention = useBinStore.getState().retentionDays;
 54→      void purgeExpired({
 55→        retentionDays: currentRetention,
 56→        userPublicKey: auth.vaultKeypair.publicKey,
 57→        userPrivateKey: auth.vaultKeypair.privateKey,
 58→      }).catch(() => {
 59→        console.error('[useBin] Auto-purge failed (non-blocking)');
 60→      });
 61→
 62→      setState({ isLoading: false, error: null });
 63→    } catch (err) {
 64→      const error = err instanceof Error ? err.message : 'Failed to load bin';
 65→      setState({ isLoading: false, error });
 66→    }
 67→  }, []);
 68→
 69→  /**
 70→   * Restore a single bin entry to its original folder via SDK.
 71→   */
 72→  const restore = useCallback(async (entryId: string) => {
 73→    setState({ isLoading: true, error: null });
 74→    try {
 75→      // Look up the target folder from the bin entry's metadata
 76→      const binEntries = useBinStore.getState().entries;
 77→      const entry = binEntries.find((e) => e.id === entryId);
 78→      if (!entry) throw new Error('Bin entry not found');
 79→
 80→      const client = getSdkClient();
 81→      await client.restoreFromBin(entryId, entry.originalParentIpnsName);
 82→      // SDK emits bin:updated -> store subscription updates entries
 83→      setState({ isLoading: false, error: null });
 84→    } catch (err) {
 85→      const error = err instanceof Error ? err.message : 'Failed to restore item';
 86→      setState({ isLoading: false, error });
 87→      throw err;
 88→    }
 89→  }, []);
 90→
 91→  /**
 92→   * Permanently delete a single bin entry via SDK.
 93→   */
 94→  const permanentDelete = useCallback(async (entryId: string) => {
 95→    setState({ isLoading: true, error: null });
 96→    try {
 97→      const client = getSdkClient();
 98→      await client.permanentDelete(entryId);
 99→      // SDK emits bin:updated -> store subscription updates entries
100→      setState({ isLoading: false, error: null });
101→    } catch (err) {
102→      const error = err instanceof Error ? err.message : 'Failed to permanently delete';
103→      setState({ isLoading: false, error });
104→      throw err;
105→    }
106→  }, []);
107→
108→  /**
109→   * Empty all bin entries permanently via SDK.
110→   */
111→  const emptyAll = useCallback(async () => {
112→    setState({ isLoading: true, error: null });
113→    try {
114→      const client = getSdkClient();
115→      await client.emptyBin();
116→      // SDK emits bin:updated with empty entries -> store subscription updates
117→      setState({ isLoading: false, error: null });
118→    } catch (err) {
119→      const error = err instanceof Error ? err.message : 'Failed to empty bin';
120→      setState({ isLoading: false, error });
121→      throw err;
122→    }
123→  }, []);
124→
125→  /**
126→   * Restore multiple bin entries via SDK.
127→   */
128→  const restoreMultiple = useCallback(async (entryIds: string[]) => {
129→    setState({ isLoading: true, error: null });
130→    try {
131→      const binEntries = useBinStore.getState().entries;
132→      const client = getSdkClient();
133→      for (const entryId of entryIds) {
134→        const entry = binEntries.find((e) => e.id === entryId);
135→        if (!entry) continue;
136→        await client.restoreFromBin(entryId, entry.originalParentIpnsName);
137→      }
138→      setState({ isLoading: false, error: null });
139→    } catch (err) {
140→      const error = err instanceof Error ? err.message : 'Failed to restore items';
141→      setState({ isLoading: false, error });
142→      throw err;
143→    }
144→  }, []);
145→
146→  /**
147→   * Permanently delete multiple bin entries via SDK.
148→   */
149→  const permanentDeleteMultiple = useCallback(async (entryIds: string[]) => {
150→    setState({ isLoading: true, error: null });
151→    try {
152→      const client = getSdkClient();
153→      for (const entryId of entryIds) {
154→        await client.permanentDelete(entryId);
155→      }
156→      setState({ isLoading: false, error: null });
157→    } catch (err) {
158→      const error = err instanceof Error ? err.message : 'Failed to permanently delete items';
159→      setState({ isLoading: false, error });
160→      throw err;
161→    }
162→  }, []);
163→
164→  /**
165→   * Calculate days remaining before a bin entry is auto-purged.
166→   */
167→  const daysRemaining = useCallback(
168→    (entry: BinEntry): number => {
169→      const elapsed = Date.now() - entry.deletedAt;
170→      const retentionMs = retentionDays * 24 * 60 * 60 * 1000;
171→      return Math.max(0, Math.ceil((retentionMs - elapsed) / (24 * 60 * 60 * 1000)));
172→    },
173→    [retentionDays]
174→  );
175→
176→  return {
177→    ...state,
178→    entries,
179→    isLoaded,
180→    retentionDays,
181→    daysRemaining,
182→    loadBin,
183→    restore,
184→    permanentDelete,
185→    emptyAll,
186→    restoreMultiple,
187→    permanentDeleteMultiple,
188→  };
189→}
