 1→/**
 2→ * Centralized cleanup of all user-scoped Zustand stores.
 3→ *
 4→ * Called from:
 5→ * - useAuth logout (normal logout flow)
 6→ * - apiClient 401 interceptor (forced logout on token refresh failure)
 7→ *
 8→ * Order matters: clear stores holding crypto keys BEFORE clearing auth state,
 9→ * so sensitive key material is zeroed from memory first. [SECURITY: HIGH-02]
10→ */
11→import { destroySdkClient } from './sdk-provider';
12→import { useFolderStore } from '../stores/folder.store';
13→import { useVaultStore } from '../stores/vault.store';
14→import { useSyncStore } from '../stores/sync.store';
15→import { useDeviceRegistryStore } from '../stores/device-registry.store';
16→import { useBinStore } from '../stores/bin.store';
17→import { useShareStore } from '../stores/share.store';
18→import { useQuotaStore } from '../stores/quota.store';
19→import { useMfaStore } from '../stores/mfa.store';
20→import { useNotificationStore } from '../stores/notification.store';
21→import { useAuthStore } from '../stores/auth.store';
22→import { clearFileSizeCache } from '../hooks/useFileSize';
23→
24→export function clearAllUserStores(): void {
25→  // 0. Destroy SDK client first (clears key caches, event subscriptions)
26→  destroySdkClient();
27→
28→  // 1. Clear stores with crypto key material first
29→  useFolderStore.getState().clearFolders();
30→  useVaultStore.getState().clearVaultKeys();
31→
32→  // 2. Clear remaining user-scoped stores
33→  useSyncStore.getState().reset();
34→  useDeviceRegistryStore.getState().clearRegistry();
35→  useBinStore.getState().clearBin();
36→  useShareStore.getState().clearShares();
37→  useQuotaStore.getState().reset();
38→  useMfaStore.getState().reset();
39→  useNotificationStore.getState().clearNotifications();
40→  clearFileSizeCache();
41→
42→  // 3. Clear auth state last (zeros keypair memory, sets isAuthenticated=false)
43→  useAuthStore.getState().logout();
44→}
