 1→import axios, {
 2→  type AxiosInstance,
 3→  type AxiosRequestConfig,
 4→  type AxiosError,
 5→  type AxiosProgressEvent,
 6→  type CancelToken,
 7→} from 'axios';
 8→
 9→export type ApiClientConfig = {
10→  /** Base URL for the CipherBox API (e.g., "http://localhost:3000") */
11→  baseUrl: string;
12→  /** Returns a valid access token. Consumer owns refresh logic. */
13→  getAccessToken: () => Promise<string>;
14→};
15→
16→/**
17→ * Create a configured axios instance for CipherBox API calls.
18→ * No Zustand, no import.meta.env -- all config injected by consumer.
19→ */
20→export function createAxiosInstance(config: ApiClientConfig): AxiosInstance {
21→  const instance = axios.create({ baseURL: config.baseUrl });
22→  instance.interceptors.request.use(async (reqConfig) => {
23→    const token = await config.getAccessToken();
24→    if (token) {
25→      reqConfig.headers.Authorization = `Bearer ${token}`;
26→    }
27→    return reqConfig;
28→  });
29→  return instance;
30→}
31→
32→/**
33→ * Custom instance function for orval-generated code.
34→ * Matches the signature orval expects from a mutator.
35→ * The consumer must call setApiClientConfig() before using generated functions.
36→ */
37→let _config: ApiClientConfig | null = null;
38→let _instance: AxiosInstance | null = null;
39→
40→export function setApiClientConfig(config: ApiClientConfig): void {
41→  _config = config;
42→  _instance = null; // Reset cached instance when config changes
43→}
44→
45→export function getApiClientConfig(): ApiClientConfig {
46→  if (!_config) throw new Error('API client not configured. Call setApiClientConfig() first.');
47→  return _config;
48→}
49→
50→function getCachedInstance(): AxiosInstance {
51→  if (!_instance) {
52→    const clientConfig = getApiClientConfig();
53→    _instance = axios.create({ baseURL: clientConfig.baseUrl });
54→  }
55→  return _instance;
56→}
57→
58→export const customInstance = async <T>(
59→  config: AxiosRequestConfig,
60→  options?: AxiosRequestConfig
61→): Promise<T> => {
62→  const clientConfig = getApiClientConfig();
63→  const token = await clientConfig.getAccessToken();
64→  const instance = getCachedInstance();
65→
66→  const response = await instance.request<T>({
67→    ...config,
68→    ...options,
69→    headers: {
70→      ...config.headers,
71→      ...options?.headers,
72→      ...(token ? { Authorization: `Bearer ${token}` } : {}),
73→    },
74→  });
75→
76→  return response.data;
77→};
78→
79→export default customInstance;
80→
81→export type ErrorType<Error> = AxiosError<Error>;
82→export type BodyType<BodyData> = BodyData;
83→
84→// Re-export axios types that consumers need for IPFS upload (progress, cancel)
85→export type { AxiosInstance, AxiosProgressEvent, CancelToken };
86→export { default as axios } from 'axios';
