  1→/**
  2→ * File Metadata Service - Per-file IPNS operations
  3→ *
  4→ * Extracted from: apps/web/src/services/file-metadata.service.ts
  5→ * Change: teeKeys passed explicitly instead of read from useAuthStore.
  6→ * Change: IPFS/IPNS operations use sdk-core internal modules instead of web app imports.
  7→ */
  8→
  9→import {
 10→  generateFileIpnsKeypair,
 11→  encryptFileMetadata,
 12→  decryptFileMetadata,
 13→  createIpnsRecord,
 14→  marshalIpnsRecord,
 15→  type FileMetadata,
 16→  type EncryptedFileMetadata,
 17→  type VersionEntry,
 18→} from '@cipherbox/core';
 19→import { wrapKey, bytesToHex, hexToBytes } from '@cipherbox/crypto';
 20→import type { SdkContext, TeeKeys } from '../types';
 21→import { addToIpfs, fetchFromIpfs } from '../ipfs';
 22→import { resolveIpnsRecord } from '../ipns';
 23→
 24→/** IPNS record lifetime: 24 hours in milliseconds */
 25→const IPNS_LIFETIME_MS = 24 * 60 * 60 * 1000;
 26→
 27→/** Maximum number of past versions retained per file (VER-04) */
 28→const MAX_VERSIONS_PER_FILE = 10;
 29→
 30→/** Safe base64 encoding that avoids call stack overflow from spread operator */
 31→function uint8ToBase64(bytes: Uint8Array): string {
 32→  let binary = '';
 33→  for (let i = 0; i < bytes.length; i++) {
 34→    binary += String.fromCharCode(bytes[i]);
 35→  }
 36→  return btoa(binary);
 37→}
 38→
 39→/** Record payload ready for batch publish */
 40→export type FileIpnsRecordPayload = {
 41→  ipnsName: string;
 42→  recordBase64: string;
 43→  metadataCid: string;
 44→  encryptedIpnsPrivateKey?: string;
 45→  keyEpoch?: number;
 46→};
 47→
 48→/**
 49→ * Create a per-file IPNS metadata record.
 50→ *
 51→ * Generates a random Ed25519 IPNS keypair for the file, encrypts file metadata
 52→ * with the parent folder's key, uploads to IPFS, and creates a signed IPNS record.
 53→ *
 54→ * @returns File IPNS name, record payload for batch publish, and ECIES-wrapped IPNS private key
 55→ */
 56→export async function createFileMetadata(params: {
 57→  fileId: string;
 58→  cid: string;
 59→  fileKeyEncrypted: string;
 60→  fileIv: string;
 61→  size: number;
 62→  mimeType: string;
 63→  folderKey: Uint8Array;
 64→  userPublicKey: Uint8Array;
 65→  ctx: SdkContext;
 66→  teeKeys?: TeeKeys;
 67→  encryptionMode?: 'GCM' | 'CTR';
 68→}): Promise<{
 69→  fileMetaIpnsName: string;
 70→  ipnsRecord: FileIpnsRecordPayload;
 71→  ipnsPrivateKeyEncrypted: string;
 72→}> {
 73→  // 1. Generate random Ed25519 IPNS keypair for this file
 74→  const ipnsKeypair = await generateFileIpnsKeypair();
 75→
 76→  // 2. ECIES-wrap the IPNS private key with user's public key for storage in FilePointer
 77→  const wrappedIpnsKey = await wrapKey(ipnsKeypair.privateKey, params.userPublicKey);
 78→  const ipnsPrivateKeyEncrypted = bytesToHex(wrappedIpnsKey);
 79→
 80→  // 3. Create FileMetadata object
 81→  const now = Date.now();
 82→  const metadata: FileMetadata = {
 83→    version: 'v1',
 84→    cid: params.cid,
 85→    fileKeyEncrypted: params.fileKeyEncrypted,
 86→    fileIv: params.fileIv,
 87→    size: params.size,
 88→    mimeType: params.mimeType,
 89→    encryptionMode: params.encryptionMode ?? 'GCM',
 90→    createdAt: now,
 91→    modifiedAt: now,
 92→  };
 93→
 94→  // 4. Encrypt with parent folderKey
 95→  const encrypted: EncryptedFileMetadata = await encryptFileMetadata(metadata, params.folderKey);
 96→
 97→  // 5. Upload encrypted metadata to IPFS
 98→  const jsonStr = JSON.stringify(encrypted);
 99→  const encryptedBytes = new TextEncoder().encode(jsonStr);
100→  const { cid: metadataCid } = await addToIpfs(params.ctx, encryptedBytes);
101→
102→  // 6. Create IPNS record (sequence number 1 for new records)
103→  const record = await createIpnsRecord(
104→    ipnsKeypair.privateKey,
105→    `/ipfs/${metadataCid}`,
106→    1n,
107→    IPNS_LIFETIME_MS
108→  );
109→
110→  // 7. Marshal and base64 encode the record
111→  const recordBytes = marshalIpnsRecord(record);
112→  const recordBase64 = uint8ToBase64(recordBytes);
113→
114→  // 8. TEE enrollment: encrypt IPNS private key with TEE public key
115→  let teeEncryptedIpnsPrivateKey: string | undefined;
116→  let keyEpoch: number | undefined;
117→
118→  if (params.teeKeys?.currentPublicKey) {
119→    const teePublicKey = hexToBytes(params.teeKeys.currentPublicKey);
120→    const encryptedKey = await wrapKey(ipnsKeypair.privateKey, teePublicKey);
121→    teeEncryptedIpnsPrivateKey = bytesToHex(encryptedKey);
122→    keyEpoch = params.teeKeys.currentEpoch;
123→  }
124→
125→  // Zero the private key now that wrapping, signing, and TEE enrollment are done
126→  ipnsKeypair.privateKey.fill(0);
127→
128→  return {
129→    fileMetaIpnsName: ipnsKeypair.ipnsName,
130→    ipnsRecord: {
131→      ipnsName: ipnsKeypair.ipnsName,
132→      recordBase64,
133→      metadataCid,
134→      encryptedIpnsPrivateKey: teeEncryptedIpnsPrivateKey,
135→      keyEpoch,
136→    },
137→    ipnsPrivateKeyEncrypted,
138→  };
139→}
