 78→/**
 79→ * Create a new subfolder with generated keys.
 80→ *
 81→ * Generates new Ed25519 IPNS keypair and AES-256 folder key,
 82→ * wraps them with the user's public key for storage.
 83→ *
 84→ * @returns Created folder entry and decrypted keys
 85→ */
 86→export async function createSubfolder(params: {
 87→  name: string;
 88→  userPublicKey: Uint8Array;
 89→  teeKeys?: TeeKeys;
 90→}): Promise<{
 91→  folder: FolderEntry;
 92→  ipnsPrivateKey: Uint8Array;
 93→  folderKey: Uint8Array;
 94→  encryptedIpnsPrivateKey?: string;
 95→  keyEpoch?: number;
 96→}> {
 97→  // 1. Generate Ed25519 keypair for folder IPNS
 98→  const ipnsKeypair = await generateEd25519Keypair();
 99→  const ipnsName = await deriveIpnsName(ipnsKeypair.publicKey);
100→
101→  // 2. Generate random AES-256 folder key
102→  const folderKey = generateRandomBytes(32);
103→
104→  // 3. Wrap keys with user's public key (ECIES encryption)
105→  const ipnsPrivateKeyEncrypted = bytesToHex(
106→    await wrapKey(ipnsKeypair.privateKey, params.userPublicKey)
107→  );
108→  const folderKeyEncrypted = bytesToHex(await wrapKey(folderKey, params.userPublicKey));
109→
110→  // 4. TEE-02: Encrypt IPNS private key with TEE public key for republishing
111→  let encryptedIpnsPrivateKey: string | undefined;
112→  let keyEpoch: number | undefined;
113→
114→  if (params.teeKeys?.currentPublicKey) {
115→    const teePublicKey = hexToBytes(params.teeKeys.currentPublicKey);
116→    const encryptedKey = await wrapKey(ipnsKeypair.privateKey, teePublicKey);
117→    encryptedIpnsPrivateKey = bytesToHex(encryptedKey);
118→    keyEpoch = params.teeKeys.currentEpoch;
119→  }
120→
121→  // 5. Create folder entry for parent's metadata
122→  const now = Date.now();
123→  const folder: FolderEntry = {
124→    type: 'folder',
125→    id: crypto.randomUUID(),
126→    name: params.name,
127→    ipnsName,
128→    ipnsPrivateKeyEncrypted,
129→    folderKeyEncrypted,
130→    createdAt: now,
131→    modifiedAt: now,
132→  };
133→
134→  return {
135→    folder,
136→    ipnsPrivateKey: ipnsKeypair.privateKey,
137→    folderKey,
138→    encryptedIpnsPrivateKey,
139→    keyEpoch,
140→  };
141→}
142→
143→/**
144→ * Update folder metadata and publish to IPNS.
145→ *
146→ * Encrypts the metadata with the folder key, uploads to IPFS,
147→ * and publishes an updated IPNS record pointing to the new CID.
148→ *
149→ * @returns New CID and sequence number
150→ */
151→export async function updateFolderMetadataAndPublish(params: {
152→  children: FolderChild[];
153→  folderKey: Uint8Array;
154→  ipnsPrivateKey: Uint8Array;
155→  ipnsName: string;
156→  sequenceNumber: bigint;
157→  ctx: SdkContext;
158→  encryptedIpnsPrivateKey?: string;
159→  keyEpoch?: number;
160→}): Promise<{ cid: string; newSequenceNumber: bigint }> {
161→  // 1. Create v2 folder metadata
162→  const metadata: FolderMetadata = {
163→    version: 'v2',
164→    children: params.children,
165→  };
166→
167→  // 2. Encrypt metadata with folder key
168→  const encrypted = await encryptFolderMetadata(metadata, params.folderKey);
169→
170→  // 3. Upload to IPFS via backend relay
171→  const jsonStr = JSON.stringify(encrypted);
172→  const encryptedBytes = new TextEncoder().encode(jsonStr);
173→  const { cid } = await addToIpfs(params.ctx, encryptedBytes);
174→
175→  // 4. Publish IPNS record with conflict retry
176→  //    On 409, resolve current seq from IPNS and retry once
177→  let currentSeq = params.sequenceNumber;
178→
179→  for (let attempt = 0; attempt < 2; attempt++) {
180→    const newSeq = currentSeq + 1n;
181→    try {
182→      await createAndPublishIpnsRecord({
183→        ipnsPrivateKey: params.ipnsPrivateKey,
184→        ipnsName: params.ipnsName,
185→        metadataCid: cid,
186→        sequenceNumber: newSeq,
187→        encryptedIpnsPrivateKey: params.encryptedIpnsPrivateKey,
188→        keyEpoch: params.keyEpoch,
189→        expectedSequenceNumber: currentSeq.toString(),
190→      });
191→      return { cid, newSequenceNumber: newSeq };
192→    } catch (err) {
193→      const is409 =
194→        (err as Error & { status?: number }).status === 409 ||
195→        (err as Error & { response?: { status?: number } }).response?.status === 409;
196→      if (!is409 || attempt > 0) throw err;
197→
198→      // Re-sync: resolve current seq from IPNS
199→      const resolved = await resolveIpnsRecord(params.ipnsName);
200→      if (resolved) {
201→        currentSeq = resolved.sequenceNumber;
202→      } else {
203→        throw err; // Can't resolve → give up
204→      }
205→    }
206→  }
207→
208→  // Should not reach here, but TypeScript needs it
209→  throw new Error('Publish failed after retry');
210→}
