290→/**
291→ * Move a child entry between folders.
292→ *
293→ * Pure metadata operation: returns updated source and dest children arrays.
294→ * Uses add-before-remove pattern conceptually (caller publishes dest first, then source).
295→ */
296→export function moveItem(params: {
297→  sourceChildren: FolderChild[];
298→  destChildren: FolderChild[];
299→  childId: string;
300→}): {
301→  updatedSourceChildren: FolderChild[];
302→  updatedDestChildren: FolderChild[];
303→  movedItem: FolderChild;
304→} {
305→  const index = params.sourceChildren.findIndex((c) => c.id === params.childId);
306→  if (index === -1) throw new Error('Item not found');
307→
308→  const movedItem = {
309→    ...params.sourceChildren[index],
310→    modifiedAt: Date.now(),
311→  };
312→
313→  // Check name collision in destination
314→  const nameExists = params.destChildren.some((c) => c.name === movedItem.name);
315→  if (nameExists) {
316→    throw new Error('An item with this name already exists in destination');
317→  }
318→
319→  const updatedSourceChildren = params.sourceChildren.filter((c) => c.id !== params.childId);
320→  const updatedDestChildren = [...params.destChildren, movedItem];
321→
322→  return { updatedSourceChildren, updatedDestChildren, movedItem };
323→}
