 1→/**
 2→ * @cipherbox/sdk - Key cache
 3→ *
 4→ * Caches derived keys to avoid redundant HKDF derivations.
 5→ * All cached values are zeroed on clear() to prevent key material
 6→ * from persisting in memory after the client is destroyed.
 7→ */
 8→
 9→export class KeyCache {
10→  private cache = new Map<string, Uint8Array>();
11→
12→  /** Get a cached key by its derivation identifier */
13→  get(key: string): Uint8Array | undefined {
14→    return this.cache.get(key);
15→  }
16→
17→  /** Cache a derived key */
18→  set(key: string, value: Uint8Array): void {
19→    this.cache.set(key, value);
20→  }
21→
22→  /**
23→   * Clear all cached keys, zeroing memory.
24→   * Called during client destroy().
25→   */
26→  clear(): void {
27→    for (const value of this.cache.values()) {
28→      value.fill(0);
29→    }
30→    this.cache.clear();
31→  }
32→}
