 18→import { initializeOrSyncRegistry } from '../services/device-registry.service';
 19→import { initializeBin } from '../services/bin.service';
 20→import { useBinStore } from '../stores/bin.store';
 21→import { vaultControllerGetConfig } from '../api/vault/vault';
 22→
 23→export function useAuth() {
 24→  const navigate = useNavigate();
 25→  const {
 26→    isLoggedIn: coreKitLoggedIn,
 27→    isInitialized: coreKitInitialized,
 28→    isRequiredShare,
 29→    loginWithGoogle: coreKitLoginGoogle,
 30→    loginWithEmailOtp: coreKitLoginEmail,
 31→    loginWithWallet: coreKitLoginWallet,
 32→    getVaultKeypair,
 33→    getPublicKeyHex,
 34→    logout: coreKitLogout,
 35→  } = useCoreKitAuth();
 36→  const { syncStatus } = useCoreKit();
 37→  const {
 38→    accessToken,
 39→    isAuthenticated,
 40→    lastAuthMethod,
 41→    userEmail,
 42→    setAccessToken,
 43→    setLastAuthMethod,
 44→    setUserEmail,
 45→    setVaultKeypair,
 46→  } = useAuthStore();
 47→
 48→  const [isLoggingIn, setIsLoggingIn] = useState(false);
 49→  const [isLoggingOut, setIsLoggingOut] = useState(false);
 50→  const restoringRef = useRef(false);
 51→
 52→  // Stable refs for functions used in the session restoration effect.
 53→  // This prevents the effect from re-firing when function references change.
 54→  const initializeOrLoadVaultRef = useRef<(() => Promise<void>) | null>(null);
 55→  const coreKitLogoutRef = useRef<(() => Promise<void>) | null>(null);
 56→
 57→  // Pending auth state for REQUIRED_SHARE flow.
 58→  // Stored in Zustand (not useState) so the state is shared across all
 59→  // useAuth() hook instances — Login.tsx sets it, useDeviceApproval reads it
 60→  // via its own useAuth() call.
 61→  const pendingAuthMethod = useAuthStore((s) => s.pendingAuthMethod);
 62→  const setPendingAuth = useAuthStore((s) => s.setPendingAuth);
 63→
 64→  const isLoading = !coreKitInitialized || isLoggingIn || isLoggingOut;
 65→
 66→  // Get vault store actions
 67→  const setVaultKeys = useVaultStore((state) => state.setVaultKeys);
 68→
 69→  /**
 70→   * Initialize vault for new users or load existing vault keys.
 71→   * Called after successful backend authentication.
 72→   * Uses Core Kit's getVaultKeypair() instead of PnP provider.
 73→   */
 74→  const initializeOrLoadVault = useCallback(async (): Promise<void> => {
 75→    // Get user's secp256k1 keypair from Core Kit TSS export
 76→    const userKeypair = await getVaultKeypair();
 77→
 78→    if (!userKeypair) {
 79→      throw new Error('Failed to get vault keypair from Core Kit');
 80→    }
 81→
 82→    // Store keypair in auth store for crypto operations
 83→    setVaultKeypair(userKeypair);
 84→
 85→    try {
 86→      // Try to fetch existing vault
 87→      const existingVault = await vaultApi.getVault();
 88→
 89→      // Store TEE keys if available
 90→      if (existingVault.teeKeys) {
 91→        useAuthStore.getState().setTeeKeys(existingVault.teeKeys);
 92→      }
 93→
 94→      // Vault exists - decrypt keys and load into store
 95→      // decryptVaultKeys derives the IPNS public key internally from the decrypted private key
 96→      const decryptedVault = await decryptVaultKeys(
 97→        {
 98→          encryptedRootFolderKey: hexToBytes(existingVault.encryptedRootFolderKey),
 99→          encryptedIpnsPrivateKey: hexToBytes(existingVault.encryptedRootIpnsPrivateKey),
100→        },
101→        userKeypair.privateKey
102→      );
103→
104→      setVaultKeys({
105→        rootFolderKey: decryptedVault.rootFolderKey,
106→        rootIpnsKeypair: decryptedVault.rootIpnsKeypair,
107→        rootIpnsName: existingVault.rootIpnsName,
108→        vaultId: existingVault.id,
109→      });
110→    } catch (error) {
111→      const is404 = (error as { response?: { status?: number } })?.response?.status === 404;
112→
113→      if (is404) {
114→        // New user - initialize vault
115→        console.log(
116→          '[Auth] New user on Core Kit. If migrating from PnP, vault re-initialization may be needed.'
117→        );
118→        const newVault = await initializeVault(userKeypair.privateKey);
119→        const encryptedVault = await encryptVaultKeys(newVault, userKeypair.publicKey);
120→        const rootIpnsName = await deriveIpnsName(newVault.rootIpnsKeypair.publicKey);
121→
122→        const storedVault = await vaultApi.initVault({
123→          ownerPublicKey: bytesToHex(userKeypair.publicKey),
124→          encryptedRootFolderKey: bytesToHex(encryptedVault.encryptedRootFolderKey),
125→          encryptedRootIpnsPrivateKey: bytesToHex(encryptedVault.encryptedIpnsPrivateKey),
126→          rootIpnsName,
127→        });
128→
129→        if (storedVault.teeKeys) {
130→          useAuthStore.getState().setTeeKeys(storedVault.teeKeys);
131→        }
132→
133→        setVaultKeys({
134→          rootFolderKey: newVault.rootFolderKey,
135→          rootIpnsKeypair: newVault.rootIpnsKeypair,
136→          rootIpnsName,
137→          vaultId: storedVault.id,
138→          isNewVault: true,
139→        });
140→      } else {
141→        console.error('[useAuth] Failed to load vault:', error);
142→        throw error;
143→      }
144→    }
145→
146→    // Initialize SDK client with decrypted vault keys
147→    const vaultState = useVaultStore.getState();
148→    const authState = useAuthStore.getState();
149→    if (vaultState.rootFolderKey && vaultState.rootIpnsKeypair && vaultState.rootIpnsName) {
150→      const apiUrl = import.meta.env.VITE_API_URL || window.location.origin + '/api';
151→      const getAccessToken = async () => {
152→        const state = useAuthStore.getState();
153→        return state.accessToken || '';
154→      };
155→
156→      // Configure @cipherbox/api-client for SDK-core IPNS operations
157→      setApiClientConfig({ baseUrl: apiUrl, getAccessToken });
158→
159→      const sdkClient = initSdkClient({
160→        apiUrl,
161→        getAccessToken,
162→        vaultKeypair: {
163→          publicKey: userKeypair.publicKey,
164→          privateKey: userKeypair.privateKey,
165→        },
166→        rootIpnsName: vaultState.rootIpnsName,
167→        rootFolderKey: vaultState.rootFolderKey,
168→        teeKeys: authState.teeKeys ?? undefined,
169→      });
170→
171→      // Subscribe folder store to SDK events
172→      useFolderStore.getState().subscribeToSdk(sdkClient);
173→
174→      // Subscribe bin store to SDK events
175→      useBinStore.getState().subscribeToSdk(sdkClient);
176→    }
177→
178→    // Non-blocking device registry initialization (fire-and-forget)
179→    // Placed after vault load so registry failures never block login
180→    void (async () => {
181→      try {
182→        const deviceKeypair = await getOrCreateDeviceIdentity({
183→          mode: 'persisted',
184→          vaultPrivateKey: userKeypair.privateKey,
185→        });
186→        const deviceInfo = detectDeviceInfo();
187→        const result = await initializeOrSyncRegistry({
188→          userPrivateKey: userKeypair.privateKey,
189→          userPublicKey: userKeypair.publicKey,
190→          deviceKeypair,
191→          deviceInfo: { ...deviceInfo, ipHash: '' },
192→        });
193→        if (result) {
194→          useDeviceRegistryStore
195→            .getState()
196→            .setRegistry(result.registry, result.ipnsName, deviceKeypair.deviceId);
197→        }
198→      } catch (error) {
199→        console.error('[Auth] Device registry init failed (non-blocking):', error);
200→      }
201→    })();
202→
203→    // Non-blocking bin initialization (fire-and-forget)
204→    // After old service creates/loads bin, also load into SDK for deleteToBin support
205→    void (async () => {
206→      try {
207→        await initializeBin({
208→          userPrivateKey: userKeypair.privateKey,
209→          userPublicKey: userKeypair.publicKey,
210→        });
211→        // Now load bin into SDK (old service ensures bin IPNS record exists)
212→        const { getSdkClient, hasSdkClient } = await import('../lib/sdk-provider');
213→        if (hasSdkClient()) {
214→          await getSdkClient().loadBin();
215→        }
216→      } catch (error) {
217→        console.error('[Auth] Bin initialization failed (non-blocking):', error);
218→      }
219→    })();
220→
221→    // Non-blocking: fetch retention config from API
222→    void (async () => {
223→      try {
224→        const config = await vaultControllerGetConfig();
225→        if (config.recycleBinRetentionDays != null) {
226→          useBinStore.getState().setRetentionDays(config.recycleBinRetentionDays);
227→        }
228→      } catch (error) {
229→        console.error('[Auth] Failed to fetch vault config (non-blocking):', error);
230→      }
231→    })();
232→  }, [getVaultKeypair, setVaultKeypair, setVaultKeys]);
233→
234→  /**
235→   * Complete backend authentication after Core Kit login.
236→   * Sends the CipherBox-issued JWT (which we used for Core Kit loginWithJWT)
237→   * to the backend with loginType 'corekit'. The backend verifies it against
238→   * its own JWKS since CipherBox is the identity provider.
239→   */
240→  const completeBackendAuth = useCallback(
241→    async (authMethod: string, cipherboxJwt: string): Promise<void> => {
242→      // 1. Get real publicKey from Core Kit TSS export
243→      const publicKey = await getPublicKeyHex();
244→      if (!publicKey) {
245→        throw new Error('Failed to get publicKey from Core Kit');
246→      }
247→
248→      // publicKey available for debugging via DevTools if needed
249→
250→      // 2. Authenticate with CipherBox backend
251→      // Backend verifies our CipherBox JWT and resolves placeholder publicKey
252→      const response = await authApi.login({
253→        idToken: cipherboxJwt,
254→        publicKey,
255→        loginType: 'corekit',
256→      });
257→
258→      // 3. Store access token (refresh token in HTTP-only cookie)
259→      setAccessToken(response.accessToken);
260→
261→      // 4. Remember auth method for UX
262→      setLastAuthMethod(authMethod);
263→
264→      // 5. Initialize or load vault
265→      await initializeOrLoadVault();
266→    },
267→    [getPublicKeyHex, setAccessToken, setLastAuthMethod, initializeOrLoadVault]
268→  );
269→
270→  /**
271→   * Complete the login flow after REQUIRED_SHARE is resolved.
272→   * Called after inputFactorKey() succeeds (from recovery phrase or cross-device approval).
273→   * Uses the stored pendingCipherboxJwt to call completeBackendAuth with the REAL publicKey
274→   * (since Core Kit is now LOGGED_IN), then navigates to /files.
275→   */
276→  const completeRequiredShare = useCallback(async (): Promise<void> => {
277→    // Read directly from Zustand store to get fresh values — this callback
278→    // may be called from useDeviceApproval's useAuth() instance, so we
279→    // can't rely on closure-captured selector values.
280→    const { pendingCipherboxJwt: jwt, pendingAuthMethod: method } = useAuthStore.getState();
281→
282→    if (!jwt || !method) {
283→      throw new Error('No pending auth info for REQUIRED_SHARE completion');
284→    }
285→
286→    // Core Kit should now be LOGGED_IN after inputFactorKey()
287→    // Complete backend auth with the REAL publicKey (replaces the placeholder session)
288→    await completeBackendAuth(method, jwt);
289→
290→    // NOW sync Core Kit React state to LOGGED_IN.
291→    // We deliberately delayed this from inputFactorKey() to prevent the session
292→    // restoration effect from firing before backend auth completed.
293→    // At this point isAuthenticated is true (from completeBackendAuth -> setAccessToken),
294→    // so the session restore guard (coreKitLoggedIn && !isAuthenticated) won't trigger.
295→    syncStatus();
296→
297→    // Clear pending state
298→    setPendingAuth(null, null);
299→
300→    // Navigate to files
301→    navigate('/files');
302→  }, [completeBackendAuth, syncStatus, setPendingAuth, navigate]);
303→
304→  /**
305→   * Login with Google OAuth token.
306→   * Flow: Google idToken -> CipherBox backend -> CipherBox JWT ->
307→   * Core Kit loginWithJWT -> backend /auth/login (corekit type)
308→   */
309→  const loginWithGoogle = useCallback(
310→    async (googleIdToken: string): Promise<void> => {
311→      if (isLoggingIn) return;
312→      setIsLoggingIn(true);
313→      try {
314→        // 1. Core Kit login via CipherBox identity provider
315→        const {
316→          cipherboxJwt,
317→          email,
318→          userId,
319→          status: coreKitStatus,
320→        } = await coreKitLoginGoogle(googleIdToken);
321→
322→        if (coreKitStatus === 'required_share') {
323→          // MFA enabled but device factor missing.
324→          // Store pending auth info for later completion after factor input.
325→          setPendingAuth(cipherboxJwt, 'google');
326→
327→          // Obtain temporary backend access token so the new device can
328→          // call bulletin board API endpoints (device-approval/*).
329→          // Uses placeholder publicKey since Core Kit is in REQUIRED_SHARE
330→          // state and we can't export the TSS key yet.
331→          const tempLoginResponse = await authApi.login({
332→            idToken: cipherboxJwt,
333→            publicKey: `pending-core-kit-${userId}`,
334→            loginType: 'corekit',
335→          });
336→          setAccessToken(tempLoginResponse.accessToken);
337→
338→          if (email) {
339→            setUserEmail(email);
340→          }
341→
342→          // Do NOT call completeBackendAuth() or navigate('/files')
343→          // The component tree will see isRequiredShare === true and
344→          // render recovery/approval UI.
345→          return;
346→        }
347→
348→        // Normal path: Core Kit logged in, proceed as before
349→        // 2. Complete backend auth + vault init
350→        await completeBackendAuth('google', cipherboxJwt);
351→
352→        // 3. Store email for UI display (returned from identity endpoint)
353→        if (email) {
354→          setUserEmail(email);
355→        }
356→
357→        // Navigation handled by Login.tsx redirect effect (isAuthenticated → /files)
358→      } catch (error) {
359→        console.error('[useAuth] Google login failed:', error);
360→        throw error;
361→      } finally {
362→        setIsLoggingIn(false);
363→      }
364→    },
365→    [isLoggingIn, coreKitLoginGoogle, completeBackendAuth, setAccessToken, setUserEmail]
366→  );
367→
368→  /**
369→   * Login with Email OTP.
370→   * Flow: email+otp -> CipherBox backend -> CipherBox JWT ->
371→   * Core Kit loginWithJWT -> backend /auth/login (corekit type)
372→   */
373→  const loginWithEmail = useCallback(
374→    async (email: string, otp: string): Promise<void> => {
375→      if (isLoggingIn) return;
376→      setIsLoggingIn(true);
377→      try {
378→        // 1. Core Kit login via CipherBox identity provider
379→        const { cipherboxJwt, userId, status: coreKitStatus } = await coreKitLoginEmail(email, otp);
380→
381→        if (coreKitStatus === 'required_share') {
382→          setPendingAuth(cipherboxJwt, 'email');
383→
384→          const tempLoginResponse = await authApi.login({
385→            idToken: cipherboxJwt,
386→            publicKey: `pending-core-kit-${userId}`,
387→            loginType: 'corekit',
388→          });
389→          setAccessToken(tempLoginResponse.accessToken);
390→          setUserEmail(email);
391→          return;
392→        }
393→
394→        // Normal path
395→        await completeBackendAuth('email', cipherboxJwt);
396→        setUserEmail(email);
397→        // Navigation handled by Login.tsx redirect effect (isAuthenticated → /files)
398→      } catch (error) {
399→        console.error('[useAuth] Email login failed:', error);
400→        throw error;
401→      } finally {
402→        setIsLoggingIn(false);
403→      }
404→    },
405→    [isLoggingIn, coreKitLoginEmail, completeBackendAuth, setAccessToken, setUserEmail]
406→  );
407→
408→  /**
409→   * Login with Wallet (SIWE).
410→   * Flow: Wallet connects + signs SIWE message -> backend verifies ->
411→   * CipherBox JWT -> Core Kit loginWithJWT -> backend /auth/login (corekit type)
412→   */
413→  const loginWithWallet = useCallback(
414→    async (cipherboxJwt: string, userId: string): Promise<void> => {
415→      if (isLoggingIn) return;
416→      setIsLoggingIn(true);
417→      try {
418→        // 1. Core Kit login via CipherBox identity provider
419→        const { status: coreKitStatus } = await coreKitLoginWallet(cipherboxJwt, userId);
420→
421→        if (coreKitStatus === 'required_share') {
422→          setPendingAuth(cipherboxJwt, 'wallet');
423→
424→          const tempLoginResponse = await authApi.login({
425→            idToken: cipherboxJwt,
426→            publicKey: `pending-core-kit-${userId}`,
427→            loginType: 'corekit',
428→          });
429→          setAccessToken(tempLoginResponse.accessToken);
430→          return;
431→        }
432→
433→        // Normal path
434→        await completeBackendAuth('wallet', cipherboxJwt);
435→        // Navigation is handled by Login.tsx's redirect effect (isAuthenticated → /files).
436→        // completeBackendAuth sets the access token early, but initializeOrLoadVault()
437→        // inside it may still be pending. An explicit navigate here would fire AFTER
438→        // vault init completes — by which point the user may have navigated away from
439→        // the login page, causing a disruptive late redirect.
440→      } catch (error) {
441→        console.error('[useAuth] Wallet login failed:', error);
442→        throw error;
443→      } finally {
444→        setIsLoggingIn(false);
445→      }
446→    },
447→    [isLoggingIn, coreKitLoginWallet, completeBackendAuth, setAccessToken]
448→  );
449→
450→  /**
451→   * Legacy login() for backward compatibility with AuthButton.
452→   * With Core Kit, login requires specifying the auth method.
453→   * This will be replaced by the new Login UI in Plan 04.
454→   */
455→  const login = useCallback(async () => {
456→    // Plan 04 will build the new login UI with method selection.
457→    // For now, this is a no-op placeholder that AuthButton calls.
458→    console.warn(
459→      '[useAuth] login() called without method -- ' +
460→        'use loginWithGoogle() or loginWithEmail() instead. ' +
461→        'Plan 04 will provide the new Login UI.'
462→    );
463→  }, []);
464→
465→  // Complete logout: Backend -> Core Kit -> Clear state
466→  const logout = useCallback(async () => {
467→    if (isLoggingOut) return;
468→
469→    setIsLoggingOut(true);
470→    try {
471→      // 1. Call backend logout (clears cookie)
472→      if (accessToken) {
473→        try {
474→          await authApi.logout();
475→        } catch {
476→          // Ignore errors -- we'll clear state anyway
477→        }
478→      }
479→
480→      // 2. Logout Core Kit (clears session from localStorage)
481→      await coreKitLogout();
482→
483→      // 3. Clear all user-scoped stores (centralized helper)
484→      clearAllUserStores();
485→
486→      // 4. Navigate to login
487→      navigate('/');
488→    } catch (error) {
489→      console.error('[useAuth] Logout failed:', error);
490→      // Still clear state even if backend fails
491→      clearAllUserStores();
492→      navigate('/');
493→    } finally {
494→      setIsLoggingOut(false);
495→    }
496→  }, [accessToken, coreKitLogout, navigate, isLoggingOut]);
497→
498→  // Keep function refs up-to-date for use in session restoration effect.
499→  // Using refs prevents the effect from re-firing when function identities change.
500→  initializeOrLoadVaultRef.current = initializeOrLoadVault;
501→  coreKitLogoutRef.current = coreKitLogout;
502→
503→  // Session restoration: if Core Kit restores a session from localStorage
504→  // on init, we have LOGGED_IN status without going through login flow.
505→  // Complete backend auth + vault loading.
506→  useEffect(() => {
507→    const restoreSession = async () => {
508→      // Only restore if Core Kit has a session but we don't have
509→      // a backend access token yet
510→      if (coreKitLoggedIn && !isAuthenticated && !isLoggingIn && !restoringRef.current) {
511→        restoringRef.current = true;
512→        setIsLoggingIn(true);
513→        try {
514→          // Try to refresh using the HTTP-only cookie first
515→          const response = await authApi.refresh();
516→          setAccessToken(response.accessToken);
517→
518→          // Restore email from backend if available
519→          if (response.email) {
520→            setUserEmail(response.email);
521→          }
522→
523→          // Load vault keys from Core Kit keypair
524→          await initializeOrLoadVaultRef.current?.();
525→        } catch {
526→          // No valid backend session -- user needs to re-login
527→          // Core Kit session exists but backend cookie expired
528→          // Clear Core Kit session to avoid inconsistent state
529→          try {
530→            await coreKitLogoutRef.current?.();
531→          } catch {
532→            // Ignore logout errors during cleanup
533→          }
534→        } finally {
535→          restoringRef.current = false;
536→          setIsLoggingIn(false);
537→        }
538→      }
539→    };
540→    restoreSession();
541→  }, [coreKitLoggedIn, isAuthenticated, isLoggingIn, setAccessToken, setUserEmail]);
542→
543→  return {
544→    isLoading,
545→    isAuthenticated,
546→    isRequiredShare,
547→    lastAuthMethod,
548→    userEmail,
549→    pendingAuthMethod,
550→    login,
551→    loginWithGoogle,
552→    loginWithEmail,
553→    loginWithWallet,
554→    completeRequiredShare,
555→    logout,
556→  };
557→}
